  ('照相', null, 'zhàoxiàng', 'to take a photograph', 'fotografiar; hacer fotos; sacar fotos; tomar fotografías; retratar; sesión de fotos; fotografía (la actividad); estudio fotográfico; posar para una foto; hacerse un retrato', null, 3, 'verb', 117001, null, array['照相']::text[]),
