  ('只能', null, 'zhǐ néng', 'can only; obliged to do sth; to have no other choice', 'solo poder; no tener más remedio que; estar obligado a; verse forzado a; tener que limitarse a; la única opción es; no quedar otra que', null, 3, '', 3644329, null, array['只能']::text[]),
  ('直到', null, 'zhídào', 'until', 'hasta; hasta que; hasta el punto de; no fue hasta... que; no parar hasta; llegar hasta; alcanzar hasta', null, 3, 'verb', 1276279, null, array['直到']::text[]),
  ('只是', null, 'zhǐshì', 'merely; only; just; nothing but; simply', 'solo; solamente; meramente; únicamente; nada más que; simplemente; no es más que; tan solo; pero; sin embargo (al final de frase)', null, 3, 'adverb', 7002717, null, array['只是']::text[]),
  ('只要', null, 'zhǐyào', 'so long as; provided; if', 'siempre que; con tal de que; basta con que; solo si; en tanto que', null, 3, 'conjunction', 4142480, null, array['只要']::text[]),
  ('只有', null, 'zhǐyǒu', 'only have ...; there is only ...; (used in combination with 才[cai2]) it is only if ... (that one can ...) (as in 只有通過治療才能痊愈|只有通过治疗才能痊愈[zhi3 you3 tong1 guo4 zhi4 liao2 cai2 neng2 quan2 yu4] ''the only way to cure it is with therapy''); it is only (someone) who ... (as in 只有男性才有此需要[zhi3 you3 nan2 xing4 cai2 you3 ci3 xu1 yao4] ''only men would have such a requirement''); (used to express lack of alternatives) can only', 'solo si; solamente cuando; únicamente; no tener más remedio que', null, 3, 'conjunction', 7327973, null, array['只有']::text[]),
  ('种', '種', 'zhǒng', 'seed; species; kind; type; classifier for types, kinds, sorts', 'tipo; clase; especie; variedad; género; cultivar; plantar; sembrar', null, 3, 'measure word', 14993403, null, array['种']::text[]),
  ('中', null, 'zhōng', 'within; among; in; middle; center', 'centro; medio; central; China (abrev.); dentro de; entre; durante; adecuado para', null, 3, 'noun', 65460099, null, array['中']::text[]),
  ('中间', '中', 'zhōngjiān', 'the middle; the inside; in the middle; within; between', 'en medio; entre; centro; medio; intermedio; en el centro de; durante', null, 3, 'noun', 1156458, null, array['中间']::text[]),
  ('重要', null, 'zhòngyào', 'important; significant; major', 'importante; significativo; relevante; fundamental; crucial; de peso', null, 3, 'adjective', 9812054, null, array['重要']::text[]),
  ('终于', '終', 'zhōngyú', 'at last; in the end; finally; eventually', 'por fin; finalmente; al fin; al cabo; después de todo; al final', null, 3, 'adverb', 4420176, null, array['终于']::text[]),
  ('周末', '週', 'zhōumò', 'weekend', 'fin de semana; sábado y domingo; final de la semana', null, 3, 'noun', 0, null, array['周末']::text[]),
  ('主要', null, 'zhǔyào', 'main; principal; major; primary', 'principal; fundamental; esencial; primordial; mayoritario; sobre todo', null, 3, 'adjective', 9304580, null, array['主要']::text[]),
  ('注意', null, 'zhùyì', 'to take note of; to pay attention to', 'prestar atención; tener cuidado; fijarse en; poner atención; observar', null, 3, 'verb', 3732141, null, array['注意']::text[]),
  ('住院', null, 'zhùyuàn', 'to stay in hospital; to be hospitalized', 'estar hospitalizado; ingresar', null, 3, 'verb', 493697, null, array['住院']::text[]),
  ('子', null, 'zi', 'noun suffix, as in 椅子[yi3 zi5] ''chair''', 'hijo; niño; descendiente; semilla; huevo; (sufijo nominal diminutivo o lexicalizado); persona; sabio; maestro; vizconde (título nobiliario); tú (respetuoso); raíz; rama; pieza (de ajedrez); moneda de cobre; horario (子时 = 23:00-01:00)', null, 3, 'suffix', 4674640, null, array['子']::text[]),
  ('字典', null, 'zìdiǎn', 'Chinese character dictionary (containing entries for single characters, contrasted with a 詞典|词典[ci2 dian3], which has entries for words of one or more characters); (coll.) dictionary', 'diccionario de caracteres chinos; léxico de sinogramas', '本', 3, 'noun', 60497, null, array['字典']::text[]),
  ('自行车', '自', 'zìxíngchē', 'bicycle; bike', 'bicicleta; bici; velocípedo; vehículo de dos ruedas a pedales', '辆', 3, 'noun', 608200, null, array['自行车']::text[]),
  ('总', '總', 'zǒng', '(bound form) general; overall; to sum up; in every case; always', 'total; general; siempre; en cualquier caso; jefe; director; resumir; agrupar', null, 3, 'adverb', 6443030, null, array['总']::text[]),
  ('总是', '總', 'zǒngshì', 'always', 'siempre; invariablemente; constantemente; en todo momento; sin excepción', null, 3, 'adverb', 2757109, null, array['总是']::text[]),
  ('嘴', null, 'zuǐ', 'mouth; beak; nozzle; spout (of teapot etc)', 'boca; pico; boquilla', '张、个', 3, 'noun', 1451793, null, array['嘴']::text[]),
  ('最好', null, 'zuìhǎo', 'best; had better ...; it would be best to ...', 'el mejor; óptimo; lo mejor; sería mejor que...; más vale que...; convendría que...; lo ideal sería; lo más aconsejable; preferiblemente; a lo sumo; como máximo', null, 3, 'adverb', 2918438, null, array['最好']::text[]),
  ('最后', '最', 'zuìhòu', 'final; last; ultimate; finally; in the end', 'final; último; al final; finalmente; por último; en el último momento; postrero; definitivo', null, 3, 'noun', 7078430, null, array['最后']::text[]),
  ('最近', null, 'zuìjìn', 'recently; soon; nearest', 'últimamente; recientemente; hace poco; el más cercano; el más próximo; en breve', null, 3, 'noun', 3710081, null, array['最近']::text[]),
  ('做客', null, 'zuòkè', 'to be a guest or visitor', 'ser invitado; ir de visita; estar de visita en casa de alguien; ser huésped; hacer una visita social; visitar a alguien; acudir como invitado; ser recepcionado; pasar una temporada en casa ajena; estar convidado', null, 3, 'verb', 159415, null, array['做客']::text[]),
  ('作业', '作', 'zuòyè', 'school assignment; homework; work; task; operation', 'deberes; tarea escolar; trabajo; ejercicios; operación; faena; labor', '个', 3, 'noun', 911821, null, array['作业']::text[])
insert into public.grammar_points (hsk_level, code, "group", category, detail, title, pattern, explanation, examples, items, order_idx, markers, common_errors, see_also)
values
  (1, '1.1', '语素', '前缀', null, '前缀', '第 + número (+ clasificador) · 小 + nombre', '第 delante de un número forma los ordinales: 第一 «primero», 第二天 «el segundo día». 小 delante de un apellido de una sílaba sirve para llamar con confianza a alguien más joven o cercano, y además forma palabras con la idea de «pequeño»: 小朋友, 小学. Los dos son prefijos: van pegados a lo que modifican, sin 的.', '[{"zh":"这是我的第一本汉语书。","pinyin":"Zhè shì wǒ de dì yī běn Hànyǔ shū.","es":"Este es mi primer libro de chino."},{"zh":"第二天我们去了医院。","pinyin":"Dì èr tiān wǒmen qù le yīyuàn.","es":"Al día siguiente fuimos al hospital."},{"zh":"小朋友，你几岁了？","pinyin":"Xiǎopéngyǒu, nǐ jǐ suì le?","es":"Pequeño, ¿cuántos años tienes?"},{"zh":"我女儿在上小学。","pinyin":"Wǒ nǚ’ér zài shàng xiǎoxué.","es":"Mi hija va a la escuela primaria."}]'::jsonb, array['小—、第—']::text[], 1, array['第—', '小—']::text[], '[{"wrong":"这是我一本汉语书。","right":"这是我的第一本汉语书。","why":"Sin 第, 一本 es «un libro», no «el primer libro»: el ordinal necesita 第 delante del número."}]'::jsonb, '[{"hsk_level":2,"code":"8.1"}]'::jsonb),
  (1, '1.2', '语素', '后缀', null, '后缀', 'pronombre / persona + 们 · 前 / 后 / 外 / 这 / 那 + 边', '们 forma el plural de los pronombres (我们, 你们) y de algunos nombres de persona (同学们). No se usa con cosas ni cuando ya hay un número: 三个朋友, nunca «三个朋友们». 边 se pega a una palabra de posición o a 这 / 那 para formar un lugar: 前边 «delante», 外边 «fuera», 这边 «este lado».', '[{"zh":"你们去哪儿？","pinyin":"Nǐmen qù nǎr?","es":"¿Adónde vais?"},{"zh":"同学们，你们好！","pinyin":"Tóngxuémen, nǐmen hǎo!","es":"¡Hola a todos!"},{"zh":"商店在前边。","pinyin":"Shāngdiàn zài qiánbian.","es":"La tienda está delante."},{"zh":"外边下雨了。","pinyin":"Wàibian xià yǔ le.","es":"Fuera está lloviendo."},{"zh":"我们去那边吧。","pinyin":"Wǒmen qù nàbian ba.","es":"Vamos hacia allí."}]'::jsonb, array['—们、—边']::text[], 2, array['们', '边']::text[], '[{"wrong":"我有三个朋友们。","right":"我有三个朋友。","why":"Con un número delante ya se sabe que es plural; 们 sobra."}]'::jsonb, '[{"hsk_level":2,"code":"1.1"}]'::jsonb),
  (1, '2.1.1', '词类', '名词', '方位名词', '方位名词', 'nombre + 上 / 下 / 里 / 外 / 前 / 后', 'Estas palabras van detrás de un nombre para situar algo: 桌子上 «encima de la mesa», 房间里 «en la habitación». El orden es el contrario al español: primero el objeto de referencia y después la posición. Con 在 delante dicen dónde está algo (书在桌子上), y con expresiones de tiempo sitúan antes o después: 吃饭后.', '[{"zh":"你的手机在桌子上。","pinyin":"Nǐ de shǒujī zài zhuōzi shang.","es":"Tu móvil está encima de la mesa."},{"zh":"妈妈在房间里。","pinyin":"Māma zài fángjiān li.","es":"Mamá está en la habitación."},{"zh":"椅子下有一只猫。","pinyin":"Yǐzi xià yǒu yì zhī māo.","es":"Debajo de la silla hay un gato."},{"zh":"学校前有一个商店。","pinyin":"Xuéxiào qián yǒu yí gè shāngdiàn.","es":"Delante del colegio hay una tienda."},{"zh":"吃饭后我们去看电影。","pinyin":"Chī fàn hòu wǒmen qù kàn diànyǐng.","es":"Después de comer vamos al cine."}]'::jsonb, array['上、下、里、外、前、后']::text[], 3, array['上', '里', '下', '前', '后']::text[], '[{"wrong":"你的手机在上桌子。","right":"你的手机在桌子上。","why":"La posición va detrás del nombre: 桌子上, no delante como en «encima de la mesa»."}]'::jsonb, '[{"hsk_level":2,"code":"1.1"},{"hsk_level":2,"code":"2.1.1"}]'::jsonb),
  (1, '2.2.1', '词类', '动词', '能愿动词', '能愿动词', '会 / 能 / 可以 / 想 / 要 + verbo', 'Van delante de otro verbo. 会 es saber hacer algo que se ha aprendido: 我会说汉语. 能 es poder porque hay capacidad o se dan las circunstancias: 我今天不能去. 可以 es tener permiso: 我可以坐这儿吗？ 想 expresa ganas, «querer», y 要, una intención más firme: 我要喝茶.', '[{"zh":"我会说汉语。","pinyin":"Wǒ huì shuō Hànyǔ.","es":"Sé hablar chino."},{"zh":"今天我很忙，不能去。","pinyin":"Jīntiān wǒ hěn máng, bù néng qù.","es":"Hoy estoy muy ocupado, no puedo ir."},{"zh":"我可以坐这儿吗？","pinyin":"Wǒ kěyǐ zuò zhèr ma?","es":"¿Puedo sentarme aquí?"},{"zh":"我想去中国。","pinyin":"Wǒ xiǎng qù Zhōngguó.","es":"Quiero ir a China."},{"zh":"我要喝茶。","pinyin":"Wǒ yào hē chá.","es":"Quiero té."}]'::jsonb, array['会、能', '想、要', '可以']::text[], 4, array['会', '能', '可以', '想', '要']::text[], '[{"wrong":"我可以说汉语。","right":"我会说汉语。","why":"Para una habilidad aprendida se usa 会; 可以 es tener permiso, no saber hacer algo."}]'::jsonb, '[{"hsk_level":2,"code":"2.2.2"}]'::jsonb),
  (1, '2.2.2', '词类', '动词', '离合词', '离合词', 'verbo + (了 / duración) + objeto: 睡了八个小时觉 · 和 + persona + 说话', 'Estas palabras son un verbo y su objeto unidos, y se pueden separar: 了 o la duración van en medio, como en 睡了八个小时觉 «dormí ocho horas». Por eso no admiten otro objeto detrás: «hablar con él» no es «说话他», sino 和他说话. Sin separar funcionan como un verbo sin objeto: 我们几点下课？', '[{"zh":"我昨天睡了八个小时觉。","pinyin":"Wǒ zuótiān shuì le bā gè xiǎoshí jiào.","es":"Ayer dormí ocho horas."},{"zh":"我想和你说话。","pinyin":"Wǒ xiǎng hé nǐ shuōhuà.","es":"Quiero hablar contigo."},{"zh":"他生病了，今天没上班。","pinyin":"Tā shēngbìng le, jīntiān méi shàngbān.","es":"Está enfermo y hoy no ha ido a trabajar."},{"zh":"我们几点下课？","pinyin":"Wǒmen jǐ diǎn xiàkè?","es":"¿A qué hora terminamos la clase?"},{"zh":"明天我去医院看病。","pinyin":"Míngtiān wǒ qù yīyuàn kànbìng.","es":"Mañana voy al médico."}]'::jsonb, array['看病、睡觉、说话、上课、下课、上班、下班、生病']::text[], 5, array['睡', '说话', '病', '下课']::text[], '[{"wrong":"我想说话你。","right":"我想和你说话。","why":"说话 ya lleva su objeto (话); la persona con la que hablas va delante, con 和."},{"wrong":"我睡觉了八个小时。","right":"我睡了八个小时觉。","why":"La duración va entre el verbo y su objeto interno."}]'::jsonb, '[{"hsk_level":2,"code":"2.2.3"}]'::jsonb),
  (1, '2.3.1', '词类', '代词', '疑问代词', '疑问代词', 'La palabra interrogativa ocupa el lugar de la respuesta', 'En chino la palabra interrogativa no se adelanta: va donde iría la respuesta. 你去哪儿？ → 我去商店. 谁 pregunta por personas, 什么 por cosas, 哪儿 por lugares, 几 por cantidades pequeñas (con clasificador) y 多少 por cualquier cantidad. 怎么 pregunta cómo se hace algo y 怎么样, qué tal está. Con todas ellas la frase ya es pregunta y no lleva 吗.', '[{"zh":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","es":"¿Cómo te llamas?"},{"zh":"他是谁？","pinyin":"Tā shì shéi?","es":"¿Quién es él?"},{"zh":"你去哪儿？","pinyin":"Nǐ qù nǎr?","es":"¿Adónde vas?"},{"zh":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?","es":"¿Cuántas personas sois en tu familia?"},{"zh":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?","es":"¿Qué tiempo hace hoy?"}]'::jsonb, array['多、多少、几、哪、哪儿、哪里、哪些、什么、谁、怎么、怎么样']::text[], 6, array['什么', '谁', '哪', '几', '怎么']::text[], '[{"wrong":"什么你喜欢？","right":"你喜欢什么？","why":"La palabra interrogativa no se adelanta como en «¿qué te gusta?»: se queda donde iría la respuesta."}]'::jsonb, '[{"hsk_level":2,"code":"2.3.1"}]'::jsonb),
  (1, '2.3.2', '词类', '代词', '人称代词', '人称代词', '我 / 你 / 您 / 他 / 她 / 它 (+ 们) · 大家', 'Los pronombres no cambian según su función: 我 vale para «yo», «me» y «mí». El plural se forma con 们. 您 es el «usted» de cortesía y normalmente no lleva 们. 他, 她 y 它 se pronuncian igual (tā) y solo se distinguen por escrito: hombre, mujer, y animal o cosa. 大家 es «todos»: 大家好.', '[{"zh":"我喜欢他，他也喜欢我。","pinyin":"Wǒ xǐhuan tā, tā yě xǐhuan wǒ.","es":"Él me gusta y yo le gusto a él."},{"zh":"您好，请坐。","pinyin":"Nín hǎo, qǐng zuò.","es":"Buenos días, siéntese, por favor."},{"zh":"这是我的猫，它很小。","pinyin":"Zhè shì wǒ de māo, tā hěn xiǎo.","es":"Este es mi gato; es muy pequeño."},{"zh":"大家好！","pinyin":"Dàjiā hǎo!","es":"¡Hola a todos!"},{"zh":"她们是我的同学。","pinyin":"Tāmen shì wǒ de tóngxué.","es":"Ellas son mis compañeras de clase."}]'::jsonb, array['我、你、您、他、她、我们、你们、他们、她们、它、它们、大家']::text[], 7, array['我', '您', '它', '大家', '她们']::text[], '[{"wrong":"您们好！","right":"大家好！","why":"您 casi nunca lleva 们; para saludar a un grupo se dice 大家好 o 你们好."}]'::jsonb, '[{"hsk_level":2,"code":"2.3.2"}]'::jsonb),
  (1, '2.3.3', '词类', '代词', '指示代词', '指示代词', '这 / 那 (+ número) + clasificador + nombre · 这儿 / 那儿 · 有的 + nombre', '这 señala lo cercano y 那 lo lejano. Delante de un nombre necesitan un clasificador: 这个人, 那本书; en plural, 这些 y 那些. Para lugares se usan 这儿 y 那儿, o 这里 y 那里. 有的 y 有些 significan «algunos» y van delante del sujeto: 有的人喜欢喝茶.', '[{"zh":"这个苹果很好吃。","pinyin":"Zhège píngguǒ hěn hǎochī.","es":"Esta manzana está muy rica."},{"zh":"那本书是我的。","pinyin":"Nà běn shū shì wǒ de.","es":"Ese libro es mío."},{"zh":"你来这儿吧。","pinyin":"Nǐ lái zhèr ba.","es":"Ven aquí."},{"zh":"这些东西都很贵。","pinyin":"Zhèxiē dōngxi dōu hěn guì.","es":"Todas estas cosas son muy caras."},{"zh":"有的人喜欢喝茶，有的人喜欢喝水。","pinyin":"Yǒude rén xǐhuan hē chá, yǒude rén xǐhuan hē shuǐ.","es":"A unos les gusta el té y a otros el agua."}]'::jsonb, array['这、那、这儿、那儿、这里、那里、这些、那些、有的、这个、那个、有些']::text[], 8, array['这', '那', '有的']::text[], '[{"wrong":"我喜欢这书。","right":"我喜欢这本书。","why":"这 y 那 necesitan un clasificador antes del nombre."}]'::jsonb, '[{"hsk_level":2,"code":"2.3.3"}]'::jsonb),
  (1, '2.4', '词类', '数词', null, '数词', 'número + clasificador + nombre · 两 + clasificador · 二 al contar', 'Los números se forman sumando: 十二 es diez y dos, 二十 son dos dieces, y 零 marca el hueco: 一百零五 = 105. Delante de un clasificador, «dos» se dice 两 (两个人); al contar, en las cifras y en los ordinales se usa 二 (十二, 第二). 半 es «medio»: 半个小时.', '[{"zh":"我有两个孩子。","pinyin":"Wǒ yǒu liǎng gè háizi.","es":"Tengo dos hijos."},{"zh":"今天是十二号。","pinyin":"Jīntiān shì shí’èr hào.","es":"Hoy es día doce."},{"zh":"这个手机两千块。","pinyin":"Zhège shǒujī liǎngqiān kuài.","es":"Este móvil cuesta dos mil yuanes."},{"zh":"我睡了半个小时。","pinyin":"Wǒ shuì le bàn gè xiǎoshí.","es":"Dormí media hora."},{"zh":"这本书一百零五块。","pinyin":"Zhè běn shū yìbǎi líng wǔ kuài.","es":"Este libro cuesta ciento cinco yuanes."}]'::jsonb, array['一、二/两、三、四、五、六、七、八、九、零、十、百、半、千']::text[], 9, array['两', '十二', '千', '半', '零']::text[], '[{"wrong":"我有二个孩子。","right":"我有两个孩子。","why":"Delante de un clasificador «dos» se dice 两, no 二."}]'::jsonb, '[{"hsk_level":2,"code":"2.5"}]'::jsonb),
  (1, '2.5.1', '词类', '量词', '名量词', '名量词', 'número / 这 / 那 + clasificador + nombre', 'En chino un número no va directamente delante de un nombre: entre los dos hay un clasificador. 个 es el más general; 本 es para libros, 件 para ropa y asuntos, 家 para comercios, 口 para los miembros de una familia, 只 para animales pequeños y 块 o 元 para el dinero. 杯 se toma de «vaso»: 一杯茶.', '[{"zh":"我买了两本书。","pinyin":"Wǒ mǎi le liǎng běn shū.","es":"Compré dos libros."},{"zh":"他家有四口人。","pinyin":"Tā jiā yǒu sì kǒu rén.","es":"En su familia son cuatro."},{"zh":"这件衣服很漂亮。","pinyin":"Zhè jiàn yīfu hěn piàoliang.","es":"Esta ropa es muy bonita."},{"zh":"我想喝一杯水。","pinyin":"Wǒ xiǎng hē yì bēi shuǐ.","es":"Quiero beber un vaso de agua."},{"zh":"那只猫很小。","pinyin":"Nà zhī māo hěn xiǎo.","es":"Ese gato es muy pequeño."}]'::jsonb, array['（1）专用名量词：本、个、家、口、块、件、只、元', '（2）借用名量词：杯']::text[], 10, array['本', '口', '件', '杯', '只']::text[], '[{"wrong":"我有两书。","right":"我有两本书。","why":"Entre el número y el nombre siempre va un clasificador."}]'::jsonb, '[{"hsk_level":2,"code":"2.6.1"}]'::jsonb),
  (1, '2.5.2', '词类', '量词', '时量词', '时量词', 'número + 年 / 天 / 岁 / 点 / 分 · 月 + 号 / 日', 'Estas palabras miden el tiempo y van directamente detrás del número, sin otro clasificador: 三天, 两年, 五岁, 八点十分. 号 y 日 dan el día del mes (二十号; 日 es más escrito). 点 es la hora del reloj y 分, los minutos. Las horas de duración llevan 个 (三个小时), pero 天 y 年 no: 三天, nunca «三个天».', '[{"zh":"我在中国住了三天。","pinyin":"Wǒ zài Zhōngguó zhù le sān tiān.","es":"Estuve tres días en China."},{"zh":"他今年五岁。","pinyin":"Tā jīnnián wǔ suì.","es":"Este año cumple cinco años."},{"zh":"现在八点十分。","pinyin":"Xiànzài bā diǎn shí fēn.","es":"Son las ocho y diez."},{"zh":"今天是十二月二十号。","pinyin":"Jīntiān shì shí’èr yuè èrshí hào.","es":"Hoy es veinte de diciembre."},{"zh":"我学了两年汉语。","pinyin":"Wǒ xué le liǎng nián Hànyǔ.","es":"Estudié chino dos años."}]'::jsonb, array['日、号、岁、点、分、年、天']::text[], 11, array['天', '岁', '点', '号', '年']::text[], '[{"wrong":"我住了三个天。","right":"我住了三天。","why":"天 y 年 ya hacen de clasificador: van directamente detrás del número, sin 个."}]'::jsonb, '[{"hsk_level":1,"code":"7.2"},{"hsk_level":2,"code":"5.4.4"}]'::jsonb),
  (1, '2.6.1', '词类', '副词', '程度副词', '程度副词', '很 / 非常 / 真 / 有点儿 + adjetivo · 太 + adjetivo + 了', 'Van delante del adjetivo. 很 es el más neutro y a veces apenas intensifica: 今天很冷. 非常 es «muchísimo» y 真 expresa sorpresa o admiración: 真漂亮！ 太…了 es «demasiado» o, con algo bueno, «¡qué…!». 有点儿 «un poco» se usa para lo que molesta o no gusta: 有点儿贵.', '[{"zh":"今天很冷。","pinyin":"Jīntiān hěn lěng.","es":"Hoy hace frío."},{"zh":"这个菜非常好吃。","pinyin":"Zhège cài fēicháng hǎochī.","es":"Este plato está riquísimo."},{"zh":"你的衣服真漂亮！","pinyin":"Nǐ de yīfu zhēn piàoliang!","es":"¡Qué bonita es tu ropa!"},{"zh":"这个太贵了。","pinyin":"Zhège tài guì le.","es":"Esto es demasiado caro."},{"zh":"这个有点儿贵。","pinyin":"Zhège yǒudiǎnr guì.","es":"Esto es un poco caro."}]'::jsonb, array['非常、很、太、真、有（一）点儿']::text[], 12, array['很', '非常', '真', '太', '有点儿']::text[], '[{"wrong":"这个有点儿便宜。","right":"这个很便宜。","why":"有点儿 acompaña a lo que molesta o no gusta (有点儿贵, 有点儿冷); para algo positivo se usa 很 o 非常."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.1"}]'::jsonb),
  (1, '2.6.2', '词类', '副词', '范围副词', '范围副词', 'Sujeto (plural) + 都 + verbo', '都 significa «todos» o «los dos» y va detrás del sujeto, delante del verbo: 我们都是学生. Abarca lo que está delante de él, así que el grupo se coloca antes: 这些书我都喜欢. Con negación, 都不 es «ninguno» y 不都, «no todos».', '[{"zh":"我们都是学生。","pinyin":"Wǒmen dōu shì xuésheng.","es":"Todos somos estudiantes."},{"zh":"爸爸和妈妈都在家。","pinyin":"Bàba hé māma dōu zài jiā.","es":"Papá y mamá están los dos en casa."},{"zh":"这些书我都喜欢。","pinyin":"Zhèxiē shū wǒ dōu xǐhuan.","es":"Me gustan todos estos libros."},{"zh":"他们都不喝茶。","pinyin":"Tāmen dōu bù hē chá.","es":"Ninguno de ellos toma té."}]'::jsonb, array['都1']::text[], 13, array['都']::text[], '[{"wrong":"都我们是学生。","right":"我们都是学生。","why":"都 va detrás del sujeto, nunca al principio como «todos nosotros»."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.7"}]'::jsonb),
  (1, '2.6.3', '词类', '副词', '时间副词', '时间副词', 'Sujeto + (正)在 + verbo (+ 呢)', '在 y 正在 delante de un verbo indican que la acción está en curso, como «estar + -ando»: 我在吃饭. 正在 subraya que es justo ahora. A menudo se añade 呢 al final. No se usan con verbos que no son acciones, como 是, 有 o 喜欢.', '[{"zh":"我在吃饭。","pinyin":"Wǒ zài chī fàn.","es":"Estoy comiendo."},{"zh":"妈妈正在做饭呢。","pinyin":"Māma zhèngzài zuò fàn ne.","es":"Mamá está cocinando ahora mismo."},{"zh":"你在做什么？","pinyin":"Nǐ zài zuò shénme?","es":"¿Qué estás haciendo?"},{"zh":"他们正在上课。","pinyin":"Tāmen zhèngzài shàngkè.","es":"Están en clase."}]'::jsonb, array['在、正在']::text[], 14, array['在']::text[], '[{"wrong":"我在喜欢他。","right":"我喜欢他。","why":"在 marca acciones en curso; con verbos de estado como 喜欢 o 是 no se usa."}]'::jsonb, '[{"hsk_level":1,"code":"6.1.3"}]'::jsonb),
  (1, '2.6.4', '词类', '副词', '频率副词', '频率副词', '再 + verbo', '再 significa «otra vez» o «más» para algo que todavía no ha pasado: 明天再来吧 «vuelve mañana». Va delante del verbo. Para una repetición que ya ocurrió se usa 又, no 再. Aparece en peticiones (请再说一下) y en la despedida 再见.', '[{"zh":"请你再说一下。","pinyin":"Qǐng nǐ zài shuō yíxià.","es":"Repítelo, por favor."},{"zh":"明天再来吧。","pinyin":"Míngtiān zài lái ba.","es":"Vuelve mañana."},{"zh":"我想再喝一点儿茶。","pinyin":"Wǒ xiǎng zài hē yìdiǎnr chá.","es":"Quiero tomar un poco más de té."},{"zh":"再见！","pinyin":"Zàijiàn!","es":"¡Hasta luego!"}]'::jsonb, array['再1']::text[], 15, array['再']::text[], '[{"wrong":"他昨天再来了。","right":"他昨天又来了。","why":"再 mira hacia lo que no ha pasado; para «volvió a venir» se usa 又."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.6"}]'::jsonb),
  (1, '2.6.5', '词类', '副词', '关联副词', '关联副词', 'Sujeto + 也 + verbo · Sujeto + 还 + verbo', '也 significa «también» y va detrás del sujeto, delante del verbo: 我也是学生. 还 añade algo más a lo dicho, «además»: 我买了苹果，还买了牛奶. Ninguno va delante del sujeto como «también yo», ni al final como «yo también».', '[{"zh":"我也是学生。","pinyin":"Wǒ yě shì xuésheng.","es":"Yo también soy estudiante."},{"zh":"他喜欢喝茶，我也喜欢。","pinyin":"Tā xǐhuan hē chá, wǒ yě xǐhuan.","es":"A él le gusta el té, y a mí también."},{"zh":"我买了苹果，还买了牛奶。","pinyin":"Wǒ mǎi le píngguǒ, hái mǎi le niúnǎi.","es":"Compré manzanas y además leche."},{"zh":"你还想吃什么？","pinyin":"Nǐ hái xiǎng chī shénme?","es":"¿Qué más quieres comer?"}]'::jsonb, array['还1、也']::text[], 16, array['也', '还']::text[], '[{"wrong":"也我是学生。","right":"我也是学生。","why":"也 va detrás del sujeto, no delante como «también yo»."}]'::jsonb, '[{"hsk_level":1,"code":"5.4.2"}]'::jsonb),
  (1, '2.6.6', '词类', '副词', '否定副词', '否定副词', '不 + verbo/adjetivo · 没(有) + verbo · 不要 + verbo', 'Hay tres negaciones y no son intercambiables. 不 niega lo habitual, lo que uno quiere hacer y los adjetivos: 我不喝茶 («no bebo té»). 没 o 没有 niega que algo haya pasado o que se tenga: 我没去 («no fui»), 我没有钱. El verbo 有 nunca se niega con 不. 不要 delante de un verbo pide a alguien que no haga algo: 不要说话.', '[{"zh":"她不是老师。","pinyin":"Tā bú shì lǎoshī.","es":"Ella no es profesora."},{"zh":"我不喝茶。","pinyin":"Wǒ bù hē chá.","es":"No bebo té."},{"zh":"我昨天没去学校。","pinyin":"Wǒ zuótiān méi qù xuéxiào.","es":"Ayer no fui al colegio."},{"zh":"我没有钱。","pinyin":"Wǒ méiyǒu qián.","es":"No tengo dinero."},{"zh":"不要说话。","pinyin":"Bú yào shuōhuà.","es":"No hables."}]'::jsonb, array['不、没（有）、不要']::text[], 17, array['不', '没', '不要']::text[], '[{"wrong":"我不有钱。","right":"我没有钱。","why":"有 solo se niega con 没: «不有» no existe."},{"wrong":"我昨天不去学校。","right":"我昨天没去学校。","why":"Para negar algo que no ocurrió se usa 没. En español «no» sirve para todo; en chino hay que elegir según si hablas de un hecho pasado o de un hábito."}]'::jsonb, '[]'::jsonb),
  (1, '2.7.1', '词类', '介词', '引出时间、处所', '引出时间、处所', 'Sujeto + 在 + lugar + verbo', '在 + lugar va delante del verbo e indica dónde ocurre la acción: 我在学校学习. Es el orden contrario al español «estudio en el colegio». Si el lugar es una cosa, necesita una palabra de posición: 在桌子上. Sin otro verbo, 在 significa «estar en»: 他在家.', '[{"zh":"我在学校学习汉语。","pinyin":"Wǒ zài xuéxiào xuéxí Hànyǔ.","es":"Estudio chino en el colegio."},{"zh":"他在商店买东西。","pinyin":"Tā zài shāngdiàn mǎi dōngxi.","es":"Está comprando en la tienda."},{"zh":"我们在家吃饭。","pinyin":"Wǒmen zài jiā chī fàn.","es":"Comemos en casa."},{"zh":"妈妈不在家。","pinyin":"Māma bú zài jiā.","es":"Mamá no está en casa."}]'::jsonb, array['在']::text[], 18, array['在']::text[], '[{"wrong":"我学习汉语在学校。","right":"我在学校学习汉语。","why":"El lugar con 在 va delante del verbo, no al final como en español."}]'::jsonb, '[{"hsk_level":1,"code":"2.1.1"}]'::jsonb),
  (1, '2.7.2', '词类', '介词', '引出对象', '引出对象', '和 + persona + verbo · 对 + persona / cosa + adjetivo / verbo', '和 presenta a la persona con quien se hace algo: 我和朋友去看电影. 对 presenta hacia quién va una actitud o una acción, «con» o «a»: 老师对我们很好 «el profesor es muy bueno con nosotros». Los dos grupos van delante del verbo o del adjetivo, no detrás.', '[{"zh":"我和妈妈去商店。","pinyin":"Wǒ hé māma qù shāngdiàn.","es":"Voy a la tienda con mamá."},{"zh":"你想和我说话吗？","pinyin":"Nǐ xiǎng hé wǒ shuōhuà ma?","es":"¿Quieres hablar conmigo?"},{"zh":"老师对我们很好。","pinyin":"Lǎoshī duì wǒmen hěn hǎo.","es":"El profesor es muy bueno con nosotros."},{"zh":"他对我说：“谢谢。”","pinyin":"Tā duì wǒ shuō: “Xièxie.”","es":"Me dijo: «Gracias»."}]'::jsonb, array['和1、对']::text[], 19, array['和', '对']::text[], '[{"wrong":"老师很好对我们。","right":"老师对我们很好。","why":"对 y la persona van delante del adjetivo, no detrás como en «es bueno con nosotros»."}]'::jsonb, '[{"hsk_level":2,"code":"2.8.3"}]'::jsonb),
  (1, '2.8.1', '词类', '连词', '连接词语或短语', '连接词语或短语', 'nombre + 和 + nombre', '和 une nombres o pronombres: 爸爸和妈妈, 苹果和面包. No une verbos ni frases, como sí hace «y» en español: «como y bebo» no lleva 和. En una lista de tres o más, 和 va solo antes del último y los demás se separan con 、.', '[{"zh":"我和他是同学。","pinyin":"Wǒ hé tā shì tóngxué.","es":"Él y yo somos compañeros de clase."},{"zh":"我买了苹果和面包。","pinyin":"Wǒ mǎi le píngguǒ hé miànbāo.","es":"Compré manzanas y pan."},{"zh":"我爸爸、妈妈和姐姐都在家。","pinyin":"Wǒ bàba, māma hé jiějie dōu zài jiā.","es":"Mi padre, mi madre y mi hermana están en casa."}]'::jsonb, array['和2']::text[], 20, array['和']::text[], '[{"wrong":"我吃饭和喝水。","right":"我吃饭，也喝水。","why":"和 solo une nombres; para unir dos acciones no sirve."}]'::jsonb, '[{"hsk_level":2,"code":"2.9.1"}]'::jsonb),
  (1, '2.9.1', '词类', '助词', '结构助词', '结构助词', 'poseedor / descripción + 的 + nombre', '的 une lo que posee o describe con el nombre, que va al final: 我的书 «mi libro», 很漂亮的衣服. El poseedor va delante, al revés que en «el libro del profesor» → 老师的书. Con familiares y relaciones cercanas se suele omitir: 我妈妈, 我们学校.', '[{"zh":"这是我的书。","pinyin":"Zhè shì wǒ de shū.","es":"Este es mi libro."},{"zh":"这是老师的电脑。","pinyin":"Zhè shì lǎoshī de diànnǎo.","es":"Este es el ordenador del profesor."},{"zh":"她买了一件很漂亮的衣服。","pinyin":"Tā mǎi le yí jiàn hěn piàoliang de yīfu.","es":"Se compró una ropa muy bonita."},{"zh":"你的手机在这儿。","pinyin":"Nǐ de shǒujī zài zhèr.","es":"Tu móvil está aquí."}]'::jsonb, array['的1']::text[], 21, array['的']::text[], '[{"wrong":"这是书的老师。","right":"这是老师的书。","why":"El poseedor va delante de 的: «el libro del profesor» es 老师的书, al revés que en español."}]'::jsonb, '[{"hsk_level":2,"code":"2.10.1"}]'::jsonb),
  (1, '2.9.2', '词类', '助词', '动态助词', '动态助词', 'verbo + 了 (+ número + clasificador + objeto)', '了 detrás del verbo indica que la acción se ha completado: 我买了两本书. Suele pedir un objeto con número o con más información; «我买了书» a secas suena incompleto. Se niega con 没 y entonces 了 desaparece: 我没买书. No equivale al pasado español: una costumbre del pasado no lleva 了.', '[{"zh":"我买了两本书。","pinyin":"Wǒ mǎi le liǎng běn shū.","es":"Compré dos libros."},{"zh":"他喝了很多水。","pinyin":"Tā hē le hěn duō shuǐ.","es":"Bebió mucha agua."},{"zh":"昨天我看了一个电影。","pinyin":"Zuótiān wǒ kàn le yí gè diànyǐng.","es":"Ayer vi una película."},{"zh":"我昨天没去学校，去了医院。","pinyin":"Wǒ zuótiān méi qù xuéxiào, qù le yīyuàn.","es":"Ayer no fui al colegio; fui al hospital."}]'::jsonb, array['了1']::text[], 22, array['了']::text[], '[{"wrong":"我没买了书。","right":"我没买书。","why":"Con 没 desaparece 了: la negación ya dice que la acción no se hizo."}]'::jsonb, '[{"hsk_level":1,"code":"6.1.1"}]'::jsonb),
  (1, '2.9.3', '词类', '助词', '语气助词', '语气助词', 'frase + 吗 / 吧 / 呢 / 了', 'Estas partículas van al final de la frase y cambian su intención sin tocar el orden de las palabras. 吗 convierte una afirmación en una pregunta de sí o no. 吧 propone algo o pide confirmación. 呢 detrás de un nombre pregunta «¿y…?» (你呢？), y con 在 subraya que algo está pasando ahora. 了 al final indica que la situación ha cambiado: 下雨了 («ya llueve»). Si la frase ya tiene una palabra interrogativa (什么, 哪儿, 谁), no se añade 吗.', '[{"zh":"你是学生吗？","pinyin":"Nǐ shì xuésheng ma?","es":"¿Eres estudiante?"},{"zh":"我们去吃饭吧。","pinyin":"Wǒmen qù chīfàn ba.","es":"Vamos a comer."},{"zh":"我很好，你呢？","pinyin":"Wǒ hěn hǎo, nǐ ne?","es":"Yo estoy bien, ¿y tú?"},{"zh":"他在看书呢。","pinyin":"Tā zài kàn shū ne.","es":"Está leyendo."},{"zh":"下雨了。","pinyin":"Xià yǔ le.","es":"Ya está lloviendo."}]'::jsonb, array['吧1、了2 、吗、呢1、呢2、呢3']::text[], 23, array['吗', '吧', '呢', '了']::text[], '[{"wrong":"你去哪儿吗？","right":"你去哪儿？","why":"Con una palabra interrogativa como 哪儿 la frase ya es una pregunta; añadir 吗 sobra."}]'::jsonb, '[]'::jsonb),
  (1, '2.10', '词类', '叹词', null, '叹词', '喂，… (al teléfono o para llamar la atención)', '喂 se usa sobre todo al contestar o empezar una llamada, como «¿diga?» o «¿sí?»; ahí suele pronunciarse wéi. También sirve para llamar la atención de alguien (wèi), pero cara a cara y con desconocidos suena brusco. Va al principio de la frase, separado por una coma.', '[{"zh":"喂，你好！","pinyin":"Wéi, nǐ hǎo!","es":"¿Diga? ¡Hola!"},{"zh":"喂，请问你是谁？","pinyin":"Wéi, qǐngwèn nǐ shì shéi?","es":"¿Sí? ¿Quién es, por favor?"},{"zh":"喂，你在哪儿？","pinyin":"Wéi, nǐ zài nǎr?","es":"Oye, ¿dónde estás?"}]'::jsonb, array['喂']::text[], 24, array['喂']::text[], '[{"wrong":"喂，请问医院在哪儿？（a un desconocido en la calle）","right":"你好，请问医院在哪儿？","why":"Cara a cara con un desconocido 喂 resulta brusco; se empieza con 你好 o 请问."}]'::jsonb, '[{"hsk_level":1,"code":"2.9.3"}]'::jsonb),
  (1, '3.1.1', '短语', '结构类型', '基本结构类型', '基本结构类型', 'A + 和 + B · modificador + núcleo · verbo + objeto · sujeto + predicado', 'Las frases chinas se construyen con cuatro piezas. Unión: dos palabras del mismo tipo, a menudo con 和 (爸爸和妈妈). Modificador y núcleo: lo que describe va siempre delante (中国朋友, 很冷). Verbo y objeto: el objeto va detrás del verbo (喝茶). Sujeto y predicado: quién hace algo o cómo es (我喝茶, 今天很冷). A diferencia del español, el modificador nunca va detrás: «un amigo chino» es 一个中国朋友.', '[{"zh":"爸爸和妈妈都在家。","pinyin":"Bàba hé māma dōu zài jiā.","es":"Papá y mamá están en casa."},{"zh":"他是我的中国朋友。","pinyin":"Tā shì wǒ de Zhōngguó péngyou.","es":"Es mi amigo chino."},{"zh":"我喝茶。","pinyin":"Wǒ hē chá.","es":"Bebo té."},{"zh":"今天很冷。","pinyin":"Jīntiān hěn lěng.","es":"Hoy hace mucho frío."}]'::jsonb, array['（1）联合短语', '（2）偏正短语', '（3）动宾短语', '（4）主谓短语']::text[], 25, array['和', '中国朋友', '喝茶', '很冷']::text[], '[{"wrong":"我有一个朋友中国。","right":"我有一个中国朋友。","why":"El modificador va delante del núcleo: «amigo chino» se dice 中国朋友, al revés que en español."}]'::jsonb, '[]'::jsonb),
  (1, '3.1.2', '短语', '结构类型', '其他结构类型', '其他结构类型', 'número + clasificador · preposición + nombre · nombre + posición', 'Tres grupos pequeños que funcionan como piezas de la frase. El de cantidad une número y clasificador: 三本, 两个. El de preposición une 在, 和 o 对 con un nombre y va delante del verbo: 在学校. El de posición pone 上, 里 o 前 detrás de un nombre: 桌子上. Se combinan entre ellos: 在桌子上 es una preposición con un grupo de posición.', '[{"zh":"我买了三本书。","pinyin":"Wǒ mǎi le sān běn shū.","es":"Compré tres libros."},{"zh":"我在学校学习。","pinyin":"Wǒ zài xuéxiào xuéxí.","es":"Estudio en el colegio."},{"zh":"你的书在桌子上。","pinyin":"Nǐ de shū zài zhuōzi shang.","es":"Tu libro está encima de la mesa."},{"zh":"我有两个中国朋友。","pinyin":"Wǒ yǒu liǎng gè Zhōngguó péngyou.","es":"Tengo dos amigos chinos."}]'::jsonb, array['（1）数量短语', '（2）介宾短语', '（3）方位短语']::text[], 26, array['三本', '在学校', '桌子上', '两个']::text[], '[{"wrong":"你的书在桌子。","right":"你的书在桌子上。","why":"Una cosa no es un lugar por sí misma: hace falta una palabra de posición, 桌子上."}]'::jsonb, '[{"hsk_level":1,"code":"3.1.1"},{"hsk_level":2,"code":"3.1.2"}]'::jsonb),
  (1, '4.1', '句子成分', '主语', null, '主语', 'Sujeto (nombre / pronombre / grupo nominal) + predicado', 'El sujeto va al principio, delante del predicado, y puede ser un nombre (老师), un pronombre (他) o un grupo nominal (我的朋友). El verbo no cambia con el sujeto: 我是, 他是, 他们是. A diferencia del español, el sujeto no puede ir detrás del verbo, como en «le gusta el té a mi amigo». Igual que en español, se omite cuando ya se sabe de quién se habla.', '[{"zh":"老师来了。","pinyin":"Lǎoshī lái le.","es":"Ha llegado el profesor."},{"zh":"他是我的同学。","pinyin":"Tā shì wǒ de tóngxué.","es":"Es mi compañero de clase."},{"zh":"我的朋友喜欢喝茶。","pinyin":"Wǒ de péngyou xǐhuan hē chá.","es":"A mi amigo le gusta el té."},{"zh":"这个苹果很好吃。","pinyin":"Zhège píngguǒ hěn hǎochī.","es":"Esta manzana está muy rica."}]'::jsonb, array['名词、代词或名词性短语作主语']::text[], 27, array['老师', '他', '我的朋友', '这个苹果']::text[], '[{"wrong":"喜欢喝茶我的朋友。","right":"我的朋友喜欢喝茶。","why":"El sujeto va delante del verbo; no se puede posponer como en «le gusta el té a mi amigo»."}]'::jsonb, '[{"hsk_level":1,"code":"5.1.1"}]'::jsonb),
  (1, '4.2', '句子成分', '谓语', null, '谓语', 'Sujeto + verbo / adjetivo / nombre (fecha, edad, precio)', 'El predicado dice qué hace o cómo es el sujeto. Puede ser un verbo (他喝茶), un adjetivo (今天很冷) o, con fechas, edades y precios, un nombre o un número (今天星期一, 她八岁). Con adjetivos no se usa 是: «hoy hace frío» es 今天很冷. El verbo no cambia de forma ni con la persona ni con el tiempo.', '[{"zh":"他喝茶。","pinyin":"Tā hē chá.","es":"Él toma té."},{"zh":"今天很冷。","pinyin":"Jīntiān hěn lěng.","es":"Hoy hace frío."},{"zh":"今天星期一。","pinyin":"Jīntiān xīngqīyī.","es":"Hoy es lunes."},{"zh":"我女儿八岁。","pinyin":"Wǒ nǚ’ér bā suì.","es":"Mi hija tiene ocho años."}]'::jsonb, array['名词、代词、数词或数量短语作谓语', '动词或动词性短语、形容词或形容词性短语作谓语']::text[], 28, array['喝', '冷', '星期', '岁']::text[], '[{"wrong":"今天是冷。","right":"今天很冷。","why":"Un adjetivo hace de predicado sin 是; se le pone delante un adverbio como 很."}]'::jsonb, '[{"hsk_level":2,"code":"5.2"},{"hsk_level":2,"code":"3.2.2"}]'::jsonb),
  (1, '4.3', '句子成分', '宾语', null, '宾语', 'Sujeto + verbo + objeto', 'El objeto va detrás del verbo: 我喝牛奶, 我认识他. Puede ser un nombre, un pronombre o un grupo nominal (一个新手机). Los pronombres de objeto no cambian de forma ni se adelantan: «te quiero» es 我爱你, nunca «我你爱».', '[{"zh":"我喜欢喝牛奶。","pinyin":"Wǒ xǐhuan hē niúnǎi.","es":"Me gusta la leche."},{"zh":"我认识他。","pinyin":"Wǒ rènshi tā.","es":"Lo conozco."},{"zh":"他爱他的妈妈。","pinyin":"Tā ài tā de māma.","es":"Quiere mucho a su madre."},{"zh":"我想买一个新手机。","pinyin":"Wǒ xiǎng mǎi yí gè xīn shǒujī.","es":"Quiero comprarme un móvil nuevo."}]'::jsonb, array['名词、代词或名词性短语作宾语']::text[], 29, array['牛奶', '他', '妈妈', '手机']::text[], '[{"wrong":"我你爱。","right":"我爱你。","why":"El pronombre objeto va detrás del verbo, no delante como en «te quiero»."}]'::jsonb, '[{"hsk_level":1,"code":"4.1"},{"hsk_level":1,"code":"3.1.1"}]'::jsonb),
  (1, '4.4', '句子成分', '定语', null, '定语', 'modificador (+ 的) + nombre', 'Todo lo que describe a un nombre va delante de él. Un poseedor lleva 的 (哥哥的电脑); un adjetivo de una sílaba suele ir sin 的 (新书, 大苹果), y un grupo como 很好 sí lo lleva (很好的医生). La cantidad, con número y clasificador, va antes de todo: 两本新书.', '[{"zh":"这是哥哥的电脑。","pinyin":"Zhè shì gēge de diànnǎo.","es":"Este es el ordenador de mi hermano mayor."},{"zh":"我买了一个大苹果。","pinyin":"Wǒ mǎi le yí gè dà píngguǒ.","es":"Compré una manzana grande."},{"zh":"她是一个很好的医生。","pinyin":"Tā shì yí gè hěn hǎo de yīshēng.","es":"Es una médica muy buena."},{"zh":"我有两本新书。","pinyin":"Wǒ yǒu liǎng běn xīn shū.","es":"Tengo dos libros nuevos."}]'::jsonb, array['名词性词语、形容词性短语、数量短语作定语']::text[], 30, array['的', '大苹果', '新书']::text[], '[{"wrong":"我买了一个苹果大。","right":"我买了一个大苹果。","why":"El adjetivo va delante del nombre, no detrás como en «una manzana grande»."}]'::jsonb, '[{"hsk_level":2,"code":"3.2.1"},{"hsk_level":2,"code":"5.3"}]'::jsonb),
  (1, '4.5', '句子成分', '状语', null, '状语', 'Sujeto + (tiempo) + (adverbio) + (在 + lugar) + verbo', 'Lo que dice cuándo, dónde o cómo pasa algo va delante del verbo, nunca detrás. El tiempo va delante o detrás del sujeto (我明天去, 明天我去) y el lugar con 在 justo antes del verbo: 我明天在家休息. Los adverbios como 很, 都 o 也 también van delante. En español «mañana» o «en casa» pueden ir al final; en chino no.', '[{"zh":"我明天在家休息。","pinyin":"Wǒ míngtiān zài jiā xiūxi.","es":"Mañana descanso en casa."},{"zh":"他早上七点起床。","pinyin":"Tā zǎoshang qī diǎn qǐchuáng.","es":"Se levanta a las siete de la mañana."},{"zh":"我们中午在饭店吃饭。","pinyin":"Wǒmen zhōngwǔ zài fàndiàn chī fàn.","es":"Al mediodía comemos en un restaurante."},{"zh":"你明天来吗？","pinyin":"Nǐ míngtiān lái ma?","es":"¿Vienes mañana?"}]'::jsonb, array['副词、形容词作状语表示时间、处所的词语作状语']::text[], 31, array['明天', '早上', '中午']::text[], '[{"wrong":"我休息在家明天。","right":"我明天在家休息。","why":"El tiempo y el lugar van delante del verbo, no al final como en «descanso en casa mañana»."}]'::jsonb, '[{"hsk_level":1,"code":"2.7.1"}]'::jsonb),
  (1, '4.6.1', '句子成分', '补语', '数量补语1', '数量补语1', 'verbo + 一下 (+ objeto)', '一下 detrás de un verbo indica que la acción es breve o se hace sin esfuerzo, y suaviza las peticiones: 你看一下 «échale un vistazo», 我们休息一下吧. Va pegado al verbo y antes del objeto: 看一下这本书. Su efecto se parece al de repetir el verbo (看看).', '[{"zh":"你看一下这本书。","pinyin":"Nǐ kàn yíxià zhè běn shū.","es":"Échale un vistazo a este libro."},{"zh":"我们休息一下吧。","pinyin":"Wǒmen xiūxi yíxià ba.","es":"Descansemos un momento."},{"zh":"请你说一下你的名字。","pinyin":"Qǐng nǐ shuō yíxià nǐ de míngzi.","es":"Dime tu nombre, por favor."},{"zh":"我想问一下，医院在哪儿？","pinyin":"Wǒ xiǎng wèn yíxià, yīyuàn zài nǎr?","es":"Una pregunta: ¿dónde está el hospital?"}]'::jsonb, array['动词+动量补语']::text[], 32, array['一下']::text[], '[{"wrong":"你看这本书一下。","right":"你看一下这本书。","why":"一下 va pegado al verbo, antes del objeto."}]'::jsonb, '[{"hsk_level":2,"code":"2.6.2"},{"hsk_level":2,"code":"2.2.1"}]'::jsonb),
  (1, '5.1.1', '句子的类型', '句型', '单句', '单句', 'S + verbo · S + 很 + adjetivo · S + nombre / número · frase sin sujeto', 'Hay cuatro tipos básicos de frase simple. Con verbo: 我学习汉语. Con adjetivo, sin 是 y casi siempre con 很: 天气很好. Con un nombre o un número como predicado, para fechas, edades o precios: 今天星期六. Y sin sujeto, para el tiempo atmosférico o avisos breves: 下雨了, 上课了.', '[{"zh":"我学习汉语。","pinyin":"Wǒ xuéxí Hànyǔ.","es":"Estudio chino."},{"zh":"天气很好。","pinyin":"Tiānqì hěn hǎo.","es":"Hace buen tiempo."},{"zh":"今天星期六。","pinyin":"Jīntiān xīngqīliù.","es":"Hoy es sábado."},{"zh":"下雨了。","pinyin":"Xià yǔ le.","es":"Está lloviendo."},{"zh":"上课了！","pinyin":"Shàngkè le!","es":"¡Empieza la clase!"}]'::jsonb, array['主谓句1：动词谓语句', '主谓句2：形容词谓语句', '主谓句3：名词谓语句', '非主谓句']::text[], 33, array['学习', '很好', '星期', '下雨', '上课']::text[], '[{"wrong":"天气是好。","right":"天气很好。","why":"En una frase con adjetivo no se usa 是: se pone 很 u otro adverbio."}]'::jsonb, '[{"hsk_level":1,"code":"4.2"}]'::jsonb),
  (1, '5.2.1', '句子的类型', '句类', '陈述句', '陈述句', 'Sujeto + (tiempo / lugar) + predicado。 · Sujeto + 不 / 没 + predicado。', 'Una frase declarativa informa de algo y termina en 。. Su orden básico es sujeto, tiempo y lugar, verbo y objeto: 我今天在家看书. Para negarla se pone 不 o 没 justo delante del verbo o del adjetivo, sin tocar nada más. A diferencia del español, la entonación sola no la convierte en pregunta: hace falta 吗 u otra estructura.', '[{"zh":"我今天在家看书。","pinyin":"Wǒ jīntiān zài jiā kàn shū.","es":"Hoy leo en casa."},{"zh":"他是医生。","pinyin":"Tā shì yīshēng.","es":"Es médico."},{"zh":"我不喝牛奶。","pinyin":"Wǒ bù hē niúnǎi.","es":"No tomo leche."},{"zh":"昨天下雨了。","pinyin":"Zuótiān xià yǔ le.","es":"Ayer llovió."}]'::jsonb, null, 34, array['。']::text[], '[{"wrong":"你是学生。（preguntando）","right":"你是学生吗？","why":"La entonación sola no convierte una afirmación en pregunta; hace falta 吗 u otra forma interrogativa."}]'::jsonb, '[{"hsk_level":1,"code":"5.2.2"}]'::jsonb),
  (1, '5.2.2', '句子的类型', '句类', '疑问句', '疑问句', '… 吗？ · palabra interrogativa en su sitio · verbo / adjetivo + 不 / 没 + verbo / adjetivo？', 'Hay tres maneras de preguntar. Con 吗 al final se pregunta sí o no: 你是学生吗？ Con una palabra interrogativa (什么, 谁, 哪儿) en el sitio de la respuesta: 你去哪儿？ Y repitiendo el verbo o el adjetivo con 不 en medio: 你去不去？, 好吃不好吃？; con 有, la forma es 有没有. En las dos últimas no se añade 吗.', '[{"zh":"你是学生吗？","pinyin":"Nǐ shì xuésheng ma?","es":"¿Eres estudiante?"},{"zh":"你去哪儿？","pinyin":"Nǐ qù nǎr?","es":"¿Adónde vas?"},{"zh":"你去不去？","pinyin":"Nǐ qù bu qù?","es":"¿Vas o no?"},{"zh":"这个菜好吃不好吃？","pinyin":"Zhège cài hǎochī bu hǎochī?","es":"¿Está rico este plato?"},{"zh":"你有没有中文书？","pinyin":"Nǐ yǒu méiyǒu Zhōngwén shū?","es":"¿Tienes libros en chino?"}]'::jsonb, array['（1）是非问句', '（2）特指问句', '（3）正反问句']::text[], 35, array['吗', '哪', '去不去', '好吃不好吃', '有没有']::text[], '[{"wrong":"你去不去吗？","right":"你去不去？","why":"La forma verbo + 不 + verbo ya es una pregunta; no se le añade 吗."},{"wrong":"你有不有书？","right":"你有没有书？","why":"有 se niega con 没, también en esta forma: 有没有."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.1"},{"hsk_level":1,"code":"2.9.3"}]'::jsonb),
  (1, '5.2.3', '句子的类型', '句类', '祈使句', '祈使句', '(请) + verbo · verbo + 吧 · 不要 + verbo', 'Para pedir u ordenar algo se usa el verbo solo o con 你: el verbo no cambia de forma como el imperativo español. 请 delante lo hace cortés: 请坐 «siéntese». 吧 al final lo convierte en una propuesta suave: 我们去吃饭吧. 不要 delante del verbo prohíbe: 不要说话.', '[{"zh":"请坐。","pinyin":"Qǐng zuò.","es":"Siéntese, por favor."},{"zh":"请喝茶。","pinyin":"Qǐng hē chá.","es":"Tome un té, por favor."},{"zh":"我们去吃饭吧。","pinyin":"Wǒmen qù chī fàn ba.","es":"Vamos a comer."},{"zh":"不要在这儿睡觉。","pinyin":"Búyào zài zhèr shuìjiào.","es":"No duermas aquí."},{"zh":"你来一下。","pinyin":"Nǐ lái yíxià.","es":"Ven un momento."}]'::jsonb, null, 36, array['请', '吧', '不要', '一下']::text[], '[{"wrong":"请你不说话。","right":"请你不要说话。","why":"Para prohibir se usa 不要; con 不 solo se describe lo que alguien hace."}]'::jsonb, '[{"hsk_level":2,"code":"6.2.2"}]'::jsonb),
  (1, '5.2.4', '句子的类型', '句类', '感叹句', '感叹句', '太 + adjetivo + 了！ · 真 + adjetivo！', 'Para exclamar se pone 太…了 o 真 alrededor de un adjetivo: 太好了！ «¡genial!», 真漂亮！ «¡qué bonito!». 太…了 también puede expresar exceso, «demasiado», según el contexto. Se escribe con ！ al final. Equivale al «¡qué…!» español, pero sin ninguna palabra interrogativa.', '[{"zh":"太好了！","pinyin":"Tài hǎo le!","es":"¡Genial!"},{"zh":"你的中文真好！","pinyin":"Nǐ de Zhōngwén zhēn hǎo!","es":"¡Qué bien hablas chino!"},{"zh":"今天太冷了！","pinyin":"Jīntiān tài lěng le!","es":"¡Qué frío hace hoy!"},{"zh":"这个苹果真好吃！","pinyin":"Zhège píngguǒ zhēn hǎochī!","es":"¡Qué rica está esta manzana!"}]'::jsonb, null, 37, array['太', '真']::text[], '[{"wrong":"什么漂亮！","right":"真漂亮！","why":"El «¡qué…!» exclamativo no se traduce con 什么, que solo sirve para preguntar; se usa 真 o 太…了."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.1"}]'::jsonb),
  (1, '5.3.1', '句子的类型', '特殊句型', '“是”字句1', '“是”字句1', 'A + 是 + B · A + 不是 + B', '是 une dos nombres para decir qué o quién es algo: 他是老师, 这是我的书. Solo une nombres o pronombres; delante de un adjetivo no se pone. Se niega siempre con 不是, nunca con 没. A diferencia de «ser», no describe cualidades: «es alto» es 他很高.', '[{"zh":"他是老师。","pinyin":"Tā shì lǎoshī.","es":"Es profesor."},{"zh":"这是我的书。","pinyin":"Zhè shì wǒ de shū.","es":"Este es mi libro."},{"zh":"我不是中国人。","pinyin":"Wǒ bú shì Zhōngguó rén.","es":"No soy chino."},{"zh":"她是我妈妈。","pinyin":"Tā shì wǒ māma.","es":"Es mi madre."}]'::jsonb, array['表示等同或类属']::text[], 38, array['是']::text[], '[{"wrong":"他是很高。","right":"他很高。","why":"是 une nombres; una cualidad con adjetivo se dice sin 是: 他很高."},{"wrong":"我没是老师。","right":"我不是老师。","why":"是 se niega siempre con 不."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.1"}]'::jsonb),
  (1, '5.3.2', '句子的类型', '特殊句型', '“有”字句1', '“有”字句1', 'Sujeto + 有 + objeto · Sujeto + 没有 + objeto', '有 expresa posesión, «tener»: 我有一个哥哥. Se niega siempre con 没有, nunca con 不: 我没有钱. Para preguntar se usa 有…吗 o 有没有. En la negación el objeto no suele llevar número: 我没有哥哥.', '[{"zh":"我有一个哥哥。","pinyin":"Wǒ yǒu yí gè gēge.","es":"Tengo un hermano mayor."},{"zh":"他有很多中文书。","pinyin":"Tā yǒu hěn duō Zhōngwén shū.","es":"Tiene muchos libros en chino."},{"zh":"我没有钱。","pinyin":"Wǒ méiyǒu qián.","es":"No tengo dinero."},{"zh":"你有电脑吗？","pinyin":"Nǐ yǒu diànnǎo ma?","es":"¿Tienes ordenador?"}]'::jsonb, array['表示领有']::text[], 39, array['有']::text[], '[{"wrong":"我不有哥哥。","right":"我没有哥哥。","why":"有 se niega con 没: «不有» no existe."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.2"}]'::jsonb),
  (1, '5.3.3', '句子的类型', '特殊句型', '存现句1', '存现句1', 'lugar + 有 + número + clasificador + nombre · lugar + 是 + nombre', 'Para decir qué hay en un sitio, la frase empieza por el lugar: 桌子上有一本书 «encima de la mesa hay un libro». Con 有 se dice que algo existe allí; con 是 se identifica qué es lo que ocupa ese lugar: 学校前边是一个商店 «lo que hay delante del colegio es una tienda». El lugar va sin 在 delante.', '[{"zh":"桌子上有一本书。","pinyin":"Zhuōzi shang yǒu yì běn shū.","es":"Encima de la mesa hay un libro."},{"zh":"房间里有两个人。","pinyin":"Fángjiān li yǒu liǎng gè rén.","es":"En la habitación hay dos personas."},{"zh":"学校前边是一个商店。","pinyin":"Xuéxiào qiánbian shì yí gè shāngdiàn.","es":"Delante del colegio hay una tienda."},{"zh":"我家后边是医院。","pinyin":"Wǒ jiā hòubian shì yīyuàn.","es":"Detrás de mi casa está el hospital."}]'::jsonb, array['（1）所处+是+名词', '（2）处所+有+数量短语+名词']::text[], 40, array['有', '是']::text[], '[{"wrong":"在桌子上有一本书。","right":"桌子上有一本书。","why":"En estas frases el lugar abre la frase sin 在."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.3"}]'::jsonb),
  (1, '5.3.4', '句子的类型', '特殊句型', '连动句1', '连动句1', 'Sujeto + 去 / 来 + lugar + verbo · Sujeto + 坐 / 开车 + 去 / 来', 'Dos verbos seguidos, sin conjunción, cuentan acciones encadenadas. Si el primero es ir o venir, el segundo dice para qué: 我去超市买水果 «voy al súper a comprar fruta». Si el primero es un medio, como 坐 o 开车, dice cómo se hace el segundo: 我们坐出租车去医院. El orden sigue el de los hechos y no lleva «para» ni «en».', '[{"zh":"我去超市买水果。","pinyin":"Wǒ qù chāoshì mǎi shuǐguǒ.","es":"Voy al súper a comprar fruta."},{"zh":"他来中国学习汉语。","pinyin":"Tā lái Zhōngguó xuéxí Hànyǔ.","es":"Viene a China a estudiar chino."},{"zh":"我们坐出租车去医院。","pinyin":"Wǒmen zuò chūzūchē qù yīyuàn.","es":"Vamos al hospital en taxi."},{"zh":"爸爸开车去公司。","pinyin":"Bàba kāichē qù gōngsī.","es":"Papá va en coche a la empresa."}]'::jsonb, array['（1）前后动作先后发生，后一动作是前一动作的目的', '（2）前一动作是后一动作的方式']::text[], 41, array['买', '学习', '坐', '开车']::text[], '[{"wrong":"我去中国坐飞机。","right":"我坐飞机去中国。","why":"El medio va primero: al revés se entiende que vas a China a coger un avión."}]'::jsonb, '[{"hsk_level":2,"code":"3.1.2"}]'::jsonb),
  (1, '5.3.5', '句子的类型', '特殊句型', '双宾语句1', '双宾语句1', 'Sujeto + 给 / 问 + persona + cosa', 'Algunos verbos llevan dos objetos seguidos: primero la persona y después la cosa, sin preposición: 妈妈给我一个苹果 «mamá me da una manzana», 我问老师一个问题. El orden es fijo y la persona no lleva delante nada parecido a la «a» española.', '[{"zh":"妈妈给我一个苹果。","pinyin":"Māma gěi wǒ yí gè píngguǒ.","es":"Mamá me da una manzana."},{"zh":"我问老师一个问题。","pinyin":"Wǒ wèn lǎoshī yí gè wèntí.","es":"Le hago una pregunta al profesor."},{"zh":"请给我一个面包。","pinyin":"Qǐng gěi wǒ yí gè miànbāo.","es":"Deme un pan, por favor."}]'::jsonb, array['主语+动词+宾语1+宾语2']::text[], 42, array['给', '问']::text[], '[{"wrong":"妈妈给一个苹果我。","right":"妈妈给我一个苹果。","why":"La persona va primero y la cosa después."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.7"}]'::jsonb),
  (1, '5.4.1', '句子的类型', '复句', '不用关联词语的复句', '不用关联词语的复句', 'frase 1，frase 2', 'Muchas veces dos frases se unen solo con una coma, sin «y», «pero» ni «porque»: la relación se entiende por el sentido. 下雨了，我们不去了 se lee como «llueve, así que no vamos», y 我喜欢喝茶，他喜欢喝水 contrasta dos gustos. En español solemos añadir un conector; en el chino básico lo normal es no ponerlo.', '[{"zh":"下雨了，我们不去了。","pinyin":"Xià yǔ le, wǒmen bú qù le.","es":"Llueve, así que no vamos."},{"zh":"我喜欢喝茶，他喜欢喝水。","pinyin":"Wǒ xǐhuan hē chá, tā xǐhuan hē shuǐ.","es":"A mí me gusta el té y a él el agua."},{"zh":"今天太冷了，我在家看书。","pinyin":"Jīntiān tài lěng le, wǒ zài jiā kàn shū.","es":"Hoy hace demasiado frío; me quedo en casa leyendo."},{"zh":"他生病了，没去上班。","pinyin":"Tā shēngbìng le, méi qù shàngbān.","es":"Está enfermo y no ha ido a trabajar."}]'::jsonb, null, 43, array['，']::text[], '[{"wrong":"下雨了和我们不去了。","right":"下雨了，我们不去了。","why":"和 no une frases; dos frases se juntan con una coma o con un conector propio."}]'::jsonb, '[{"hsk_level":1,"code":"5.4.2"},{"hsk_level":2,"code":"2.9.2"}]'::jsonb),
  (1, '5.4.2', '句子的类型', '复句', '并列复句', '并列复句', 'frase 1，(sujeto +) 也 + … · frase 1，还 + …', 'Para añadir una segunda idea del mismo tipo, la segunda frase lleva 也 o 还 delante del verbo. 也 «también» repite lo mismo con otro sujeto o en otro aspecto: 我是学生，他也是学生. 还 «además» suma algo nuevo a lo que hace el mismo sujeto: 我买了苹果，还买了面包. Los dos van detrás del sujeto, nunca al principio de la segunda frase.', '[{"zh":"我是学生，他也是学生。","pinyin":"Wǒ shì xuésheng, tā yě shì xuésheng.","es":"Yo soy estudiante y él también."},{"zh":"她会说汉语，也会写汉字。","pinyin":"Tā huì shuō Hànyǔ, yě huì xiě Hànzì.","es":"Sabe hablar chino y también escribir caracteres."},{"zh":"我买了苹果，还买了面包。","pinyin":"Wǒ mǎi le píngguǒ, hái mǎi le miànbāo.","es":"Compré manzanas y además pan."},{"zh":"他喜欢看电影，还喜欢听歌。","pinyin":"Tā xǐhuan kàn diànyǐng, hái xǐhuan tīng gē.","es":"Le gusta ver películas y además escuchar música."}]'::jsonb, array['……，也……', '……，还……']::text[], 44, array['也', '还']::text[], '[{"wrong":"我是学生，也他是学生。","right":"我是学生，他也是学生。","why":"也 va detrás del sujeto de la segunda frase, no delante."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.5"}]'::jsonb),
  (1, '6.1.1', '动作的态', '', '完成态', '完成态', 'verbo + 了 + (cantidad +) objeto · verbo + 了 + objeto + otra acción', '了 detrás del verbo marca la acción como terminada. Encaja sobre todo cuando el objeto lleva una cantidad (买了三个苹果) o cuando después viene otra acción: 下了课我们去吃饭. Por eso también sirve para el futuro: 明天下了班我去找你 «mañana, cuando salga del trabajo, te busco». Las costumbres, aunque sean pasadas, no llevan 了.', '[{"zh":"我买了三个苹果。","pinyin":"Wǒ mǎi le sān gè píngguǒ.","es":"Compré tres manzanas."},{"zh":"他看了两个小时电视。","pinyin":"Tā kàn le liǎng gè xiǎoshí diànshì.","es":"Vio la tele dos horas."},{"zh":"下了课我们去吃饭。","pinyin":"Xià le kè wǒmen qù chī fàn.","es":"Después de clase vamos a comer."},{"zh":"明天下了班我去找你。","pinyin":"Míngtiān xià le bān wǒ qù zhǎo nǐ.","es":"Mañana, al salir del trabajo, voy a buscarte."},{"zh":"昨天我只睡了五个小时。","pinyin":"Zuótiān wǒ zhǐ shuì le wǔ gè xiǎoshí.","es":"Ayer solo dormí cinco horas."}]'::jsonb, array['用动态助词“了1”表示']::text[], 45, array['了']::text[], '[{"wrong":"我每天早上吃了早饭。","right":"我每天早上吃早饭。","why":"Una costumbre no lleva 了: 了 marca una acción concreta terminada."}]'::jsonb, '[{"hsk_level":1,"code":"2.9.2"},{"hsk_level":1,"code":"6.1.2"}]'::jsonb),
  (1, '6.1.2', '动作的态', '', '变化态', '变化态', 'frase + 了', '了 al final de la frase indica que la situación ha cambiado o que algo es nuevo: 下雪了 «se ha puesto a nevar», 我女儿六岁了 «mi hija ya tiene seis años». Con negación dice que algo ha dejado de ser: 我不想去了 «ya no quiero ir». A diferencia del 了 pegado al verbo, no dice que una acción terminó, sino que ahora las cosas son distintas.', '[{"zh":"下雪了。","pinyin":"Xià xuě le.","es":"Se ha puesto a nevar."},{"zh":"我女儿六岁了。","pinyin":"Wǒ nǚ’ér liù suì le.","es":"Mi hija ya tiene seis años."},{"zh":"他是大学生了。","pinyin":"Tā shì dàxuéshēng le.","es":"Ya es universitario."},{"zh":"我不想去了。","pinyin":"Wǒ bù xiǎng qù le.","es":"Ya no quiero ir."},{"zh":"天气冷了。","pinyin":"Tiānqì lěng le.","es":"Ya hace frío."}]'::jsonb, array['用动态助词“了2”表示']::text[], 46, array['了']::text[], '[{"wrong":"我不想去。（para decir «ya no quiero ir»）","right":"我不想去了。","why":"El «ya no» de un cambio de idea necesita 了 al final; sin él solo dices que no quieres ir."}]'::jsonb, '[{"hsk_level":1,"code":"2.9.3"},{"hsk_level":1,"code":"6.1.1"}]'::jsonb),
  (1, '6.1.3', '动作的态', '', '进行态', '进行态', '在 / 正在 + verbo (+ 呢) · verbo + 呢', 'Para decir que algo está pasando ahora, se pone 在 o 正在 delante del verbo: 他在睡觉. 呢 al final refuerza la idea y puede ir solo, sin 在: 他们看电视呢. Se niega con 没(在): 他没在睡觉. No sirve para planes futuros como el «mañana me voy» español.', '[{"zh":"他在睡觉。","pinyin":"Tā zài shuìjiào.","es":"Está durmiendo."},{"zh":"我正在写汉字呢。","pinyin":"Wǒ zhèngzài xiě Hànzì ne.","es":"Estoy escribiendo caracteres."},{"zh":"他们看电视呢。","pinyin":"Tāmen kàn diànshì ne.","es":"Están viendo la tele."},{"zh":"他没在睡觉，他在看书。","pinyin":"Tā méi zài shuìjiào, tā zài kàn shū.","es":"No está durmiendo, está leyendo."}]'::jsonb, array['（1）……在/正在+动词', '（2）……在/正在+动词……+呢', '（3）……呢']::text[], 47, array['在', '呢']::text[], '[{"wrong":"明天我在去中国。","right":"明天我去中国。","why":"在 + verbo describe lo que ocurre ahora; para un plan se usa el verbo solo o con 要."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.3"},{"hsk_level":2,"code":"7.1.1"}]'::jsonb),
  (1, '7.1', '特殊表达法', '数的表达法', null, '数的表达法', 'número + 块 / 元 (+ 钱) · 第 + número', 'El dinero se cuenta con 元 por escrito y con 块 al hablar: 十五块, 三百元. Delante de 块, «dos» es 两: 两块钱. 钱 al final es opcional. Para preguntar el precio se dice 多少钱？ Los ordinales se forman con 第 delante del número: 第一, 第三.', '[{"zh":"这本书十五块。","pinyin":"Zhè běn shū shíwǔ kuài.","es":"Este libro cuesta quince yuanes."},{"zh":"一个苹果两块钱。","pinyin":"Yí gè píngguǒ liǎng kuài qián.","es":"Una manzana cuesta dos yuanes."},{"zh":"这件衣服三百元。","pinyin":"Zhè jiàn yīfu sānbǎi yuán.","es":"Esta ropa cuesta trescientos yuanes."},{"zh":"这个多少钱？","pinyin":"Zhège duōshao qián?","es":"¿Cuánto cuesta esto?"},{"zh":"他是第一个来的。","pinyin":"Tā shì dì yī gè lái de.","es":"Fue el primero en llegar."}]'::jsonb, array['钱数表示法', '序数表达法1：第+数词']::text[], 48, array['块', '元', '第', '钱']::text[], '[{"wrong":"一个苹果二块钱。","right":"一个苹果两块钱。","why":"Delante de 块 «dos» se dice 两."}]'::jsonb, '[{"hsk_level":1,"code":"1.1"},{"hsk_level":1,"code":"2.4"}]'::jsonb),
  (1, '7.2', '特殊表达法', '时间表示法', null, '时间表示法', 'año + 月 + 号 + 星期 · (上午 / 下午 / 晚上) + 点 + 分', 'Las fechas van de lo grande a lo pequeño: año, mes, día y día de la semana (2026年11月25号，星期三). La hora sigue el mismo orden: primero la parte del día y después la hora: 下午三点半. Los meses son número + 月 y los días de la semana, 星期 + número, salvo el domingo: 星期天. Fecha y hora van delante del verbo.', '[{"zh":"今天是十一月二十五号，星期三。","pinyin":"Jīntiān shì shíyī yuè èrshíwǔ hào, xīngqīsān.","es":"Hoy es miércoles, veinticinco de noviembre."},{"zh":"现在下午三点半。","pinyin":"Xiànzài xiàwǔ sān diǎn bàn.","es":"Son las tres y media de la tarde."},{"zh":"我们星期天上午十点见。","pinyin":"Wǒmen xīngqītiān shàngwǔ shí diǎn jiàn.","es":"Nos vemos el domingo a las diez de la mañana."},{"zh":"他晚上十一点睡觉。","pinyin":"Tā wǎnshang shíyī diǎn shuìjiào.","es":"Se acuesta a las once de la noche."}]'::jsonb, array['（1）年、月、日、星期表示法', '（2）钟点表示法']::text[], 49, array['月', '号', '星期', '点']::text[], '[{"wrong":"我们见十点星期天。","right":"我们星期天十点见。","why":"La fecha y la hora van delante del verbo, de lo más grande a lo más pequeño."}]'::jsonb, '[{"hsk_level":1,"code":"2.5.2"},{"hsk_level":2,"code":"5.2"}]'::jsonb),
  (2, '1.1', '语素', '后缀', null, '后缀', '前 / 后 / 里 / 外 / 上 / 下 + 面', '面 se pega a una palabra de posición y forma un sustantivo de lugar: 前面 «delante», 里面 «dentro», 上面 «encima». Funciona igual que 边 (前边, 里边) y casi siempre se pueden intercambiar. Como son sustantivos, pueden ir solos como sujeto (外面下雨了) o detrás de un nombre, sin 的: 桌子上面. Al revés que en español, primero va el objeto de referencia y después la posición: «encima de la mesa» es 桌子上面.', '[{"zh":"医院在商店前面。","pinyin":"Yīyuàn zài shāngdiàn qiánmiàn.","es":"El hospital está delante de la tienda."},{"zh":"学校后面有一个饭馆。","pinyin":"Xuéxiào hòumiàn yǒu yí gè fànguǎn.","es":"Detrás del colegio hay un restaurante."},{"zh":"书包里面有什么？","pinyin":"Shūbāo lǐmiàn yǒu shénme?","es":"¿Qué hay dentro de la mochila?"},{"zh":"外面下雨了。","pinyin":"Wàimiàn xià yǔ le.","es":"Fuera está lloviendo."},{"zh":"你的手机在桌子上面。","pinyin":"Nǐ de shǒujī zài zhuōzi shàngmiàn.","es":"Tu móvil está encima de la mesa."}]'::jsonb, array['面']::text[], 1, array['前面', '后面', '里面', '外面', '上面']::text[], '[{"wrong":"你的手机在上面桌子。","right":"你的手机在桌子上面。","why":"La posición va detrás del objeto de referencia, no delante como en «encima de la mesa»."}]'::jsonb, '[{"hsk_level":1,"code":"1.2"},{"hsk_level":1,"code":"2.1.1"}]'::jsonb),
  (2, '2.1.1', '词类', '名词', '方位名词', '方位名词', 'lugar + 左边 / 右边 · 往左 / 往右 + verbo', '左 «izquierda» y 右 «derecha» casi nunca van solos como lugar: se usan como 左边 y 右边. Siguen la misma regla que 上 o 里: primero el objeto de referencia y después la posición, 学校右边 «a la derecha del colegio». Para indicar una dirección se combinan con 往: 往右走 «gira a la derecha».', '[{"zh":"我家左边是一个超市。","pinyin":"Wǒ jiā zuǒbian shì yí gè chāoshì.","es":"A la izquierda de mi casa hay un supermercado."},{"zh":"医院在学校右边。","pinyin":"Yīyuàn zài xuéxiào yòubian.","es":"El hospital está a la derecha del colegio."},{"zh":"你往右走。","pinyin":"Nǐ wǎng yòu zǒu.","es":"Gira a la derecha."},{"zh":"坐在我左边的是我朋友。","pinyin":"Zuò zài wǒ zuǒbian de shì wǒ péngyou.","es":"Quien está sentado a mi izquierda es mi amigo."}]'::jsonb, array['左、右']::text[], 2, array['左', '右']::text[], '[{"wrong":"医院在右边学校。","right":"医院在学校右边。","why":"右边 va detrás del lugar de referencia; el orden de «a la derecha del colegio» se invierte."}]'::jsonb, '[{"hsk_level":1,"code":"2.1.1"}]'::jsonb),
  (2, '2.2.1', '词类', '动词', '动词重叠', '动词重叠', 'V + V · V + 一 + V · V + 了 + V · AB + AB', 'Repetir un verbo suaviza la acción: indica que dura poco, que se hace sin esfuerzo o que solo se intenta. Por eso sirve para pedir algo con cortesía (你看看) o proponer (我们休息休息吧). Con 了 en medio (想了想) cuenta una acción breve que ya se hizo. Los verbos de dos sílabas se repiten enteros, ABAB, nunca AABB. No encaja con una duración larga ni con verbos que no son acciones, como 是 o 有.', '[{"zh":"你看看这本书。","pinyin":"Nǐ kànkan zhè běn shū.","es":"Échale un vistazo a este libro."},{"zh":"晚上我看看书，也喝茶。","pinyin":"Wǎnshang wǒ kànkan shū, yě hē chá.","es":"Por la noche leo un rato y tomo té."},{"zh":"这个问题你再想一想。","pinyin":"Zhège wèntí nǐ zài xiǎng yi xiǎng.","es":"Piensa un poco más en esta pregunta."},{"zh":"他想了想，说：“好吧。”","pinyin":"Tā xiǎng le xiǎng, shuō: “Hǎo ba.”","es":"Lo pensó un momento y dijo: «Vale»."},{"zh":"我们休息休息吧。","pinyin":"Wǒmen xiūxi xiūxi ba.","es":"Descansemos un poco."}]'::jsonb, array['AA、A一A、A了A、ABAB']::text[], 3, array['看看', '想一想', '想了想', '休息休息']::text[], '[{"wrong":"我看看了三个小时书。","right":"我看了三个小时书。","why":"La repetición indica que la acción es breve; no encaja con una duración larga."},{"wrong":"我们休休息息吧。","right":"我们休息休息吧。","why":"Los verbos de dos sílabas se repiten como bloque (ABAB); AABB es la forma de los adjetivos."}]'::jsonb, '[{"hsk_level":2,"code":"2.4.1"}]'::jsonb),
  (2, '2.2.2', '词类', '动词', '能愿动词', '能愿动词', '可能 + verbo / frase · 不可能', '可能 expresa probabilidad: algo que quizá pase o quizá sea cierto, como «puede que» o «a lo mejor». Va delante del verbo o al principio de la frase (可能他不来了). No sirve para la capacidad ni para el permiso: «sé / puedo hablar chino» se dice con 会 o 能, y para pedir permiso se usa 可以. 不可能 significa «es imposible».', '[{"zh":"明天可能下雨。","pinyin":"Míngtiān kěnéng xià yǔ.","es":"Puede que mañana llueva."},{"zh":"他可能不来了。","pinyin":"Tā kěnéng bù lái le.","es":"A lo mejor ya no viene."},{"zh":"可能他已经回家了。","pinyin":"Kěnéng tā yǐjīng huí jiā le.","es":"Quizá ya ha vuelto a casa."},{"zh":"这不可能！","pinyin":"Zhè bù kěnéng!","es":"¡Eso es imposible!"}]'::jsonb, array['可能']::text[], 4, array['可能']::text[], '[{"wrong":"我可能说汉语。","right":"我会说汉语。","why":"可能 no es el «poder» de saber hacer algo; para eso se usa 会. 可能 solo dice que algo es probable."}]'::jsonb, '[{"hsk_level":1,"code":"2.2.1"}]'::jsonb),
  (2, '2.2.3', '词类', '动词', '离合词', '离合词', 'V + (了 / 过 / duración / 的…) + O: 帮我的忙 · 游了一个小时泳', 'Estos verbos son un verbo y su objeto pegados, así que se pueden separar: 了, 过, una duración o un posesivo van en medio. Por eso no admiten otro objeto detrás: «ayudarte» no es «帮忙你», sino 帮你的忙 o simplemente 帮你. La duración también se mete en medio: 跑了半个小时步. Sin separar, se usan como un verbo sin objeto: 她喜欢跳舞.', '[{"zh":"你能帮我一个忙吗？","pinyin":"Nǐ néng bāng wǒ yí gè máng ma?","es":"¿Me puedes hacer un favor?"},{"zh":"我昨天游了一个小时泳。","pinyin":"Wǒ zuótiān yóu le yí gè xiǎoshí yǒng.","es":"Ayer nadé una hora."},{"zh":"她很喜欢跳舞。","pinyin":"Tā hěn xǐhuan tiàowǔ.","es":"Le encanta bailar."},{"zh":"我每天早上跑半个小时步。","pinyin":"Wǒ měi tiān zǎoshang pǎo bàn gè xiǎoshí bù.","es":"Cada mañana corro media hora."}]'::jsonb, array['帮忙、游泳、跳舞、跑步']::text[], 5, array['帮', '游', '跳舞', '跑']::text[], '[{"wrong":"你能帮忙我吗？","right":"你能帮我的忙吗？","why":"帮忙 ya lleva su objeto (忙): la persona va en medio, 帮我的忙, o se usa solo 帮: 帮我."},{"wrong":"我游泳了一个小时。","right":"我游了一个小时泳。","why":"La duración se mete entre el verbo y su objeto interno, no detrás del verbo entero."}]'::jsonb, '[{"hsk_level":1,"code":"2.2.2"}]'::jsonb),
  (2, '2.3.1', '词类', '代词', '疑问代词', '疑问代词', 'Sujeto + 为什么 + verbo？', '为什么 pregunta por la causa, como «¿por qué?». Va detrás del sujeto y delante del verbo, no al final de la frase: 你为什么不去？ La respuesta suele empezar con 因为. Como la frase ya es una pregunta, no se añade 吗.', '[{"zh":"你为什么不去？","pinyin":"Nǐ wèishénme bú qù?","es":"¿Por qué no vas?"},{"zh":"他为什么没来上课？","pinyin":"Tā wèishénme méi lái shàngkè?","es":"¿Por qué no vino a clase?"},{"zh":"为什么你每天都这么累？","pinyin":"Wèishénme nǐ měi tiān dōu zhème lèi?","es":"¿Por qué estás tan cansado todos los días?"},{"zh":"“你为什么学汉语？”“因为我喜欢中国。”","pinyin":"“Nǐ wèishénme xué Hànyǔ?” “Yīnwèi wǒ xǐhuan Zhōngguó.”","es":"—¿Por qué estudias chino? —Porque me gusta China."}]'::jsonb, array['为什么']::text[], 6, array['为什么']::text[], '[{"wrong":"你不去为什么？","right":"你为什么不去？","why":"为什么 va delante del verbo; no se deja al final como en «no vas, ¿por qué?»."},{"wrong":"你为什么不去吗？","right":"你为什么不去？","why":"Con 为什么 la frase ya es una pregunta; 吗 sobra."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.1"}]'::jsonb),
  (2, '2.3.2', '词类', '代词', '人称代词', '人称代词', 'Pronombre + 自己 + verbo · 自己的 + nombre', '自己 significa «uno mismo» y no cambia con la persona. Detrás del sujeto subraya que es él y no otro quien hace la acción, o que la hace sin ayuda: 我自己去, 他自己做饭. También puede ser objeto (只想自己) o posesivo con 的 (自己的房间). Va siempre delante del verbo cuando significa «yo mismo», nunca al final.', '[{"zh":"我自己去吧。","pinyin":"Wǒ zìjǐ qù ba.","es":"Ya voy yo."},{"zh":"他每天自己做饭。","pinyin":"Tā měi tiān zìjǐ zuò fàn.","es":"Se hace la comida él solo todos los días."},{"zh":"这是我自己的房间。","pinyin":"Zhè shì wǒ zìjǐ de fángjiān.","es":"Esta es mi propia habitación."},{"zh":"你不能只想自己。","pinyin":"Nǐ bù néng zhǐ xiǎng zìjǐ.","es":"No puedes pensar solo en ti."}]'::jsonb, array['自己']::text[], 7, array['自己']::text[], '[{"wrong":"我去自己。","right":"我自己去。","why":"Para «voy yo mismo», 自己 va pegado al sujeto y delante del verbo, no al final como en español."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.2"}]'::jsonb),
  (2, '2.3.3', '词类', '代词', '指示代词', '指示代词', '这么 / 那么 + adjetivo · 这样 / 那样 + verbo · 每 + clasificador + nombre (+ 都)', '这么 y 那么 van delante de un adjetivo y equivalen a «tan»: 这么贵. 这样 y 那样 significan «así, de esta manera»: delante de un verbo (这样写) o, con 的, delante de un nombre (那样的人). Con 这 se señala lo cercano o lo que se acaba de decir; con 那, lo lejano. 每 «cada» va con un clasificador (每个人, 每天) y casi siempre se refuerza con 都 delante del verbo.', '[{"zh":"这件衣服这么贵！","pinyin":"Zhè jiàn yīfu zhème guì!","es":"¡Esta ropa es tan cara!"},{"zh":"你不要那么说。","pinyin":"Nǐ búyào nàme shuō.","es":"No lo digas así."},{"zh":"这个字要这样写。","pinyin":"Zhège zì yào zhèyàng xiě.","es":"Este carácter se escribe así."},{"zh":"我不喜欢那样的人。","pinyin":"Wǒ bù xǐhuan nàyàng de rén.","es":"No me gusta la gente así."},{"zh":"他每天都跑步。","pinyin":"Tā měi tiān dōu pǎobù.","es":"Corre todos los días."}]'::jsonb, array['那么、那样、这么、这样、每']::text[], 8, array['这么', '那么', '这样', '那样', '每']::text[], '[{"wrong":"这件衣服很这么贵。","right":"这件衣服这么贵。","why":"这么 ya hace de «tan»; no se combina con 很."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.3"}]'::jsonb),
  (2, '2.4.1', '词类', '形容词', '形容词重叠', '形容词重叠', 'AA(的 / 地) · AABB(的 / 地)', 'Repetir un adjetivo lo hace más vivo y expresivo, como «bien grande» o un diminutivo en español. Los de una sílaba se repiten AA (大大的, 慢慢地) y los de dos, AABB (高高兴兴). La forma repetida ya lleva la intensidad, así que no admite 很 ni 非常 delante. Suele terminar en 的 cuando describe un nombre y en 地 cuando acompaña a un verbo.', '[{"zh":"她的眼睛大大的。","pinyin":"Tā de yǎnjing dàdà de.","es":"Tiene los ojos bien grandes."},{"zh":"你慢慢地说。","pinyin":"Nǐ mànmàn de shuō.","es":"Habla despacito."},{"zh":"孩子高高兴兴地回家了。","pinyin":"Háizi gāogāoxìngxìng de huí jiā le.","es":"El niño volvió a casa muy contento."},{"zh":"她今天穿得漂漂亮亮的。","pinyin":"Tā jīntiān chuān de piàopiaoliàngliàng de.","es":"Hoy va muy arreglada."}]'::jsonb, array['AA、AABB']::text[], 9, array['大大', '慢慢', '高高兴兴', '漂漂亮亮']::text[], '[{"wrong":"她的眼睛很大大的。","right":"她的眼睛大大的。","why":"La repetición ya intensifica; añadir 很 sobra."},{"wrong":"孩子高兴高兴地回家了。","right":"孩子高高兴兴地回家了。","why":"Los adjetivos de dos sílabas se repiten AABB; ABAB es la forma de los verbos (休息休息)."}]'::jsonb, '[{"hsk_level":2,"code":"2.2.1"}]'::jsonb),
  (2, '2.5', '词类', '数词', null, '数词', '一万 / 十万 · 好多 + nombre · número + 多 (+ clasificador)', '万 es la unidad de diez mil: el chino agrupa de diez mil en diez mil, así que cien mil es 十万. 好多 significa «muchísimos» y va delante del nombre, como 很多 pero más coloquial. 多 detrás de un número añade «y pico»: con decenas va delante del clasificador (二十多岁, «veintitantos años»); con unidades, detrás (一个多小时, «más de una hora»).', '[{"zh":"我们学校有一万个学生。","pinyin":"Wǒmen xuéxiào yǒu yíwàn gè xuésheng.","es":"Nuestro colegio tiene diez mil estudiantes."},{"zh":"商店里有好多人。","pinyin":"Shāngdiàn li yǒu hǎoduō rén.","es":"En la tienda hay muchísima gente."},{"zh":"他二十多岁。","pinyin":"Tā èrshí duō suì.","es":"Tiene veintitantos años."},{"zh":"我等了一个多小时。","pinyin":"Wǒ děng le yí gè duō xiǎoshí.","es":"Esperé más de una hora."},{"zh":"这个手机三千多块钱。","pinyin":"Zhège shǒujī sānqiān duō kuài qián.","es":"Este móvil cuesta tres mil y pico yuanes."}]'::jsonb, array['万、好多、多']::text[], 10, array['万', '好多', '多']::text[], '[{"wrong":"我们学校有十千个学生。","right":"我们学校有一万个学生。","why":"«十千» no existe: a partir de diez mil se cuenta con 万."},{"wrong":"我等了一个小时多。","right":"我等了一个多小时。","why":"Con unidades, 多 va entre el clasificador y el nombre: 一个多小时, no al final."}]'::jsonb, '[{"hsk_level":1,"code":"2.4"}]'::jsonb),
  (2, '2.6.1', '词类', '量词', '名量词', '名量词', 'número / 这 / 那 + 条 / 位 / 间 / 名 / 包 + nombre', 'Cada clasificador va con un tipo de nombre. 条 cuenta cosas largas y estrechas: calles, ríos, peces, pantalones. 位 cuenta personas con respeto (这位老师) y es más cortés que 个. 间 cuenta habitaciones y aulas, y 名 cuenta personas dentro de un grupo o una lista, como los alumnos de una clase. 包 es un clasificador prestado: «paquete», para lo que viene envasado (一包茶).', '[{"zh":"这条路很长。","pinyin":"Zhè tiáo lù hěn cháng.","es":"Esta calle es muy larga."},{"zh":"这位是我们的老师。","pinyin":"Zhè wèi shì wǒmen de lǎoshī.","es":"Este es nuestro profesor."},{"zh":"这间教室很大。","pinyin":"Zhè jiān jiàoshì hěn dà.","es":"Esta aula es muy grande."},{"zh":"我们班有三十名学生。","pinyin":"Wǒmen bān yǒu sānshí míng xuésheng.","es":"Nuestra clase tiene treinta alumnos."},{"zh":"我买了一包茶和两条鱼。","pinyin":"Wǒ mǎi le yì bāo chá hé liǎng tiáo yú.","es":"Compré un paquete de té y dos peces."}]'::jsonb, array['（1）专用名量词：条、位、间、名', '（2）借用名量词：包']::text[], 11, array['条', '位', '间', '名', '包']::text[], '[{"wrong":"这个路很长。","right":"这条路很长。","why":"Las cosas largas y estrechas se cuentan con 条; 个 es el comodín para lo que no tiene clasificador propio."}]'::jsonb, '[{"hsk_level":1,"code":"2.5.1"}]'::jsonb),
  (2, '2.6.2', '词类', '量词', '动量词', '动量词', 'verbo + (了 / 过) + número + 次 (+ objeto)', '次 cuenta las veces que ocurre una acción, como «vez». Va detrás del verbo y de 了 o 过: 去过两次. Un objeto común suele ir detrás de 次 (上两次课); un lugar o una persona pueden ir antes (去过中国两次). Para preguntar se usa 几次. Al contrario que en español, las veces nunca van delante del verbo.', '[{"zh":"我去过中国两次。","pinyin":"Wǒ qùguo Zhōngguó liǎng cì.","es":"He estado en China dos veces."},{"zh":"这个电影我看了三次。","pinyin":"Zhège diànyǐng wǒ kàn le sān cì.","es":"Esta película la he visto tres veces."},{"zh":"你来过几次？","pinyin":"Nǐ láiguo jǐ cì?","es":"¿Cuántas veces has venido?"},{"zh":"我们一个星期上两次课。","pinyin":"Wǒmen yí gè xīngqī shàng liǎng cì kè.","es":"Tenemos clase dos veces por semana."}]'::jsonb, array['次']::text[], 12, array['次']::text[], '[{"wrong":"我两次去过中国。","right":"我去过中国两次。","why":"Las veces van detrás del verbo; delante, como en «dos veces he ido», no funciona."}]'::jsonb, '[{"hsk_level":1,"code":"4.6.1"}]'::jsonb),
  (2, '2.7.1', '词类', '副词', '程度副词', '程度副词', '最 + adjetivo / verbo · 好 + adjetivo (+ 啊) · 多 + adjetivo (+ 啊)', '最 forma el superlativo, «el más»: 最高, 最喜欢. 好 delante de un adjetivo intensifica con emoción, como «qué» o «muy»: 好冷啊！ 多 sirve para exclamar (多漂亮啊！) y para preguntar por una medida: 多大 «qué edad, qué tamaño». Para un «muy» neutro, sin exclamación, se sigue usando 很. El ámbito del superlativo va delante: 我们班最高的.', '[{"zh":"你最喜欢吃什么？","pinyin":"Nǐ zuì xǐhuan chī shénme?","es":"¿Qué es lo que más te gusta comer?"},{"zh":"他是我们班最高的。","pinyin":"Tā shì wǒmen bān zuì gāo de.","es":"Es el más alto de nuestra clase."},{"zh":"今天好冷啊！","pinyin":"Jīntiān hǎo lěng a!","es":"¡Qué frío hace hoy!"},{"zh":"这里多漂亮啊！","pinyin":"Zhèlǐ duō piàoliang a!","es":"¡Qué bonito es esto!"},{"zh":"你今年多大？","pinyin":"Nǐ jīnnián duō dà?","es":"¿Cuántos años tienes?"}]'::jsonb, array['多、好、最']::text[], 13, array['最', '好', '多']::text[], '[{"wrong":"他是最高在我们班。","right":"他是我们班最高的。","why":"El ámbito («de la clase») va delante de 最; no se añade un «en» con 在 al final."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.1"}]'::jsonb),
  (2, '2.7.2', '词类', '副词', '范围副词', '范围副词', 'Sujeto + (和 / 跟 + persona) + 一起 + verbo', '一起 significa «juntos» y va delante del verbo, nunca al final como en «vamos juntos». La persona con la que se hace algo se presenta antes con 和 o 跟: 我和朋友一起去. Para proponer un plan se combina con 吧: 我们一起吃饭吧.', '[{"zh":"我们一起去吧。","pinyin":"Wǒmen yìqǐ qù ba.","es":"Vamos juntos."},{"zh":"我和朋友一起吃饭。","pinyin":"Wǒ hé péngyou yìqǐ chī fàn.","es":"Como con un amigo."},{"zh":"他们每天一起上学。","pinyin":"Tāmen měi tiān yìqǐ shàngxué.","es":"Van juntos al colegio todos los días."},{"zh":"你跟我一起走吗？","pinyin":"Nǐ gēn wǒ yìqǐ zǒu ma?","es":"¿Te vienes conmigo?"}]'::jsonb, array['一起']::text[], 14, array['一起']::text[], '[{"wrong":"我们去一起吧。","right":"我们一起去吧。","why":"一起 va delante del verbo, no detrás como en «vamos juntos»."}]'::jsonb, '[{"hsk_level":1,"code":"2.7.2"}]'::jsonb),
  (2, '2.7.3', '词类', '副词', '时间副词', '时间副词', '已经 + V + 了 · 还 + V · 有时候 + V · 快(要) + V + 了 · 正 + V (+ 呢)', '已经 «ya» marca algo terminado y casi siempre lleva 了: 他已经走了. 还 es «todavía»: la situación sigue igual (他还在睡觉). 有时候, o 有时, es «a veces». 快 y 快要 anuncian que algo va a pasar enseguida y exigen 了 al final: 快下雨了. 正 dice que la acción está en marcha justo en ese momento: 我正吃饭呢.', '[{"zh":"他已经走了。","pinyin":"Tā yǐjīng zǒu le.","es":"Ya se ha ido."},{"zh":"十点了，他还在睡觉。","pinyin":"Shí diǎn le, tā hái zài shuìjiào.","es":"Son las diez y todavía está durmiendo."},{"zh":"我有时候坐地铁上班。","pinyin":"Wǒ yǒushíhou zuò dìtiě shàngbān.","es":"A veces voy al trabajo en metro."},{"zh":"快下雨了，我们回家吧。","pinyin":"Kuài xià yǔ le, wǒmen huí jiā ba.","es":"Va a llover, volvamos a casa."},{"zh":"他来的时候，我正吃饭呢。","pinyin":"Tā lái de shíhou, wǒ zhèng chī fàn ne.","es":"Cuando llegó, yo estaba comiendo."}]'::jsonb, array['还2、已经、有时（候）、快、快要、正']::text[], 15, array['已经', '还', '有时', '快', '正']::text[], '[{"wrong":"快要下雨。","right":"快要下雨了。","why":"快 y 快要 necesitan 了 al final; sin él la frase queda a medias."},{"wrong":"我已经吃饭。","right":"我已经吃饭了。","why":"已经 presenta algo ya terminado y pide 了."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.3"},{"hsk_level":1,"code":"2.6.5"}]'::jsonb),
  (2, '2.7.4', '词类', '副词', '频率副词', '频率副词', 'Sujeto + 经常 / 常 + verbo', '经常 y 常 significan «a menudo» y van delante del verbo, detrás del sujeto. 常 es más breve y algo más escrito; en la conversación se oye sobre todo 经常. No se colocan al final de la frase como en «voy mucho». Para negarlo basta con poner 不 delante: 不经常.', '[{"zh":"我经常去那个饭馆。","pinyin":"Wǒ jīngcháng qù nàge fànguǎn.","es":"Voy a menudo a ese restaurante."},{"zh":"他经常工作到很晚。","pinyin":"Tā jīngcháng gōngzuò dào hěn wǎn.","es":"A menudo trabaja hasta muy tarde."},{"zh":"你经常运动吗？","pinyin":"Nǐ jīngcháng yùndòng ma?","es":"¿Haces deporte a menudo?"},{"zh":"我不经常看电视。","pinyin":"Wǒ bù jīngcháng kàn diànshì.","es":"No veo mucho la tele."}]'::jsonb, array['常、经常']::text[], 16, array['经常']::text[], '[{"wrong":"我去那个饭馆经常。","right":"我经常去那个饭馆。","why":"经常 va delante del verbo, no al final como en «voy ahí a menudo»."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.4"}]'::jsonb),
  (2, '2.7.5', '词类', '副词', '否定副词', '否定副词', '(你) + 别 + verbo (+ 了)', '别 pide a alguien que no haga algo: «no…». Es más directo y coloquial que 不要 y va delante del verbo. Con 了 al final pide que se deje de hacer algo que ya está pasando: 别说了 «deja de hablar». No sirve para negar hechos: «no fui» es 我没去.', '[{"zh":"别走！","pinyin":"Bié zǒu!","es":"¡No te vayas!"},{"zh":"别说了，我知道了。","pinyin":"Bié shuō le, wǒ zhīdào le.","es":"Deja de hablar, ya lo sé."},{"zh":"外面下雨，别出去了。","pinyin":"Wàimiàn xià yǔ, bié chūqu le.","es":"Fuera llueve, no salgas."},{"zh":"你别喝太多。","pinyin":"Nǐ bié hē tài duō.","es":"No bebas demasiado."}]'::jsonb, array['别']::text[], 17, array['别']::text[], '[{"wrong":"我昨天别去学校。","right":"我昨天没去学校。","why":"别 solo pide que alguien no haga algo; para negar lo que pasó se usa 没."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.6"},{"hsk_level":2,"code":"6.2.2"}]'::jsonb),
  (2, '2.7.6', '词类', '副词', '关联副词', '关联副词', 'V1 (+ 了…) + 再 + V2 · V1 + 了… + 就 + V2', 'Los dos enlazan dos acciones: la segunda ocurre después de la primera y van delante del segundo verbo. 再 mira hacia lo que aún no ha pasado, a menudo para pedir que se espere: 吃了饭再走 «come y después te vas». 就 subraya que la segunda acción llega enseguida y vale también para lo que ya ocurrió: 他下了课就回家了.', '[{"zh":"我们吃了饭再走吧。","pinyin":"Wǒmen chī le fàn zài zǒu ba.","es":"Comamos y después nos vamos."},{"zh":"你休息一下，明天再说。","pinyin":"Nǐ xiūxi yíxià, míngtiān zài shuō.","es":"Descansa un poco; mañana lo hablamos."},{"zh":"他下了课就回家了。","pinyin":"Tā xià le kè jiù huí jiā le.","es":"Al salir de clase se fue directo a casa."},{"zh":"我到了就给你打电话。","pinyin":"Wǒ dào le jiù gěi nǐ dǎ diànhuà.","es":"En cuanto llegue te llamo."}]'::jsonb, array['再2、就1']::text[], 18, array['再', '就']::text[], '[{"wrong":"他下了课再回家了。","right":"他下了课就回家了。","why":"Para lo que ya pasó se usa 就; 再 solo mira hacia lo que todavía no ha ocurrido."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.4"}]'::jsonb),
  (2, '2.7.7', '词类', '副词', '语气副词', '语气副词', '都 + tiempo / cantidad + 了 · 就 + verbo / 是 · 还是 + verbo (+ 吧)', 'Estos adverbios añaden la opinión de quien habla. 都…了 subraya que algo es más tarde o más de lo esperado: 都十点了 «¡si ya son las diez!». 就 insiste en que es exactamente eso: 这就是我的家 «esta es precisamente mi casa». 还是 recomienda la opción que, pensándolo bien, parece mejor: 你还是去吧 «mejor ve».', '[{"zh":"都十点了，你怎么还不起床？","pinyin":"Dōu shí diǎn le, nǐ zěnme hái bù qǐchuáng?","es":"¡Si ya son las diez! ¿Cómo es que no te levantas?"},{"zh":"这就是我的家。","pinyin":"Zhè jiù shì wǒ de jiā.","es":"Esta es precisamente mi casa."},{"zh":"我就要这个。","pinyin":"Wǒ jiù yào zhège.","es":"Quiero justo este."},{"zh":"外面很冷，你还是别出去了。","pinyin":"Wàimiàn hěn lěng, nǐ háishi bié chūqu le.","es":"Fuera hace mucho frío; mejor no salgas."},{"zh":"我们还是坐出租车吧。","pinyin":"Wǒmen háishi zuò chūzūchē ba.","es":"Mejor vamos en taxi."}]'::jsonb, array['都2、就2、还是1']::text[], 19, array['都', '就', '还是']::text[], '[{"wrong":"都十点，你怎么还不起床？","right":"都十点了，你怎么还不起床？","why":"都 con el sentido de «ya» necesita 了 al final."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.2"},{"hsk_level":2,"code":"4.1"}]'::jsonb),
  (2, '2.8.1', '词类', '介词', '引出时间、处所', '引出时间、处所', '从 + tiempo / lugar (+ 到 + tiempo / lugar) + verbo', '从 marca el punto de partida, en el tiempo o en el espacio: «desde», «de». Se combina a menudo con 到 para el final: 从九点到十二点. Todo el grupo va delante del verbo, no detrás: «vengo de China» es 我从中国来.', '[{"zh":"我从中国来。","pinyin":"Wǒ cóng Zhōngguó lái.","es":"Vengo de China."},{"zh":"我们从九点到十二点上课。","pinyin":"Wǒmen cóng jiǔ diǎn dào shí’èr diǎn shàngkè.","es":"Tenemos clase de nueve a doce."},{"zh":"他从明天开始工作。","pinyin":"Tā cóng míngtiān kāishǐ gōngzuò.","es":"Empieza a trabajar a partir de mañana."},{"zh":"从我家到学校很近。","pinyin":"Cóng wǒ jiā dào xuéxiào hěn jìn.","es":"De mi casa al colegio hay muy poco."}]'::jsonb, array['从1']::text[], 20, array['从']::text[], '[{"wrong":"我来从中国。","right":"我从中国来。","why":"El grupo con 从 va delante del verbo; no se copia el orden de «vengo de China»."}]'::jsonb, '[{"hsk_level":1,"code":"2.7.1"}]'::jsonb),
  (2, '2.8.2', '词类', '介词', '引出方向、路径', '引出方向、路径', '往 + dirección + verbo · 从 + lugar de paso + verbo', '往 indica hacia dónde va el movimiento: 往前走 «sigue recto», 往左走 «gira a la izquierda». 从, además del punto de partida, marca el sitio por donde se pasa: 从这儿走 «ve por aquí», 从门口进来 «entra por la puerta». Los dos grupos van delante del verbo, nunca detrás.', '[{"zh":"你往前走，医院就在右边。","pinyin":"Nǐ wǎng qián zǒu, yīyuàn jiù zài yòubian.","es":"Sigue recto y el hospital está a la derecha."},{"zh":"往左走是车站。","pinyin":"Wǎng zuǒ zǒu shì chēzhàn.","es":"Si giras a la izquierda está la estación."},{"zh":"我们从这儿走吧。","pinyin":"Wǒmen cóng zhèr zǒu ba.","es":"Vamos por aquí."},{"zh":"他从门口进来了。","pinyin":"Tā cóng ménkǒu jìnlai le.","es":"Entró por la puerta."}]'::jsonb, array['往', '从2']::text[], 21, array['往', '从']::text[], '[{"wrong":"你走往前。","right":"你往前走。","why":"往 y la dirección van delante del verbo, no detrás como en «camina hacia delante»."}]'::jsonb, '[{"hsk_level":2,"code":"2.8.1"}]'::jsonb),
  (2, '2.8.3', '词类', '介词', '引出对象', '引出对象', '给 + persona + verbo · 跟 + persona + verbo · A + 比 + B + adjetivo', 'Las tres presentan a la otra persona o cosa de la acción y van delante del verbo. 给 dice a quién va dirigida o para quién es: 给妈妈打电话 «llamar a mamá». 跟 es «con» o «a» en las acciones de dos: 跟朋友说话, 跟我来. 比 introduce con qué se compara: 他比我高; el adjetivo va al final y sin 很.', '[{"zh":"我晚上给你打电话。","pinyin":"Wǒ wǎnshang gěi nǐ dǎ diànhuà.","es":"Te llamo esta noche."},{"zh":"妈妈给我买了一件衣服。","pinyin":"Māma gěi wǒ mǎi le yí jiàn yīfu.","es":"Mamá me compró ropa."},{"zh":"我跟你说一件事。","pinyin":"Wǒ gēn nǐ shuō yí jiàn shì.","es":"Te voy a contar una cosa."},{"zh":"他比我高。","pinyin":"Tā bǐ wǒ gāo.","es":"Es más alto que yo."}]'::jsonb, array['给', '比', '跟1']::text[], 22, array['给', '跟', '比']::text[], '[{"wrong":"我说你一件事。","right":"我跟你说一件事。","why":"说 no lleva a la persona como objeto: «decirle algo a alguien» pide 跟 delante, 跟你说."},{"wrong":"他比我很高。","right":"他比我高。","why":"En una comparación con 比 el adjetivo va solo, sin 很."}]'::jsonb, '[{"hsk_level":1,"code":"2.7.2"},{"hsk_level":2,"code":"6.3.4"}]'::jsonb),
  (2, '2.8.4', '词类', '介词', '引出原因', '引出原因', 'Sujeto + 因为 + causa + predicado', '因为 también puede ir dentro de una sola frase, delante del verbo y con la causa justo detrás: 他因为生病没来. Así se da el motivo sin partir la frase en dos. La causa puede ser un nombre (因为这件事) o una frase corta. Si va detrás del verbo, necesita una pausa y forma otra frase: 他没来，因为他生病了.', '[{"zh":"他因为生病没来上课。","pinyin":"Tā yīnwèi shēngbìng méi lái shàngkè.","es":"No vino a clase porque estaba enfermo."},{"zh":"我因为这件事很不高兴。","pinyin":"Wǒ yīnwèi zhè jiàn shì hěn bù gāoxìng.","es":"Estoy muy disgustado por este asunto."},{"zh":"她因为工作很忙，没时间运动。","pinyin":"Tā yīnwèi gōngzuò hěn máng, méi shíjiān yùndòng.","es":"Como tiene mucho trabajo, no tiene tiempo para hacer deporte."},{"zh":"我们因为下雨没出去。","pinyin":"Wǒmen yīnwèi xià yǔ méi chūqu.","es":"No salimos por la lluvia."}]'::jsonb, array['因为1']::text[], 23, array['因为']::text[], '[{"wrong":"他没来上课因为生病。","right":"他因为生病没来上课。","why":"Sin pausa, 因为 y la causa van delante del verbo; detrás solo funcionan como otra frase: 他没来上课，因为他生病了."}]'::jsonb, '[{"hsk_level":2,"code":"6.4.3"}]'::jsonb),
  (2, '2.9.1', '词类', '连词', '连接词或短语', '连接词或短语', 'nombre / pronombre + 跟 + nombre / pronombre', '跟 puede unir dos nombres o pronombres, igual que 和: 我跟他 «él y yo». Solo une nombres, nunca dos verbos ni dos frases. Cuando después viene un verbo que vale para los dos, se suele poner 都 o 一起: 我跟他都是学生.', '[{"zh":"我跟他都是学生。","pinyin":"Wǒ gēn tā dōu shì xuésheng.","es":"Él y yo somos estudiantes."},{"zh":"爸爸跟妈妈都不在家。","pinyin":"Bàba gēn māma dōu bú zài jiā.","es":"Ni papá ni mamá están en casa."},{"zh":"我买了面包跟鸡蛋。","pinyin":"Wǒ mǎi le miànbāo gēn jīdàn.","es":"Compré pan y huevos."}]'::jsonb, array['跟2']::text[], 24, array['跟']::text[], '[{"wrong":"我吃了饭跟看了电视。","right":"我吃了饭，还看了电视。","why":"跟, como 和, solo une nombres; para encadenar dos acciones no sirve."}]'::jsonb, '[{"hsk_level":1,"code":"2.8.1"}]'::jsonb),
  (2, '2.9.2', '词类', '连词', '连接分句或者句子', '连接分句或者句子', '…，但是… · 虽然…，但是… · 那… · A 还是 B？ · 因为…，所以…', 'Estas palabras unen frases. 但是, o 但, introduce un contraste: «pero». 虽然 «aunque» va en la primera parte y se completa con 但是 en la segunda, cosa que en español sobraría. 那 al principio saca una conclusión de lo que acaba de decir el otro: «entonces». 还是 une dos opciones en una pregunta, «¿A o B?». 因为 presenta la causa y 所以 la consecuencia.', '[{"zh":"这件衣服很漂亮，但是太贵了。","pinyin":"Zhè jiàn yīfu hěn piàoliang, dànshì tài guì le.","es":"Esta ropa es muy bonita, pero demasiado cara."},{"zh":"虽然下雨了，但是他来了。","pinyin":"Suīrán xià yǔ le, dànshì tā lái le.","es":"Aunque llovía, vino."},{"zh":"“我不想去。”“那我们在家吧。”","pinyin":"“Wǒ bù xiǎng qù.” “Nà wǒmen zài jiā ba.”","es":"—No quiero ir. —Entonces quedémonos en casa."},{"zh":"你喝茶还是喝咖啡？","pinyin":"Nǐ hē chá háishi hē kāfēi?","es":"¿Tomas té o café?"},{"zh":"因为太累了，所以我没去。","pinyin":"Yīnwèi tài lèi le, suǒyǐ wǒ méi qù.","es":"Como estaba muy cansado, no fui."}]'::jsonb, array['但、但是、那、虽然、还是2、因为2、所以']::text[], 25, array['但', '虽然', '那', '还是', '所以']::text[], '[{"wrong":"虽然很贵，我买了。","right":"虽然很贵，但是我买了。","why":"虽然 pide su pareja 但是 en la segunda parte, aunque en español «aunque…, pero» sea incorrecto."},{"wrong":"你喝茶还是喝咖啡吗？","right":"你喝茶还是喝咖啡？","why":"Una pregunta con 还是 ya es pregunta; 吗 sobra."}]'::jsonb, '[{"hsk_level":2,"code":"6.4.1"},{"hsk_level":2,"code":"6.4.2"},{"hsk_level":2,"code":"6.4.3"}]'::jsonb),
  (2, '2.10.1', '词类', '助词', '结构助词', '结构助词', 'verbo + 得 + valoración · adjetivo + 地 + verbo', 'Los dos se pronuncian de y se distinguen por su sitio. 得 va detrás del verbo y presenta cómo sale la acción o hasta qué punto: 他说得很快. 地 va delante del verbo y convierte lo anterior en la manera de hacerlo, como el «-mente» español: 高兴地说. Si el verbo con 得 tiene objeto, se repite el verbo o se adelanta el objeto: 他汉语说得很好.', '[{"zh":"他说得很快。","pinyin":"Tā shuō de hěn kuài.","es":"Habla muy rápido."},{"zh":"你汉语说得真好！","pinyin":"Nǐ Hànyǔ shuō de zhēn hǎo!","es":"¡Qué bien hablas chino!"},{"zh":"她高兴地说：“谢谢！”","pinyin":"Tā gāoxìng de shuō: “Xièxie!”","es":"Dijo contenta: «¡Gracias!»."},{"zh":"我们慢慢地走吧。","pinyin":"Wǒmen mànmàn de zǒu ba.","es":"Vamos andando despacio."}]'::jsonb, array['得、地']::text[], 26, array['得', '地']::text[], '[{"wrong":"他说汉语得很好。","right":"他说汉语说得很好。","why":"得 va pegado al verbo; si hay objeto, se repite el verbo (说汉语说得) o se adelanta el objeto (汉语说得)."}]'::jsonb, '[{"hsk_level":1,"code":"2.9.1"},{"hsk_level":2,"code":"5.4.3"}]'::jsonb),
  (2, '2.10.2', '词类', '助词', '动态助词', '动态助词', 'verbo + 过 (experiencia) · verbo + 着 (estado que continúa)', '过 detrás del verbo cuenta una experiencia: algo que se ha hecho alguna vez, sin decir cuándo: 我去过中国. Se niega con 没…过. 着 indica que un estado se mantiene o que algo se hace a la vez que otra cosa: 门开着 «la puerta está abierta», 笑着说 «decir sonriendo». Los dos van pegados al verbo, antes del objeto.', '[{"zh":"我去过中国。","pinyin":"Wǒ qùguo Zhōngguó.","es":"He estado en China."},{"zh":"你吃过中国菜吗？","pinyin":"Nǐ chīguo Zhōngguó cài ma?","es":"¿Has probado la comida china?"},{"zh":"我没看过这个电影。","pinyin":"Wǒ méi kànguo zhège diànyǐng.","es":"No he visto esta película."},{"zh":"门开着。","pinyin":"Mén kāizhe.","es":"La puerta está abierta."},{"zh":"他笑着说：“没关系。”","pinyin":"Tā xiàozhe shuō: “Méi guānxi.”","es":"Dijo sonriendo: «No pasa nada»."}]'::jsonb, array['过', '着']::text[], 27, array['过', '着']::text[], '[{"wrong":"我不去过中国。","right":"我没去过中国。","why":"La experiencia con 过 se niega con 没, nunca con 不."}]'::jsonb, '[{"hsk_level":2,"code":"7.1.1"},{"hsk_level":2,"code":"7.1.2"}]'::jsonb),
  (2, '2.10.3', '词类', '助词', '语气助词', '语气助词', 'frase + 吧 / 呢 / 的 / 啊', 'Estas partículas finales dan el tono de la frase. 吧 detrás de una afirmación pide confirmación, como «¿verdad?»: 你是老师吧？ 呢 subraya un hecho que contradice lo esperado: 他还没来呢 «pues todavía no ha llegado». 的 al final da seguridad: 我会来的 «vendré, seguro». 啊 añade emoción o suaviza: 好啊！', '[{"zh":"你是老师吧？","pinyin":"Nǐ shì lǎoshī ba?","es":"Eres profesor, ¿verdad?"},{"zh":"他还没来呢。","pinyin":"Tā hái méi lái ne.","es":"Pues todavía no ha llegado."},{"zh":"我会来的。","pinyin":"Wǒ huì lái de.","es":"Vendré, seguro."},{"zh":"好啊，我们走吧。","pinyin":"Hǎo a, wǒmen zǒu ba.","es":"¡Vale, vámonos!"},{"zh":"今天天气真好啊！","pinyin":"Jīntiān tiānqì zhēn hǎo a!","es":"¡Qué buen tiempo hace hoy!"}]'::jsonb, array['呢4、吧2、的2、啊1']::text[], 28, array['吧', '呢', '的', '啊']::text[], '[{"wrong":"你是老师吧吗？","right":"你是老师吧？","why":"吧 ya convierte la frase en una pregunta de confirmación; no se junta con 吗."}]'::jsonb, '[{"hsk_level":1,"code":"2.9.3"}]'::jsonb),
  (2, '3.1.1', '短语', '结构类型', '基本结构类型', '基本结构类型', 'verbo + complemento de resultado / dirección: 看完, 听懂, 找到, 进来', 'El resultado de una acción se pega al verbo como un segundo elemento: 看完 «terminar de leer», 听懂 «entender lo que se oye», 找到 «encontrar». El primer verbo dice qué se hace y el segundo qué se consigue o hacia dónde va. Se niega con 没: 我没听懂. En español solemos usar otro verbo («encontrar» frente a «buscar»), por eso al principio se olvida el complemento.', '[{"zh":"我看完这本书了。","pinyin":"Wǒ kànwán zhè běn shū le.","es":"He terminado de leer este libro."},{"zh":"你说的我都听懂了。","pinyin":"Nǐ shuō de wǒ dōu tīngdǒng le.","es":"He entendido todo lo que has dicho."},{"zh":"我找到我的手机了。","pinyin":"Wǒ zhǎodào wǒ de shǒujī le.","es":"He encontrado mi móvil."},{"zh":"请进来！","pinyin":"Qǐng jìnlai!","es":"¡Pasa, por favor!"},{"zh":"我没听懂。","pinyin":"Wǒ méi tīngdǒng.","es":"No lo he entendido."}]'::jsonb, array['动补短语1']::text[], 29, array['完', '懂', '到', '进来']::text[], '[{"wrong":"我找我的手机了。","right":"我找到我的手机了。","why":"找 solo es «buscar»; para decir que lo has encontrado hace falta el resultado 到."},{"wrong":"我不听懂。","right":"我没听懂。","why":"Un verbo con resultado se niega con 没 cuando hablas de lo que pasó."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.1"},{"hsk_level":2,"code":"5.4.2"}]'::jsonb),
  (2, '3.1.2', '短语', '结构类型', '其他结构类型', '其他结构类型', '… + 的 (sin nombre) · V1 + O1 + V2 + O2 · 请 / 让 + persona + verbo', 'Tres construcciones muy frecuentes. Con 的 al final se puede omitir el nombre cuando ya se sabe de qué se habla: 这本书是我的, 我要大的. Dos verbos seguidos, sin conjunción, encadenan acciones y el segundo suele ser la finalidad: 去商店买东西 «ir a la tienda a comprar». En 请朋友来, la persona es a la vez quien recibe el primer verbo y quien hace el segundo.', '[{"zh":"这本书是我的。","pinyin":"Zhè běn shū shì wǒ de.","es":"Este libro es mío."},{"zh":"我要大的，不要小的。","pinyin":"Wǒ yào dà de, bú yào xiǎo de.","es":"Quiero el grande, no el pequeño."},{"zh":"我去商店买东西。","pinyin":"Wǒ qù shāngdiàn mǎi dōngxi.","es":"Voy a la tienda a comprar."},{"zh":"他坐飞机去中国。","pinyin":"Tā zuò fēijī qù Zhōngguó.","es":"Va a China en avión."},{"zh":"我请朋友来我家吃饭。","pinyin":"Wǒ qǐng péngyou lái wǒ jiā chī fàn.","es":"Invito a unos amigos a comer a casa."}]'::jsonb, array['（1）“的”字短语', '（2）连谓短语', '（3）兼语短语']::text[], 30, array['的', '去商店买', '坐飞机去', '请']::text[], '[{"wrong":"我去买东西在商店。","right":"我去商店买东西。","why":"Las acciones van en orden: primero adónde vas y luego qué haces allí; el lugar no se deja al final."}]'::jsonb, '[{"hsk_level":1,"code":"3.1.2"},{"hsk_level":1,"code":"5.3.4"},{"hsk_level":2,"code":"6.3.6"}]'::jsonb),
  (2, '3.2.1', '短语', '功能类型', '名词性短语', '名词性短语', '这 / 那 + número + clasificador + (descripción + 的) + nombre', 'Un grupo nominal funciona como un nombre: puede ser sujeto u objeto. Todo lo que describe al nombre va delante, en orden fijo: demostrativo, número, clasificador, descripción y, al final, el nombre: 那两本新书. Las descripciones largas llevan 的 (很好的朋友); las cortas y fijas, no (中国菜). En español la descripción suele ir detrás del nombre; en chino nunca.', '[{"zh":"那两本新书是我的。","pinyin":"Nà liǎng běn xīn shū shì wǒ de.","es":"Esos dos libros nuevos son míos."},{"zh":"我的老师是中国人。","pinyin":"Wǒ de lǎoshī shì Zhōngguó rén.","es":"Mi profesor es chino."},{"zh":"他是我很好的朋友。","pinyin":"Tā shì wǒ hěn hǎo de péngyou.","es":"Es un muy buen amigo mío."},{"zh":"我喜欢吃中国菜。","pinyin":"Wǒ xǐhuan chī Zhōngguó cài.","es":"Me gusta la comida china."}]'::jsonb, null, 31, array['两本新书', '我的老师', '很好的朋友', '中国菜']::text[], '[{"wrong":"我有朋友很好。","right":"我有很好的朋友。","why":"La descripción va delante del nombre con 的; detrás, como en «amigos muy buenos», no funciona."}]'::jsonb, '[{"hsk_level":1,"code":"4.4"}]'::jsonb),
  (2, '3.2.2', '短语', '功能类型', '动词性短语', '动词性短语', '(adverbio) + verbo + objeto / complemento', 'Un grupo verbal es un verbo con lo que lo acompaña: adverbios delante (每天跑步) y objeto o complemento detrás (看书, 看完). Además de predicado, puede ser sujeto u objeto sin cambiar de forma, porque el chino no tiene infinitivo: 学汉语很有意思 «estudiar chino es interesante», 我喜欢看书 «me gusta leer». Si el predicado es un adjetivo, no se pone 是 en medio.', '[{"zh":"学汉语很有意思。","pinyin":"Xué Hànyǔ hěn yǒu yìsi.","es":"Estudiar chino es muy interesante."},{"zh":"我喜欢看书。","pinyin":"Wǒ xǐhuan kàn shū.","es":"Me gusta leer."},{"zh":"每天跑步对身体好。","pinyin":"Měi tiān pǎobù duì shēntǐ hǎo.","es":"Correr todos los días es bueno para la salud."},{"zh":"他不想打电话。","pinyin":"Tā bù xiǎng dǎ diànhuà.","es":"No quiere llamar por teléfono."}]'::jsonb, null, 32, array['学汉语', '看书', '跑步', '打电话']::text[], '[{"wrong":"学汉语是很有意思。","right":"学汉语很有意思。","why":"Cuando el predicado es un adjetivo no se pone 是: el grupo verbal va seguido directamente de 很 + adjetivo."}]'::jsonb, '[{"hsk_level":1,"code":"4.2"}]'::jsonb),
  (2, '3.2.3', '短语', '功能类型', '形容词性短语', '形容词性短语', '很 / 非常 / 不太 + adjetivo · 太 + adjetivo + 了', 'Un grupo adjetival es un adjetivo con un adverbio de grado: 很好, 非常贵, 不太好, 太大了. Hace de predicado sin 是 (这个很贵) y, con 的, describe a un nombre (很贵的衣服). 不太 suaviza la negación, «no muy». 太…了 dice que algo pasa de la medida, «demasiado».', '[{"zh":"这个菜非常好吃。","pinyin":"Zhège cài fēicháng hǎochī.","es":"Este plato está riquísimo."},{"zh":"这件衣服太大了。","pinyin":"Zhè jiàn yīfu tài dà le.","es":"Esta ropa es demasiado grande."},{"zh":"今天天气不太好。","pinyin":"Jīntiān tiānqì bú tài hǎo.","es":"Hoy no hace muy buen tiempo."},{"zh":"我买了一件很贵的衣服。","pinyin":"Wǒ mǎi le yí jiàn hěn guì de yīfu.","es":"Me compré una ropa muy cara."}]'::jsonb, null, 33, array['很', '非常', '太', '不太']::text[], '[{"wrong":"这个菜是很好吃。","right":"这个菜很好吃。","why":"El adjetivo hace de predicado por sí solo; el «es» español no se traduce con 是."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.1"},{"hsk_level":1,"code":"4.2"}]'::jsonb),
  (2, '3.3.1', '短语', '固定短语', '其他', '其他', 'A、B + 什么的', '什么的 cierra una lista de ejemplos, como «y cosas así» o «etcétera». Va detrás del último elemento, sin 和 delante, y es propio de la conversación. Puede cerrar una lista de cosas (面包、鸡蛋什么的) o de actividades (看书、看电影什么的).', '[{"zh":"我买了面包、鸡蛋什么的。","pinyin":"Wǒ mǎi le miànbāo, jīdàn shénmede.","es":"Compré pan, huevos y cosas así."},{"zh":"星期天我喜欢看书、看电影什么的。","pinyin":"Xīngqītiān wǒ xǐhuan kàn shū, kàn diànyǐng shénmede.","es":"Los domingos me gusta leer, ver películas y cosas así."},{"zh":"桌子上有手机、书什么的。","pinyin":"Zhuōzi shang yǒu shǒujī, shū shénmede.","es":"En la mesa hay un móvil, libros y esas cosas."}]'::jsonb, array['什么的']::text[], 34, array['什么的']::text[], '[{"wrong":"我买了面包、鸡蛋和什么的。","right":"我买了面包、鸡蛋什么的。","why":"什么的 ya cierra la lista; no se pone 和 delante como en «y cosas así»."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.1"}]'::jsonb),
  (2, '4.1', '固定格式', '', null, '', '还是 + V + 吧 · 要 / 快要 / 就要 + V + 了 · 都 + … + 了', 'Tres moldes fijos. 还是…吧 recomienda la mejor opción después de pensarlo: 还是回家吧 «mejor volvamos a casa». 要…了, 快要…了 y 就要…了 anuncian que algo va a pasar pronto; si se dice cuándo (明天, 下个星期), solo vale 就要. 都…了 subraya que ya es tarde o que ya es mucho: 都十二点了.', '[{"zh":"太晚了，我们还是回家吧。","pinyin":"Tài wǎn le, wǒmen háishi huí jiā ba.","es":"Es muy tarde; mejor volvamos a casa."},{"zh":"火车快要开了。","pinyin":"Huǒchē kuàiyào kāi le.","es":"El tren está a punto de salir."},{"zh":"明天就要考试了。","pinyin":"Míngtiān jiù yào kǎoshì le.","es":"Mañana ya es el examen."},{"zh":"都十二点了，快睡觉吧。","pinyin":"Dōu shí’èr diǎn le, kuài shuìjiào ba.","es":"Ya son las doce; vete a dormir."}]'::jsonb, array['还是……吧', '要/快要/就要……了', '都……了']::text[], 35, array['还是', '快要', '就要', '都']::text[], '[{"wrong":"明天快要考试了。","right":"明天就要考试了。","why":"Con un momento concreto (明天) se usa 就要; 快要 no admite una indicación de tiempo."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.3"},{"hsk_level":2,"code":"2.7.7"}]'::jsonb),
  (2, '5.1', '句子成分', '主语', null, '主语', 'Objeto (como sujeto) + verbo + resultado / 了', 'Lo que recibe la acción puede ir al principio, como sujeto, sin ninguna marca de pasiva: 饭做好了 «la comida está hecha». Se usa cuando importa la cosa y no quién lo hizo, porque ya se sabe o da igual. El verbo casi siempre lleva un resultado o 了. En español equivale a una pasiva refleja («se ha agotado») o a «está hecho».', '[{"zh":"饭做好了，快来吃吧。","pinyin":"Fàn zuòhǎo le, kuài lái chī ba.","es":"La comida está lista, venid a comer."},{"zh":"衣服洗好了吗？","pinyin":"Yīfu xǐhǎo le ma?","es":"¿Ya está lavada la ropa?"},{"zh":"那本书卖完了。","pinyin":"Nà běn shū màiwán le.","es":"Ese libro se ha agotado."},{"zh":"你的手机找到了。","pinyin":"Nǐ de shǒujī zhǎodào le.","es":"Tu móvil ha aparecido."}]'::jsonb, array['受事主语']::text[], 36, array['做好了', '洗好了', '卖完了', '找到了']::text[], '[{"wrong":"饭被做好了。","right":"饭做好了。","why":"No hace falta ninguna marca de pasiva: la cosa va delante y el verbo detrás. 被 se reserva para cuando hay que señalar quién lo hizo o algo salió mal."}]'::jsonb, '[{"hsk_level":1,"code":"4.1"}]'::jsonb),
  (2, '5.2', '句子成分', '谓语', null, '谓语', 'Sujeto + fecha / edad / precio / hora', 'Con fechas, horas, edades y precios, el predicado puede ser directamente un grupo nominal, sin verbo: 今天星期三, 他二十岁, 这个一百块. En español siempre hace falta un verbo («es», «tiene», «cuesta»); en chino no. Para negarlo, en cambio, sí aparece 是: 今天不是星期三.', '[{"zh":"今天星期三。","pinyin":"Jīntiān xīngqīsān.","es":"Hoy es miércoles."},{"zh":"我弟弟八岁。","pinyin":"Wǒ dìdi bā suì.","es":"Mi hermano pequeño tiene ocho años."},{"zh":"这件衣服一百块。","pinyin":"Zhè jiàn yīfu yìbǎi kuài.","es":"Esta ropa cuesta cien yuanes."},{"zh":"现在三点半。","pinyin":"Xiànzài sān diǎn bàn.","es":"Son las tres y media."},{"zh":"今天不是星期三。","pinyin":"Jīntiān bú shì xīngqīsān.","es":"Hoy no es miércoles."}]'::jsonb, array['名词性短语作谓语']::text[], 37, array['星期', '岁', '块', '点']::text[], '[{"wrong":"我弟弟有八岁。","right":"我弟弟八岁。","why":"La edad no se «tiene»: va directamente detrás del sujeto, sin 有."}]'::jsonb, '[{"hsk_level":1,"code":"4.2"},{"hsk_level":1,"code":"7.2"}]'::jsonb),
  (2, '5.3', '句子成分', '定语', null, '定语', '(sujeto +) verbo (+ …) + 的 + nombre', 'Una acción, o una frase entera con su sujeto, puede describir a un nombre si va delante con 的: 妈妈做的菜 «la comida que hace mamá», 来的人 «la gente que viene». Equivale a las oraciones con «que» del español, pero en orden inverso: primero la descripción y después el nombre, sin ningún «que».', '[{"zh":"妈妈做的菜很好吃。","pinyin":"Māma zuò de cài hěn hǎochī.","es":"La comida que hace mamá está muy rica."},{"zh":"这是我昨天买的书。","pinyin":"Zhè shì wǒ zuótiān mǎi de shū.","es":"Este es el libro que compré ayer."},{"zh":"今天来的人很多。","pinyin":"Jīntiān lái de rén hěn duō.","es":"Hoy ha venido mucha gente."},{"zh":"你说的话我都听懂了。","pinyin":"Nǐ shuō de huà wǒ dōu tīngdǒng le.","es":"He entendido todo lo que has dicho."}]'::jsonb, array['动词或动词性短语、主谓短语作定语']::text[], 38, array['做的菜', '买的书', '来的人', '说的话']::text[], '[{"wrong":"这是书我昨天买的。","right":"这是我昨天买的书。","why":"La descripción va delante del nombre; el «que» de «el libro que compré» no existe y el orden se invierte."}]'::jsonb, '[{"hsk_level":1,"code":"4.4"},{"hsk_level":2,"code":"3.2.1"}]'::jsonb),
  (2, '5.4.1', '句子成分', '补语', '结果补语1', '结果补语1', 'verbo + 完 / 好 / 懂 / 会 / 错', 'Estos complementos dicen cómo acaba la acción. 完 es «terminar» (吃完), 好 «dejar algo hecho y listo» (准备好), 懂 «entender» (听懂, 看懂), 会 «aprender a hacer algo» (学会) y 错 «hacerlo mal» (写错, 说错). Se niegan con 没 y suelen llevar 了 cuando ya ha pasado: 我没听懂, 我学会了.', '[{"zh":"我吃完了。","pinyin":"Wǒ chīwán le.","es":"Ya he terminado de comer."},{"zh":"我准备好了。","pinyin":"Wǒ zhǔnbèi hǎo le.","es":"Ya estoy listo."},{"zh":"这个字我写错了。","pinyin":"Zhège zì wǒ xiěcuò le.","es":"Este carácter lo he escrito mal."},{"zh":"你看懂了吗？","pinyin":"Nǐ kàndǒng le ma?","es":"¿Lo has entendido?"},{"zh":"我学会做中国菜了。","pinyin":"Wǒ xuéhuì zuò Zhōngguó cài le.","es":"He aprendido a hacer comida china."}]'::jsonb, array['动词+错/懂/好/会/完']::text[], 39, array['完', '好', '懂', '会', '错']::text[], '[{"wrong":"这个字我写得错了。","right":"这个字我写错了。","why":"El resultado 错 se pega directamente al verbo; 得 sirve para valorar cómo se hace, no para decir cómo acaba."}]'::jsonb, '[{"hsk_level":2,"code":"3.1.1"}]'::jsonb),
  (2, '5.4.2', '句子成分', '补语', '趋向补语1', '趋向补语1', 'verbo + 来 / 去 · verbo + 进 / 出 / 回 / 过 / 上 / 下 (+ 来 / 去)', 'Detrás del verbo se indica la dirección del movimiento. 来 es hacia quien habla y 去, alejándose de él: 进来 «entra aquí», 出去 «sal fuera». 进, 出, 回, 过, 上 y 下 dan la dirección concreta y se combinan con 来 o 去: 走过来, 跑出去. Si hay un lugar, va entre la dirección y 来 / 去: 回家去.', '[{"zh":"外面冷，快进来吧。","pinyin":"Wàimiàn lěng, kuài jìnlai ba.","es":"Fuera hace frío, entra."},{"zh":"他跑出去了。","pinyin":"Tā pǎo chūqu le.","es":"Salió corriendo."},{"zh":"妈妈什么时候回来？","pinyin":"Māma shénme shíhou huílai?","es":"¿Cuándo vuelve mamá?"},{"zh":"你走过来，我看看。","pinyin":"Nǐ zǒu guòlai, wǒ kànkan.","es":"Acércate, que te vea."}]'::jsonb, array['简单趋向补语的趋向意义用法：（1）动词+来/去', '（2）动词+上/下/进/出/过/回', '复合趋向补语的趋向意义用法：动词+出来/出去/过来/过去/回来/回去/进来/进去/起来/上来/上去/下来/下去']::text[], 40, array['进来', '出去', '回来', '过来']::text[], '[{"wrong":"他回去家了。","right":"他回家去了。","why":"El lugar va entre el verbo de dirección y 来 / 去: 回家去, no detrás de 去."}]'::jsonb, '[{"hsk_level":2,"code":"3.1.1"}]'::jsonb),
  (2, '5.4.3', '句子成分', '补语', '状态补语1', '状态补语1', 'verbo + 得 + (很 / 非常 / 不) + adjetivo', 'Para valorar cómo se hace una acción, el adjetivo va detrás del verbo con 得: 他跑得很快 «corre muy rápido». Describe lo habitual o lo que ya pasó; no sirve para dar órdenes. La negación va detrás de 得, sobre la valoración: 跑得不快. Si el verbo tiene objeto, se repite el verbo: 唱歌唱得很好.', '[{"zh":"他跑得很快。","pinyin":"Tā pǎo de hěn kuài.","es":"Corre muy rápido."},{"zh":"你今天来得很早。","pinyin":"Nǐ jīntiān lái de hěn zǎo.","es":"Hoy has venido muy pronto."},{"zh":"她唱歌唱得非常好。","pinyin":"Tā chàng gē chàng de fēicháng hǎo.","es":"Canta muy bien."},{"zh":"我昨天睡得不太好。","pinyin":"Wǒ zuótiān shuì de bú tài hǎo.","es":"Ayer no dormí muy bien."}]'::jsonb, array['动词+得+形容词性短语']::text[], 41, array['得']::text[], '[{"wrong":"他不跑得快。","right":"他跑得不快。","why":"La negación va detrás de 得, sobre la valoración; no delante del verbo."}]'::jsonb, '[{"hsk_level":2,"code":"2.10.1"}]'::jsonb),
  (2, '5.4.4', '句子成分', '补语', '数量补语2', '数量补语2', 'verbo + (了) + duración (+ objeto) · adjetivo + cantidad', 'La duración de una acción va detrás del verbo: 我学了两年汉语, 他睡了八个小时. Un objeto común se coloca detrás de la duración (两年汉语); un pronombre, delante (等了你半个小时). Detrás de un adjetivo, una cantidad expresa la diferencia: 他比我大两岁 «me lleva dos años». En español la duración puede abrir la frase; en chino no.', '[{"zh":"我学了两年汉语。","pinyin":"Wǒ xué le liǎng nián Hànyǔ.","es":"Estudié chino durante dos años."},{"zh":"他每天睡八个小时。","pinyin":"Tā měi tiān shuì bā gè xiǎoshí.","es":"Duerme ocho horas al día."},{"zh":"我等了你半个小时。","pinyin":"Wǒ děng le nǐ bàn gè xiǎoshí.","es":"Te he esperado media hora."},{"zh":"他比我大两岁。","pinyin":"Tā bǐ wǒ dà liǎng suì.","es":"Me lleva dos años."},{"zh":"这件比那件贵一百块。","pinyin":"Zhè jiàn bǐ nà jiàn guì yìbǎi kuài.","es":"Esta cuesta cien yuanes más que aquella."}]'::jsonb, array['（1）表示动作持续的时间', '（2）形容词+数量补语']::text[], 42, array['年', '小时', '岁', '块']::text[], '[{"wrong":"我两年学了汉语。","right":"我学了两年汉语。","why":"La duración va detrás del verbo, no delante como en «dos años estudié chino»."}]'::jsonb, '[{"hsk_level":1,"code":"4.6.1"},{"hsk_level":2,"code":"6.3.4"}]'::jsonb),
  (2, '6.1.1', '句子的类型', '句型', '单句', '单句', 'Sujeto + [sujeto 2 + predicado]', 'El predicado es a su vez una frase pequeña con su propio sujeto. En 他身体很好 se habla de «él» y, dentro de él, de su salud: «él está bien de salud». El primer sujeto es el tema y el segundo, la parte concreta de la que se dice algo. Es la forma normal de hablar de salud, aspecto o rasgos de algo: 我头疼, 这个饭馆菜很好吃. No hace falta 有 ni 的.', '[{"zh":"他身体很好。","pinyin":"Tā shēntǐ hěn hǎo.","es":"Él está bien de salud."},{"zh":"我今天头疼。","pinyin":"Wǒ jīntiān tóu téng.","es":"Hoy me duele la cabeza."},{"zh":"这个饭馆菜很好吃。","pinyin":"Zhège fànguǎn cài hěn hǎochī.","es":"En este restaurante la comida está muy rica."},{"zh":"我工作很忙。","pinyin":"Wǒ gōngzuò hěn máng.","es":"Estoy muy ocupado con el trabajo."},{"zh":"我妈妈身体不太好。","pinyin":"Wǒ māma shēntǐ bú tài hǎo.","es":"Mi madre no está muy bien de salud."}]'::jsonb, array['主谓句4：主谓谓语句']::text[], 43, array['身体', '头疼', '菜很好吃', '工作很忙']::text[], '[{"wrong":"我有头疼。","right":"我头疼。","why":"En chino no se «tiene» dolor de cabeza: la parte del cuerpo es el sujeto de su propio predicado."}]'::jsonb, '[{"hsk_level":1,"code":"3.1.1"}]'::jsonb),
  (2, '6.2.1', '句子的类型', '句类', '疑问句', '疑问句', '(是) A 还是 B？', 'Para preguntar entre dos opciones se unen con 还是: 你要大的还是小的？ La pregunta ya está hecha, así que no lleva 吗. Si las opciones son acciones, se repite el verbo (你今天去还是明天去？) y se puede poner 是 delante de la primera. En las afirmaciones la «o» no es 还是, sino 或者.', '[{"zh":"你要大的还是小的？","pinyin":"Nǐ yào dà de háishi xiǎo de?","es":"¿Quieres el grande o el pequeño?"},{"zh":"你今天去还是明天去？","pinyin":"Nǐ jīntiān qù háishi míngtiān qù?","es":"¿Vas hoy o mañana?"},{"zh":"他是老师还是学生？","pinyin":"Tā shì lǎoshī háishi xuésheng?","es":"¿Es profesor o estudiante?"},{"zh":"你是坐地铁来的还是打车来的？","pinyin":"Nǐ shì zuò dìtiě lái de háishi dǎchē lái de?","es":"¿Has venido en metro o en taxi?"}]'::jsonb, array['用“还是”连接的选择问句']::text[], 44, array['还是']::text[], '[{"wrong":"你喝茶或者咖啡？","right":"你喝茶还是咖啡？","why":"En una pregunta entre dos opciones la «o» es 还是; 或者 es la «o» de las afirmaciones."}]'::jsonb, '[{"hsk_level":1,"code":"5.2.2"},{"hsk_level":2,"code":"2.9.2"}]'::jsonb),
  (2, '6.2.2', '句子的类型', '句类', '祈使句', '祈使句', '(你 / 请) + 别 + verbo (+ 了 / 吧)', 'Una orden negativa se forma con 别 delante del verbo: 别走. Con 了 al final pide dejar algo que ya está pasando: 别玩手机了 «deja el móvil». Para sonar más amable se pone 请 delante: 请别在这儿说话. 不要 expresa lo mismo con un tono algo más firme; con 不 solo no se puede prohibir.', '[{"zh":"别玩手机了，快吃饭吧。","pinyin":"Bié wán shǒujī le, kuài chī fàn ba.","es":"Deja el móvil y come."},{"zh":"请别在这儿说话。","pinyin":"Qǐng bié zài zhèr shuōhuà.","es":"Por favor, no habléis aquí."},{"zh":"别忘了明天的考试。","pinyin":"Bié wàng le míngtiān de kǎoshì.","es":"No olvides el examen de mañana."},{"zh":"你别走，我们一起吃饭吧。","pinyin":"Nǐ bié zǒu, wǒmen yìqǐ chī fàn ba.","es":"No te vayas, comamos juntos."}]'::jsonb, array['用“别”的祈使句']::text[], 45, array['别']::text[], '[{"wrong":"你不说话！","right":"你别说话！","why":"Con 不 solo se describe lo que alguien hace; para prohibir se usa 别 o 不要."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.5"},{"hsk_level":1,"code":"5.2.3"}]'::jsonb),
  (2, '6.3.1', '句子的类型', '特殊句式', '“是”字句2', '“是”字句2', 'Sujeto + 是 + descripción + 的 · 不是…，是…', 'Además de identificar (我是学生), 是 sirve para explicar cómo es algo: 这本书是新的, 我的手机是黑色的. La descripción suele cerrar con 的 porque se omite el nombre: «es (uno) nuevo». También aclara o corrige una situación: 我不是不想去，是没有时间 «no es que no quiera ir, es que no tengo tiempo».', '[{"zh":"这本书是新的。","pinyin":"Zhè běn shū shì xīn de.","es":"Este libro es nuevo."},{"zh":"我的手机是黑色的。","pinyin":"Wǒ de shǒujī shì hēisè de.","es":"Mi móvil es negro."},{"zh":"我不是不想去，是没有时间。","pinyin":"Wǒ bú shì bù xiǎng qù, shì méiyǒu shíjiān.","es":"No es que no quiera ir, es que no tengo tiempo."},{"zh":"这件衣服是妈妈的。","pinyin":"Zhè jiàn yīfu shì māma de.","es":"Esta ropa es de mamá."}]'::jsonb, array['表示说明或特征']::text[], 46, array['是']::text[], '[{"wrong":"这本书是新。","right":"这本书是新的。","why":"Si describes con 是 + adjetivo, cierra con 的 (是新的); sin 是 basta con 很: 这本书很新."}]'::jsonb, '[{"hsk_level":1,"code":"5.3.1"}]'::jsonb),
  (2, '6.3.2', '句子的类型', '特殊句式', '“有”字句2', '“有”字句2', 'Sujeto + 有 + cantidad / B (+ 这么 / 那么) + adjetivo', '有 seguido de una medida indica que algo llega a ella: 从我家到学校有一个小时 «hay una hora», 他有二十岁了 «ya tiene sus veinte años». Con otra persona o cosa compara si se alcanza su nivel: 你有他这么高吗？ «¿eres tan alto como él?». En español usamos «medir», «llegar a» o «tan… como»; en chino basta con 有.', '[{"zh":"你有他这么高吗？","pinyin":"Nǐ yǒu tā zhème gāo ma?","es":"¿Eres tan alto como él?"},{"zh":"他今年有二十岁了吧？","pinyin":"Tā jīnnián yǒu èrshí suì le ba?","es":"Este año ya tiene sus veinte, ¿no?"},{"zh":"这个房间有那个房间大吗？","pinyin":"Zhège fángjiān yǒu nàge fángjiān dà ma?","es":"¿Esta habitación es tan grande como aquella?"},{"zh":"从我家到学校有一个小时。","pinyin":"Cóng wǒ jiā dào xuéxiào yǒu yí gè xiǎoshí.","es":"De mi casa al colegio hay una hora."}]'::jsonb, array['表示达到']::text[], 47, array['有']::text[], '[{"wrong":"你是他这么高吗？","right":"你有他这么高吗？","why":"Para preguntar si algo llega a la medida de otro se usa 有, no 是."}]'::jsonb, '[{"hsk_level":1,"code":"5.3.2"},{"hsk_level":2,"code":"6.3.4"}]'::jsonb),
  (2, '6.3.3', '句子的类型', '特殊句式', '存现句2', '存现句2', 'lugar + verbo + 着 + (número + clasificador) + nombre', 'Para describir qué hay en un sitio y en qué postura, la frase empieza por el lugar y sigue con un verbo con 着: 门口站着一个人 «en la puerta hay un hombre de pie». Lo que hay va al final, casi siempre con número y clasificador, y el lugar no lleva 在 delante. Dice más que 有: además de qué hay, cuenta cómo está.', '[{"zh":"门口站着一个人。","pinyin":"Ménkǒu zhànzhe yí gè rén.","es":"En la puerta hay un hombre de pie."},{"zh":"椅子上坐着一个孩子。","pinyin":"Yǐzi shang zuòzhe yí gè háizi.","es":"En la silla está sentado un niño."},{"zh":"书上写着我的名字。","pinyin":"Shū shang xiězhe wǒ de míngzi.","es":"En el libro está escrito mi nombre."},{"zh":"这个房间里住着两个学生。","pinyin":"Zhège fángjiān li zhùzhe liǎng gè xuésheng.","es":"En esta habitación viven dos estudiantes."}]'::jsonb, array['处所+动词+着(+数量短语)+名词']::text[], 48, array['着']::text[], '[{"wrong":"在门口站着一个人。","right":"门口站着一个人。","why":"En esta construcción el lugar abre la frase sin 在."}]'::jsonb, '[{"hsk_level":1,"code":"5.3.3"},{"hsk_level":2,"code":"7.1.1"}]'::jsonb),
  (2, '6.3.4', '句子的类型', '特殊句式', '比较句1', '比较句1', 'A 比 B + adjetivo (+ diferencia) · A 没有 B (那么) + adjetivo · A + V 得 + 比 B + adjetivo', 'A 比 B + adjetivo dice que A supera a B: 今天比昨天冷. La diferencia va detrás del adjetivo: 高一点儿, 贵多了. Para decir que A no llega a B se usa 没有: 我没有他那么高. Con una acción, 比 va detrás de 得 o delante del verbo: 他跑得比我快. En una comparación el adjetivo nunca lleva 很 ni 非常.', '[{"zh":"今天比昨天冷。","pinyin":"Jīntiān bǐ zuótiān lěng.","es":"Hoy hace más frío que ayer."},{"zh":"他比我高一点儿。","pinyin":"Tā bǐ wǒ gāo yìdiǎnr.","es":"Es un poco más alto que yo."},{"zh":"这个比那个贵多了。","pinyin":"Zhège bǐ nàge guì duō le.","es":"Este es mucho más caro que aquel."},{"zh":"我没有他那么高。","pinyin":"Wǒ méiyǒu tā nàme gāo.","es":"No soy tan alto como él."},{"zh":"他跑得比我快。","pinyin":"Tā pǎo de bǐ wǒ kuài.","es":"Corre más rápido que yo."}]'::jsonb, array['（1）A比B+形容词', '（2）A比B+形容词+数量补语/程度补语', '（3）A有/没有B（+这么/那么）+形容词', '（4）A比B+动词+得+形容词/A+动词+得+比+B+形容词']::text[], 49, array['比', '没有']::text[], '[{"wrong":"我比他不高。","right":"我没有他高。","why":"Para decir que A no supera a B no se pone 不 detrás de 比: se usa 没有."},{"wrong":"今天比昨天很冷。","right":"今天比昨天冷多了。","why":"Con 比 el adjetivo no lleva 很; la diferencia se expresa detrás: 冷多了, 冷一点儿."}]'::jsonb, '[{"hsk_level":2,"code":"2.8.3"},{"hsk_level":2,"code":"5.4.4"}]'::jsonb),
  (2, '6.3.5', '句子的类型', '特殊句式', '“是……的”句1', '“是……的”句1', 'Sujeto + 是 + (cuándo / dónde / cómo / quién) + verbo + 的', 'Cuando ya se sabe que algo pasó y lo que interesa es un detalle (cuándo, dónde, cómo o quién), ese detalle se encierra entre 是 y 的: 我是昨天来的 «vine ayer, no otro día». Solo se usa con hechos pasados y no lleva 了. En la afirmación 是 a veces se omite, pero en la negación es obligatorio: 我不是坐飞机来的.', '[{"zh":"我是昨天来的。","pinyin":"Wǒ shì zuótiān lái de.","es":"Vine ayer."},{"zh":"“你是怎么来的？”“我是坐地铁来的。”","pinyin":"“Nǐ shì zěnme lái de?” “Wǒ shì zuò dìtiě lái de.”","es":"—¿Cómo has venido? —En metro."},{"zh":"我是在中国学的汉语。","pinyin":"Wǒ shì zài Zhōngguó xué de Hànyǔ.","es":"Aprendí chino en China."},{"zh":"这个菜是谁做的？","pinyin":"Zhège cài shì shéi zuò de?","es":"¿Quién ha hecho este plato?"},{"zh":"我不是坐飞机来的。","pinyin":"Wǒ bú shì zuò fēijī lái de.","es":"No he venido en avión."}]'::jsonb, array['强调时间、地点、方式、动作者']::text[], 50, array['是昨天', '是坐', '是在', '是谁']::text[], '[{"wrong":"我是昨天来了。","right":"我是昨天来的。","why":"La construcción 是…的 cierra con 的; 了 no entra en ella."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.1"}]'::jsonb),
  (2, '6.3.6', '句子的类型', '特殊句式', '兼语句1', '兼语句1', 'Sujeto + 请 / 叫 / 让 + persona + verbo (+ objeto)', 'Con 请, 叫 y 让 alguien hace que otra persona haga algo. Esa persona va justo detrás del primer verbo y es quien realiza la segunda acción: 妈妈让我去买菜 «mamá me pide que vaya a comprar». 请 es invitar o pedir con cortesía; 叫 y 让 son mandar o permitir, más directos. En español se usa «que + subjuntivo»; en chino no hay ningún «que».', '[{"zh":"我请你吃饭。","pinyin":"Wǒ qǐng nǐ chī fàn.","es":"Te invito a comer."},{"zh":"妈妈让我去买菜。","pinyin":"Māma ràng wǒ qù mǎi cài.","es":"Mamá me ha pedido que vaya a comprar comida."},{"zh":"老师叫我们明天八点来。","pinyin":"Lǎoshī jiào wǒmen míngtiān bā diǎn lái.","es":"El profesor nos ha dicho que vengamos mañana a las ocho."},{"zh":"他不让我看他的手机。","pinyin":"Tā bú ràng wǒ kàn tā de shǒujī.","es":"No me deja mirar su móvil."}]'::jsonb, array['表使令：主语+请/叫/让……+宾语1+动词+宾语2']::text[], 51, array['请', '叫', '让']::text[], '[{"wrong":"妈妈让了我去买菜。","right":"妈妈让我去买菜了。","why":"了 no va detrás de 让 o 请: se pone al final de la frase o detrás del segundo verbo."}]'::jsonb, '[{"hsk_level":2,"code":"3.1.2"}]'::jsonb),
  (2, '6.3.7', '句子的类型', '特殊句式', '双宾语句2', '双宾语句2', 'Sujeto + verbo + 给 + persona + cosa', 'Con verbos que hacen pasar algo de una persona a otra, como 送 «regalar» o 卖 «vender», se pone 给 detrás del verbo y luego la persona y la cosa: 他送给我一本书 «me regaló un libro». El orden es fijo: primero quien recibe, después lo que recibe, sin ninguna preposición más. 给 deja claro hacia quién va la cosa.', '[{"zh":"他送给我一本书。","pinyin":"Tā sòng gěi wǒ yì běn shū.","es":"Me regaló un libro."},{"zh":"我想送给妈妈一件衣服。","pinyin":"Wǒ xiǎng sòng gěi māma yí jiàn yīfu.","es":"Quiero regalarle una prenda a mamá."},{"zh":"他卖给我一个手机。","pinyin":"Tā mài gěi wǒ yí gè shǒujī.","es":"Me vendió un móvil."},{"zh":"这本书是朋友送给我的。","pinyin":"Zhè běn shū shì péngyou sòng gěi wǒ de.","es":"Este libro me lo regaló un amigo."}]'::jsonb, array['主语+动词+给+宾语1+宾语2']::text[], 52, array['给']::text[], '[{"wrong":"他送给一本书我。","right":"他送给我一本书。","why":"Detrás de 给 va primero la persona y después la cosa."}]'::jsonb, '[{"hsk_level":1,"code":"5.3.5"},{"hsk_level":2,"code":"2.8.3"}]'::jsonb),
  (2, '6.4.1', '句子的类型', '复句', '选择复句', '选择复句', '(是) A，还是 B？ · 不知道 + (是) A 还是 B', 'Cuando las dos opciones son frases enteras, se separan con una coma: 你是今天去，还是明天去？ La primera parte puede llevar 是 para anunciar la elección. La misma duda puede ir dentro de otra frase, con verbos como 知道 o 想, y entonces no es una pregunta: 我不知道他是今天来还是明天来 «no sé si viene hoy o mañana». Como en toda pregunta con 还是, no se añade 吗.', '[{"zh":"你是今天去，还是明天去？","pinyin":"Nǐ shì jīntiān qù, háishi míngtiān qù?","es":"¿Vas hoy o mañana?"},{"zh":"我们是坐地铁，还是打车？","pinyin":"Wǒmen shì zuò dìtiě, háishi dǎchē?","es":"¿Vamos en metro o cogemos un taxi?"},{"zh":"我不知道他是今天来还是明天来。","pinyin":"Wǒ bù zhīdào tā shì jīntiān lái háishi míngtiān lái.","es":"No sé si viene hoy o mañana."},{"zh":"你想在家吃饭，还是去饭馆吃？","pinyin":"Nǐ xiǎng zài jiā chī fàn, háishi qù fànguǎn chī?","es":"¿Quieres comer en casa o ir a un restaurante?"}]'::jsonb, array['（是）……，还是……']::text[], 53, array['还是']::text[], '[{"wrong":"我不知道他今天来或者明天来。","right":"我不知道他是今天来还是明天来。","why":"Una duda entre dos opciones, aunque vaya dentro de otra frase, se expresa con 还是; 或者 solo dice que vale cualquiera."}]'::jsonb, '[{"hsk_level":2,"code":"6.2.1"},{"hsk_level":2,"code":"2.9.2"}]'::jsonb),
  (2, '6.4.2', '句子的类型', '复句', '转折复句', '转折复句', '虽然 + lo que se concede，但是 + lo que pasa igualmente', '虽然 presenta un hecho que se reconoce y 但是 (o 但) lo que ocurre a pesar de él: 虽然很贵，但是很好吃. En chino se usan los dos juntos, al contrario que en español, donde «aunque…, pero» es incorrecto. 虽然 va en la primera parte, delante o detrás del sujeto; 但是 abre siempre la segunda.', '[{"zh":"虽然很贵，但是很好吃。","pinyin":"Suīrán hěn guì, dànshì hěn hǎochī.","es":"Aunque es caro, está muy rico."},{"zh":"他虽然很累，但是还在工作。","pinyin":"Tā suīrán hěn lèi, dànshì hái zài gōngzuò.","es":"Aunque está muy cansado, sigue trabajando."},{"zh":"虽然下雨了，但是我们还是去了。","pinyin":"Suīrán xià yǔ le, dànshì wǒmen háishi qù le.","es":"Aunque llovía, fuimos igualmente."},{"zh":"这件衣服虽然不新，但是很漂亮。","pinyin":"Zhè jiàn yīfu suīrán bù xīn, dànshì hěn piàoliang.","es":"Esta ropa no es nueva, pero es muy bonita."}]'::jsonb, array['虽然……，但是……']::text[], 54, array['虽然', '但是']::text[], '[{"wrong":"很贵，虽然很好吃。","right":"虽然很好吃，但是很贵。","why":"虽然 va en la primera parte, delante de lo que se concede; no se usa en la segunda como «…, aunque…»."}]'::jsonb, '[{"hsk_level":2,"code":"2.9.2"}]'::jsonb),
  (2, '6.4.3', '句子的类型', '复句', '因果复句', '因果复句', '因为 + causa，所以 + resultado', '因为 presenta la causa y 所以 la consecuencia. Pueden ir los dos o solo uno, pero el orden es fijo: 所以 siempre introduce el resultado. Si quieres dar la causa al final, como el «porque» español, pon 因为 en la segunda parte y ningún 所以: 我没去，因为下雨了.', '[{"zh":"因为下雨，所以我没去。","pinyin":"Yīnwèi xià yǔ, suǒyǐ wǒ méi qù.","es":"Como llovía, no fui."},{"zh":"因为他生病了，所以没来上课。","pinyin":"Yīnwèi tā shēngbìng le, suǒyǐ méi lái shàngkè.","es":"Como estaba enfermo, no vino a clase."},{"zh":"我今天很累，所以想去睡觉。","pinyin":"Wǒ jīntiān hěn lèi, suǒyǐ xiǎng qù shuìjiào.","es":"Hoy estoy muy cansado, así que quiero irme a dormir."},{"zh":"我没去，因为下雨了。","pinyin":"Wǒ méi qù, yīnwèi xià yǔ le.","es":"No fui porque llovía."}]'::jsonb, array['因为……，所以……']::text[], 55, array['因为', '所以']::text[], '[{"wrong":"所以我没去，因为下雨了。","right":"因为下雨，所以我没去。","why":"所以 introduce el resultado y va detrás de la causa; si la causa va al final, se usa solo 因为."}]'::jsonb, '[]'::jsonb),
  (2, '6.4.4', '句子的类型', '复句', '紧缩复句', '紧缩复句', 'Sujeto + 一 + acción 1 + 就 + acción 2', '一…就… une dos acciones que se siguen sin pausa, como «en cuanto» o «nada más»: 我一到家就给你打电话. También expresa que cada vez que pasa lo primero, pasa lo segundo: 他一累就头疼. 一 y 就 van detrás del sujeto, pegados a sus verbos; si cada parte tiene su sujeto, cada uno va delante de la suya: 我一说他就懂了.', '[{"zh":"我一到家就给你打电话。","pinyin":"Wǒ yí dào jiā jiù gěi nǐ dǎ diànhuà.","es":"En cuanto llegue a casa te llamo."},{"zh":"他一下课就回家了。","pinyin":"Tā yí xiàkè jiù huí jiā le.","es":"Nada más acabar la clase se fue a casa."},{"zh":"我一说他就懂了。","pinyin":"Wǒ yì shuō tā jiù dǒng le.","es":"En cuanto se lo dije, lo entendió."},{"zh":"他一累就头疼。","pinyin":"Tā yí lèi jiù tóu téng.","es":"Siempre que se cansa le duele la cabeza."}]'::jsonb, array['一……就……']::text[], 56, array['一到', '一下课', '一说', '一累']::text[], '[{"wrong":"一我到家就给你打电话。","right":"我一到家就给你打电话。","why":"一 va detrás del sujeto, pegado al verbo; no abre la frase como «en cuanto»."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.6"}]'::jsonb),
  (2, '7.1.1', '动作的态', '', '持续态', '持续态', 'verbo + 着 (+ objeto) · verbo + 着 + 呢', '着 detrás del verbo presenta algo como un estado que se mantiene: 电视开着 «la tele está encendida», 他穿着一件白色的衣服. También muestra una acción que sigue en marcha, a menudo con 呢: 外面下着雨呢. Mientras 在 + verbo cuenta qué se está haciendo, 着 se fija en cómo queda la situación. Va pegado al verbo, antes del objeto.', '[{"zh":"他穿着一件白色的衣服。","pinyin":"Tā chuānzhe yí jiàn báisè de yīfu.","es":"Lleva puesta una prenda blanca."},{"zh":"外面下着雨呢。","pinyin":"Wàimiàn xiàzhe yǔ ne.","es":"Fuera está lloviendo."},{"zh":"电视开着，但是没有人看。","pinyin":"Diànshì kāizhe, dànshì méiyǒu rén kàn.","es":"La tele está encendida, pero nadie la mira."},{"zh":"我们坐着说吧。","pinyin":"Wǒmen zuòzhe shuō ba.","es":"Hablemos sentados."}]'::jsonb, array['动词+着：（1）表示状态的持续', '（2）表示动作的持续']::text[], 57, array['着']::text[], '[{"wrong":"他穿一件白色的衣服着。","right":"他穿着一件白色的衣服。","why":"着 va pegado al verbo, antes del objeto, no al final de la frase."}]'::jsonb, '[{"hsk_level":1,"code":"6.1.3"},{"hsk_level":2,"code":"2.10.2"},{"hsk_level":2,"code":"6.3.3"}]'::jsonb),
  (2, '7.1.2', '动作的态', '', '经历态', '经历态', 'verbo + 过 (+ objeto) · 没 + verbo + 过', '过 cuenta lo que alguien ha vivido alguna vez: 我去过中国 «he estado en China». No habla de una ocasión concreta, sino de la experiencia, por eso responde a preguntas del tipo «¿alguna vez has…?». Se niega con 没…过 y se pregunta con 吗 o con 没有 al final: 你吃过中国菜没有？ No se combina con 了.', '[{"zh":"我没去过中国。","pinyin":"Wǒ méi qùguo Zhōngguó.","es":"No he estado nunca en China."},{"zh":"你吃过中国菜没有？","pinyin":"Nǐ chīguo Zhōngguó cài méiyǒu?","es":"¿Has probado alguna vez la comida china?"},{"zh":"他学过两年汉语。","pinyin":"Tā xuéguo liǎng nián Hànyǔ.","es":"Estudió chino durante dos años."},{"zh":"这个电影我看过。","pinyin":"Zhège diànyǐng wǒ kànguo.","es":"Esta película ya la he visto."}]'::jsonb, array['用动态助词“过”表示']::text[], 58, array['过']::text[], '[{"wrong":"我没去过了中国。","right":"我没去过中国。","why":"过 ya marca la experiencia; no se le añade 了."}]'::jsonb, '[{"hsk_level":2,"code":"2.10.2"},{"hsk_level":1,"code":"6.1.1"}]'::jsonb),
  (2, '8.1', '特殊表达法', '数的表达法', null, '数的表达法', 'número + 楼 / 号 · 几 + clasificador · número + 多 + clasificador · número + clasificador + 多', 'Algunos ordinales se dicen sin 第, con el número delante de la unidad: 三楼 «el tercer piso», 二号 «el número dos». Para cantidades aproximadas, 几 es «unos cuantos» (几个苹果) y detrás de 十 da «doce, trece…» (十几个). 多 añade «y pico»: con decenas va delante del clasificador (二十多个) y con unidades, detrás (一个多月).', '[{"zh":"我家在三楼。","pinyin":"Wǒ jiā zài sān lóu.","es":"Vivo en el tercer piso."},{"zh":"他买了几个苹果。","pinyin":"Tā mǎi le jǐ gè píngguǒ.","es":"Compró unas cuantas manzanas."},{"zh":"我们班有十几个学生。","pinyin":"Wǒmen bān yǒu shí jǐ gè xuésheng.","es":"En nuestra clase hay doce o trece alumnos."},{"zh":"昨天来了二十多个人。","pinyin":"Zuótiān lái le èrshí duō gè rén.","es":"Ayer vinieron veintitantas personas."},{"zh":"我学了一个多月汉语。","pinyin":"Wǒ xué le yí gè duō yuè Hànyǔ.","es":"Llevo algo más de un mes estudiando chino."}]'::jsonb, array['序数表示法2：数词+量词', '概数表达法1：（1）用“几”表示概数', '（2）数词+多+量词', '（3）数词+量词+多']::text[], 59, array['楼', '几', '多']::text[], '[{"wrong":"我家在楼三。","right":"我家在三楼。","why":"El número va delante de la unidad: 三楼, no «planta tres»."}]'::jsonb, '[{"hsk_level":1,"code":"7.1"},{"hsk_level":2,"code":"2.5"}]'::jsonb),
  (3, '1.1', '语素', '前缀', null, '前缀', '老 + apellido · 老 + nombre (palabra fija)', '老 delante de un apellido de una sílaba sirve para llamar con confianza a alguien de nuestra edad o mayor, igual que 小 se usa con los más jóvenes. También forma palabras fijas en las que ya no significa «viejo»: 老师 «profesor». Delante de 朋友 indica que la amistad viene de lejos: 老朋友 «un amigo de toda la vida», aunque la persona sea joven. Como prefijo va pegado, sin 的.', '[{"zh":"他是我的老朋友。","pinyin":"Tā shì wǒ de lǎo péngyou.","es":"Es un amigo de toda la vida."},{"zh":"我们的老师很好。","pinyin":"Wǒmen de lǎoshī hěn hǎo.","es":"Nuestro profesor es muy bueno."},{"zh":"我老家在南方。","pinyin":"Wǒ lǎojiā zài nánfāng.","es":"Mi pueblo natal está en el sur."},{"zh":"这位老人每天都去公园。","pinyin":"Zhè wèi lǎorén měi tiān dōu qù gōngyuán.","es":"Este anciano va al parque todos los días."}]'::jsonb, array['老—']::text[], 1, array['老']::text[], '[{"wrong":"他是我的老的朋友。","right":"他是我的老朋友。","why":"Como prefijo, 老 va pegado y sin 的; 老的 hablaría de la edad de la persona."}]'::jsonb, '[{"hsk_level":1,"code":"1.1"}]'::jsonb),
  (3, '1.2', '语素', '后缀', null, '后缀', 'actividad + 家 · puesto + 员 · raíz + 子', '家 detrás de una actividad designa a quien la ejerce como profesión o con maestría: 画家 «pintor». 员 designa a quien ocupa un puesto o forma parte de un grupo: 运动员 «deportista», 服务员 «camarero». 子 no aporta significado propio y forma muchos nombres comunes: 桌子, 杯子, 儿子. Ninguno de los tres se separa de la palabra a la que va unido.', '[{"zh":"他爸爸是一个画家。","pinyin":"Tā bàba shì yí gè huàjiā.","es":"Su padre es pintor."},{"zh":"她是一个很有名的运动员。","pinyin":"Tā shì yí gè hěn yǒumíng de yùndòngyuán.","es":"Es una deportista muy famosa."},{"zh":"服务员，我们要两碗米饭。","pinyin":"Fúwùyuán, wǒmen yào liǎng wǎn mǐfàn.","es":"Camarero, queremos dos cuencos de arroz."},{"zh":"桌子上有一个杯子。","pinyin":"Zhuōzi shang yǒu yí gè bēizi.","es":"Encima de la mesa hay un vaso."}]'::jsonb, array['—家、—子、—员']::text[], 2, array['家', '员', '子']::text[], '[{"wrong":"他是一个画人。","right":"他是一个画家。","why":"La profesión se forma con el sufijo 家 (画家), no con «persona que pinta»."}]'::jsonb, '[{"hsk_level":1,"code":"1.2"},{"hsk_level":2,"code":"1.1"}]'::jsonb),
  (3, '2.1.1', '词类', '名词', '方位名词', '方位名词', '东 / 南 / 西 / 北 + 边 / 方 · A 和 B + 中间', 'Con 边, los puntos cardinales indican un lado de un lugar (学校东边); con 方, regiones o grandes zonas: 北方 «el norte», 西方 «Occidente». En los puntos intermedios el este y el oeste van primero: 东南 «sudeste», 西北 «noroeste», al revés que en español. 中间 es «en medio»: 他们两个人中间.', '[{"zh":"银行在学校东边。","pinyin":"Yínháng zài xuéxiào dōngbian.","es":"El banco está al este del colegio."},{"zh":"我是北方人。","pinyin":"Wǒ shì běifāng rén.","es":"Soy del norte."},{"zh":"南方的冬天不太冷。","pinyin":"Nánfāng de dōngtiān bú tài lěng.","es":"En el sur el invierno no es muy frío."},{"zh":"我坐在他们两个人中间。","pinyin":"Wǒ zuò zài tāmen liǎng gè rén zhōngjiān.","es":"Me senté entre los dos."}]'::jsonb, array['东、南、西、北、北方、东方、南方、西方、中间']::text[], 3, array['东', '北方', '南方', '中间']::text[], '[{"wrong":"我住在南东边。","right":"我住在东南边。","why":"En los puntos intermedios el este o el oeste van primero: 东南, no «南东»."}]'::jsonb, '[{"hsk_level":1,"code":"2.1.1"},{"hsk_level":2,"code":"2.1.1"}]'::jsonb),
  (3, '2.2.1', '词类', '动词', '能愿动词', '能愿动词', '应该 / 该 / 得 / 需要 / 愿意 + verbo', '应该 y 该 expresan lo que conviene o es correcto, «deberías»: 你应该多休息. 得 (děi) es una obligación práctica, «tener que», muy oral: 我得走了. 需要 es «hacer falta» y admite un verbo o un nombre. 愿意 es «estar dispuesto, querer de buena gana». La negación de 得 no es «不得», sino 不用: 你不用去.', '[{"zh":"你应该多休息。","pinyin":"Nǐ yīnggāi duō xiūxi.","es":"Deberías descansar más."},{"zh":"太晚了，我得走了。","pinyin":"Tài wǎn le, wǒ děi zǒu le.","es":"Es muy tarde, me tengo que ir."},{"zh":"你不需要买新的。","pinyin":"Nǐ bù xūyào mǎi xīn de.","es":"No hace falta que compres uno nuevo."},{"zh":"他不愿意跟我说话。","pinyin":"Tā bú yuànyì gēn wǒ shuōhuà.","es":"No quiere hablar conmigo."},{"zh":"我该回家了。","pinyin":"Wǒ gāi huí jiā le.","es":"Ya es hora de que vuelva a casa."}]'::jsonb, array['需要、该、应该、愿意、得']::text[], 4, array['应该', '得', '需要', '愿意', '该']::text[], '[{"wrong":"你不得去。","right":"你不用去。","why":"La negación de 得 («tener que») es 不用: «no hace falta que vayas»."}]'::jsonb, '[{"hsk_level":1,"code":"2.2.1"},{"hsk_level":2,"code":"2.2.2"}]'::jsonb),
  (3, '2.2.2', '词类', '动词', '离合词', '离合词', '跟 + persona + 见面 / 结婚 · 见了一面 · 离开 + lugar · 离不开', 'Los de tipo verbo + objeto (见面, 结婚, 洗澡, 放假) no admiten otro objeto detrás: la persona va delante con 跟 o 和 (我跟他见面) y otras palabras pueden ir en medio (放了三天假). Los de tipo verbo + resultado (离开, 完成, 分开) sí llevan objeto detrás (离开家) y admiten 得 o 不 en medio para decir si algo es posible: 离不开.', '[{"zh":"我明天跟朋友见面。","pinyin":"Wǒ míngtiān gēn péngyou jiànmiàn.","es":"Mañana quedo con un amigo."},{"zh":"他们去年结婚了。","pinyin":"Tāmen qùnián jiéhūn le.","es":"Se casaron el año pasado."},{"zh":"我们放了三天假。","pinyin":"Wǒmen fàng le sān tiān jià.","es":"Tuvimos tres días de vacaciones."},{"zh":"他离开家已经两年了。","pinyin":"Tā líkāi jiā yǐjīng liǎng nián le.","es":"Hace ya dos años que se fue de casa."},{"zh":"现在我们离不开手机。","pinyin":"Xiànzài wǒmen lí bu kāi shǒujī.","es":"Hoy no podemos vivir sin el móvil."}]'::jsonb, array['动宾式离合词：放假、见面、结婚、洗澡', '动补式离合词：离开、完成、分开']::text[], 5, array['见面', '结婚', '放了三天假', '离开', '离不开']::text[], '[{"wrong":"我想见面你。","right":"我想跟你见面。","why":"见面 ya lleva su objeto (面): la persona va delante, con 跟 o 和."},{"wrong":"他结婚她了。","right":"他跟她结婚了。","why":"结婚 tampoco admite objeto: «casarse con alguien» es 跟 + persona + 结婚."}]'::jsonb, '[{"hsk_level":1,"code":"2.2.2"},{"hsk_level":2,"code":"2.2.3"}]'::jsonb),
  (3, '2.3.1', '词类', '代词', '疑问代词', '疑问代词', '怎样 + verbo？ · interrogativo + 都 / 也 · interrogativo … interrogativo · interrogativo = «algo»', '怎样 pregunta la manera, como 怎么, en un registro algo más formal: 这个字怎样写？ Las palabras interrogativas también se usan sin preguntar. Con 都 o 也 significan «todos» o, con negación, «nada, nadie»: 谁都知道, 什么也不想吃. Repetidas en dos partes se refieren a lo mismo: 你想去哪儿就去哪儿 «ve adonde quieras». Y en afirmaciones pueden significar «algo»: 我想喝一点儿什么.', '[{"zh":"这个字怎样写？","pinyin":"Zhège zì zěnyàng xiě?","es":"¿Cómo se escribe este carácter?"},{"zh":"这件事谁都知道。","pinyin":"Zhè jiàn shì shéi dōu zhīdào.","es":"Esto lo sabe todo el mundo."},{"zh":"我今天什么也不想吃。","pinyin":"Wǒ jīntiān shénme yě bù xiǎng chī.","es":"Hoy no quiero comer nada."},{"zh":"你想去哪儿就去哪儿。","pinyin":"Nǐ xiǎng qù nǎr jiù qù nǎr.","es":"Ve adonde quieras."},{"zh":"我想喝一点儿什么。","pinyin":"Wǒ xiǎng hē yìdiǎnr shénme.","es":"Me apetece beber algo."}]'::jsonb, array['怎样', '疑问代词的非疑问用法：（1）任指用法：①疑问代词+都……②疑问代词+疑问代词', '（2）不定指用法']::text[], 6, array['怎样', '谁都', '什么也', '哪儿就去哪儿', '什么']::text[], '[{"wrong":"我不想吃什么都。","right":"我什么都不想吃。","why":"El interrogativo con 都 o 也 va delante del verbo, no al final como «no quiero comer nada»."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.1"},{"hsk_level":2,"code":"2.3.1"}]'::jsonb),
  (3, '2.3.2', '词类', '代词', '人称代词', '人称代词', '咱们 (incluye al oyente) · 别人 (los demás)', '咱们 es un «nosotros» que siempre incluye a quien escucha: «tú y yo», «todos los aquí presentes». 我们 puede incluirlo o no, así que 咱们 suena más cercano y coloquial. 别人 significa «los demás, otra gente», en oposición a uno mismo: 别人的东西 «lo ajeno». No se usa para una persona concreta que ya se ha mencionado.', '[{"zh":"咱们一起去吧。","pinyin":"Zánmen yìqǐ qù ba.","es":"Vamos juntos."},{"zh":"别人都走了，咱们也走吧。","pinyin":"Biérén dōu zǒu le, zánmen yě zǒu ba.","es":"Los demás ya se han ido; vámonos nosotros también."},{"zh":"不要拿别人的东西。","pinyin":"Búyào ná biérén de dōngxi.","es":"No cojas las cosas de los demás."},{"zh":"他不太听别人的话。","pinyin":"Tā bú tài tīng biérén de huà.","es":"No suele hacer caso a los demás."}]'::jsonb, array['别人、咱们']::text[], 7, array['咱们', '别人']::text[], '[{"wrong":"（a la profesora）咱们是学生，您是老师。","right":"我们是学生，您是老师。","why":"咱们 incluye siempre a quien escucha; si lo excluyes, se dice 我们."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.2"},{"hsk_level":2,"code":"2.3.2"}]'::jsonb),
  (3, '2.3.3', '词类', '代词', '指示代词', '指示代词', '别的 (+ nombre) · 其他 (+ 的) + nombre', 'Los dos significan «otro(s)» en el sentido de «distinto de lo que ya se ha mencionado»: 你还要别的吗？ 别的 es más oral y puede ir solo como objeto; 其他 es algo más formal y suele referirse al resto de un grupo conocido: 其他同学都回家了 «los demás compañeros se fueron». Ninguno sirve para «otro más del mismo», que se dice con 还 o 再.', '[{"zh":"你还要别的吗？","pinyin":"Nǐ hái yào biéde ma?","es":"¿Quieres algo más?"},{"zh":"我不喜欢这个，有别的吗？","pinyin":"Wǒ bù xǐhuan zhège, yǒu biéde ma?","es":"Este no me gusta, ¿hay otros?"},{"zh":"其他同学都回家了。","pinyin":"Qítā tóngxué dōu huí jiā le.","es":"Los demás compañeros se han ido a casa."},{"zh":"除了他，其他人都来了。","pinyin":"Chúle tā, qítā rén dōu lái le.","es":"Han venido todos menos él."}]'::jsonb, array['别的、其他']::text[], 8, array['别的', '其他']::text[], '[{"wrong":"我还要一碗别的米饭。（para pedir otro igual）","right":"我还要一碗米饭。","why":"别的 es «otro distinto»; para «otro más del mismo» basta con 还 o 再."}]'::jsonb, '[{"hsk_level":1,"code":"2.3.3"}]'::jsonb),
  (3, '2.4.1', '词类', '量词', '名量词', '名量词', 'número + 双 / 张 / 辆 / 节 / 种 / 把… + nombre · número + 碗 / 盘 + comida', 'Cada clasificador agrupa nombres por su forma o su uso. 张 es para cosas planas (一张纸, 一张桌子), 把 para objetos con mango o asiento (一把椅子), 双 para pares (一双鞋), 辆 para vehículos, 节 para clases, 封 para cartas y 种 para tipos de algo. Las medidas (公斤, 米) y los recipientes prestados (一碗米饭, 一盘菜) van en el mismo sitio, entre el número y el nombre.', '[{"zh":"我买了一双鞋。","pinyin":"Wǒ mǎi le yì shuāng xié.","es":"Me compré un par de zapatos."},{"zh":"桌子上有一张纸。","pinyin":"Zhuōzi shang yǒu yì zhāng zhǐ.","es":"Encima de la mesa hay una hoja de papel."},{"zh":"他家有两辆车。","pinyin":"Tā jiā yǒu liǎng liàng chē.","es":"En su casa tienen dos coches."},{"zh":"我们下午有两节课。","pinyin":"Wǒmen xiàwǔ yǒu liǎng jié kè.","es":"Por la tarde tenemos dos clases."},{"zh":"我要一碗米饭和一盘菜。","pinyin":"Wǒ yào yì wǎn mǐfàn hé yì pán cài.","es":"Quiero un cuenco de arroz y un plato de verdura."}]'::jsonb, array['（1）专用名量词：把、双、张、种、层、封、页、辆、节、所、班、段、头、句公斤、斤、角、毛、刻、米', '（2）借用名量词：碗、盘']::text[], 9, array['双', '张', '辆', '节', '碗']::text[], '[{"wrong":"我买了一个鞋。","right":"我买了一双鞋。","why":"Los pares de cosas (zapatos, palillos) se cuentan con 双, no con 个."}]'::jsonb, '[{"hsk_level":1,"code":"2.5.1"},{"hsk_level":2,"code":"2.6.1"}]'::jsonb),
  (3, '2.4.2', '词类', '量词', '动量词', '动量词', 'verbo + número + 遍 / 回 / 声 / 口', 'Cuentan las veces de una acción, como 次, cada uno con su matiz. 遍 cuenta una acción hecha de principio a fin: 这本书我看了三遍 «me lo he leído entero tres veces». 回 es casi igual que 次, más oral. 声 cuenta sonidos o llamadas de voz (叫了一声) y 口, bocados o tragos (喝了一口水). Como 次, van detrás del verbo.', '[{"zh":"这本书我看了三遍。","pinyin":"Zhè běn shū wǒ kàn le sān biàn.","es":"Me he leído este libro entero tres veces."},{"zh":"那个地方我去过两回。","pinyin":"Nàge dìfang wǒ qùguo liǎng huí.","es":"He estado dos veces en ese sitio."},{"zh":"他叫了我一声。","pinyin":"Tā jiào le wǒ yì shēng.","es":"Me llamó en voz alta."},{"zh":"我喝了一口水。","pinyin":"Wǒ hē le yì kǒu shuǐ.","es":"Bebí un trago de agua."},{"zh":"请再说一遍。","pinyin":"Qǐng zài shuō yí biàn.","es":"Repítelo, por favor."}]'::jsonb, array['口、回、遍、声']::text[], 10, array['遍', '回', '声', '口']::text[], '[{"wrong":"我三遍看了这本书。","right":"这本书我看了三遍。","why":"Las veces van detrás del verbo, igual que con 次."}]'::jsonb, '[{"hsk_level":2,"code":"2.6.2"}]'::jsonb),
  (3, '2.4.3', '词类', '量词', '量词重叠', '量词重叠', 'clasificador + clasificador (+ 都)', 'Repetir un clasificador significa «todos y cada uno»: 个个 «cada uno de ellos», 张张 «todas las hojas, una por una». Subraya que no hay excepción y casi siempre va con 都 delante del verbo. Se usa como sujeto o delante del nombre (张张照片), nunca detrás del verbo.', '[{"zh":"我们班的学生个个都很认真。","pinyin":"Wǒmen bān de xuésheng gègè dōu hěn rènzhēn.","es":"Los alumnos de nuestra clase son todos muy aplicados."},{"zh":"这些照片张张都很漂亮。","pinyin":"Zhèxiē zhàopiàn zhāngzhāng dōu hěn piàoliang.","es":"Estas fotos son preciosas, todas y cada una."},{"zh":"他的孩子个个都很聪明。","pinyin":"Tā de háizi gègè dōu hěn cōngming.","es":"Sus hijos son todos muy listos."}]'::jsonb, array['个个、张张']::text[], 11, array['个个', '张张']::text[], '[{"wrong":"学生个个很认真。","right":"学生个个都很认真。","why":"El clasificador repetido suele ir reforzado con 都 delante del predicado."}]'::jsonb, '[{"hsk_level":2,"code":"2.6.1"}]'::jsonb),
  (3, '2.5.1', '词类', '副词', '程度副词', '程度副词', '比较 / 挺 / 特别 / 有些 + adjetivo · 更 / 还 + adjetivo · 越来越 · adjetivo + 极了', 'Gradúan un adjetivo. 比较 «bastante, relativamente» y 挺 «bastante», muy oral, suavizan; 特别 es «especialmente». 有些 «un poco» suele ir con algo negativo. 更 «aún más» y 还 «todavía más» comparan con algo ya dicho: 今天比昨天更冷. 越来越 marca un aumento progresivo, y 极了 detrás del adjetivo es «muchísimo»: 好极了.', '[{"zh":"这个问题比较难。","pinyin":"Zhège wèntí bǐjiào nán.","es":"Esta pregunta es bastante difícil."},{"zh":"他人挺好的。","pinyin":"Tā rén tǐng hǎo de.","es":"Es muy buena persona."},{"zh":"今天比昨天更冷。","pinyin":"Jīntiān bǐ zuótiān gèng lěng.","es":"Hoy hace aún más frío que ayer."},{"zh":"天气越来越热了。","pinyin":"Tiānqì yuè lái yuè rè le.","es":"Cada vez hace más calor."},{"zh":"这个菜好吃极了！","pinyin":"Zhège cài hǎochī jí le!","es":"¡Este plato está buenísimo!"}]'::jsonb, array['比较、还3、更、特别、挺、有些、越、极']::text[], 12, array['比较', '挺', '更', '越来越', '极了']::text[], '[{"wrong":"今天比昨天很冷。","right":"今天比昨天更冷。","why":"En una comparación con 比 no se usa 很; para reforzarla se pone 更 o 还."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.1"},{"hsk_level":3,"code":"3.2.2"}]'::jsonb),
  (3, '2.5.2', '词类', '副词', '范围副词', '范围副词', '一共 + cantidad · 只 + verbo · 到处 + verbo · 一块儿 + verbo · 就 + cantidad · …，只是…', 'Delimitan el alcance. 一共 suma un total, «en total». 只 es «solo»: va delante del verbo, no del nombre. 就 con una cantidad también es «solo», con matiz de que es poco: 我就有十块钱. 到处 es «por todas partes» y 一块儿, «juntos» en lo oral. 只是 introduce una pega suave: «solo que…».', '[{"zh":"一共多少钱？","pinyin":"Yígòng duōshao qián?","es":"¿Cuánto es en total?"},{"zh":"我只喝了一点儿。","pinyin":"Wǒ zhǐ hē le yìdiǎnr.","es":"Solo bebí un poco."},{"zh":"我就有十块钱。","pinyin":"Wǒ jiù yǒu shí kuài qián.","es":"Solo tengo diez yuanes."},{"zh":"公园里到处都是人。","pinyin":"Gōngyuán li dàochù dōu shì rén.","es":"En el parque hay gente por todas partes."},{"zh":"这件衣服很好看，只是有点儿贵。","pinyin":"Zhè jiàn yīfu hěn hǎokàn, zhǐshì yǒudiǎnr guì.","es":"Esta ropa es muy bonita, solo que es algo cara."}]'::jsonb, array['就3、一块儿、一共、只、到处、只是']::text[], 13, array['一共', '只', '就', '到处']::text[], '[{"wrong":"我喝了只一点儿。","right":"我只喝了一点儿。","why":"只 va delante del verbo, no delante de la cantidad como «solo un poco»."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.2"}]'::jsonb),
  (3, '2.5.3', '词类', '副词', '时间副词', '时间副词', '才 / 刚 / 先 / 马上 / 一直 + verbo · 一会儿', '才 dice que algo pasó más tarde de lo esperado: 他九点才来 «no vino hasta las nueve»; al contrario que 就, no lleva 了. 刚 o 刚刚 es «acabar de»: 我刚到. 先 es «primero» y suele seguir con 再 o 然后. 马上 es «enseguida», 一直 «todo el rato, sin parar» y 一会儿 «un rato».', '[{"zh":"他九点才来。","pinyin":"Tā jiǔ diǎn cái lái.","es":"No vino hasta las nueve."},{"zh":"我刚到家。","pinyin":"Wǒ gāng dào jiā.","es":"Acabo de llegar a casa."},{"zh":"你先吃饭，再做作业。","pinyin":"Nǐ xiān chī fàn, zài zuò zuòyè.","es":"Primero come y luego haz los deberes."},{"zh":"等一会儿，我马上来。","pinyin":"Děng yíhuìr, wǒ mǎshàng lái.","es":"Espera un momento, voy enseguida."},{"zh":"昨天一直下雨。","pinyin":"Zuótiān yìzhí xià yǔ.","es":"Ayer no paró de llover."}]'::jsonb, array['才1、马上、先、一会儿、刚、刚刚、一直']::text[], 14, array['才', '刚', '先', '马上', '一直']::text[], '[{"wrong":"他九点才来了。","right":"他九点才来。","why":"Con 才 («hasta tan tarde») la frase no lleva 了."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.3"},{"hsk_level":2,"code":"2.7.6"}]'::jsonb),
  (3, '2.5.4', '词类', '副词', '频率副词', '频率副词', '总 / 总是 / 常常 + verbo · 又 + verbo (+ 了)', '总 y 总是 significan «siempre, una y otra vez», a menudo con un tono de queja: 他总是迟到. 常常 es «a menudo». 又 es «otra vez» para algo que ya ha vuelto a pasar, por eso suele llevar 了: 他又来了. Para una repetición futura se usa 再, no 又.', '[{"zh":"他总是迟到。","pinyin":"Tā zǒngshì chídào.","es":"Siempre llega tarde."},{"zh":"我常常去那个公园。","pinyin":"Wǒ chángcháng qù nàge gōngyuán.","es":"Voy a menudo a ese parque."},{"zh":"他昨天来了，今天又来了。","pinyin":"Tā zuótiān lái le, jīntiān yòu lái le.","es":"Vino ayer y hoy ha vuelto a venir."},{"zh":"你怎么又忘了？","pinyin":"Nǐ zěnme yòu wàng le?","es":"¿Cómo es que se te ha vuelto a olvidar?"}]'::jsonb, array['总、总是、又、常常']::text[], 15, array['总', '常常', '又']::text[], '[{"wrong":"我明天又来。","right":"我明天再来。","why":"又 es para lo que ya ha vuelto a pasar; para una repetición futura se usa 再."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.4"},{"hsk_level":2,"code":"2.7.4"}]'::jsonb),
  (3, '2.5.5', '词类', '副词', '关联副词', '关联副词', '一边 + verbo 1，一边 + verbo 2', '一边…一边… dice que una misma persona hace dos cosas a la vez, como «mientras»: 他一边吃饭，一边看电视. Los dos 一边 van delante de su verbo, detrás del sujeto, y cada acción debe ser algo que dura. No sirve para dos personas distintas ni para acciones puntuales.', '[{"zh":"他一边吃饭，一边看电视。","pinyin":"Tā yìbiān chī fàn, yìbiān kàn diànshì.","es":"Come mientras ve la tele."},{"zh":"我们一边走，一边说话。","pinyin":"Wǒmen yìbiān zǒu, yìbiān shuōhuà.","es":"Hablamos mientras caminábamos."},{"zh":"她一边听歌，一边做作业。","pinyin":"Tā yìbiān tīng gē, yìbiān zuò zuòyè.","es":"Hace los deberes escuchando música."}]'::jsonb, array['一边']::text[], 16, array['一边']::text[], '[{"wrong":"他吃饭一边，看电视一边。","right":"他一边吃饭，一边看电视。","why":"一边 va delante de cada verbo, no detrás como «comiendo mientras»."}]'::jsonb, '[{"hsk_level":3,"code":"6.3.3"}]'::jsonb),
  (3, '2.5.6', '词类', '副词', '情态副词', '情态副词', '大概 / 一定 / 必须 / 好像 / 差不多 / 几乎 + verbo / adjetivo', 'Expresan la seguridad o la necesidad de quien habla. 大概 es «probablemente» y también «aproximadamente». 一定 es «seguro que» o, en consejos, «sin falta». 必须 es «tener que» obligatorio; su negación es 不用. 好像 es «parece que». 差不多 es «casi, más o menos» y 几乎, «casi», con más fuerza.', '[{"zh":"他大概不来了。","pinyin":"Tā dàgài bù lái le.","es":"Probablemente ya no viene."},{"zh":"明天你一定要来！","pinyin":"Míngtiān nǐ yídìng yào lái!","es":"¡Mañana tienes que venir sin falta!"},{"zh":"你必须九点以前到。","pinyin":"Nǐ bìxū jiǔ diǎn yǐqián dào.","es":"Tienes que llegar antes de las nueve."},{"zh":"外面好像下雨了。","pinyin":"Wàimiàn hǎoxiàng xià yǔ le.","es":"Parece que fuera está lloviendo."},{"zh":"我们差不多到了。","pinyin":"Wǒmen chàbuduō dào le.","es":"Ya casi hemos llegado."},{"zh":"我几乎每天都跑步。","pinyin":"Wǒ jīhū měi tiān dōu pǎobù.","es":"Corro casi todos los días."}]'::jsonb, array['大概、必须、差不多、一定、好像、几乎']::text[], 17, array['大概', '一定', '必须', '好像', '差不多', '几乎']::text[], '[{"wrong":"你不必须来。","right":"你不用来。","why":"La negación de 必须 no es «不必须», sino 不用 o 不必."}]'::jsonb, '[{"hsk_level":3,"code":"2.2.1"},{"hsk_level":3,"code":"2.5.8"}]'::jsonb),
  (3, '2.5.7', '词类', '副词', '语气副词', '语气副词', '当然 / 其实 / 终于 / 才 / 就 + verbo', 'Añaden la actitud de quien habla. 当然 es «claro, por supuesto». 其实 corrige lo que se cree: «en realidad». 终于 es «por fin», tras esperar mucho. 才 puede subrayar que algo es poco o pronto (他才十岁 «solo tiene diez años») o que solo así se cumple algo. 就 insiste en una decisión o en un hecho: 我就不去 «pues no voy».', '[{"zh":"“你会来吗？”“当然会。”","pinyin":"“Nǐ huì lái ma?” “Dāngrán huì.”","es":"—¿Vendrás? —Por supuesto."},{"zh":"其实他不是中国人。","pinyin":"Qíshí tā bú shì Zhōngguó rén.","es":"En realidad no es chino."},{"zh":"我们终于到了。","pinyin":"Wǒmen zhōngyú dào le.","es":"Por fin hemos llegado."},{"zh":"他才十岁，就会做饭了。","pinyin":"Tā cái shí suì, jiù huì zuò fàn le.","es":"Solo tiene diez años y ya sabe cocinar."},{"zh":"你不让我去，我就要去。","pinyin":"Nǐ bú ràng wǒ qù, wǒ jiù yào qù.","es":"Aunque no me dejes, pienso ir."}]'::jsonb, array['当然、其实、终于、才2、才3、就4']::text[], 18, array['当然', '其实', '终于', '才', '就']::text[], '[{"wrong":"我们到了终于。","right":"我们终于到了。","why":"终于 va delante del verbo, no al final como en «hemos llegado por fin»."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.7"},{"hsk_level":3,"code":"2.5.3"}]'::jsonb),
  (3, '2.5.8', '词类', '副词', '否定副词', '否定副词', '不用 / 不必 + verbo', '不用 y 不必 significan «no hace falta»: 你不用来 «no hace falta que vengas». Son la negación de 得 y de 必须: no prohíben, solo quitan la obligación. 不用 es más oral; 不必, algo más formal. Para prohibir se usa 别 o 不要. 不用谢 es la respuesta habitual a «gracias».', '[{"zh":"你不用来了，我自己去。","pinyin":"Nǐ búyòng lái le, wǒ zìjǐ qù.","es":"No hace falta que vengas, voy yo solo."},{"zh":"“谢谢！”“不用谢。”","pinyin":"“Xièxie!” “Búyòng xiè.”","es":"—¡Gracias! —De nada."},{"zh":"这件事你不必担心。","pinyin":"Zhè jiàn shì nǐ búbì dānxīn.","es":"No tienes por qué preocuparte por esto."}]'::jsonb, array['不必、不用']::text[], 19, array['不用', '不必']::text[], '[{"wrong":"你不用在这儿说话！（para prohibir）","right":"你别在这儿说话！","why":"不用 solo quita la obligación («no hace falta»); para prohibir se usa 别 o 不要."}]'::jsonb, '[{"hsk_level":3,"code":"2.2.1"},{"hsk_level":2,"code":"2.7.5"}]'::jsonb),
  (3, '2.6.1', '词类', '介词', '引出对象', '引出对象', '为 / 向 + persona + verbo · 关于 + tema (+ 的 + nombre)', '为 presenta a quien se beneficia de algo, «por, para»: 妈妈为我做了一个蛋糕. 向 presenta a quien se dirige una acción, «a, hacia»: 向老师问好, 向他学习 «aprender de él». 关于 introduce el tema, «sobre, acerca de», y suele ir delante de un nombre con 的: 关于中国历史的书. Los tres grupos van delante del verbo.', '[{"zh":"妈妈为我准备了早饭。","pinyin":"Māma wèi wǒ zhǔnbèi le zǎofàn.","es":"Mamá me ha preparado el desayuno."},{"zh":"我们应该向他学习。","pinyin":"Wǒmen yīnggāi xiàng tā xuéxí.","es":"Deberíamos aprender de él."},{"zh":"我想看一本关于中国历史的书。","pinyin":"Wǒ xiǎng kàn yì běn guānyú Zhōngguó lìshǐ de shū.","es":"Quiero leer un libro sobre la historia de China."},{"zh":"关于这个问题，我们明天再说。","pinyin":"Guānyú zhège wèntí, wǒmen míngtiān zài shuō.","es":"Sobre este tema, ya hablaremos mañana."}]'::jsonb, array['为1、向1、关于']::text[], 20, array['为', '向', '关于']::text[], '[{"wrong":"我想看一本书关于中国历史。","right":"我想看一本关于中国历史的书。","why":"El grupo con 关于 que describe un nombre va delante de él con 的, no detrás como «un libro sobre…»."}]'::jsonb, '[{"hsk_level":2,"code":"2.8.3"}]'::jsonb),
  (3, '2.6.2', '词类', '介词', '引出方向、路径', '引出方向、路径', '向 + dirección + verbo', '向 indica hacia dónde va un movimiento o hacia dónde se mira, como 往: 向前走 «sigue recto», 向左看 «mira a la izquierda». Es algo más formal que 往 y es el que aparece en carteles e indicaciones escritas. El grupo va delante del verbo.', '[{"zh":"你向前走，银行就在右边。","pinyin":"Nǐ xiàng qián zǒu, yínháng jiù zài yòubian.","es":"Sigue recto y el banco está a la derecha."},{"zh":"请向左看。","pinyin":"Qǐng xiàng zuǒ kàn.","es":"Mire a la izquierda, por favor."},{"zh":"他向我们走过来了。","pinyin":"Tā xiàng wǒmen zǒu guòlai le.","es":"Vino andando hacia nosotros."},{"zh":"从这儿向东走十分钟就到了。","pinyin":"Cóng zhèr xiàng dōng zǒu shí fēnzhōng jiù dào le.","es":"Desde aquí, a diez minutos andando hacia el este."}]'::jsonb, array['向2']::text[], 21, array['向']::text[], '[{"wrong":"你走向前。","right":"你向前走。","why":"En las indicaciones, 向 y la dirección van delante del verbo."}]'::jsonb, '[{"hsk_level":2,"code":"2.8.2"},{"hsk_level":3,"code":"2.6.1"}]'::jsonb),
  (3, '2.6.3', '词类', '介词', '引出目的、原因', '引出目的、原因', '为了 + finalidad，… · 为 + causa / beneficiario + verbo', '为了 introduce la finalidad, «para, con el fin de», y suele abrir la frase: 为了学好汉语，他每天都听写. 为 puede indicar la causa de un sentimiento («por») o a quién beneficia algo: 我为你高兴 «me alegro por ti». La finalidad no se pone al final como en español «estudio para aprobar»: va delante.', '[{"zh":"为了学好汉语，他每天都看中文电视。","pinyin":"Wèile xuéhǎo Hànyǔ, tā měi tiān dōu kàn Zhōngwén diànshì.","es":"Para aprender bien chino, ve la tele en chino todos los días."},{"zh":"为了身体健康，我每天跑步。","pinyin":"Wèile shēntǐ jiànkāng, wǒ měi tiān pǎobù.","es":"Para estar sano, corro todos los días."},{"zh":"我真为你高兴。","pinyin":"Wǒ zhēn wèi nǐ gāoxìng.","es":"Me alegro mucho por ti."},{"zh":"他为这件事很不高兴。","pinyin":"Tā wèi zhè jiàn shì hěn bù gāoxìng.","es":"Está muy disgustado por esto."}]'::jsonb, array['为了、为2']::text[], 22, array['为了', '为']::text[], '[{"wrong":"我每天跑步为了身体健康。","right":"为了身体健康，我每天跑步。","why":"La finalidad con 为了 suele ir delante, no al final como en «corro para estar sano»."}]'::jsonb, '[{"hsk_level":3,"code":"6.3.8"}]'::jsonb),
  (3, '2.6.4', '词类', '介词', '引出施事、受事', '引出施事、受事', 'Sujeto + 把 + objeto + verbo + resultado · Sujeto + 被 (+ agente) + verbo + resultado', '把 adelanta el objeto para contar qué le pasa: 我把杯子打坏了 «he roto el vaso». 被 hace lo contrario: el afectado es el sujeto y quien actúa va detrás de 被, o se omite: 杯子被他打坏了. 被 suele usarse para algo negativo o inesperado. En los dos casos el verbo no puede ir solo: necesita un resultado, una dirección o 了.', '[{"zh":"我把杯子打坏了。","pinyin":"Wǒ bǎ bēizi dǎhuài le.","es":"He roto el vaso."},{"zh":"杯子被弟弟打坏了。","pinyin":"Bēizi bèi dìdi dǎhuài le.","es":"Mi hermano pequeño ha roto el vaso."},{"zh":"我的手机被人拿走了。","pinyin":"Wǒ de shǒujī bèi rén názǒu le.","es":"Alguien se ha llevado mi móvil."},{"zh":"你把这本书带回家吧。","pinyin":"Nǐ bǎ zhè běn shū dài huí jiā ba.","es":"Llévate este libro a casa."}]'::jsonb, array['把、被']::text[], 23, array['把', '被']::text[], '[{"wrong":"杯子被他打。","right":"杯子被他打坏了。","why":"Con 被 el verbo no se queda solo: hay que decir qué le pasó al sujeto (打坏了)."}]'::jsonb, '[{"hsk_level":3,"code":"6.2.1"},{"hsk_level":3,"code":"6.2.2"}]'::jsonb),
  (3, '2.6.5', '词类', '介词', '引出凭借、依据', '引出凭借、依据', '根据 + fuente / dato，…', '根据 «según, de acuerdo con» presenta aquello en lo que se basa una afirmación o una decisión: 根据天气情况，我们决定明天去. Suele abrir la frase, separado por una coma. A diferencia de «según tú», no se usa con personas: para opiniones se dice 在我看来 o 我觉得.', '[{"zh":"根据天气，我们决定明天去。","pinyin":"Gēnjù tiānqì, wǒmen juédìng míngtiān qù.","es":"Según el tiempo que haga, hemos decidido ir mañana."},{"zh":"根据这本书，这个地方很有名。","pinyin":"Gēnjù zhè běn shū, zhège dìfang hěn yǒumíng.","es":"Según este libro, este sitio es muy famoso."},{"zh":"老师根据我们的成绩分班。","pinyin":"Lǎoshī gēnjù wǒmen de chéngjì fēn bān.","es":"El profesor nos reparte en grupos según las notas."}]'::jsonb, array['根据']::text[], 24, array['根据']::text[], '[{"wrong":"根据我，这个电影很好看。","right":"我觉得这个电影很好看。","why":"根据 se basa en datos o fuentes, no en personas; para dar una opinión se usa 我觉得 o 在我看来."}]'::jsonb, '[{"hsk_level":3,"code":"3.2.2"}]'::jsonb),
  (3, '2.7.1', '词类', '连词', '连接词或者短语', '连接词或者短语', 'A + 或者 / 或 + B (en afirmaciones)', '或者, y su forma breve 或, une dos opciones en una afirmación: «o». 你今天或者明天来都可以 «puedes venir hoy o mañana». En una pregunta que pide elegir no se usan: ahí la «o» es 还是. 或 es más escrito y aparece sobre todo entre palabras sueltas.', '[{"zh":"你今天或者明天来都可以。","pinyin":"Nǐ jīntiān huòzhě míngtiān lái dōu kěyǐ.","es":"Puedes venir hoy o mañana."},{"zh":"我们坐地铁或者打车去。","pinyin":"Wǒmen zuò dìtiě huòzhě dǎchē qù.","es":"Iremos en metro o en taxi."},{"zh":"周末我喜欢看书或看电影。","pinyin":"Zhōumò wǒ xǐhuan kàn shū huò kàn diànyǐng.","es":"Los fines de semana me gusta leer o ver películas."}]'::jsonb, array['或、或者']::text[], 25, array['或者', '或']::text[], '[{"wrong":"你喝茶或者咖啡？","right":"你喝茶还是咖啡？","why":"En una pregunta para elegir la «o» es 还是; 或者 es para afirmaciones."}]'::jsonb, '[{"hsk_level":2,"code":"6.2.1"},{"hsk_level":3,"code":"6.3.2"}]'::jsonb),
  (3, '2.7.2', '词类', '连词', '连接分句或句子', '连接分句或句子', '如果 / 只要 / 只有 / 不但…而且 / 可是 / 然后', 'Unen frases con relaciones distintas. 如果 «si» plantea una condición hipotética. 只要 «basta con que» pide una condición suficiente; 只有 «solo si» pide la única condición posible. 不但…而且… es «no solo… sino también». 可是 y 可 son «pero», más orales que 但是. 然后 es «después, luego» en una secuencia.', '[{"zh":"如果明天下雨，我们就不去了。","pinyin":"Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù le.","es":"Si mañana llueve, no iremos."},{"zh":"只要你努力，就能学好。","pinyin":"Zhǐyào nǐ nǔlì, jiù néng xuéhǎo.","es":"Basta con que te esfuerces para aprenderlo bien."},{"zh":"只有多练习，才能说得好。","pinyin":"Zhǐyǒu duō liànxí, cái néng shuō de hǎo.","es":"Solo practicando mucho se llega a hablar bien."},{"zh":"他不但会说汉语，而且说得很好。","pinyin":"Tā búdàn huì shuō Hànyǔ, érqiě shuō de hěn hǎo.","es":"No solo habla chino, sino que lo habla muy bien."},{"zh":"我想去，可是没有时间。","pinyin":"Wǒ xiǎng qù, kěshì méiyǒu shíjiān.","es":"Quiero ir, pero no tengo tiempo."},{"zh":"我们先吃饭，然后去看电影。","pinyin":"Wǒmen xiān chī fàn, ránhòu qù kàn diànyǐng.","es":"Primero comemos y luego vamos al cine."}]'::jsonb, array['只有、只要、不但、而且、如果、可1、可是、然后']::text[], 26, array['如果', '只要', '只有', '不但', '可是', '然后']::text[], '[{"wrong":"只有你努力，就能学好。","right":"只要你努力，就能学好。","why":"只有 va con 才 («solo si…, entonces»); 只要 va con 就 («basta con que…»)."}]'::jsonb, '[{"hsk_level":3,"code":"6.3.6"},{"hsk_level":3,"code":"6.3.7"},{"hsk_level":3,"code":"6.3.4"}]'::jsonb),
  (3, '2.8.1', '词类', '助词', '其他助词', '其他助词', '(如果 +) condición + 的话，…', '的话 cierra una condición, como un «si» puesto al final: 明天下雨的话，我们就不去了. Puede ir solo o reforzar a 如果 (如果…的话). Es muy frecuente en la conversación. La consecuencia va detrás, a menudo con 就.', '[{"zh":"明天下雨的话，我们就不去了。","pinyin":"Míngtiān xià yǔ dehuà, wǒmen jiù bú qù le.","es":"Si mañana llueve, no iremos."},{"zh":"如果你有时间的话，来我家吃饭吧。","pinyin":"Rúguǒ nǐ yǒu shíjiān dehuà, lái wǒ jiā chī fàn ba.","es":"Si tienes tiempo, ven a comer a casa."},{"zh":"不舒服的话，就去医院看看。","pinyin":"Bù shūfu dehuà, jiù qù yīyuàn kànkan.","es":"Si no te encuentras bien, ve al médico."}]'::jsonb, array['的话']::text[], 27, array['的话']::text[], '[{"wrong":"的话明天下雨，我们不去。","right":"明天下雨的话，我们就不去了。","why":"的话 cierra la condición; va al final de esa parte, no al principio como «si»."}]'::jsonb, '[{"hsk_level":3,"code":"6.3.6"}]'::jsonb),
  (3, '3.1.1', '短语', '结构类型', '其他结构类型', '其他结构类型', 'nombre + nombre (aposición) · verbo + 好 / 完 / 到… · un + clasificador + un + clasificador', 'Tres construcciones. En la aposición dos nombres se refieren a lo mismo, sin coma: 我们两个人, 你们大家. El grupo verbo + complemento une un verbo con su resultado: 洗干净, 找到. Y repetir «uno + clasificador» indica que se va uno por uno: 一个一个地说 «hablad de uno en uno», 一天一天 «día a día».', '[{"zh":"我们两个人一起去吧。","pinyin":"Wǒmen liǎng gè rén yìqǐ qù ba.","es":"Vamos los dos juntos."},{"zh":"你们大家都准备好了吗？","pinyin":"Nǐmen dàjiā dōu zhǔnbèi hǎo le ma?","es":"¿Estáis todos listos?"},{"zh":"衣服洗干净了。","pinyin":"Yīfu xǐ gānjìng le.","es":"La ropa ya está bien limpia."},{"zh":"请大家一个一个地说。","pinyin":"Qǐng dàjiā yí gè yí gè de shuō.","es":"Hablad de uno en uno, por favor."},{"zh":"孩子一天一天地长大了。","pinyin":"Háizi yì tiān yì tiān de zhǎngdà le.","es":"El niño ha ido creciendo día a día."}]'::jsonb, array['同位短语', '动补短语2', '数量重叠：数词+量词+数词+量词']::text[], 28, array['我们两个', '你们大家', '干净', '一个一个', '一天一天']::text[], '[{"wrong":"请大家说一个一个。","right":"请大家一个一个地说。","why":"La repetición «uno a uno» describe cómo se hace la acción y va delante del verbo, con 地."}]'::jsonb, '[{"hsk_level":2,"code":"3.1.1"},{"hsk_level":3,"code":"2.4.3"}]'::jsonb),
  (3, '3.2.1', '短语', '固定短语', '四字格', '四字格', '不 + A + 不 + B', 'Con dos adjetivos opuestos, 不A不B dice que algo está en el punto justo, «ni A ni B»: 不冷不热 «ni frío ni calor», 不大不小 «ni grande ni pequeño». Es un molde fijo de cuatro sílabas que suele valorar positivamente. Funciona como predicado o, con 的, delante de un nombre.', '[{"zh":"今天的天气不冷不热。","pinyin":"Jīntiān de tiānqì bù lěng bú rè.","es":"Hoy no hace ni frío ni calor."},{"zh":"这件衣服不大不小，正好。","pinyin":"Zhè jiàn yīfu bú dà bù xiǎo, zhènghǎo.","es":"Esta ropa no es ni grande ni pequeña: justo de mi talla."},{"zh":"我的房间不大不小。","pinyin":"Wǒ de fángjiān bú dà bù xiǎo.","es":"Mi habitación no es ni grande ni pequeña."},{"zh":"这里的人不多不少。","pinyin":"Zhèlǐ de rén bù duō bù shǎo.","es":"Aquí no hay ni mucha ni poca gente."}]'::jsonb, array['不A 不 B']::text[], 29, array['不冷不热', '不大不小', '不多不少']::text[], '[{"wrong":"天气不冷和不热。","right":"天气不冷不热。","why":"Es un molde fijo de cuatro sílabas: no lleva 和 ni otra conjunción en medio."}]'::jsonb, '[{"hsk_level":1,"code":"2.6.6"}]'::jsonb),
  (3, '3.2.2', '短语', '固定短语', '其 他', '其 他', '看来 · 在…看来 · 看起来 / 看上去 · 一般来说 · 越来越 · 不一会儿 · 不怎么样', 'Expresiones fijas muy frecuentes. 看来 saca una conclusión, «por lo que se ve»; 在我看来 da una opinión, «en mi opinión». 看起来 y 看上去 describen la apariencia, «parece». 一般来说 es «por lo general». 越来越 marca un cambio progresivo, «cada vez más». 不一会儿 es «al poco rato» y 不怎么样, «no gran cosa».', '[{"zh":"看来他今天不来了。","pinyin":"Kànlái tā jīntiān bù lái le.","es":"Por lo que se ve, hoy ya no viene."},{"zh":"在我看来，这个办法不错。","pinyin":"Zài wǒ kànlái, zhège bànfǎ búcuò.","es":"En mi opinión, esta solución no está mal."},{"zh":"他看起来很年轻。","pinyin":"Tā kàn qǐlai hěn niánqīng.","es":"Parece muy joven."},{"zh":"一般来说，南方的冬天不太冷。","pinyin":"Yìbān lái shuō, nánfāng de dōngtiān bú tài lěng.","es":"Por lo general, en el sur el invierno no es muy frío."},{"zh":"他的汉语越来越好了，不一会儿就看完了一本书。","pinyin":"Tā de Hànyǔ yuè lái yuè hǎo le, bù yíhuìr jiù kànwán le yì běn shū.","es":"Su chino es cada vez mejor: en un momento se ha leído un libro."},{"zh":"这个电影不怎么样。","pinyin":"Zhège diànyǐng bù zěnmeyàng.","es":"Esta película no es gran cosa."}]'::jsonb, array['不一会儿', '看来', '在……看来', '越来越', '看起来', '看上去', '一般来说', '不怎么样']::text[], 30, array['看来', '看起来', '一般来说', '越来越', '不一会儿', '不怎么样']::text[], '[{"wrong":"他的汉语越来越很好。","right":"他的汉语越来越好了。","why":"越来越 ya expresa el grado: el adjetivo va solo, sin 很, y suele cerrar con 了."}]'::jsonb, '[{"hsk_level":3,"code":"2.5.1"},{"hsk_level":3,"code":"4.1"}]'::jsonb),
  (3, '4.1', '固定格式', '', null, '', '除了…（以外），…还/也/都… · 对…来说 · 一点儿也不… · 越…越… · …以前/以后 · 该…了 · 在…上/中', 'Moldes fijos que hay que aprender enteros. 除了…以外 con 还 o 也 es «además de», y con 都 es «excepto». 对…来说 da el punto de vista: «para mí». 一点儿也不 es «nada en absoluto». 越…越… dice que una cosa aumenta con otra: 越学越有意思. …以前 y …以后 van detrás de lo que sitúan, al revés que «antes de». 该…了 es «ya toca». 在…上 / 中 marca un ámbito: 在学习上.', '[{"zh":"除了茶以外，他还喜欢喝咖啡。","pinyin":"Chúle chá yǐwài, tā hái xǐhuan hē kāfēi.","es":"Además del té, también le gusta el café."},{"zh":"对我来说，这个问题很难。","pinyin":"Duì wǒ lái shuō, zhège wèntí hěn nán.","es":"Para mí esta pregunta es muy difícil."},{"zh":"今天一点儿也不冷。","pinyin":"Jīntiān yìdiǎnr yě bù lěng.","es":"Hoy no hace nada de frío."},{"zh":"汉语越学越有意思。","pinyin":"Hànyǔ yuè xué yuè yǒu yìsi.","es":"Cuanto más estudio chino, más interesante me parece."},{"zh":"吃饭以前要洗手。","pinyin":"Chī fàn yǐqián yào xǐ shǒu.","es":"Antes de comer hay que lavarse las manos."},{"zh":"十一点了，该睡觉了。","pinyin":"Shíyī diǎn le, gāi shuìjiào le.","es":"Son las once, ya toca dormir."}]'::jsonb, array['除了 ……（以外），……还/也/都……', '从……起', '对……来说', '一……也/都+不/没……', '一点儿也不', '越……越……', '（在）……以前/以后/前/后', 'X什么（啊）', '该……了', '在……上/下/中']::text[], 31, array['除了', '对我来说', '一点儿也不', '越', '以前', '该']::text[], '[{"wrong":"以前吃饭要洗手。","right":"吃饭以前要洗手。","why":"以前 y 以后 van detrás de lo que sitúan: «antes de comer» es 吃饭以前."},{"wrong":"除了他，我们也都去了。（queriendo decir «menos él»）","right":"除了他，我们都去了。","why":"Con 都 el sentido es «excepto»; con 也 o 还 sería «además de», y mezclarlos no se entiende."}]'::jsonb, '[{"hsk_level":3,"code":"3.2.2"},{"hsk_level":2,"code":"4.1"}]'::jsonb),
  (3, '5.1', '句子成分', '主语', null, '主语', 'grupo verbal / adjetival / frase con sujeto + predicado', 'Una acción, una cualidad o una frase entera pueden ser el sujeto sin cambiar de forma, porque el chino no tiene infinitivo ni «el hecho de que»: 学汉语很有意思 «estudiar chino es interesante», 健康最重要 «la salud es lo más importante», 他不来没关系 «que él no venga no importa». El predicado que sigue suele ser un adjetivo o 是.', '[{"zh":"学汉语很有意思。","pinyin":"Xué Hànyǔ hěn yǒu yìsi.","es":"Estudiar chino es muy interesante."},{"zh":"身体健康最重要。","pinyin":"Shēntǐ jiànkāng zuì zhòngyào.","es":"Tener buena salud es lo más importante."},{"zh":"他不来没关系。","pinyin":"Tā bù lái méi guānxi.","es":"Que él no venga no importa."},{"zh":"多运动对身体好。","pinyin":"Duō yùndòng duì shēntǐ hǎo.","es":"Hacer mucho deporte es bueno para la salud."}]'::jsonb, array['动词或动词性短语、形容词或形容词性短语作主语', '主谓短语作主语']::text[], 32, array['学汉语', '健康', '他不来', '多运动']::text[], '[{"wrong":"学汉语的事情很有意思。","right":"学汉语很有意思。","why":"No hace falta un «el hecho de»: la acción misma puede ser el sujeto."}]'::jsonb, '[{"hsk_level":2,"code":"3.2.2"},{"hsk_level":1,"code":"4.1"}]'::jsonb),
  (3, '5.2', '句子成分', '定语', null, '定语', 'poseedor + demostrativo + número + clasificador + descripción + 的 + nombre', 'Cuando un nombre lleva varias descripciones, todas van delante en un orden bastante fijo: primero el poseedor, luego el demostrativo, el número y el clasificador, después las descripciones con 的 y, pegadas al nombre, las que no lo llevan: 我的那两件新衣服. Al revés que en español, ninguna va detrás del nombre.', '[{"zh":"我的那两件新衣服都很贵。","pinyin":"Wǒ de nà liǎng jiàn xīn yīfu dōu hěn guì.","es":"Esas dos prendas nuevas mías son muy caras."},{"zh":"那位穿白色衣服的老师是我们的老师。","pinyin":"Nà wèi chuān báisè yīfu de lǎoshī shì wǒmen de lǎoshī.","es":"Ese profesor vestido de blanco es nuestro profesor."},{"zh":"我家后边有一个很大的公园。","pinyin":"Wǒ jiā hòubian yǒu yí gè hěn dà de gōngyuán.","es":"Detrás de mi casa hay un parque muy grande."},{"zh":"他送给我两本新的中文书。","pinyin":"Tā sòng gěi wǒ liǎng běn xīn de Zhōngwén shū.","es":"Me regaló dos libros nuevos en chino."}]'::jsonb, array['多项定语']::text[], 33, array['我的那两件', '那位', '一个很大的', '两本新']::text[], '[{"wrong":"两件我的新衣服。","right":"我的两件新衣服。","why":"El poseedor va antes del número y el clasificador: 我的两件新衣服."}]'::jsonb, '[{"hsk_level":2,"code":"3.2.1"},{"hsk_level":1,"code":"4.4"}]'::jsonb),
  (3, '5.3.1', '句子成分', '补语', '结果补语2', '结果补语2', 'verbo + 到 / 住 / 走 / 上', 'Más complementos de resultado. 到 dice que se alcanza un objetivo: 买到 «conseguir comprar», 找到 «encontrar». 住 indica que algo queda fijo: 记住 «memorizar». 走 indica que algo se va del lugar: 拿走 «llevarse». 上 indica que algo se cierra o se une: 关上门. Se niegan con 没: 我没买到.', '[{"zh":"我买到火车票了。","pinyin":"Wǒ mǎidào huǒchē piào le.","es":"He conseguido comprar los billetes de tren."},{"zh":"你记住他的名字了吗？","pinyin":"Nǐ jìzhù tā de míngzi le ma?","es":"¿Te has quedado con su nombre?"},{"zh":"谁把我的书拿走了？","pinyin":"Shéi bǎ wǒ de shū názǒu le?","es":"¿Quién se ha llevado mi libro?"},{"zh":"请关上门。","pinyin":"Qǐng guānshang mén.","es":"Cierra la puerta, por favor."}]'::jsonb, array['动词+到/住/走/上']::text[], 34, array['到', '住', '走', '上']::text[], '[{"wrong":"我买了票，可是没买。","right":"我去买票了，可是没买到。","why":"Para decir que no se consiguió, se niega el resultado: 没买到; 买 solo es intentar comprar."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.1"}]'::jsonb),
  (3, '5.3.2', '句子成分', '补语', '趋向补语2', '趋向补语2', 'verbo + 出 / 起 / 下 (resultado) · verbo + 起来 / 上 (comienzo) · verbo + 下去 / 下来 (continuidad)', 'Los complementos de dirección también tienen usos figurados. 出 y 起 expresan resultado: 想出办法 «dar con una solución», 想起来 «acordarse». 起来 o 上 marcan el comienzo de algo: 笑起来 «echarse a reír», 爱上 «enamorarse». 下去 es seguir haciendo algo, 说下去 «sigue hablando», y 下来, que algo se calma o se mantiene: 安静下来.', '[{"zh":"我想出了一个好办法。","pinyin":"Wǒ xiǎngchū le yí gè hǎo bànfǎ.","es":"Se me ha ocurrido una buena idea."},{"zh":"我想起来了，我的手机在桌子上。","pinyin":"Wǒ xiǎng qǐlai le, wǒ de shǒujī zài zhuōzi shang.","es":"Ya me acuerdo: mi móvil está en la mesa."},{"zh":"大家都笑起来了。","pinyin":"Dàjiā dōu xiào qǐlai le.","es":"Todos se echaron a reír."},{"zh":"你说下去，我在听。","pinyin":"Nǐ shuō xiàqu, wǒ zài tīng.","es":"Sigue hablando, te escucho."},{"zh":"教室里安静下来了。","pinyin":"Jiàoshì li ānjìng xiàlai le.","es":"El aula se quedó en silencio."}]'::jsonb, array['趋向补语的引申用法：（1）表示结果意义：动词+出/起/下', '（2）表示动作行为的开始：动词+上/起来', '（3）表示动作行为的持续：动词+下去/下来']::text[], 35, array['想出', '想起来', '起来', '下去', '下来']::text[], '[{"wrong":"我想了，我的手机在桌子上。（para «ya me acuerdo»）","right":"我想起来了，我的手机在桌子上。","why":"想 es «pensar»; para «acordarse» hace falta el complemento 起来."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.2"}]'::jsonb),
  (3, '5.3.3', '句子成分', '补语', '可能补语1', '可能补语1', 'verbo + 得 / 不 + resultado o dirección', 'Un 得 o un 不 entre el verbo y su complemento dicen si algo se puede o no se puede conseguir: 听得懂 «lo entiendo (al oírlo)», 听不懂 «no lo entiendo». La negativa es mucho más frecuente. Se diferencia de 能 + verbo en que habla del resultado: 我听不懂 es «oigo pero no entiendo», no «no puedo oír». No lleva 了 y se pregunta con 吗 o con 得…不…: 听得懂听不懂？', '[{"zh":"老师说的话你听得懂吗？","pinyin":"Lǎoshī shuō de huà nǐ tīng de dǒng ma?","es":"¿Entiendes lo que dice el profesor?"},{"zh":"他说得太快，我听不懂。","pinyin":"Tā shuō de tài kuài, wǒ tīng bu dǒng.","es":"Habla demasiado rápido, no le entiendo."},{"zh":"菜太多了，我吃不完。","pinyin":"Cài tài duō le, wǒ chī bu wán.","es":"Hay demasiada comida, no puedo acabármela."},{"zh":"你看得见黑板上的字吗？","pinyin":"Nǐ kàn de jiàn hēibǎn shang de zì ma?","es":"¿Ves las letras de la pizarra?"},{"zh":"这本书在这儿买不到。","pinyin":"Zhè běn shū zài zhèr mǎi bu dào.","es":"Este libro no se encuentra aquí."}]'::jsonb, array['动词+得/不+动词/形容词']::text[], 36, array['得懂', '不懂', '不完', '得见', '不到']::text[], '[{"wrong":"我不能听懂。","right":"我听不懂。","why":"Para «no lo entiendo» se usa el complemento potencial 听不懂; 不能 se refiere al permiso o a la posibilidad, no al resultado."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.1"},{"hsk_level":3,"code":"5.3.1"}]'::jsonb),
  (3, '5.3.4', '句子成分', '补语', '程度补语1', '程度补语1', 'adjetivo + 得很 · adjetivo / verbo + 极了 / 坏了', 'Detrás del adjetivo se puede expresar un grado muy alto. 得很 es «muy» con más énfasis que 很 delante: 好得很. 极了 es «muchísimo» y vale para cosas buenas o malas: 漂亮极了. 坏了 se usa con estados físicos o de ánimo que llegan al límite: 累坏了 «estar molido», 饿坏了 «muerto de hambre». Ninguno lleva 很 delante del adjetivo.', '[{"zh":"这里的东西便宜得很。","pinyin":"Zhèlǐ de dōngxi piányi de hěn.","es":"Aquí las cosas son baratísimas."},{"zh":"这个地方漂亮极了。","pinyin":"Zhège dìfang piàoliang jí le.","es":"Este sitio es precioso."},{"zh":"今天我累坏了。","pinyin":"Jīntiān wǒ lèihuài le.","es":"Hoy estoy molido."},{"zh":"孩子们饿坏了。","pinyin":"Háizimen èhuài le.","es":"Los niños están muertos de hambre."}]'::jsonb, array['（1）形容词+得很', '（2）形容词/动词+极了/坏了']::text[], 37, array['得很', '极了', '坏了']::text[], '[{"wrong":"这个地方很漂亮极了。","right":"这个地方漂亮极了。","why":"极了 ya expresa el grado máximo; no se pone 很 delante del adjetivo."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.3"},{"hsk_level":3,"code":"2.5.1"}]'::jsonb),
  (3, '5.3.5', '句子成分', '补语', '数量补语3', '数量补语3', 'verbo (+ objeto) + duración + 了', 'Con verbos que ocurren de una vez (来, 走, 回国, 离开), la duración detrás no dice cuánto dura la acción, sino cuánto tiempo ha pasado desde que ocurrió: 他来中国三年了 «hace tres años que vino a China». El objeto va antes que la duración y el final lleva 了. En español se dice «hace… que».', '[{"zh":"他来中国三年了。","pinyin":"Tā lái Zhōngguó sān nián le.","es":"Hace tres años que vino a China."},{"zh":"他走了两个小时了。","pinyin":"Tā zǒu le liǎng gè xiǎoshí le.","es":"Hace dos horas que se fue."},{"zh":"他回国一年了。","pinyin":"Tā huí guó yì nián le.","es":"Hace un año que volvió a su país."},{"zh":"他离开家半年了。","pinyin":"Tā líkāi jiā bàn nián le.","es":"Hace medio año que se fue de casa."}]'::jsonb, array['表示动作结束到某个时间点的间隔时间']::text[], 38, array['三年了', '两个小时了', '一年了', '半年了']::text[], '[{"wrong":"三年以前他来中国了。（para «hace tres años que está aquí»）","right":"他来中国三年了。","why":"Para el tiempo transcurrido desde que algo ocurrió, la duración va detrás del verbo y la frase cierra con 了."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.4"}]'::jsonb),
  (3, '6.1.1', '句子的类型', '句类', '疑问句', '疑问句', '怎样 + verbo？', '怎样 delante de un verbo pregunta cómo se hace algo: 这个字怎样写？ «¿cómo se escribe este carácter?». Equivale a 怎么 en esta función, con un tono algo más formal o escrito. Como toda palabra interrogativa, ocupa el sitio de la respuesta y la frase no lleva 吗.', '[{"zh":"去火车站怎样走？","pinyin":"Qù huǒchēzhàn zěnyàng zǒu?","es":"¿Cómo se va a la estación de tren?"},{"zh":"这个菜怎样做？","pinyin":"Zhège cài zěnyàng zuò?","es":"¿Cómo se prepara este plato?"},{"zh":"你是怎样学汉语的？","pinyin":"Nǐ shì zěnyàng xué Hànyǔ de?","es":"¿Cómo aprendiste chino?"}]'::jsonb, array['“怎样+动词”的特指问句']::text[], 39, array['怎样']::text[], '[{"wrong":"怎样去火车站走吗？","right":"去火车站怎样走？","why":"怎样 va delante del verbo que pregunta y la frase no lleva 吗."}]'::jsonb, '[{"hsk_level":3,"code":"2.3.1"},{"hsk_level":1,"code":"2.3.1"}]'::jsonb),
  (3, '6.1.2', '句子的类型', '句类', '反问句1', '反问句1', '不是 + … + 吗？', 'Una pregunta con 不是…吗？ no pide información: subraya algo que se considera evidente, a menudo con sorpresa o reproche: 你不是说你会来吗？ «¿no dijiste que venías?». Equivale a «¿no…?» retórico. La respuesta que se espera es «sí», y el tono puede ser fuerte, así que con desconocidos conviene usarla con cuidado.', '[{"zh":"你不是说你会来吗？","pinyin":"Nǐ bú shì shuō nǐ huì lái ma?","es":"¿No dijiste que venías?"},{"zh":"他不是你的朋友吗？","pinyin":"Tā bú shì nǐ de péngyou ma?","es":"¿No es amigo tuyo?"},{"zh":"今天不是星期天吗？你怎么还去上班？","pinyin":"Jīntiān bú shì xīngqītiān ma? Nǐ zěnme hái qù shàngbān?","es":"¿No es hoy domingo? ¿Cómo es que vas a trabajar?"}]'::jsonb, array['用反问句表示强调：不是……吗？']::text[], 40, array['不是']::text[], '[{"wrong":"你不是说你会来？","right":"你不是说你会来吗？","why":"La pregunta retórica con 不是 necesita 吗 al final."}]'::jsonb, '[{"hsk_level":1,"code":"5.2.2"}]'::jsonb),
  (3, '6.2.1', '句子的类型', '特殊句型', '“把”字句1', '“把”字句1', 'Sujeto + 把 + objeto + verbo + 在/到 + lugar · + 给 + persona · + complemento', '把 adelanta el objeto delante del verbo para contar qué le pasa: dónde acaba, a quién llega o en qué estado queda. El objeto es algo concreto que ya se conoce (este libro, la puerta), nunca «uno cualquiera». El verbo no puede quedarse solo: detrás necesita un lugar con 在/到, un destinatario con 给 o un complemento de resultado o de dirección (完, 上). La negación y los verbos como 要 o 能 van delante de 把, no del verbo.', '[{"zh":"我把书放在桌子上了。","pinyin":"Wǒ bǎ shū fàng zài zhuōzi shang le.","es":"He dejado el libro encima de la mesa."},{"zh":"请把门关上。","pinyin":"Qǐng bǎ mén guānshang.","es":"Cierra la puerta, por favor."},{"zh":"他把作业做完了。","pinyin":"Tā bǎ zuòyè zuòwán le.","es":"Ha terminado los deberes."},{"zh":"你把这本书给他吧。","pinyin":"Nǐ bǎ zhè běn shū gěi tā ba.","es":"Dale este libro a él."},{"zh":"我把车开到学校了。","pinyin":"Wǒ bǎ chē kāidào xuéxiào le.","es":"He llevado el coche hasta el colegio."}]'::jsonb, array['（1）主语+把+宾语+动词+在/到+处所', '（2）主语+把+宾语1+动词（+给）+宾语2', '（3）主语+把+宾语+动词+结果补语/趋向补语/状态补语']::text[], 41, array['把']::text[], '[{"wrong":"我把书看。","right":"我把书看完了。","why":"Con 把 el verbo no puede ir solo: hay que decir qué resultado tiene la acción (看完), adónde va el objeto o a quién se da."},{"wrong":"我把一本书放在桌子上。","right":"我把那本书放在桌子上了。","why":"El objeto de 把 tiene que ser algo concreto y conocido; con «un libro cualquiera» no se usa 把."}]'::jsonb, '[]'::jsonb),
  (3, '6.2.2', '句子的类型', '特殊句型', '被动句1', '被动句1', 'Sujeto (afectado) + 被 (+ agente) + verbo + resultado / 了', 'Con 被, el sujeto es quien sufre la acción y quien la hace va detrás de 被, o se omite si no importa: 我的自行车被人骑走了. Se usa sobre todo para algo negativo o inesperado; para lo neutro basta con poner la cosa delante sin marca (饭做好了). El verbo no puede quedarse solo: necesita un resultado, una dirección o 了. La negación va delante de 被: 没被.', '[{"zh":"我的自行车被人骑走了。","pinyin":"Wǒ de zìxíngchē bèi rén qízǒu le.","es":"Alguien se ha llevado mi bici."},{"zh":"杯子被我打坏了。","pinyin":"Bēizi bèi wǒ dǎhuài le.","es":"He roto el vaso sin querer."},{"zh":"他被老师叫走了。","pinyin":"Tā bèi lǎoshī jiàozǒu le.","es":"El profesor lo ha llamado y se ha ido."},{"zh":"我的书没被拿走。","pinyin":"Wǒ de shū méi bèi názǒu.","es":"No se han llevado mi libro."}]'::jsonb, array['（1）主语+被+宾语+动词+其他成分', '（2）主语+被+动词+其他成分']::text[], 42, array['被']::text[], '[{"wrong":"我的自行车被人骑。","right":"我的自行车被人骑走了。","why":"Con 被 el verbo no va solo: hay que decir qué le pasó al sujeto (骑走了)."},{"wrong":"饭被妈妈做好了。","right":"饭妈妈做好了。","why":"Para algo neutro o positivo no hace falta 被; se reserva para lo que perjudica o sorprende."}]'::jsonb, '[{"hsk_level":3,"code":"2.6.4"},{"hsk_level":2,"code":"5.1"}]'::jsonb),
  (3, '6.2.3', '句子的类型', '特殊句型', '连动句2', '连动句2', 'verbo 1 + 着 + verbo 2', 'Con 着 detrás del primer verbo, la primera acción es la manera en que se hace la segunda: 他笑着说 «dijo sonriendo», 我们走着去吧 «vamos andando». La acción principal es la segunda. En español se traduce con un gerundio o con «a pie», «de pie», «sentado».', '[{"zh":"他笑着说：“没关系。”","pinyin":"Tā xiàozhe shuō: “Méi guānxi.”","es":"Dijo sonriendo: «No pasa nada»."},{"zh":"学校不远，我们走着去吧。","pinyin":"Xuéxiào bù yuǎn, wǒmen zǒuzhe qù ba.","es":"El colegio no está lejos, vamos andando."},{"zh":"他每天站着工作。","pinyin":"Tā měi tiān zhànzhe gōngzuò.","es":"Trabaja de pie todos los días."},{"zh":"孩子哭着找妈妈。","pinyin":"Háizi kūzhe zhǎo māma.","es":"El niño busca a su madre llorando."}]'::jsonb, array['“着”表示动作的伴随：动词1+着+动词2']::text[], 43, array['着']::text[], '[{"wrong":"他说着笑。（para «dijo sonriendo»）","right":"他笑着说。","why":"La manera va primero con 着 y la acción principal después: 笑着说."}]'::jsonb, '[{"hsk_level":2,"code":"7.1.1"},{"hsk_level":1,"code":"5.3.4"}]'::jsonb),
  (3, '6.2.4', '句子的类型', '特殊句型', '比较句2', '比较句2', 'A 比 B 更 / 还 + adj · A 跟 B 一样 (+ adj) · A 不比 B + adj · A 比 B 早 / 晚 / 多 / 少 + verbo + cantidad', '更 o 还 refuerzan una comparación con 比: 今天比昨天还冷. 跟…一样 expresa igualdad, «igual de»: 我跟你一样高. A 不比 B + adjetivo corrige a quien piensa lo contrario: «no es que sea más…». Y con 早, 晚, 多 o 少 delante del verbo, la diferencia va detrás: 他比我早来十分钟 «llegó diez minutos antes que yo».', '[{"zh":"今天比昨天还冷。","pinyin":"Jīntiān bǐ zuótiān hái lěng.","es":"Hoy hace todavía más frío que ayer."},{"zh":"这本书比那本更有意思。","pinyin":"Zhè běn shū bǐ nà běn gèng yǒu yìsi.","es":"Este libro es aún más interesante que aquel."},{"zh":"我跟你一样高。","pinyin":"Wǒ gēn nǐ yíyàng gāo.","es":"Soy igual de alto que tú."},{"zh":"我的汉语不比他差。","pinyin":"Wǒ de Hànyǔ bù bǐ tā chà.","es":"Mi chino no es peor que el suyo."},{"zh":"他比我早来十分钟。","pinyin":"Tā bǐ wǒ zǎo lái shí fēnzhōng.","es":"Llegó diez minutos antes que yo."}]'::jsonb, array['（1）A比B+更/还+形容词', '（2）A跟B一样', '（3）A跟B一样+形容词', '（4）A不比B+形容词', '（5）A比B+多/少/早/晚+动词+数量短语']::text[], 44, array['还', '更', '一样', '不比', '早来']::text[], '[{"wrong":"我跟你一样很高。","right":"我跟你一样高。","why":"Con 一样 el adjetivo va solo, sin 很."},{"wrong":"他来比我早十分钟。","right":"他比我早来十分钟。","why":"比 y 早 van delante del verbo y la diferencia detrás: 比我早来十分钟."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.4"}]'::jsonb),
  (3, '6.2.5', '句子的类型', '特殊句型', '存现句3', '存现句3', 'lugar / tiempo + verbo + complemento + 了 + cantidad + persona / cosa', 'Para contar que algo aparece o desaparece de un sitio, la frase empieza por el lugar o el tiempo y lo que aparece va al final, con número y clasificador: 前边走过来一个人 «por delante vino una persona», 我们班走了两个学生 «de nuestra clase se han ido dos alumnos». Lo que aparece es algo nuevo, por eso no va como sujeto delante. El lugar no lleva 在.', '[{"zh":"前边走过来一个人。","pinyin":"Qiánbian zǒu guòlai yí gè rén.","es":"Por delante se acercó una persona."},{"zh":"昨天我们班来了一个新同学。","pinyin":"Zuótiān wǒmen bān lái le yí gè xīn tóngxué.","es":"Ayer llegó un compañero nuevo a nuestra clase."},{"zh":"我们公司走了两个人。","pinyin":"Wǒmen gōngsī zǒu le liǎng gè rén.","es":"De nuestra empresa se han ido dos personas."},{"zh":"房间里跑出来一只小狗。","pinyin":"Fángjiān li pǎo chūlai yì zhī xiǎo gǒu.","es":"De la habitación salió corriendo un perrito."}]'::jsonb, array['（1）表示出现：处所词+动词+趋向补语/结果补语+动态助词（了）+数量短语+人/物', '（2）表示消失：处所词+动词+结果补语+动态助词（了）+数量短语+人/物']::text[], 45, array['走过来', '来了', '走了', '跑出来']::text[], '[{"wrong":"一个新同学来了我们班。","right":"我们班来了一个新同学。","why":"Cuando algo nuevo aparece en un sitio, el lugar abre la frase y lo nuevo va al final."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.3"},{"hsk_level":1,"code":"5.3.3"}]'::jsonb),
  (3, '6.2.6', '句子的类型', '特殊句型', '“是……的”句2', '“是……的”句2', 'Sujeto + 是 + valoración + 的', 'Esta construcción 是…的 no habla del pasado: encierra la opinión de quien habla para darle un tono firme o tranquilizador. 这个问题是可以解决的 «este problema sí que tiene solución», 你说的是对的 «lo que dices es correcto». Dentro suelen ir 会, 能, 可以 o un adjetivo. Sin 是…的 la frase dice lo mismo pero con menos convicción.', '[{"zh":"你说的是对的。","pinyin":"Nǐ shuō de shì duì de.","es":"Lo que dices es correcto."},{"zh":"只要努力，你是能学好的。","pinyin":"Zhǐyào nǔlì, nǐ shì néng xuéhǎo de.","es":"Si te esfuerzas, seguro que lo aprendes bien."},{"zh":"他是不会来的。","pinyin":"Tā shì bú huì lái de.","es":"Él no va a venir, eso seguro."},{"zh":"这件事是很重要的。","pinyin":"Zhè jiàn shì shì hěn zhòngyào de.","es":"Este asunto es realmente importante."}]'::jsonb, array['强调说话人的看法或态度']::text[], 46, array['是', '的']::text[], '[{"wrong":"他是不会来。","right":"他是不会来的。","why":"El 是 de opinión se cierra con 的; sin 的 queda a medias."}]'::jsonb, '[{"hsk_level":2,"code":"6.3.5"}]'::jsonb),
  (3, '6.2.7', '句子的类型', '特殊句型', '重动句', '重动句', 'Sujeto + verbo + objeto + verbo + 得 / duración / complemento', 'Cuando un verbo con objeto necesita además un complemento (de modo, de duración o de resultado), el verbo se repite: 他说汉语说得很好, 我等你等了一个小时. El objeto va con la primera aparición del verbo y el complemento con la segunda. Es obligatorio: el chino no admite objeto y complemento detrás del mismo verbo.', '[{"zh":"他说汉语说得很好。","pinyin":"Tā shuō Hànyǔ shuō de hěn hǎo.","es":"Habla muy bien chino."},{"zh":"我等你等了一个小时。","pinyin":"Wǒ děng nǐ děng le yí gè xiǎoshí.","es":"Te he estado esperando una hora."},{"zh":"他看书看到十二点。","pinyin":"Tā kàn shū kàndào shí’èr diǎn.","es":"Estuvo leyendo hasta las doce."},{"zh":"妈妈做饭做得很好吃。","pinyin":"Māma zuò fàn zuò de hěn hǎochī.","es":"Mamá cocina muy rico."}]'::jsonb, array['主语+动词+宾语+动词+补语']::text[], 47, array['说汉语说', '等你等', '看书看', '做饭做']::text[], '[{"wrong":"他说汉语得很好。","right":"他说汉语说得很好。","why":"El objeto y 得 no pueden ir detrás del mismo verbo: se repite el verbo, 说汉语说得很好."}]'::jsonb, '[{"hsk_level":2,"code":"5.4.3"},{"hsk_level":2,"code":"5.4.4"}]'::jsonb),
  (3, '6.3.1', '句子的类型', '复句', '承接复句', '承接复句', '先 + acción 1，再 / 然后 + acción 2', '先 marca lo que va primero y 再 o 然后 lo que viene después: 我们先吃饭，再去看电影. 再 se usa para planes y para lo que todavía no ha pasado; 然后 vale para cualquier secuencia, también pasada. Los dos van delante de su verbo, detrás del sujeto si lo hay.', '[{"zh":"我们先吃饭，再去看电影。","pinyin":"Wǒmen xiān chī fàn, zài qù kàn diànyǐng.","es":"Primero comemos y luego vamos al cine."},{"zh":"你先休息一下，然后我们再说。","pinyin":"Nǐ xiān xiūxi yíxià, ránhòu wǒmen zài shuō.","es":"Descansa un poco y luego lo hablamos."},{"zh":"昨天我先去了银行，然后去了超市。","pinyin":"Zuótiān wǒ xiān qù le yínháng, ránhòu qù le chāoshì.","es":"Ayer primero fui al banco y luego al súper."}]'::jsonb, array['先……，再/然后……']::text[], 48, array['先', '再', '然后']::text[], '[{"wrong":"昨天我先去了银行，再去了超市。","right":"昨天我先去了银行，然后去了超市。","why":"Para una secuencia ya ocurrida se usa 然后; 再 mira hacia lo que aún no ha pasado."}]'::jsonb, '[{"hsk_level":2,"code":"2.7.6"},{"hsk_level":3,"code":"2.5.3"}]'::jsonb),
  (3, '6.3.2', '句子的类型', '复句', '选择复句', '选择复句', '或者 + opción 1，或者 + opción 2', 'Repetir 或者 delante de cada opción presenta alternativas que valen igual: «o…, o…». 或者你来，或者我去 «o vienes tú, o voy yo». Se usa en afirmaciones y propuestas; en una pregunta para elegir se usa 还是.', '[{"zh":"或者你来，或者我去，都可以。","pinyin":"Huòzhě nǐ lái, huòzhě wǒ qù, dōu kěyǐ.","es":"O vienes tú o voy yo, como prefieras."},{"zh":"周末我或者在家看书，或者去公园。","pinyin":"Zhōumò wǒ huòzhě zài jiā kàn shū, huòzhě qù gōngyuán.","es":"Los fines de semana o leo en casa o voy al parque."},{"zh":"你可以坐地铁，或者打车。","pinyin":"Nǐ kěyǐ zuò dìtiě, huòzhě dǎchē.","es":"Puedes ir en metro o coger un taxi."}]'::jsonb, array['或者……，或者……']::text[], 49, array['或者']::text[], '[{"wrong":"或者你来，或者我去？","right":"你来还是我去？","why":"Si es una pregunta para elegir, se usa 还是; 或者…或者… es para afirmar o proponer."}]'::jsonb, '[{"hsk_level":3,"code":"2.7.1"},{"hsk_level":2,"code":"6.4.1"}]'::jsonb),
  (3, '6.3.3', '句子的类型', '复句', '并列复句', '并列复句', '一会儿…，一会儿… · 又 + adj，又 + adj · 一边…，一边…', 'Tres formas de juntar cosas. 一会儿…一会儿… describe cambios que se alternan: 一会儿下雨，一会儿出太阳 «ahora llueve, ahora sale el sol». 又…又… une dos cualidades o acciones a la vez: 又便宜又好吃 «barato y además rico». 一边…一边… son dos acciones simultáneas de la misma persona.', '[{"zh":"今天一会儿下雨，一会儿出太阳。","pinyin":"Jīntiān yíhuìr xià yǔ, yíhuìr chū tàiyáng.","es":"Hoy tan pronto llueve como sale el sol."},{"zh":"这家饭馆的菜又便宜又好吃。","pinyin":"Zhè jiā fànguǎn de cài yòu piányi yòu hǎochī.","es":"La comida de este restaurante es barata y además rica."},{"zh":"他一边听歌，一边做饭。","pinyin":"Tā yìbiān tīng gē, yìbiān zuò fàn.","es":"Cocina mientras escucha música."}]'::jsonb, array['一会儿……，一会儿……', '又……，又……', '一边……，一边……']::text[], 50, array['一会儿', '又', '一边']::text[], '[{"wrong":"这个菜又便宜和好吃。","right":"这个菜又便宜又好吃。","why":"又 se repite delante de cada cualidad; no se mezcla con 和."}]'::jsonb, '[{"hsk_level":3,"code":"2.5.5"}]'::jsonb),
  (3, '6.3.4', '句子的类型', '复句', '递进复句', '递进复句', '不但 + A，而且 + B', '不但…而且… es «no solo A, sino también B»: la segunda parte añade algo más fuerte o importante. Si el sujeto es el mismo, va delante de 不但: 他不但会说，而且说得很好. Si hay dos sujetos distintos, 不但 va delante del primero. 而且 puede reforzarse con 也 o 还.', '[{"zh":"他不但会说汉语，而且说得很好。","pinyin":"Tā búdàn huì shuō Hànyǔ, érqiě shuō de hěn hǎo.","es":"No solo habla chino, sino que lo habla muy bien."},{"zh":"这个房间不但很大，而且很安静。","pinyin":"Zhège fángjiān búdàn hěn dà, érqiě hěn ānjìng.","es":"Esta habitación no solo es grande, sino también muy tranquila."},{"zh":"不但我喜欢她，而且我的家人也喜欢她。","pinyin":"Búdàn wǒ xǐhuan tā, érqiě wǒ de jiārén yě xǐhuan tā.","es":"No solo me gusta a mí, también a mi familia."}]'::jsonb, array['不但……，而且……']::text[], 51, array['不但', '而且']::text[], '[{"wrong":"不但他会说汉语，而且说得很好。","right":"他不但会说汉语，而且说得很好。","why":"Con un solo sujeto, este va delante de 不但."}]'::jsonb, '[{"hsk_level":3,"code":"2.7.2"}]'::jsonb),
  (3, '6.3.5', '句子的类型', '复句', '转折复句', '转折复句', '虽然 + lo que se concede，可是 + lo que pasa igualmente', 'Es el mismo molde que 虽然…但是…, con 可是 en la segunda parte, más oral: 虽然很累，可是我很高兴. Igual que con 但是, en chino se dicen las dos partes, aunque en español «aunque…, pero» sobre. 可是 abre siempre la segunda frase y puede reforzarse con 还 o 也: 可是他还是来了.', '[{"zh":"虽然很累，可是我很高兴。","pinyin":"Suīrán hěn lèi, kěshì wǒ hěn gāoxìng.","es":"Aunque estoy cansado, estoy muy contento."},{"zh":"虽然下雨了，可是他还是来了。","pinyin":"Suīrán xià yǔ le, kěshì tā háishi lái le.","es":"Aunque llovía, vino igualmente."},{"zh":"这个问题虽然不难，可是很多人都错了。","pinyin":"Zhège wèntí suīrán bù nán, kěshì hěn duō rén dōu cuò le.","es":"Aunque la pregunta no es difícil, mucha gente ha fallado."}]'::jsonb, array['虽然……，可是……']::text[], 52, array['虽然', '可是']::text[], '[{"wrong":"虽然很累，我很高兴。","right":"虽然很累，可是我很高兴。","why":"虽然 pide su pareja (可是 o 但是) en la segunda parte; omitirla suena incompleto."}]'::jsonb, '[{"hsk_level":2,"code":"6.4.2"}]'::jsonb),
  (3, '6.3.6', '句子的类型', '复句', '假设复句', '假设复句', '如果 + condición，(sujeto +) 就 + consecuencia · condición + 的话，就 + consecuencia', '如果 abre una condición hipotética, «si», y 就 introduce lo que pasaría: 如果明天下雨，我们就不去了. 就 va detrás del sujeto de la segunda parte, nunca delante. En lugar de 如果, o junto a él, se puede cerrar la condición con 的话. A diferencia del español, la condición casi siempre va primero.', '[{"zh":"如果明天下雨，我们就不去了。","pinyin":"Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù le.","es":"Si mañana llueve, no iremos."},{"zh":"你有问题的话，就给我打电话。","pinyin":"Nǐ yǒu wèntí dehuà, jiù gěi wǒ dǎ diànhuà.","es":"Si tienes alguna duda, llámame."},{"zh":"如果你不想去，就别去了。","pinyin":"Rúguǒ nǐ bù xiǎng qù, jiù bié qù le.","es":"Si no quieres ir, no vayas."}]'::jsonb, array['如果……，就……', '……的话，就……']::text[], 53, array['如果', '的话', '就']::text[], '[{"wrong":"如果明天下雨，就我们不去了。","right":"如果明天下雨，我们就不去了。","why":"就 es un adverbio: va detrás del sujeto, no delante como «entonces»."}]'::jsonb, '[{"hsk_level":3,"code":"2.8.1"},{"hsk_level":3,"code":"2.7.2"}]'::jsonb),
  (3, '6.3.7', '句子的类型', '复句', '条件复句', '条件复句', '只有 + única condición，才 + resultado · 只要 + condición suficiente，就 + resultado', '只有…才… presenta la única condición que lleva al resultado, «solo si…»: 只有多练习，才能说得好. 只要…就… presenta una condición que basta, «con tal de que, basta con que»: 只要你来，我就高兴. Las parejas son fijas: 只有 va con 才 y 只要, con 就. Confundirlas cambia el sentido.', '[{"zh":"只有多练习，才能说得好。","pinyin":"Zhǐyǒu duō liànxí, cái néng shuō de hǎo.","es":"Solo practicando mucho se llega a hablar bien."},{"zh":"只要你来，我就很高兴。","pinyin":"Zhǐyào nǐ lái, wǒ jiù hěn gāoxìng.","es":"Con que vengas, ya me alegro mucho."},{"zh":"只有他知道这件事。","pinyin":"Zhǐyǒu tā zhīdào zhè jiàn shì.","es":"Solo él sabe esto."},{"zh":"只要天气好，我们就去公园。","pinyin":"Zhǐyào tiānqì hǎo, wǒmen jiù qù gōngyuán.","es":"Si hace buen tiempo, vamos al parque."}]'::jsonb, array['只有……，才……', '只要……，就……']::text[], 54, array['只有', '才', '只要', '就']::text[], '[{"wrong":"只有多练习，就能说得好。","right":"只有多练习，才能说得好。","why":"只有 va con 才; con 就 la pareja correcta es 只要."}]'::jsonb, '[{"hsk_level":3,"code":"2.7.2"}]'::jsonb),
  (3, '6.3.8', '句子的类型', '复句', '目的复句', '目的复句', '为了 + finalidad，sujeto + acción', 'En una frase compuesta, 为了 abre la primera parte con la finalidad y la segunda cuenta lo que se hace para conseguirla: 为了买到票，他早上五点就起床了. En español la finalidad suele ir al final («se levantó a las cinco para conseguir billetes»); en chino va delante, separada por una coma.', '[{"zh":"为了买到票，他早上五点就起床了。","pinyin":"Wèile mǎidào piào, tā zǎoshang wǔ diǎn jiù qǐchuáng le.","es":"Para conseguir billetes, se levantó a las cinco de la mañana."},{"zh":"为了身体健康，我每天都去跑步。","pinyin":"Wèile shēntǐ jiànkāng, wǒ měi tiān dōu qù pǎobù.","es":"Para estar sano, salgo a correr todos los días."},{"zh":"为了学好汉语，她来中国了。","pinyin":"Wèile xuéhǎo Hànyǔ, tā lái Zhōngguó le.","es":"Para aprender bien chino, se vino a China."}]'::jsonb, array['为了……，……']::text[], 55, array['为了']::text[], '[{"wrong":"他早上五点起床为了买到票。","right":"为了买到票，他早上五点就起床了。","why":"La finalidad con 为了 va delante, no al final como «para conseguir billetes»."}]'::jsonb, '[{"hsk_level":3,"code":"2.6.3"}]'::jsonb),
  (3, '6.3.9', '句子的类型', '复句', '紧缩复句', '紧缩复句', 'verbo 1 + 了 (+ objeto) + (就) + verbo 2', 'Dos acciones encadenadas se pueden comprimir en una sola frase, sin coma: 吃了饭就走 «en cuanto coma, me voy». 了 marca que la primera se termina y 就 subraya que la segunda llega enseguida. Vale para el pasado y para el futuro: 他下了课就回家了, 我到了就给你打电话.', '[{"zh":"我吃了饭就走。","pinyin":"Wǒ chī le fàn jiù zǒu.","es":"En cuanto coma, me voy."},{"zh":"他下了课就回家了。","pinyin":"Tā xià le kè jiù huí jiā le.","es":"Al acabar la clase se fue a casa."},{"zh":"他想了想就同意了。","pinyin":"Tā xiǎng le xiǎng jiù tóngyì le.","es":"Lo pensó un momento y aceptó."},{"zh":"你看了这本书就明白了。","pinyin":"Nǐ kàn le zhè běn shū jiù míngbai le.","es":"En cuanto leas este libro, lo entenderás."}]'::jsonb, array['……了……（就）……']::text[], 56, array['了']::text[], '[{"wrong":"我吃饭就走了。（para el futuro）","right":"我吃了饭就走。","why":"El 了 va detrás de la primera acción para marcar que se termina; al final de la frase cambiaría el sentido a algo ya ocurrido."}]'::jsonb, '[{"hsk_level":2,"code":"6.4.4"},{"hsk_level":2,"code":"2.7.6"}]'::jsonb),
  (3, '7.1', '特殊表达法', '数的表达法', null, '数的表达法', '大概 + cantidad · dos números seguidos + clasificador (三四个, 七八天)', 'Hay dos formas de dar una cantidad aproximada. 大概 delante del número es «unos, aproximadamente»: 大概二十个人. Y dos números consecutivos seguidos, sin conjunción, significan «tres o cuatro», «siete u ocho»: 三四个人, 七八天. No se juntan números que no sean consecutivos ni se pone 或 en medio.', '[{"zh":"来了大概二十个人。","pinyin":"Lái le dàgài èrshí gè rén.","es":"Vinieron unas veinte personas."},{"zh":"我们班有三四个中国同学。","pinyin":"Wǒmen bān yǒu sān sì gè Zhōngguó tóngxué.","es":"En nuestra clase hay tres o cuatro compañeros chinos."},{"zh":"他去北方玩了七八天。","pinyin":"Tā qù běifāng wán le qī bā tiān.","es":"Estuvo siete u ocho días de viaje por el norte."},{"zh":"我在门口等了两三分钟。","pinyin":"Wǒ zài ménkǒu děng le liǎng sān fēnzhōng.","es":"Esperé dos o tres minutos en la puerta."}]'::jsonb, array['概数表达法2：（1）用“大概”表示概数', '（2）相邻数词连用表示概数']::text[], 57, array['大概', '三四', '七八', '两三']::text[], '[{"wrong":"我们班有三或四个中国同学。","right":"我们班有三四个中国同学。","why":"Para «tres o cuatro» los números van seguidos, sin 或 en medio."}]'::jsonb, '[{"hsk_level":2,"code":"8.1"},{"hsk_level":3,"code":"2.5.6"}]'::jsonb)
