  (2, 'HSK（二级）样卷 (formato 3.0)', 'Muestra oficial del HSK 2 con formato 3.0: zip «Sample Questions» enlazado desde https://www.chinesetest.cn/syllabus (https://hsk-sample-1409982902.cos.ap-beijing.myqcloud.com/HSK3.0.zip, HTTP 200, 395 322 335 bytes, Last-Modified 2026-09-09). PDF «HSK（二级）样卷.pdf» de 19 páginas, creado el 2026-07-15. Tiempos de la portada; plays y pausas medidos en «音频/HSK（二级）样卷.mp3» (17:48,6). Transcripción completa en docs/hsk/hsk2-3.0-estructura.md. Solo se toma la estructura: ninguna pregunta, imagen ni audio de la muestra.', 60, 3, '[{"code":"listening","title":"听力","minutes":17,"measured_audio_ms":1068600,"parts":[{"code":"1","question_count":5,"format":"听一句话，选择正确图片","description_es":"Una frase en audio; elegir entre 3 imágenes propias de la pregunta (A/B/C).","answer_kind":"image","has_example":true,"group_shapes":[{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1}],"plays":2,"instruction_ms":12600,"pause_between_plays_ms":2200,"pause_after_item_ms":8300},{"code":"2","question_count":10,"format":"听对话，选择最匹配的图片","description_es":"Diálogo corto en audio; elegir la imagen del grupo. Grupo 1: 6 imágenes A–F, el ejemplo gasta una. Grupo 2: 5 imágenes A–E, sin ejemplo.","answer_kind":"image","has_example":true,"group_shapes":[{"options":6,"example_uses":1,"questions":5},{"options":5,"example_uses":0,"questions":5}],"plays":2,"instruction_ms":12800,"pause_between_plays_ms":2100,"pause_after_item_ms":12200},{"code":"3","question_count":10,"format":"听对话，选择正确答案","description_es":"Diálogo de 2 turnos y pregunta en audio; elegir entre 3 respuestas impresas con pinyin (A/B/C). Cada reproducción es diálogo + pregunta.","answer_kind":"text","has_example":true,"group_shapes":[{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1}],"plays":2,"instruction_ms":12400,"pause_between_plays_ms":2100,"question_gap_ms":2100,"pause_after_item_ms":15100}]},{"code":"reading","title":"阅读","minutes":25,"parts":[{"code":"1","question_count":5,"format":null,"description_es":"Frase escrita con pinyin; elegir la imagen del grupo (6 imágenes A–F, el ejemplo gasta una).","answer_kind":"image","has_example":true,"group_shapes":[{"options":6,"example_uses":1,"questions":5}]},{"code":"2","question_count":5,"format":null,"description_es":"Frase o minidiálogo A/B con un hueco （ ）; elegir la palabra de un banco común de 6 (A–F, el ejemplo gasta una).","answer_kind":"bank","has_example":true,"group_shapes":[{"options":6,"example_uses":1,"questions":5}]},{"code":"3","question_count":10,"format":null,"description_es":"Frase china; elegir su respuesta o continuación china. Grupo 1: 6 opciones A–F, el ejemplo gasta una. Grupo 2: 5 opciones A–E, sin ejemplo.","answer_kind":"bank","has_example":true,"group_shapes":[{"options":6,"example_uses":1,"questions":5},{"options":5,"example_uses":0,"questions":5}]},{"code":"4","question_count":5,"format":null,"description_es":"Texto corto y pregunta marcada con ★; elegir entre 3 respuestas impresas (A/B/C).","answer_kind":"text","has_example":true,"group_shapes":[{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1},{"options":3,"example_uses":0,"questions":1}]}]},{"code":"writing","title":"书写","minutes":10,"parts":[{"code":"1","question_count":5,"format":null,"description_es":"Palabra de 2 caracteres con pinyin en la que a un carácter le falta un componente; elegir el componente de un banco de 6 (A–F, el ejemplo gasta uno).","answer_kind":"bank","has_example":true,"group_shapes":[{"options":6,"example_uses":1,"questions":5}]},{"code":"2","question_count":5,"format":null,"description_es":"Frase con pinyin completo y un hueco （ ）; escribir a mano el carácter que falta.","answer_kind":"handwrite","has_example":true,"group_shapes":[{"options":1,"example_uses":0,"questions":1},{"options":1,"example_uses":0,"questions":1},{"options":1,"example_uses":0,"questions":1},{"options":1,"example_uses":0,"questions":1},{"options":1,"example_uses":0,"questions":1}]}]}]'::jsonb)
insert into public.generated_exercises (type, hsk_level, target_word_id, prompt, answer, source_model, created_by)
values
  ('dictation', 1, (select w.id from public.words w where w.hanzi = '你好' and w.pinyin = 'nǐ hǎo' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"dictation","slug":"l1-dictation-01","unit_code":"2.3.2","audio_text":"你好","pinyin":"nǐ hǎo","accept_pinyin":true,"explanation":"«你好» es un saludo equivalente a «hola»; escribe las dos sílabas en ese orden."}'::jsonb, '"你好"'::jsonb, 'seed', null),
  ('dictation', 1, (select w.id from public.words w where w.hanzi = '谢谢' and w.pinyin = 'xièxie' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"dictation","slug":"l1-dictation-02","unit_code":"4.2","audio_text":"谢谢","pinyin":"xiè xie","accept_pinyin":true,"explanation":"«谢谢» expresa agradecimiento y equivale a «gracias»; conserva sus dos sílabas al escribirlo."}'::jsonb, '"谢谢"'::jsonb, 'seed', null),
  ('dictation', 1, (select w.id from public.words w where w.hanzi = '爱' and w.pinyin = 'ài' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"dictation","slug":"l1-dictation-03","unit_code":"4.2","audio_text":"我爱你","pinyin":"wǒ ài nǐ","accept_pinyin":true,"explanation":"«我爱你» sigue sujeto + verbo + objeto y significa «te quiero»; identifica cada palabra en la frase."}'::jsonb, '"我爱你"'::jsonb, 'seed', null),
  ('dictation', 1, (select w.id from public.words w where w.hanzi = '喝' and w.pinyin = 'hē' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"dictation","slug":"l1-dictation-04","unit_code":"4.3","audio_text":"我喝水","pinyin":"wǒ hē shuǐ","accept_pinyin":true,"explanation":"«我喝水» significa «bebo agua»: «我» es el sujeto, «喝» la acción y «水» lo que se bebe."}'::jsonb, '"我喝水"'::jsonb, 'seed', null),
  ('dictation', 1, (select w.id from public.words w where w.hanzi = '喜欢' and w.pinyin = 'xǐhuan' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"dictation","slug":"l1-dictation-05","unit_code":"4.3","audio_text":"我喜欢茶","pinyin":"wǒ xǐhuan chá","accept_pinyin":true,"explanation":"«我喜欢茶» expresa una preferencia: «喜欢» significa «gustar» y «茶» es el té que gusta."}'::jsonb, '"我喜欢茶"'::jsonb, 'seed', null),
  ('dictation', 1, (select w.id from public.words w where w.hanzi = '是' and w.pinyin = 'shì' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"dictation","slug":"l1-dictation-06","unit_code":"5.3.1","audio_text":"她是学生","pinyin":"tā shì xuésheng","accept_pinyin":true,"explanation":"«她是学生» usa «是» para identificar al sujeto; la frase significa «ella es estudiante»."}'::jsonb, '"她是学生"'::jsonb, 'seed', null),
  ('fill_blank', 1, (select w.id from public.words w where w.hanzi = '喜欢' and w.pinyin = 'xǐhuan' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l1-fill-blank-01","unit_code":"4.2","sentence":"我___喝茶。","options":["喜欢","要","能","很"],"correct":"喜欢","explanation":"«喜欢» expresa gusto o preferencia: «我喜欢喝茶» significa que me gusta beber té."}'::jsonb, '"喜欢"'::jsonb, 'seed', null),
  ('fill_blank', 1, (select w.id from public.words w where w.hanzi = '朋友' and w.pinyin = 'péngyou' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l1-fill-blank-02","unit_code":"5.3.1","sentence":"她是我的___。","options":["朋友","学校","中国","时候"],"correct":"朋友","explanation":"«朋友» es un sustantivo para una persona cercana; después de «我的» necesitamos esa persona, no un lugar."}'::jsonb, '"朋友"'::jsonb, 'seed', null),
  ('fill_blank', 1, (select w.id from public.words w where w.hanzi = '要' and w.pinyin = 'yào' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l1-fill-blank-03","unit_code":"2.2.1","sentence":"我___去学校。","options":["要","能","喜欢","有"],"correct":"要","explanation":"«要» expresa aquí intención o necesidad: «我要去学校» significa «quiero ir a la escuela»."}'::jsonb, '"要"'::jsonb, 'seed', null),
  ('fill_blank', 1, (select w.id from public.words w where w.hanzi = '是' and w.pinyin = 'shì' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l1-fill-blank-04","unit_code":"5.3.1","sentence":"他___学生。","options":["是","喝","朋友","茶"],"correct":"是","explanation":"«是» conecta al sujeto con su identidad o profesión: «他是学生» presenta que él es estudiante."}'::jsonb, '"是"'::jsonb, 'seed', null),
  ('fill_blank', 1, (select w.id from public.words w where w.hanzi = '是' and w.pinyin = 'shì' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l1-fill-blank-05","unit_code":"5.3.1","sentence":"她___中国人。","options":["是","在","很","也"],"correct":"是","explanation":"«是» también une a «她» con su nacionalidad; «她是中国人» identifica que ella es china."}'::jsonb, '"是"'::jsonb, 'seed', null),
  ('fill_blank', 1, (select w.id from public.words w where w.hanzi = '喜欢' and w.pinyin = 'xǐhuan' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l1-fill-blank-06","unit_code":"4.2","sentence":"我们___看书。","options":["喜欢","要","能","有"],"correct":"喜欢","explanation":"«喜欢» introduce lo que nos gusta hacer: «我们喜欢看书» expresa una preferencia por leer."}'::jsonb, '"喜欢"'::jsonb, 'seed', null),
  ('matching', 1, (select w.id from public.words w where w.hanzi = '学生' and w.pinyin = 'xuéshēng' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l1-matching-01","unit_code":"4.1","pairs":[{"left":"学生","right":"estudiante"},{"left":"老师","right":"profesor/a"},{"left":"朋友","right":"amigo/a"},{"left":"医生","right":"médico/a"}],"explanation":"Los pares distinguen personas por su papel: «学生» estudia, «老师» enseña, «朋友» es una relación y «医生» atiende pacientes."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 1, (select w.id from public.words w where w.hanzi = '大' and w.pinyin = 'dà' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l1-matching-02","unit_code":"4.2","pairs":[{"left":"大","right":"grande"},{"left":"小","right":"pequeño/a"},{"left":"好","right":"bueno/a"},{"left":"多","right":"muchos/as"}],"explanation":"Son adjetivos básicos de tamaño, valoración y cantidad: «大/小» contrastan tamaño, «好» valora y «多» indica cantidad."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 1, (select w.id from public.words w where w.hanzi = '爱' and w.pinyin = 'ài' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l1-matching-03","unit_code":"4.2","pairs":[{"left":"爱","right":"amar"},{"left":"喝","right":"beber"},{"left":"吃","right":"comer"},{"left":"看","right":"ver"}],"explanation":"Los cuatro elementos son verbos: «爱» expresa afecto, «喝» y «吃» acciones de ingerir, y «看» la acción de mirar."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 1, (select w.id from public.words w where w.hanzi = '我' and w.pinyin = 'wǒ' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l1-matching-04","unit_code":"2.3.2","pairs":[{"left":"我","right":"yo; mi"},{"left":"你","right":"tú"},{"left":"他","right":"él"},{"left":"她","right":"ella"}],"explanation":"Estos caracteres son pronombres personales: «我» habla del hablante, «你» del interlocutor y «他/她» de otra persona."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 1, (select w.id from public.words w where w.hanzi = '茶' and w.pinyin = 'chá' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l1-matching-05","unit_code":"4.3","pairs":[{"left":"茶","right":"té"},{"left":"水","right":"agua"},{"left":"书","right":"libro"},{"left":"家","right":"casa"}],"explanation":"Son sustantivos cotidianos: «茶» y «水» son bebidas, «书» es un objeto para leer y «家» es un lugar."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 1, (select w.id from public.words w where w.hanzi = '中国' and w.pinyin = 'Zhōngguó' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l1-matching-06","unit_code":"5.3.1","pairs":[{"left":"中国","right":"China"},{"left":"老师","right":"profesor/a"},{"left":"学校","right":"escuela"},{"left":"学生","right":"estudiante"}],"explanation":"El grupo combina un país, un lugar de estudio y dos roles: «中国» es China, «学校» es la escuela y «老师/学生» son personas."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('multiple_choice', 1, (select w.id from public.words w where w.hanzi = '学生' and w.pinyin = 'xuéshēng' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l1-multiple-choice-01","unit_code":"5.3.1","question":"¿Qué significa 学生?","options":["profesor/a","estudiante","médico/a","amigo/a"],"correct":"estudiante","explanation":"«学生» se refiere a la persona que estudia; por eso corresponde a «estudiante», no a quien enseña ni a una profesión médica."}'::jsonb, '"estudiante"'::jsonb, 'seed', null),
  ('multiple_choice', 1, (select w.id from public.words w where w.hanzi = '吃' and w.pinyin = 'chī' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l1-multiple-choice-02","unit_code":"4.2","question":"¿Qué significa 吃?","options":["beber","comer","ver","ir"],"correct":"comer","explanation":"«吃» describe la acción de ingerir comida; «comer» es la traducción adecuada frente a «beber» o «ver»."}'::jsonb, '"comer"'::jsonb, 'seed', null),
  ('multiple_choice', 1, (select w.id from public.words w where w.hanzi = '朋友' and w.pinyin = 'péngyou' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l1-multiple-choice-03","unit_code":"4.3","question":"¿Qué significa 朋友?","options":["profesor/a","amigo/a","estudiante","médico/a"],"correct":"amigo/a","explanation":"«朋友» nombra una relación de amistad; «amigo/a» corresponde a esa persona, no a una profesión."}'::jsonb, '"amigo/a"'::jsonb, 'seed', null),
  ('multiple_choice', 1, (select w.id from public.words w where w.hanzi = '老师' and w.pinyin = 'lǎoshī' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l1-multiple-choice-04","unit_code":"4.1","question":"¿Qué significa 老师?","options":["médico/a","profesor/a","amigo/a","estudiante"],"correct":"profesor/a","explanation":"«老师» designa a quien enseña; «profesor/a» conserva ese papel en español."}'::jsonb, '"profesor/a"'::jsonb, 'seed', null),
  ('multiple_choice', 1, (select w.id from public.words w where w.hanzi = '喝' and w.pinyin = 'hē' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l1-multiple-choice-05","unit_code":"4.2","question":"¿Qué significa 喝?","options":["ver","beber","comer","ir"],"correct":"beber","explanation":"«喝» se usa para ingerir líquidos; «beber» expresa la acción adecuada, frente a comer o ver."}'::jsonb, '"beber"'::jsonb, 'seed', null),
  ('multiple_choice', 1, (select w.id from public.words w where w.hanzi = '学校' and w.pinyin = 'xuéxiào' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l1-multiple-choice-06","unit_code":"4.3","question":"¿Qué significa 学校?","options":["hospital","escuela","casa","empresa"],"correct":"escuela","explanation":"«学校» es el lugar donde se estudia; «escuela» nombra ese lugar, no una persona ni una vivienda."}'::jsonb, '"escuela"'::jsonb, 'seed', null),
  ('reorder', 1, (select w.id from public.words w where w.hanzi = '喜欢' and w.pinyin = 'xǐhuan' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l1-reorder-01","unit_code":"4.3","words":["喝","我","茶","喜欢"],"correct_order":["我","喜欢","喝","茶"],"translation":"我喜欢喝茶","explanation":"La frase sigue sujeto + preferencia + verbo + objeto: «我喜欢喝茶» significa «me gusta beber té»."}'::jsonb, '"我喜欢喝茶"'::jsonb, 'seed', null),
  ('reorder', 1, (select w.id from public.words w where w.hanzi = '去' and w.pinyin = 'qù' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l1-reorder-02","unit_code":"5.3.4","words":["去","他","学校"],"correct_order":["他","去","学校"],"translation":"他去学校","explanation":"El patrón básico es sujeto + verbo + destino: «他去学校» significa «él va a la escuela»."}'::jsonb, '"他去学校"'::jsonb, 'seed', null),
  ('reorder', 1, (select w.id from public.words w where w.hanzi = '是' and w.pinyin = 'shì' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l1-reorder-03","unit_code":"5.3.1","words":["学生","她","是"],"correct_order":["她","是","学生"],"translation":"她是学生","explanation":"«是» une el sujeto con un sustantivo que lo identifica: «她是学生» significa «ella es estudiante»."}'::jsonb, '"她是学生"'::jsonb, 'seed', null),
  ('reorder', 1, (select w.id from public.words w where w.hanzi = '有' and w.pinyin = 'yǒu' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l1-reorder-04","unit_code":"5.3.2","words":["朋友","我","有"],"correct_order":["我","有","朋友"],"translation":"我有朋友","explanation":"Para expresar posesión usamos sujeto + «有» + objeto: «我有朋友» significa «tengo amigos»."}'::jsonb, '"我有朋友"'::jsonb, 'seed', null),
  ('reorder', 1, (select w.id from public.words w where w.hanzi = '是' and w.pinyin = 'shì' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l1-reorder-05","unit_code":"5.3.1","words":["茶","这","是"],"correct_order":["这","是","茶"],"translation":"这是茶","explanation":"Una identificación con demostrativo sigue «这 + 是 + sustantivo»: «这是茶» significa «esto es té»."}'::jsonb, '"这是茶"'::jsonb, 'seed', null),
