  ('fill_blank', 3, (select w.id from public.words w where w.hanzi = '比较' and w.pinyin = 'bǐjiào' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l3-fill-blank-02","unit_code":"2.5.1","sentence":"他的成绩___好的。","options":["比较","已经","终于","而且"],"correct":"比较","explanation":"«比较» modifica «好» como grado relativo: las notas son bastante buenas, sin afirmar que sean las mejores."}'::jsonb, '"比较"'::jsonb, 'seed', null),
  ('fill_blank', 3, (select w.id from public.words w where w.hanzi = '比较' and w.pinyin = 'bǐjiào' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l3-fill-blank-03","unit_code":"2.5.1","sentence":"这个问题___很好。","options":["比较","已经","因为","所以"],"correct":"比较","explanation":"«比较» también puede suavizar una valoración: el problema está relativamente bien, no se presenta como perfecto."}'::jsonb, '"比较"'::jsonb, 'seed', null),
  ('fill_blank', 3, (select w.id from public.words w where w.hanzi = '可能' and w.pinyin = 'kěnéng' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l3-fill-blank-04","unit_code":"2.5.6","sentence":"他___没有来。","options":["可能","虽然","而且","终于"],"correct":"可能","explanation":"«可能» presenta una posibilidad, no un hecho seguro; «可能没有来» significa que quizá no vino."}'::jsonb, '"可能"'::jsonb, 'seed', null),
  ('fill_blank', 3, (select w.id from public.words w where w.hanzi = '所以' and w.pinyin = 'suǒyǐ' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l3-fill-blank-05","unit_code":"2.7.2","sentence":"因为天气不好，___我们没有出门。","options":["所以","虽然","而且","如果"],"correct":"所以","explanation":"«所以» introduce la consecuencia de la causa anterior; tras «因为天气不好» explica por qué no salimos."}'::jsonb, '"所以"'::jsonb, 'seed', null),
  ('fill_blank', 3, (select w.id from public.words w where w.hanzi = '终于' and w.pinyin = 'zhōngyú' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"fill_blank","slug":"l3-fill-blank-06","unit_code":"2.5.3","sentence":"他___完成了作业。","options":["终于","虽然","而且","如果"],"correct":"终于","explanation":"«终于» marca un resultado alcanzado después de esperar o esforzarse; «por fin terminó los deberes»."}'::jsonb, '"终于"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '关系' and w.pinyin = 'guānxì' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-01","unit_code":"6.3.4","pairs":[{"left":"关系","right":"relación"},{"left":"终于","right":"por fin"},{"left":"根据","right":"según"},{"left":"而且","right":"además"}],"explanation":"«关系» nombra un vínculo, «终于» un resultado tras esperar, «根据» la base de una decisión y «而且» una adición."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '因为' and w.pinyin = 'yīnwèi' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-02","unit_code":"6.3.5","pairs":[{"left":"因为","right":"porque"},{"left":"虽然","right":"aunque"},{"left":"不过","right":"sin embargo"},{"left":"而且","right":"además"}],"explanation":"«因为» causa, «虽然» contraste, «不过» objeción moderada y «而且» información adicional: son conectores distintos."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '需要' and w.pinyin = 'xūyào' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-03","unit_code":"5.1","pairs":[{"left":"需要","right":"necesitar"},{"left":"决定","right":"decidir"},{"left":"问题","right":"pregunta"},{"left":"完成","right":"completar"}],"explanation":"«需要» expresa necesidad, «决定» una elección, «问题» aquello que se pregunta y «完成» el final de una tarea."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '比较' and w.pinyin = 'bǐjiào' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-04","unit_code":"2.5.3","pairs":[{"left":"比较","right":"relativamente"},{"left":"可能","right":"posiblemente"},{"left":"终于","right":"por fin"},{"left":"已经","right":"ya"}],"explanation":"«比较» expresa grado relativo, «可能» posibilidad, «终于» resultado esperado y «已经» anterioridad."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '根据' and w.pinyin = 'gēnjù' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-05","unit_code":"6.3.5","pairs":[{"left":"根据","right":"según"},{"left":"因为","right":"porque"},{"left":"所以","right":"por eso"},{"left":"虽然","right":"aunque"}],"explanation":"«根据» introduce la base, «因为» la causa, «所以» la consecuencia y «虽然» el contraste."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('matching', 3, (select w.id from public.words w where w.hanzi = '办法' and w.pinyin = 'bànfǎ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"matching","slug":"l3-matching-06","unit_code":"5.1","pairs":[{"left":"办法","right":"método"},{"left":"问题","right":"pregunta"},{"left":"希望","right":"esperar"},{"left":"重要","right":"importante"}],"explanation":"«办法» es una forma de resolver algo, «问题» lo que necesita solución, «希望» un deseo y «重要» una valoración."}'::jsonb, '"matched"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '终于' and w.pinyin = 'zhōngyú' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-01","unit_code":"2.5.3","question":"¿Qué significa 终于?","options":["de repente","por fin","casi","quizá"],"correct":"por fin","explanation":"«终于» señala que algo sucede después de esperar o superar una dificultad; «por fin» conserva ese matiz."}'::jsonb, '"por fin"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '根据' and w.pinyin = 'gēnjù' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-02","unit_code":"2.6.5","question":"¿Qué significa 根据?","options":["según","sin importar","a pesar de","además"],"correct":"según","explanation":"«根据» introduce la información en la que se apoya una decisión; «según» indica esa base."}'::jsonb, '"según"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '虽然' and w.pinyin = 'suīrán' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-03","unit_code":"6.3.5","question":"¿Qué significa 虽然?","options":["aunque","porque","por eso","si"],"correct":"aunque","explanation":"«虽然» presenta una dificultad que no impide lo principal; «aunque» introduce ese contraste."}'::jsonb, '"aunque"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '而且' and w.pinyin = 'érqiě' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-04","unit_code":"6.3.4","question":"¿Qué significa 而且?","options":["además","ya","por fin","quizá"],"correct":"además","explanation":"«而且» añade otra característica o acción además de la anterior; «además» expresa esa suma."}'::jsonb, '"además"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '关系' and w.pinyin = 'guānxì' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-05","unit_code":"5.1","question":"¿Qué significa 关系?","options":["relación","resultado","condición","pregunta"],"correct":"relación","explanation":"«关系» habla del vínculo entre personas o cosas; «relación» nombra ese vínculo."}'::jsonb, '"relación"'::jsonb, 'seed', null),
  ('multiple_choice', 3, (select w.id from public.words w where w.hanzi = '如果' and w.pinyin = 'rúguǒ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"multiple_choice","slug":"l3-multiple-choice-06","unit_code":"6.3.6","question":"¿Qué significa 如果?","options":["si","según","aunque","por fin"],"correct":"si","explanation":"«如果» plantea una condición para lo que ocurrirá después; «si» introduce esa condición."}'::jsonb, '"si"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '把' and w.pinyin = 'bǎ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-01","unit_code":"6.2.1","words":["把","请","关上","门"],"correct_order":["请","把","门","关上"],"translation":"请把门关上","explanation":"La petición usa «请 + 把 + objeto + resultado»: «请把门关上» pide cerrar la puerta."}'::jsonb, '"请把门关上"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '把' and w.pinyin = 'bǎ' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-02","unit_code":"6.2.1","words":["做完","他","作业","把","了"],"correct_order":["他","把","作业","做完","了"],"translation":"他把作业做完了","explanation":"La construcción «把» adelanta el objeto y «做完» expresa el resultado: «他把作业做完了» significa que terminó los deberes."}'::jsonb, '"他把作业做完了"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '他' and w.pinyin = 'tā' and w.hsk_level = 1 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-03","unit_code":"2.5.3","words":["到了","他","终于"],"correct_order":["他","终于","到了"],"translation":"他终于到了","explanation":"«终于» va antes del verbo para marcar el resultado esperado: «他终于到了» significa «por fin ha llegado»."}'::jsonb, '"他终于到了"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '虽然' and w.pinyin = 'suīrán' and w.hsk_level = 2 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-04","unit_code":"6.3.5","words":["不好","虽然","天气","还是","去了"],"correct_order":["虽然","天气","不好","还是","去了"],"translation":"虽然天气不好还是去了","explanation":"«虽然» introduce la subordinada y «还是» la principal contra lo esperado: aunque hacía mal tiempo, fuimos."}'::jsonb, '"虽然天气不好还是去了"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '应该' and w.pinyin = 'yīnggāi' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-05","unit_code":"2.5.6","words":["作业","应该","早点","我们","完成"],"correct_order":["我们","应该","早点","完成","作业"],"translation":"我们应该早点完成作业","explanation":"La frase combina sujeto + «应该» + tiempo + verbo + objeto: deberíamos terminar pronto los deberes."}'::jsonb, '"我们应该早点完成作业"'::jsonb, 'seed', null),
  ('reorder', 3, (select w.id from public.words w where w.hanzi = '根据' and w.pinyin = 'gēnjù' and w.hsk_level = 3 and ((w.sense_index is null and null is null) or w.sense_index = null) order by w.id limit 1), '{"type":"reorder","slug":"l3-reorder-06","unit_code":"2.6.5","words":["问题","根据","做","决定","我们"],"correct_order":["我们","根据","问题","做","决定"],"translation":"我们根据问题做决定","explanation":"«根据 + referencia» introduce el criterio y después viene la acción: decidimos según el problema."}'::jsonb, '"我们根据问题做决定"'::jsonb, 'seed', null)
insert into public.reading (slug, hsk_level, format, title, topic, series, series_index, sentences, questions, target_words, target_grammar, audio_kind, sentence_audio)
values
  ('home-01-morning', 2, 'short_text', '奶奶要来了', 'vida diaria', 'casa', 1, '[{"zh":"我叫小明，我家有四个人：爸爸、妈妈、妹妹小雪和我。","pinyin":"Wǒ jiào Xiǎomíng, wǒ jiā yǒu sì gè rén: bàba, māma, mèimei Xiǎoxuě hé wǒ.","es":"Me llamo Xiaoming; en mi casa somos cuatro: papá, mamá, mi hermana pequeña Xiaoxue y yo."},{"zh":"星期天早上，我七点起床。","pinyin":"Xīngqītiān zǎoshang, wǒ qī diǎn qǐchuáng.","es":"El domingo por la mañana me levanto a las siete."},{"zh":"妈妈已经在做早饭了，爸爸在看手机。","pinyin":"Māma yǐjīng zài zuò zǎofàn le, bàba zài kàn shǒujī.","es":"Mamá ya está haciendo el desayuno y papá está mirando el móvil."},{"zh":"小雪还在睡觉，她说她很累。","pinyin":"Xiǎoxuě hái zài shuìjiào, tā shuō tā hěn lèi.","es":"Xiaoxue todavía duerme; dice que está muy cansada."},{"zh":"吃早饭的时候，妈妈告诉我们一件事情。","pinyin":"Chī zǎofàn de shíhou, māma gàosu wǒmen yí jiàn shìqing.","es":"Mientras desayunamos, mamá nos cuenta una cosa."},{"zh":"奶奶快要来我们家住了。","pinyin":"Nǎinai kuàiyào lái wǒmen jiā zhù le.","es":"La abuela va a venir pronto a vivir a nuestra casa."},{"zh":"奶奶七十多岁了，现在一个人住。","pinyin":"Nǎinai qīshí duō suì le, xiànzài yí gè rén zhù.","es":"La abuela tiene más de setenta años y ahora vive sola."},{"zh":"爸爸说她跟我们一起住，我们每天都能看见她。","pinyin":"Bàba shuō tā gēn wǒmen yìqǐ zhù, wǒmen měi tiān dōu néng kànjiàn tā.","es":"Papá dice que, si vive con nosotros, podremos verla todos los días."},{"zh":"我和小雪都很高兴，我们要给奶奶准备一个房间。","pinyin":"Wǒ hé Xiǎoxuě dōu hěn gāoxìng, wǒmen yào gěi nǎinai zhǔnbèi yí gè fángjiān.","es":"Xiaoxue y yo estamos muy contentos; vamos a preparar una habitación para la abuela."}]'::jsonb, '[{"prompt":"谁快要来小明家住？","options":["爷爷","奶奶","小雪"],"answer_index":1,"evidence_sentence":5},{"prompt":"星期天早上，妈妈在做什么？","options":["在睡觉","在看手机","在做早饭"],"answer_index":2,"evidence_sentence":2},{"prompt":"小明和小雪要给奶奶准备什么？","options":["一个房间","一本书","一件衣服"],"answer_index":0,"evidence_sentence":8}]'::jsonb, array['奶奶', '已经', '准备']::text[], '[{"code":"2.7.3","level":2},{"code":"4.1","level":2}]'::jsonb, 'neural', '[{"path":"media/be43c00f2f61ee4f19b64215aafc9bb111116560917e69bf42a44ef47370aa5b.m4a","duration_ms":5851},{"path":"media/715eef8714a5b8d381063520d2f4050954e0aacc5bee66986e40f7aa7f370ebf.m4a","duration_ms":3043},{"path":"media/c07bf3ffedd52c29cbd07ed31881a8fa07c4c7742500acb4f7971642285b9e22.m4a","duration_ms":3691},{"path":"media/393d87987f505dd16edba0cdaaebb73a457ef65e795820e66026d9e919b443e9.m4a","duration_ms":3523},{"path":"media/70f71704b501a39a09274626baf237b78cfff1659550d1fb0de712d7823b91bd.m4a","duration_ms":3691},{"path":"media/27eb281c7ad1ab2ecd0d2f12d519ec003376280ae3c30f858d1cf7aa8599db91.m4a","duration_ms":2395},{"path":"media/b70ac6748d2607f5f56dcf4fafaeabac63ab1f48c34af2612450b51b0df17faa.m4a","duration_ms":3475},{"path":"media/1d8e8f19bbfe30716a61a4faca6cccf1abc867a29cbe250ab3a6e716ab69ff7f.m4a","duration_ms":4603},{"path":"media/c5d454b4be0dbb31fdb9330f3570f7f99535b505b1d22879ee7eb50e5dc46730.m4a","duration_ms":4243}]'::jsonb),
  ('home-02-cooking', 2, 'story', '给奶奶的房间', 'vida diaria', 'casa', 2, '[{"zh":"奶奶的房间在我的房间旁边，里面有床、桌子和椅子。","pinyin":"Nǎinai de fángjiān zài wǒ de fángjiān pángbiān, lǐmiàn yǒu chuáng, zhuōzi hé yǐzi.","es":"La habitación de la abuela está al lado de la mía; dentro hay una cama, una mesa y sillas."},{"zh":"星期六，爸爸妈妈打开门，开始准备房间。","pinyin":"Xīngqīliù, bàba māma dǎkāi mén, kāishǐ zhǔnbèi fángjiān.","es":"El sábado, papá y mamá abren la puerta y empiezan a preparar la habitación."},{"zh":"我也来帮忙，桌子上的东西都是我拿出去的。","pinyin":"Wǒ yě lái bāngmáng, zhuōzi shàng de dōngxi dōu shì wǒ ná chūqù de.","es":"Yo también vengo a ayudar: las cosas que había sobre la mesa las saqué todas yo."},{"zh":"“我也想帮忙！”小雪说。","pinyin":"\"Wǒ yě xiǎng bāngmáng!\" Xiǎoxuě shuō.","es":"«¡Yo también quiero ayudar!», dice Xiaoxue."},{"zh":"妈妈笑着让小雪给奶奶画画。","pinyin":"Māma xiào zhe ràng Xiǎoxuě gěi nǎinai huà huà.","es":"Mamá, sonriendo, le pide a Xiaoxue que haga un dibujo para la abuela."},{"zh":"小雪坐在桌子旁边，画了我们一家人。","pinyin":"Xiǎoxuě zuò zài zhuōzi pángbiān, huà le wǒmen yì jiārén.","es":"Xiaoxue se sienta junto a la mesa y dibuja a toda la familia."},{"zh":"她的画有红色、绿色和白色，颜色很漂亮。","pinyin":"Tā de huà yǒu hóngsè, lǜsè hé báisè, yánsè hěn piàoliang.","es":"Su dibujo tiene rojo, verde y blanco; los colores son muy bonitos."},{"zh":"晚上，房间已经准备好了，小雪的画在桌子上面。","pinyin":"Wǎnshang, fángjiān yǐjīng zhǔnbèi hǎo le, Xiǎoxuě de huà zài zhuōzi shàngmiàn.","es":"Por la noche la habitación ya está preparada y el dibujo de Xiaoxue está encima de la mesa."},{"zh":"爸爸说奶奶看见这个画，会非常高兴。","pinyin":"Bàba shuō nǎinai kànjiàn zhège huà, huì fēicháng gāoxìng.","es":"Papá dice que, cuando la abuela vea este dibujo, se pondrá muy contenta."}]'::jsonb, '[{"prompt":"奶奶的房间在哪儿？","options":["在门口","在小明的房间旁边","在小雪的房间里面"],"answer_index":1,"evidence_sentence":0},{"prompt":"小雪做了什么？","options":["画了一个画","准备早饭","拿东西出去"],"answer_index":0,"evidence_sentence":5},{"prompt":"晚上，小雪的画在哪儿？","options":["在床上","在门口","在桌子上面"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['帮忙', '画', '颜色']::text[], '[{"code":"2.2.3","level":2},{"code":"6.3.6","level":2},{"code":"6.3.5","level":2}]'::jsonb, 'neural', '[{"path":"media/308cd66c961a6a3857731effe5613736558925a2d669f92288bf73a7ba3f14cf.m4a","duration_ms":5323},{"path":"media/989fb8d0c447bb8218de722219d3508fb5ce241d2780979c7f89bfc3a8748671.m4a","duration_ms":4435},{"path":"media/8383b86a1e2337a62bf4bbe91771c526465284a60027a8623927d96cb25460ae.m4a","duration_ms":4435},{"path":"media/1df84c29b2ca40eed119ec636fdfa8d2c2297112d91a0f9fea610686d7a8d262.m4a","duration_ms":3259},{"path":"media/915ba9fc5af5e566bc556a2bf4380c502a2f98db518ae8798b43bb38e4a531fb.m4a","duration_ms":3595},{"path":"media/b3f6f1dba19d67f54da869165d64808c8a1abf977de9b1b308e13973eb739e63.m4a","duration_ms":3763},{"path":"media/043f06abd57bfe3f3e7505ef5a6c404c0db40ddf95fa7b7787093a46a7404dff.m4a","duration_ms":5227},{"path":"media/8788ea88517a330680519442c28bbdb80e5f20d8eb9620646fa0129bf0173e64.m4a","duration_ms":4555},{"path":"media/b008b05a3f07c833c85f68bc545c08e2fc6695d929557cedd78d321a14d5443a.m4a","duration_ms":4219}]'::jsonb),
  ('casa-03-grandma-arrives', 2, 'dialogue', '在车站等奶奶', 'vida diaria', 'casa', 3, '[{"zh":"星期天下午，爸爸和我去车站等奶奶。","pinyin":"Xīngqītiān xiàwǔ, bàba hé wǒ qù chēzhàn děng nǎinai.","es":"El domingo por la tarde, papá y yo vamos a la estación a esperar a la abuela."},{"zh":"小明：爸爸，奶奶的车几点到？","pinyin":"Xiǎomíng: Bàba, nǎinai de chē jǐ diǎn dào?","es":"Xiaoming: Papá, ¿a qué hora llega el tren de la abuela?"},{"zh":"爸爸：三点半，我们早来了二十分钟。","pinyin":"Bàba: Sān diǎn bàn, wǒmen zǎo lái le èrshí fēnzhōng.","es":"Papá: A las tres y media; hemos llegado veinte minutos antes."},{"zh":"小明：奶奶从哪个门出来？","pinyin":"Xiǎomíng: Nǎinai cóng nǎge mén chūlái?","es":"Xiaoming: ¿Por qué puerta sale la abuela?"},{"zh":"爸爸：左边那个门，我们在门口等她吧。","pinyin":"Bàba: Zuǒbian nàge mén, wǒmen zài ménkǒu děng tā ba.","es":"Papá: Por la de la izquierda; esperémosla en la entrada."},{"zh":"奶奶：小明！我在这儿！","pinyin":"Nǎinai: Xiǎomíng! Wǒ zài zhèr!","es":"Abuela: ¡Xiaoming! ¡Estoy aquí!"},{"zh":"小明：奶奶好！路上累不累？","pinyin":"Xiǎomíng: Nǎinai hǎo! Lùshang lèi bu lèi?","es":"Xiaoming: ¡Hola, abuela! ¿Estás cansada del viaje?"},{"zh":"奶奶：不累，车上的人都很好。","pinyin":"Nǎinai: Bú lèi, chē shàng de rén dōu hěn hǎo.","es":"Abuela: No; la gente del tren ha sido muy amable."},{"zh":"爸爸：妈妈，我们是坐出租车回家，还是坐地铁回家？","pinyin":"Bàba: Māma, wǒmen shì zuò chūzūchē huí jiā, háishi zuò dìtiě huí jiā?","es":"Papá: Mamá, ¿volvemos a casa en taxi o en metro?"},{"zh":"奶奶：坐地铁吧，我想看看这里的地铁。","pinyin":"Nǎinai: Zuò dìtiě ba, wǒ xiǎng kàn kàn zhèlǐ de dìtiě.","es":"Abuela: En metro; quiero ver el metro de aquí."}]'::jsonb, '[{"prompt":"奶奶的车几点到？","options":["两点半","三点半","四点"],"answer_index":1,"evidence_sentence":2},{"prompt":"他们在哪儿等奶奶？","options":["左边的门口","车上","家里"],"answer_index":0,"evidence_sentence":4},{"prompt":"他们怎么回家？","options":["坐出租车","走路","坐地铁"],"answer_index":2,"evidence_sentence":9}]'::jsonb, array['车站', '出来', '路上']::text[], '[{"code":"5.4.2","level":2},{"code":"6.2.1","level":2}]'::jsonb, 'neural', '[{"path":"media/9f2fc6b4838656032fed53df20075c412d903902664a43cc97dd0a5a99602d48.m4a","duration_ms":3859},{"path":"media/36ecaa46034c0f7a0dda93f5777f8b2a4b4a05902bbdfce0a4ac401541df246f.m4a","duration_ms":3139},{"path":"media/86ec4c5f8f06dc1ddacf0b0889d48ea1056fc71393a91381e6c4d51bb5df3537.m4a","duration_ms":3523},{"path":"media/060651d8b30edb7c84e58ecb4789fdf1d20b4dd9d2a40f40b9cfa998c10e417e.m4a","duration_ms":2299},{"path":"media/269308e3ce2b612fb44e3ea8cae0f645901d316982a239893149a1325020e012.m4a","duration_ms":3667},{"path":"media/d499a62c0b8141ab9cac01ac843a5888cee68bbf9606af8ede90bed80c397469.m4a","duration_ms":2587},{"path":"media/b41fa317c6e6d6d7657daba25d5fa0af73374916027a4ca427898621979d8460.m4a","duration_ms":3043},{"path":"media/cd790692d472418769c58c118397af68330c5ce360e01283912584ec76471dec.m4a","duration_ms":2755},{"path":"media/86f9f431352faa512cc16799a2a1382166c4cb22b7faffca085b9fcb3e4a5bd6.m4a","duration_ms":4771},{"path":"media/5f43d119ba14f9c0a3a1b1131b1fdad6574c5c37dbc72730aa11528c2dcf674d.m4a","duration_ms":3379}]'::jsonb),
  ('casa-04-first-week', 2, 'short_text', '奶奶的一个星期', 'vida diaria', 'casa', 4, '[{"zh":"奶奶来我们家已经一个星期了。","pinyin":"Nǎinai lái wǒmen jiā yǐjīng yí gè xīngqī le.","es":"Ya hace una semana que la abuela vino a nuestra casa."},{"zh":"她每天早上六点就起床，比我们都早。","pinyin":"Tā měi tiān zǎoshang liù diǎn jiù qǐchuáng, bǐ wǒmen dōu zǎo.","es":"Cada mañana se levanta ya a las seis, antes que todos nosotros."},{"zh":"起床后，她去外面走路，有时候也跑步。","pinyin":"Qǐchuáng hòu, tā qù wàimiàn zǒulù, yǒushíhou yě pǎobù.","es":"Después de levantarse sale a caminar y a veces también corre."},{"zh":"奶奶跑得不快，但是她跑得很高兴。","pinyin":"Nǎinai pǎo de bú kuài, dànshì tā pǎo de hěn gāoxìng.","es":"La abuela no corre rápido, pero corre muy contenta."},{"zh":"回来的时候，她经常给我们买早饭。","pinyin":"Huílái de shíhou, tā jīngcháng gěi wǒmen mǎi zǎofàn.","es":"Cuando vuelve, a menudo nos compra el desayuno."},{"zh":"下午，奶奶教小雪做饭。","pinyin":"Xiàwǔ, nǎinai jiāo Xiǎoxuě zuòfàn.","es":"Por la tarde, la abuela enseña a Xiaoxue a cocinar."},{"zh":"她做的鱼非常好吃，爸爸说他小时候也经常吃奶奶做的鱼。","pinyin":"Tā zuò de yú fēicháng hǎochī, bàba shuō tā xiǎoshíhou yě jīngcháng chī nǎinai zuò de yú.","es":"El pescado que hace está buenísimo; papá dice que de pequeño también comía a menudo el pescado de la abuela."},{"zh":"现在小雪也会做一点儿菜了。","pinyin":"Xiànzài Xiǎoxuě yě huì zuò yìdiǎnr cài le.","es":"Ahora Xiaoxue también sabe cocinar un poco."},{"zh":"我觉得家里有奶奶，大家都很快乐。","pinyin":"Wǒ juéde jiā lǐ yǒu nǎinai, dàjiā dōu hěn kuàilè.","es":"Creo que, con la abuela en casa, todos somos muy felices."}]'::jsonb, '[{"prompt":"奶奶每天几点起床？","options":["五点","七点","六点"],"answer_index":2,"evidence_sentence":1},{"prompt":"下午，奶奶教小雪做什么？","options":["做饭","跑步","写字"],"answer_index":0,"evidence_sentence":5},{"prompt":"爸爸小时候经常吃什么？","options":["奶奶做的鱼","妈妈做的饺子","外面的面包"],"answer_index":0,"evidence_sentence":6}]'::jsonb, array['跑步', '经常', '鱼']::text[], '[{"code":"2.7.4","level":2},{"code":"2.10.1","level":2}]'::jsonb, 'neural', '[{"path":"media/2a83989eefb5e3b986d258e05fb89cfe004dd9363cbae0738935f8665d078416.m4a","duration_ms":3235},{"path":"media/1356dd508228add3deaea5d041b4d3861965b5aadabbe43fba1123868f21f44a.m4a","duration_ms":4003},{"path":"media/91f0a01c5c087f7aaf3893526792b4765594fff4361949166fb2a160ca82103e.m4a","duration_ms":4243},{"path":"media/b7ff2d2c63408fe733dd2aaf158ab3319c93eed74c03c3eeea632b7d77db0f33.m4a","duration_ms":3619},{"path":"media/70c6ebd84c0f93f110e904488d38b147585f0e673ae73888113f470b3f71e239.m4a","duration_ms":3547},{"path":"media/2c1962e03ae5c689cc194168cb3d36fe037e8420c6778f93f403524da4cadf01.m4a","duration_ms":3211},{"path":"media/3e303e38f909fc3360b190af861940a127ae0760824f8af6cc63e4d40ee782f3.m4a","duration_ms":5371},{"path":"media/f19838de46cbdf746c0c19cf23891543249632ad9db5b95811b55515856cc30c.m4a","duration_ms":3043},{"path":"media/d4635431d527f19a53f469ad75b14f2696f7ad77bf38768b9c520a263e241c81.m4a","duration_ms":3499}]'::jsonb),
  ('casa-05-birthday-plan', 2, 'dialogue', '送奶奶什么', 'vida diaria', 'casa', 5, '[{"zh":"小雪：哥哥，下个星期三是奶奶的生日。","pinyin":"Xiǎoxuě: Gēge, xià gè xīngqīsān shì nǎinai de shēngrì.","es":"Xiaoxue: Hermano, el miércoles que viene es el cumpleaños de la abuela."},{"zh":"小明：我知道，我们送奶奶什么呢？","pinyin":"Xiǎomíng: Wǒ zhīdào, wǒmen sòng nǎinai shénme ne?","es":"Xiaoming: Ya lo sé; ¿qué le regalamos a la abuela?"},{"zh":"小雪：送她一件红色的衣服，好不好？","pinyin":"Xiǎoxuě: Sòng tā yí jiàn hóngsè de yīfu, hǎo bu hǎo?","es":"Xiaoxue: ¿Le regalamos una prenda de ropa roja?"},{"zh":"小明：她的衣服已经很多了。","pinyin":"Xiǎomíng: Tā de yīfu yǐjīng hěn duō le.","es":"Xiaoming: Ya tiene mucha ropa."},{"zh":"小雪：那送她一块手表吧，她每天早上跑步要看时间。","pinyin":"Xiǎoxuě: Nà sòng tā yí kuài shǒubiǎo ba, tā měi tiān zǎoshang pǎobù yào kàn shíjiān.","es":"Xiaoxue: Entonces regalémosle un reloj; cada mañana, cuando corre, tiene que mirar la hora."},{"zh":"小明：很好！但是手表很贵，我们的钱可能不多。","pinyin":"Xiǎomíng: Hěn hǎo! Dànshì shǒubiǎo hěn guì, wǒmen de qián kěnéng bù duō.","es":"Xiaoming: ¡Muy bien! Pero los relojes son caros y puede que no tengamos bastante dinero."},{"zh":"妈妈：为什么在说钱？你们想买什么？","pinyin":"Māma: Wèishénme zài shuō qián? Nǐmen xiǎng mǎi shénme?","es":"Mamá: ¿Por qué habláis de dinero? ¿Qué queréis comprar?"},{"zh":"小雪：妈妈，别告诉奶奶，我们想给她买手表。","pinyin":"Xiǎoxuě: Māma, bié gàosu nǎinai, wǒmen xiǎng gěi tā mǎi shǒubiǎo.","es":"Xiaoxue: Mamá, no se lo digas a la abuela: queremos comprarle un reloj."},{"zh":"妈妈：好，我给你们一些钱，星期六一起去商场买。","pinyin":"Māma: Hǎo, wǒ gěi nǐmen yìxiē qián, xīngqīliù yìqǐ qù shāngchǎng mǎi.","es":"Mamá: Vale, os doy algo de dinero y el sábado vamos juntos al centro comercial a comprarlo."}]'::jsonb, '[{"prompt":"奶奶的生日是哪天？","options":["下个星期三","这个星期六","今天"],"answer_index":0,"evidence_sentence":0},{"prompt":"小雪为什么想送手表？","options":["因为奶奶的手表坏了","因为奶奶跑步要看时间","因为手表很便宜"],"answer_index":1,"evidence_sentence":4},{"prompt":"他们什么时候去商场？","options":["星期六","星期三","明天"],"answer_index":0,"evidence_sentence":8}]'::jsonb, array['生日', '送', '手表']::text[], '[{"code":"6.3.7","level":2},{"code":"2.3.1","level":2}]'::jsonb, 'neural', '[{"path":"media/c98cadb7014970a1eebbc20ad977aac890bba5d25aae140fcdb0c2dc779b13bb.m4a","duration_ms":3643},{"path":"media/a3f95f0aa93b337cd97f13e90ee95ff6d646c5b2c73a68783430961405eef300.m4a","duration_ms":3091},{"path":"media/8c1f6d010c62fba6fa7bb6b75d4f061766d0d9c67aeef4b3887631504d22e2fd.m4a","duration_ms":3523},{"path":"media/6c4f4ae9b0f28a63581e50627857afb1961419536980d11406c836be92bd20d1.m4a","duration_ms":2659},{"path":"media/fe63c1f22566e5a5f4e5ad0dbbd7cfc2f2ed9665cca042e211bcaa2c3f825cf4.m4a","duration_ms":4531},{"path":"media/cf296d0c4a3f8dad83316f34ee669d127242e2c930dfa1cfb8d31f4cbfac8edd.m4a","duration_ms":4891},{"path":"media/8b7498e41dff740f161d43e1007f9fbc0a161546981fd03226051184d1fede59.m4a","duration_ms":3571},{"path":"media/7cf257eb66b37261f1646c897f5eedac3ad5aab87fda408302367802b01a7b3a.m4a","duration_ms":4171},{"path":"media/d1a67dcf8ed1a97c1116bd66661efbfc22fdf21d9940ef9f8cdd7004e7559bcf.m4a","duration_ms":4291}]'::jsonb),
  ('casa-06-birthday', 2, 'story', '奶奶的生日', 'vida diaria', 'casa', 6, '[{"zh":"星期三晚上，妈妈做了很多奶奶喜欢吃的菜。","pinyin":"Xīngqīsān wǎnshang, māma zuò le hěn duō nǎinai xǐhuan chī de cài.","es":"El miércoles por la noche, mamá hizo muchos platos de los que le gustan a la abuela."},{"zh":"奶奶一进门就笑了。","pinyin":"Nǎinai yí jìn mén jiù xiào le.","es":"En cuanto la abuela entró por la puerta, se echó a reír."},{"zh":"我们一起对奶奶说生日快乐。","pinyin":"Wǒmen yìqǐ duì nǎinai shuō shēngrì kuàilè.","es":"Todos juntos le deseamos a la abuela feliz cumpleaños."},{"zh":"小雪给了奶奶一块手表，说这是她和哥哥送的。","pinyin":"Xiǎoxuě gěi le nǎinai yí kuài shǒubiǎo, shuō zhè shì tā hé gēge sòng de.","es":"Xiaoxue le dio a la abuela un reloj y le dijo que era un regalo de su hermano y suyo."},{"zh":"奶奶打开一看，笑得眼睛都没有了。","pinyin":"Nǎinai dǎkāi yí kàn, xiào de yǎnjing dōu méiyǒu le.","es":"La abuela lo abrió, lo miró y sonrió tanto que se le cerraron los ojos."},{"zh":"她说明天跑步的时候，就能看时间了。","pinyin":"Tā shuō míngtiān pǎobù de shíhou, jiù néng kàn shíjiān le.","es":"Dijo que mañana, cuando corra, ya podrá ver la hora."},{"zh":"吃饭的时候，爸爸问奶奶在这里住得舒服不舒服。","pinyin":"Chī fàn de shíhou, bàba wèn nǎinai zài zhèlǐ zhù de shūfu bù shūfu.","es":"Durante la cena, papá le preguntó a la abuela si estaba a gusto viviendo aquí."},{"zh":"奶奶说住在这里很好，她希望每年都跟我们一起过生日。","pinyin":"Nǎinai shuō zhù zài zhèlǐ hěn hǎo, tā xīwàng měi nián dōu gēn wǒmen yìqǐ guò shēngrì.","es":"La abuela dijo que aquí se vive muy bien y que espera celebrar todos los años su cumpleaños con nosotros."},{"zh":"那天晚上，我们一家人都很快乐。","pinyin":"Nà tiān wǎnshang, wǒmen yì jiārén dōu hěn kuàilè.","es":"Aquella noche toda la familia estuvo muy feliz."}]'::jsonb, '[{"prompt":"奶奶一进门怎么了？","options":["走了","笑了","睡觉了"],"answer_index":1,"evidence_sentence":1},{"prompt":"手表是谁送的？","options":["爸爸和妈妈","奶奶的朋友","小雪和小明"],"answer_index":2,"evidence_sentence":3},{"prompt":"奶奶希望每年怎么样？","options":["跟他们一起过生日","一个人住","去外国旅游"],"answer_index":0,"evidence_sentence":7}]'::jsonb, array['快乐', '希望', '笑']::text[], '[{"code":"6.4.4","level":2},{"code":"5.4.3","level":2}]'::jsonb, 'neural', '[{"path":"media/58415cf38930d5e846197de6031a8eab142ce9c2366121587e53051f5398d410.m4a","duration_ms":4147},{"path":"media/9000cc3d45bc5f185be690a111e6895ebb51aa52f7129df24b573a9db3e08153.m4a","duration_ms":2395},{"path":"media/fabef37699550185c2a0549f1fa2fa50984a091015a3aa67c09e9ec73294baf6.m4a","duration_ms":3235},{"path":"media/260348493c4db806c60cc1b79b363028368a0fe35f9c937895b06db6c8809d19.m4a","duration_ms":5083},{"path":"media/30a91658cc768812c0fcb933e1cd3f174ef5ff7dcefea5c92df40736aa57d995.m4a","duration_ms":3691},{"path":"media/4de425b45a0c7c20866d51bc15650758de7b433e6dd0b9c6ba3931669494de76.m4a","duration_ms":4363},{"path":"media/8d93116d7aba4bad8cd4afaf2a7aa536abdd4618d47f69c91e0849cb8eb6dd87.m4a","duration_ms":5275},{"path":"media/a0cdd3f0d44dfc990fe4fb961ac9e637c4b756e51ff4277380d687415ef82454.m4a","duration_ms":5251},{"path":"media/3f2db87cec09d0e174a38218be0d79704664a3c761d203d94567634261c98b8d.m4a","duration_ms":3451}]'::jsonb),
  ('school-01-new-classmate', 2, 'story', '新同学', 'estudio', 'escuela', 1, '[{"zh":"我叫李文，是这个班的学生。","pinyin":"Wǒ jiào Lǐ Wén, shì zhège bān de xuéshēng.","es":"Me llamo Li Wen y soy alumna de esta clase."},{"zh":"开学第一天，我们班来了一位新同学。","pinyin":"Kāixué dì yī tiān, wǒmen bān lái le yí wèi xīn tóngxué.","es":"El primer día de curso llegó a nuestra clase un compañero nuevo."},{"zh":"王老师给我们介绍他：他叫大卫，是从外国来的。","pinyin":"Wáng lǎoshī gěi wǒmen jièshào tā: tā jiào Dàwèi, shì cóng wàiguó lái de.","es":"La profesora Wang nos lo presentó: se llama David y viene del extranjero."},{"zh":"大卫个子很高，眼睛很大，笑起来很好看。","pinyin":"Dàwèi gèzi hěn gāo, yǎnjing hěn dà, xiào qǐlái hěn hǎokàn.","es":"David es muy alto, tiene los ojos grandes y tiene una sonrisa bonita."},{"zh":"他会说一点儿汉语，但是还不会写汉字。","pinyin":"Tā huì shuō yìdiǎnr Hànyǔ, dànshì hái bú huì xiě Hànzì.","es":"Habla un poco de chino, pero todavía no sabe escribir caracteres."},{"zh":"王老师让他坐在我旁边。","pinyin":"Wáng lǎoshī ràng tā zuò zài wǒ pángbiān.","es":"La profesora Wang le dijo que se sentara a mi lado."},{"zh":"下课的时候，大卫问我一个字是什么意思。","pinyin":"Xiàkè de shíhou, Dàwèi wèn wǒ yí gè zì shì shénme yìsi.","es":"En el descanso, David me preguntó qué significaba un carácter."},{"zh":"我告诉了他，他笑着对我说谢谢。","pinyin":"Wǒ gàosu le tā, tā xiào zhe duì wǒ shuō xièxie.","es":"Se lo dije y él, sonriendo, me dio las gracias."},{"zh":"我觉得认识一个外国朋友很有意思。","pinyin":"Wǒ juéde rènshi yí gè wàiguó péngyou hěn yǒuyìsi.","es":"Me parece muy interesante conocer a un amigo extranjero."}]'::jsonb, '[{"prompt":"新同学是从哪儿来的？","options":["从外国来的","从医院来的","从商店来的"],"answer_index":0,"evidence_sentence":2},{"prompt":"王老师让大卫坐在哪儿？","options":["门口","李文旁边","前面"],"answer_index":1,"evidence_sentence":5},{"prompt":"李文觉得认识外国朋友怎么样？","options":["很有意思","没意思","很累"],"answer_index":0,"evidence_sentence":8}]'::jsonb, array['介绍', '外国', '位']::text[], '[{"code":"2.6.1","level":2},{"code":"6.3.5","level":2}]'::jsonb, 'neural', '[{"path":"media/788c331d19d2f9355f8936c6272d7775a89a313ffc680b5da24314b5f144a078.m4a","duration_ms":3115},{"path":"media/a7f62e2e386749bfe26fbe34092d15e80090da369872c88ea3a91a3c1636e4d9.m4a","duration_ms":3883},{"path":"media/6f0f7f489c505c0438837b5b981c6ab79271755f4602d0908e9d29e4e5eaff28.m4a","duration_ms":4939},{"path":"media/e9e2a80b7d3086b735fa950554fd6d5eec8d96b5d39e40ef007ae5c75d9c762a.m4a","duration_ms":4339},{"path":"media/0588029e9277fcab313a6ba888ce298531f9bd07588752c0fa904f364cd49e3b.m4a","duration_ms":3979},{"path":"media/09d26576b2d3dd4b5656aeddaa5d50f363c1c6c957a312243ed9f12e304c1a99.m4a","duration_ms":2683},{"path":"media/25da42a76af945a3279c9f2d9d9b9519abc347c410d2a509182cb6f65a3ae76d.m4a","duration_ms":4291},{"path":"media/4c919c5840b79e555e91f0dfd26f28d4238b12e85ed7a8b929007052f47e947a.m4a","duration_ms":3643},{"path":"media/6172aa9705f18618b02ba2bb61441d2c5cd2f9c1a8ef57c046cb9c6df76fbcd2.m4a","duration_ms":3931}]'::jsonb),
  ('school-02-forgot-homework', 2, 'dialogue', '大卫为什么没来', 'estudio', 'escuela', 2, '[{"zh":"星期一，大卫没有来上课。","pinyin":"Xīngqīyī, Dàwèi méiyǒu lái shàngkè.","es":"El lunes David no vino a clase."},{"zh":"王老师：李文，你知道大卫为什么没来吗？","pinyin":"Wáng lǎoshī: Lǐ Wén, nǐ zhīdào Dàwèi wèishénme méi lái ma?","es":"Profesora Wang: Li Wen, ¿sabes por qué no ha venido David?"},{"zh":"李文：他昨天给我打电话，说他身体不舒服。","pinyin":"Lǐ Wén: Tā zuótiān gěi wǒ dǎdiànhuà, shuō tā shēntǐ bù shūfu.","es":"Li Wen: Ayer me llamó por teléfono y me dijo que no se encontraba bien."},{"zh":"王老师：他去医院了吗？","pinyin":"Wáng lǎoshī: Tā qù yīyuàn le ma?","es":"Profesora Wang: ¿Ha ido al hospital?"},{"zh":"李文：去了，医生说他要休息两天。","pinyin":"Lǐ Wén: Qù le, yīshēng shuō tā yào xiūxi liǎng tiān.","es":"Li Wen: Sí; el médico le ha dicho que tiene que descansar dos días."},{"zh":"王老师：那这两天上课的东西，你能告诉他吗？","pinyin":"Wáng lǎoshī: Nà zhè liǎng tiān shàngkè de dōngxi, nǐ néng gàosu tā ma?","es":"Profesora Wang: Entonces, ¿puedes contarle lo que demos en clase estos dos días?"},{"zh":"李文：可以，下课后我给他打电话。","pinyin":"Lǐ Wén: Kěyǐ, xiàkè hòu wǒ gěi tā dǎdiànhuà.","es":"Li Wen: Sí; después de clase lo llamo por teléfono."},{"zh":"王老师：好。因为他是新同学，所以我们要多帮他。","pinyin":"Wáng lǎoshī: Hǎo. Yīnwèi tā shì xīn tóngxué, suǒyǐ wǒmen yào duō bāng tā.","es":"Profesora Wang: Bien. Como es un compañero nuevo, tenemos que ayudarle mucho."},{"zh":"李文：好的，老师。","pinyin":"Lǐ Wén: Hǎo de, lǎoshī.","es":"Li Wen: De acuerdo, profesora."}]'::jsonb, '[{"prompt":"大卫为什么没来上课？","options":["因为去旅游了","因为身体不舒服","因为忘了时间"],"answer_index":1,"evidence_sentence":2},{"prompt":"医生说大卫要怎么样？","options":["多运动","休息两天","马上上课"],"answer_index":1,"evidence_sentence":4},{"prompt":"李文下课后要做什么？","options":["去医院","写汉字","给大卫打电话"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['因为', '所以', '身体']::text[], '[{"code":"6.4.3","level":2},{"code":"2.3.1","level":2}]'::jsonb, 'neural', '[{"path":"media/ae2c5b5acc3369910937a231142ef8282ed98a65499d5571df95a429336490da.m4a","duration_ms":3091},{"path":"media/2cc748259c07b3651aa3dfefc17bcc8268995ca3635385ee085aa1fcf3dc06ed.m4a","duration_ms":3307},{"path":"media/81856dea67bb8bf09894803a0ade94a2442c40c832a4ac1bf0d5159670cb6556.m4a","duration_ms":3931},{"path":"media/75f1bcded597679b7cb9851047e8690bc9bc72c3533d68dc14cb42e1a55722e5.m4a","duration_ms":1915},{"path":"media/f81b478267f28b4868758e1a7533c25fcfacb4139d96d0dfc8e49465fb53e368.m4a","duration_ms":3235},{"path":"media/cba43316db067c960125de4290ca68d72103fde5117a7fd392ca2e3200bb3e85.m4a","duration_ms":3547},{"path":"media/4bf6ae59e71359986859930cb2af6237d232ff0cc0fbd4c50c7ffd8bd439556c.m4a","duration_ms":3475},{"path":"media/e98fc4a1e8074ea4304653a07698141efb5cd4a5a4bb707d57b0290897646c9e.m4a","duration_ms":4651},{"path":"media/1f71fa2d5afc681cfc807581fd0a4edb444968e5e99f77e8a36c9c6e3d58b20d.m4a","duration_ms":2107}]'::jsonb),
  ('escuela-03-characters', 2, 'short_text', '大卫学汉字', 'estudio', 'escuela', 3, '[{"zh":"大卫回来上课了，他的身体已经好了。","pinyin":"Dàwèi huílái shàngkè le, tā de shēntǐ yǐjīng hǎo le.","es":"David ha vuelto a clase; ya se ha recuperado."},{"zh":"他说汉字不好写，但是他很想学。","pinyin":"Tā shuō Hànzì bù hǎo xiě, dànshì tā hěn xiǎng xué.","es":"Dice que los caracteres no son fáciles de escribir, pero tiene muchas ganas de aprender."},{"zh":"每天下课后，我们在教室里一起学习一个小时。","pinyin":"Měi tiān xiàkè hòu, wǒmen zài jiàoshì lǐ yìqǐ xuéxí yí gè xiǎoshí.","es":"Cada día, después de clase, estudiamos juntos una hora en el aula."},{"zh":"我写一个字，他就跟着写一个。","pinyin":"Wǒ xiě yí gè zì, tā jiù gēn zhe xiě yí gè.","es":"Yo escribo un carácter y él escribe uno detrás de mí."},{"zh":"他写得很慢，但是写得很对。","pinyin":"Tā xiě de hěn màn, dànshì xiě de hěn duì.","es":"Escribe muy despacio, pero lo escribe bien."},{"zh":"他有一个小本子，里面写着很多新词。","pinyin":"Tā yǒu yí gè xiǎo běnzi, lǐmiàn xiě zhe hěn duō xīn cí.","es":"Tiene un cuaderno pequeño en el que hay escritas muchas palabras nuevas."},{"zh":"有的词他还不懂，就拿着笔来问我。","pinyin":"Yǒude cí tā hái bù dǒng, jiù ná zhe bǐ lái wèn wǒ.","es":"Cuando hay palabras que aún no entiende, viene con el bolígrafo a preguntarme."},{"zh":"一个星期后，大卫已经会写五十多个汉字了。","pinyin":"Yí gè xīngqī hòu, Dàwèi yǐjīng huì xiě wǔshí duō gè Hànzì le.","es":"Una semana después, David ya sabe escribir más de cincuenta caracteres."},{"zh":"王老师看了他的本子，说他写得很好。","pinyin":"Wáng lǎoshī kàn le tā de běnzi, shuō tā xiě de hěn hǎo.","es":"La profesora Wang miró su cuaderno y dijo que escribe muy bien."}]'::jsonb, '[{"prompt":"他们每天在哪儿学习？","options":["在家里","在教室里","在饭馆"],"answer_index":1,"evidence_sentence":2},{"prompt":"大卫的本子里写着什么？","options":["很多新词","老师的名字","电话号码"],"answer_index":0,"evidence_sentence":5},{"prompt":"一个星期后，大卫会写多少汉字？","options":["十多个","一百个","五十多个"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['懂', '本子', '笔']::text[], '[{"code":"5.4.3","level":2},{"code":"6.3.3","level":2},{"code":"7.1.1","level":2}]'::jsonb, 'neural', '[{"path":"media/b2f3f2295142be99781547f65b162ac5f4b3963ca12c7e3dc93304d1d15d8f86.m4a","duration_ms":3787},{"path":"media/b0fc4f138973f2f7b2ef7e68d19c1b954fba6a6e80a06cab9a59e77d47e2d92e.m4a","duration_ms":3739},{"path":"media/b5259f71642dc9d07156ebdaf3fbd6d04156a00b6e18c9794aa1f9ee27dd86d6.m4a","duration_ms":4723},{"path":"media/f666c62185bf87d754cdc25f91b775059209ab99dbd0964e564960ccca0a126c.m4a","duration_ms":3187},{"path":"media/67033cc101af934541f605cd349e9398f9f4000f54929bdbe6131b4714a30175.m4a","duration_ms":3163},{"path":"media/f0b1dd1ef57ee1e05b0ad5596bfa7027677b762e985591c9dd539a0aebec4f69.m4a","duration_ms":3907},{"path":"media/3fef181b074feb15b4368c856f84d08d57e014402e1708344bd47bf464ec5457.m4a","duration_ms":3811},{"path":"media/85cd8953a49622a32daab9e30e04089643a1cd70651f8e1197253e86cd54dd2e.m4a","duration_ms":4531},{"path":"media/60d3052b24959143fcfad8495d150a81e41d86eb4619a4a9a621bfced86dcb34.m4a","duration_ms":3739}]'::jsonb),
  ('escuela-04-before-exam', 2, 'dialogue', '考试前', 'estudio', 'escuela', 4, '[{"zh":"星期四下午，王老师告诉大家，下星期一有考试。","pinyin":"Xīngqīsì xiàwǔ, Wáng lǎoshī gàosu dàjiā, xià xīngqīyī yǒu kǎoshì.","es":"El jueves por la tarde, la profesora Wang dijo a todos que el lunes que viene hay examen."},{"zh":"大卫：李文，考试的问题多不多？","pinyin":"Dàwèi: Lǐ Wén, kǎoshì de wèntí duō bu duō?","es":"David: Li Wen, ¿el examen tiene muchas preguntas?"},{"zh":"李文：不多，王老师说有二十个问题。","pinyin":"Lǐ Wén: Bù duō, Wáng lǎoshī shuō yǒu èrshí gè wèntí.","es":"Li Wen: No muchas; la profesora Wang dice que son veinte preguntas."},{"zh":"大卫：我还有很多词不懂，可能考不好。","pinyin":"Dàwèi: Wǒ hái yǒu hěn duō cí bù dǒng, kěnéng kǎo bù hǎo.","es":"David: Todavía hay muchas palabras que no entiendo; puede que me salga mal."},{"zh":"李文：别不高兴，我们星期六一起准备吧。","pinyin":"Lǐ Wén: Bié bù gāoxìng, wǒmen xīngqīliù yìqǐ zhǔnbèi ba.","es":"Li Wen: No te preocupes; el sábado lo preparamos juntos."},{"zh":"大卫：好啊！在哪儿准备？","pinyin":"Dàwèi: Hǎo a! Zài nǎr zhǔnbèi?","es":"David: ¡Vale! ¿Dónde lo preparamos?"},{"zh":"李文：就在教室，我们九点见。","pinyin":"Lǐ Wén: Jiù zài jiàoshì, wǒmen jiǔ diǎn jiàn.","es":"Li Wen: En el aula misma; nos vemos a las nueve."},{"zh":"大卫：好，我会早一点儿来。","pinyin":"Dàwèi: Hǎo, wǒ huì zǎo yìdiǎnr lái.","es":"David: Bien, vendré un poco antes."},{"zh":"王老师：你们一起学习，很好。别忘了你们的本子和笔。","pinyin":"Wáng lǎoshī: Nǐmen yìqǐ xuéxí, hěn hǎo. Bié wàng le nǐmen de běnzi hé bǐ.","es":"Profesora Wang: Que estudiéis juntos está muy bien. No olvidéis vuestros cuadernos y bolígrafos."}]'::jsonb, '[{"prompt":"考试是什么时候？","options":["这个星期六","下星期一","明天"],"answer_index":1,"evidence_sentence":0},{"prompt":"他们星期六在哪儿准备？","options":["在教室","在大卫家","在饭馆"],"answer_index":0,"evidence_sentence":6},{"prompt":"王老师让他们别忘了什么？","options":["手机","书包","本子和笔"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['考试', '别', '可能']::text[], '[{"code":"6.2.2","level":2},{"code":"2.2.2","level":2}]'::jsonb, 'neural', '[{"path":"media/e7671a66797ba87513e397db9f347594591699d5403b85462e1fa2ccb14c0062.m4a","duration_ms":5227},{"path":"media/819a50bdbf5bdd9c4c11955777473a19e42eaf9ec9a58f089491e66a2fe98b00.m4a","duration_ms":3235},{"path":"media/7f900ab3095b9dfb22ba75e9fdebf81412aefa7c4657adf9cc13d3bd30c722e4.m4a","duration_ms":3787},{"path":"media/f6a342b57152340f4de089cf0875e320eab4d74a823c5766cfc91f166878a70e.m4a","duration_ms":3499},{"path":"media/721f45bc6d0dcb72959085935c6cc6a4bc177b07504c0cc9c0b64bc62dafab21.m4a","duration_ms":3643},{"path":"media/70fc0e47729a2101025f4b98e41c9a880a4cc250287fb0ec65dba19f18efa439.m4a","duration_ms":3187},{"path":"media/8096627f37899945867b5963ff49ca8010e1caebb459c76c52fa51e3584e7ef6.m4a","duration_ms":2875},{"path":"media/4fbdc7202deff011f9fe2059111bbde4c934379569c346193a1c25c4b38a970f.m4a","duration_ms":2683},{"path":"media/0e141bdec63f8c4d38437edc866b527753e8d17cab427dec9a9b8f72f7e148d5.m4a","duration_ms":4867}]'::jsonb),
  ('escuela-05-exam-day', 2, 'story', '考试那天', 'estudio', 'escuela', 5, '[{"zh":"星期一早上，大卫很早就到了教室。","pinyin":"Xīngqīyī zǎoshang, Dàwèi hěn zǎo jiù dào le jiàoshì.","es":"El lunes por la mañana, David llegó muy temprano al aula."},{"zh":"他说他昨天晚上睡得不好。","pinyin":"Tā shuō tā zuótiān wǎnshang shuì de bù hǎo.","es":"Dijo que la noche anterior había dormido mal."},{"zh":"九点，考试开始了。","pinyin":"Jiǔ diǎn, kǎoshì kāishǐ le.","es":"A las nueve empezó el examen."},{"zh":"大卫看了看题，觉得自己都会。","pinyin":"Dàwèi kàn le kàn tí, juéde zìjǐ dōu huì.","es":"David echó un vistazo a las preguntas y vio que se las sabía todas."},{"zh":"他写得很快，十点就写完了。","pinyin":"Tā xiě de hěn kuài, shí diǎn jiù xiě wán le.","es":"Escribió muy rápido y a las diez ya había terminado."},{"zh":"写完后，他再看了看，找到了两个错字。","pinyin":"Xiě wán hòu, tā zài kàn le kàn, zhǎo dào le liǎng gè cuò zì.","es":"Después de terminar lo repasó y encontró dos caracteres mal escritos."},{"zh":"三天后，王老师告诉大家考得怎么样。","pinyin":"Sān tiān hòu, Wáng lǎoshī gàosu dàjiā kǎo de zěnmeyàng.","es":"Tres días después, la profesora Wang dijo a todos cómo les había ido."},{"zh":"大卫考得比上次好多了。","pinyin":"Dàwèi kǎo de bǐ shàng cì hǎo duō le.","es":"A David le salió mucho mejor que la vez anterior."},{"zh":"王老师说，他已经是班里汉字写得最好的外国学生了。","pinyin":"Wáng lǎoshī shuō, tā yǐjīng shì bān lǐ Hànzì xiě de zuì hǎo de wàiguó xuéshēng le.","es":"La profesora Wang dijo que ya es el alumno extranjero de la clase que mejor escribe los caracteres."}]'::jsonb, '[{"prompt":"考试几点开始？","options":["八点","九点","十点"],"answer_index":1,"evidence_sentence":2},{"prompt":"大卫写完后做了什么？","options":["再看了看","回家了","睡觉了"],"answer_index":0,"evidence_sentence":5},{"prompt":"大卫这次考得怎么样？","options":["不太好","跟上次一样","比上次好多了"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['开始', '完', '错']::text[], '[{"code":"5.4.1","level":2},{"code":"6.3.4","level":2}]'::jsonb, 'neural', '[{"path":"media/3f6b50fabef4d4dc7f7cba9e2598f0a857cd80a35245606e303d0a3f26b339d0.m4a","duration_ms":3667},{"path":"media/5a28c5afc708d3e7d12f4575a9cefb3d58582147df3e57e9b9c8a8f91229fd55.m4a","duration_ms":3331},{"path":"media/c7a50a746804cee057ea8eebcd9775623adadf7eaec5b39fc32dc6e8d9b07185.m4a","duration_ms":2587},{"path":"media/7ea8e6a98972f948c95616d75f59d7df417812f086cd3e876348a8f35924021d.m4a","duration_ms":3379},{"path":"media/122766cda54755063e6c0ca465c2ba5aff77a39e67a2324ddef41035d002dbb0.m4a","duration_ms":3211},{"path":"media/845d8bde8bd0b877bf5c1a7ca374d2c78b8dc2f191e43b96c6a6f4efed0c1979.m4a","duration_ms":4195},{"path":"media/b63777a9c7186b5a5e71bbb2a217bc17e244e545584c0956ed85c7acefd5a5b0.m4a","duration_ms":4219},{"path":"media/f1da9e635d1db8bc10efd16bbd68b35af3319b821c90949191521725f2f0e942.m4a","duration_ms":2923},{"path":"media/78ce5b649bfb93cbe706fda2bd3119679b19dbbb3cb3d9b679407db97a2bb9b3.m4a","duration_ms":5179}]'::jsonb),
  ('escuela-06-going-home', 2, 'short_text', '大卫要回国了', 'estudio', 'escuela', 6, '[{"zh":"还有一个星期，我们就不上课了。","pinyin":"Hái yǒu yí gè xīngqī, wǒmen jiù bú shàngkè le.","es":"Dentro de una semana se acaban las clases."},{"zh":"大卫要回国看他的爸爸妈妈。","pinyin":"Dàwèi yào huí guó kàn tā de bàba māma.","es":"David va a volver a su país para ver a sus padres."},{"zh":"虽然他很想家，但是他也很喜欢这里。","pinyin":"Suīrán tā hěn xiǎng jiā, dànshì tā yě hěn xǐhuan zhèlǐ.","es":"Aunque echa mucho de menos su casa, también le gusta mucho estar aquí."},{"zh":"他说他在这里认识了很多朋友，也学会了很多汉字。","pinyin":"Tā shuō tā zài zhèlǐ rènshi le hěn duō péngyou, yě xué huì le hěn duō Hànzì.","es":"Dice que aquí ha conocido a muchos amigos y ha aprendido muchos caracteres."},{"zh":"大卫问我想不想出国看看。","pinyin":"Dàwèi wèn wǒ xiǎng bu xiǎng chūguó kàn kàn.","es":"David me preguntó si quiero salir al extranjero a conocer otros lugares."},{"zh":"我说我从小就想去外国旅游。","pinyin":"Wǒ shuō wǒ cóngxiǎo jiù xiǎng qù wàiguó lǚyóu.","es":"Le dije que desde pequeña quiero viajar al extranjero."},{"zh":"他让我明年去他家玩，他可以给我介绍他的家人。","pinyin":"Tā ràng wǒ míngnián qù tā jiā wán, tā kěyǐ gěi wǒ jièshào tā de jiārén.","es":"Me invitó a ir a su casa el año que viene; me puede presentar a su familia."},{"zh":"我说好，我会记得的。","pinyin":"Wǒ shuō hǎo, wǒ huì jìde de.","es":"Le dije que sí y que no lo olvidaría."},{"zh":"我们都希望大卫早一点儿回来。","pinyin":"Wǒmen dōu xīwàng Dàwèi zǎo yìdiǎnr huílái.","es":"Todos esperamos que David vuelva pronto."}]'::jsonb, '[{"prompt":"大卫为什么要回国？","options":["去旅游","看爸爸妈妈","考试"],"answer_index":1,"evidence_sentence":1},{"prompt":"李文从小就想做什么？","options":["去外国旅游","做老师","学游泳"],"answer_index":0,"evidence_sentence":5},{"prompt":"大卫让李文做什么？","options":["给他打电话","写汉字","明年去他家玩"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['虽然', '出国', '从小']::text[], '[{"code":"6.4.2","level":2},{"code":"2.9.2","level":2}]'::jsonb, 'neural', '[{"path":"media/9c3f1b014937bf676a213bef23d50a80a8e57727e5089a8eb9fae06137873ad6.m4a","duration_ms":3523},{"path":"media/4edbf0b0a362a2f070988d332166c52722dacacc8781fca5e391b1b80d66a407.m4a","duration_ms":3163},{"path":"media/22521a68501e966514b169cffd691db7dd514d115d2ef0b4bdc473b24868f37b.m4a","duration_ms":3979},{"path":"media/2e72517db2af60cc372f916f8842bc86f6a0dc38847860dd7289fd607e1366b3.m4a","duration_ms":5203},{"path":"media/195dfcdbf578b93d324a09b2ce13e3fd84e3fcfefb98d46008d19dabad7b5a52.m4a","duration_ms":2875},{"path":"media/5d6247ddf5a5c60a569a560b0bfe6433207a74f45e5bf4f332aea14c7708109a.m4a","duration_ms":3067},{"path":"media/86d4016b9a65c40dd97e0fdb9d8d3b271ef862b01b661dd8eb6392ff2423a150.m4a","duration_ms":5011},{"path":"media/22c6c21c03dcc865b2754e2b06b368dd64097c0158563c4fa960c044b9511578.m4a","duration_ms":2515},{"path":"media/476d1bdfee4dfc244e0c824ac99622ea6773a4bd527b45c173f4663892d45a71.m4a","duration_ms":2971}]'::jsonb),
  ('fiesta-01-new-year-plan', 2, 'dialogue', '去我家过年吧', 'eventos', 'fiesta', 1, '[{"zh":"小雨：高飞，快要过年了，你回家吗？","pinyin":"Xiǎoyǔ: Gāo Fēi, kuàiyào guònián le, nǐ huí jiā ma?","es":"Xiaoyu: Gao Fei, ya casi es Año Nuevo; ¿vuelves a casa?"},{"zh":"高飞：我不回去了，机票太贵了。","pinyin":"Gāo Fēi: Wǒ bù huíqù le, jīpiào tài guì le.","es":"Gao Fei: No voy a volver; los billetes de avión son demasiado caros."},{"zh":"小雨：那你一个人在这里过年吗？","pinyin":"Xiǎoyǔ: Nà nǐ yí gè rén zài zhèlǐ guònián ma?","es":"Xiaoyu: ¿Entonces vas a pasar el Año Nuevo aquí solo?"},{"zh":"高飞：是啊。我来中国两年了，还没有去过中国人家里。","pinyin":"Gāo Fēi: Shì a. Wǒ lái Zhōngguó liǎng nián le, hái méiyǒu qùguo Zhōngguó rén jiā lǐ.","es":"Gao Fei: Sí. Llevo dos años en China y todavía no he estado nunca en una casa china."},{"zh":"小雨：那你来我家过年吧！我家人很多，很快乐。","pinyin":"Xiǎoyǔ: Nà nǐ lái wǒ jiā guònián ba! Wǒ jiārén hěn duō, hěn kuàilè.","es":"Xiaoyu: ¡Pues ven a pasarlo a mi casa! Somos mucha gente y es muy alegre."},{"zh":"高飞：真的吗？你妈妈会不会不高兴？","pinyin":"Gāo Fēi: Zhēn de ma? Nǐ māma huì bu huì bù gāoxìng?","es":"Gao Fei: ¿De verdad? ¿No le molestará a tu madre?"},{"zh":"小雨：不会，我现在就给她打电话。","pinyin":"Xiǎoyǔ: Bú huì, wǒ xiànzài jiù gěi tā dǎdiànhuà.","es":"Xiaoyu: Qué va; ahora mismo la llamo por teléfono."},{"zh":"小雨妈妈：小雨的朋友就是我们的朋友，请他来吧！","pinyin":"Xiǎoyǔ māma: Xiǎoyǔ de péngyou jiù shì wǒmen de péngyou, qǐng tā lái ba!","es":"Madre de Xiaoyu: Los amigos de Xiaoyu son nuestros amigos; ¡que venga!"},{"zh":"高飞：太好了！谢谢你们！","pinyin":"Gāo Fēi: Tài hǎo le! Xièxie nǐmen!","es":"Gao Fei: ¡Estupendo! ¡Muchas gracias!"}]'::jsonb, '[{"prompt":"高飞为什么不回家过年？","options":["因为要工作","因为机票太贵了","因为身体不好"],"answer_index":1,"evidence_sentence":1},{"prompt":"高飞去过中国人家里吗？","options":["没有去过","去过一次","经常去"],"answer_index":0,"evidence_sentence":3},{"prompt":"小雨妈妈说什么？","options":["高飞不能来","让高飞明年来","请高飞来过年"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['过年', '机票', '回去']::text[], '[{"code":"7.1.2","level":2},{"code":"2.8.3","level":2}]'::jsonb, 'neural', '[{"path":"media/cf574daf01a71ebacd9004c1153b4f1eb5b819fce54cad7e50d949a435ef9f57.m4a","duration_ms":3451},{"path":"media/ba1fcc2e11886b5f02c04c02040bc4b58276852501cee2aa9c7e6904c7562e40.m4a","duration_ms":3091},{"path":"media/034f1f3f68411c909a6b22233583a9634aaf8e333e8843f322ba42aab71ac209.m4a","duration_ms":2779},{"path":"media/436cddb6c0a22b2e5d7d860f573bc4065a9dc2f3b7d89ec1a55858a81b7830ac.m4a","duration_ms":5083},{"path":"media/cf0c5457592ccb50ce158418d8ecba40dc995890b10d1005759fcc77e53eff1e.m4a","duration_ms":4795},{"path":"media/a22731bdeb79d6d3e79765cf6994a95e12df0ca599bf9af84ed2aa610e63e98b.m4a","duration_ms":3547},{"path":"media/d1cffc0db5a0f6d813b0c109335500ea7b7f942e1c16af399712e22ac363e030.m4a","duration_ms":3091},{"path":"media/0a5f7c1fa6a750850fe7dc72c68195400a6e58a46a5748be7365f70ecfeec466.m4a","duration_ms":3859},{"path":"media/3849f9297e5e35bca0f83fe4a24d6cd63e2050270c40cb488ff6c67729a7c22e.m4a","duration_ms":2971}]'::jsonb),
  ('fiesta-02-preparing', 2, 'short_text', '过年前', 'eventos', 'fiesta', 2, '[{"zh":"过年前一个星期，小雨家里非常忙。","pinyin":"Guònián qián yí gè xīngqī, Xiǎoyǔ jiā lǐ fēicháng máng.","es":"Una semana antes del Año Nuevo, en casa de Xiaoyu todos están muy ocupados."},{"zh":"小雨妈妈去超市买了很多肉和鱼。","pinyin":"Xiǎoyǔ māma qù chāoshì mǎi le hěn duō ròu hé yú.","es":"La madre de Xiaoyu ha ido al supermercado a comprar mucha carne y pescado."},{"zh":"爷爷去商店买花，他说过年家里要有红色的花。","pinyin":"Yéye qù shāngdiàn mǎi huā, tā shuō guònián jiā lǐ yào yǒu hóngsè de huā.","es":"El abuelo ha ido a la tienda a comprar flores; dice que en Año Nuevo en casa tiene que haber flores rojas."},{"zh":"小雨和高飞一起帮忙，房间很快就准备好了。","pinyin":"Xiǎoyǔ hé Gāo Fēi yìqǐ bāngmáng, fángjiān hěn kuài jiù zhǔnbèi hǎo le.","es":"Xiaoyu y Gao Fei ayudan juntos, y las habitaciones quedan preparadas enseguida."},{"zh":"高飞第一次看见这么多人一起准备过年。","pinyin":"Gāo Fēi dì yī cì kànjiàn zhème duō rén yìqǐ zhǔnbèi guònián.","es":"Es la primera vez que Gao Fei ve a tanta gente preparando juntos el Año Nuevo."},{"zh":"他觉得很有意思，也想学做中国菜。","pinyin":"Tā juéde hěn yǒuyìsi, yě xiǎng xué zuò Zhōngguó cài.","es":"Le parece muy interesante y también quiere aprender a hacer comida china."},{"zh":"小雨妈妈教他做饺子，他做得不太好看。","pinyin":"Xiǎoyǔ māma jiāo tā zuò jiǎozi, tā zuò de bú tài hǎokàn.","es":"La madre de Xiaoyu le enseña a hacer jiaozi; no le salen muy bonitos."},{"zh":"大家都笑了，爷爷说第一次做饺子都是这样。","pinyin":"Dàjiā dōu xiào le, yéye shuō dì yī cì zuò jiǎozi dōu shì zhèyàng.","es":"Todos se ríen, y el abuelo dice que la primera vez que se hacen jiaozi siempre salen así."},{"zh":"晚上，饺子做好了，有两百多个。","pinyin":"Wǎnshang, jiǎozi zuò hǎo le, yǒu liǎngbǎi duō gè.","es":"Por la noche los jiaozi están hechos: hay más de doscientos."}]'::jsonb, '[{"prompt":"小雨妈妈去超市买了什么？","options":["花和水果","肉和鱼","饺子"],"answer_index":1,"evidence_sentence":1},{"prompt":"爷爷说过年家里要有什么？","options":["红色的花","很多钱","新衣服"],"answer_index":0,"evidence_sentence":2},{"prompt":"一共做了多少饺子？","options":["二十多个","一百个","两百多个"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['花', '肉', '爷爷']::text[], '[{"code":"3.1.2","level":2},{"code":"5.1","level":2}]'::jsonb, 'neural', '[{"path":"media/e05959aff845e952bf8e452bcf860cef0b1a110ae7bd34efad664fd476190d36.m4a","duration_ms":3379},{"path":"media/27f70a4dfa147bc31a9dd629e0418eeeff00f91875ef4e2865558bcbdbc19c74.m4a","duration_ms":3283},{"path":"media/556e18a05deb4a3613cb19b4a8ecf43c83d956cfbc7983d7f0dfc52509704974.m4a","duration_ms":4771},{"path":"media/2fe4ddcc242ca52d845b60ddc3499a5a019853115c7ec6841519312d34f8f779.m4a","duration_ms":4147},{"path":"media/e8332f15b7b16b5b670580df38d62a65802628b497aa154523a757305e9c59b5.m4a","duration_ms":3667},{"path":"media/2911e2d7bc1f64aa9d892cd241ac20e5e86449778a62d4ff1afff14c88d8bbb4.m4a","duration_ms":3403},{"path":"media/9502f43970aa3874bd7cf44ae8443bb5f3ffb655f4b44fb5fa17fc5802abee57.m4a","duration_ms":3667},{"path":"media/e352153ed4aca74cddb30443168c364c6643e59d031de9b0d8e00f61baa21493.m4a","duration_ms":4147},{"path":"media/ddef523d5c90da11989228ce8d35a751b6f00069cee369cc8aaeea6fb589e5f4.m4a","duration_ms":3259}]'::jsonb),
  ('fiesta-03-new-year-eve', 2, 'story', '过年的晚上', 'eventos', 'fiesta', 3, '[{"zh":"过年那天晚上，小雨家来了很多人。","pinyin":"Guònián nà tiān wǎnshang, Xiǎoyǔ jiā lái le hěn duō rén.","es":"La noche de Año Nuevo vino mucha gente a casa de Xiaoyu."},{"zh":"桌子上有很多菜，有鱼、有肉，还有饺子。","pinyin":"Zhuōzi shàng yǒu hěn duō cài, yǒu yú, yǒu ròu, hái yǒu jiǎozi.","es":"En la mesa había muchos platos: pescado, carne y además jiaozi."},{"zh":"大家坐在一起，慢慢地吃，慢慢地说。","pinyin":"Dàjiā zuò zài yìqǐ, màn màn de chī, màn màn de shuō.","es":"Todos se sentaron juntos a comer y a charlar sin prisas."},{"zh":"吃完饭，小孩儿们在外面玩，男孩儿跑来跑去，女孩儿在唱歌。","pinyin":"Chī wán fàn, xiǎoháir men zài wàimiàn wán, nánháir pǎo lái pǎo qù, nǚháir zài chàng gē.","es":"Después de cenar, los niños jugaban fuera: los chicos corrían de un lado a otro y las chicas cantaban."},{"zh":"爷爷说他想跳舞，大家都笑了。","pinyin":"Yéye shuō tā xiǎng tiàowǔ, dàjiā dōu xiào le.","es":"El abuelo dijo que quería bailar, y todos se rieron."},{"zh":"小雨让高飞和她一起跟爷爷跳舞。","pinyin":"Xiǎoyǔ ràng Gāo Fēi hé tā yìqǐ gēn yéye tiàowǔ.","es":"Xiaoyu le pidió a Gao Fei que bailara con ella y con el abuelo."},{"zh":"高飞跳舞不太好看，但是他很快乐。","pinyin":"Gāo Fēi tiàowǔ bú tài hǎokàn, dànshì tā hěn kuàilè.","es":"Gao Fei no bailaba muy bien, pero estaba muy feliz."},{"zh":"十二点的时候，大家一起说过年好。","pinyin":"Shí''èr diǎn de shíhou, dàjiā yìqǐ shuō guònián hǎo.","es":"A las doce, todos dijeron juntos «¡Feliz Año Nuevo!»."},{"zh":"高飞说这是他过得最快乐的一个年。","pinyin":"Gāo Fēi shuō zhè shì tā guò de zuì kuàilè de yí gè nián.","es":"Gao Fei dijo que ha sido el Año Nuevo más feliz que ha pasado."}]'::jsonb, '[{"prompt":"吃完饭，小孩儿们在做什么？","options":["在睡觉","在外面玩","在做饺子"],"answer_index":1,"evidence_sentence":3},{"prompt":"谁说想跳舞？","options":["爷爷","小雨妈妈","高飞"],"answer_index":0,"evidence_sentence":4},{"prompt":"高飞觉得这个年过得怎么样？","options":["很累","没意思","最快乐"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['小孩儿', '跳舞', '一起']::text[], '[{"code":"2.4.1","level":2},{"code":"2.7.2","level":2}]'::jsonb, 'neural', '[{"path":"media/e28b2482227c02c3c24584c6ad9adcef21555d47c50ec740d44de98e4aba66d6.m4a","duration_ms":3451},{"path":"media/19973619570806bf1bb0f72fb756b44e0442e25bdff9bf4c2ca7ccc0f3514df6.m4a","duration_ms":4483},{"path":"media/a19aeb1f401517c7bf1dc8b1defa6ec0e4b3b2bd75a40cde2a43efa689213bca.m4a","duration_ms":3859},{"path":"media/6d6be9f674ebe0600b19ab84de3f5139f0a053c4b5deca41d20ddec08db5d068.m4a","duration_ms":5323},{"path":"media/2d319a39ea681c5273ec68cb8f049a77ce265cc3eff20ce580336bb3a00aedbd.m4a","duration_ms":3115},{"path":"media/d87e5cef33e8f732bbf1aad8051dcd939539125f9e509c50227ebb912ee512ed.m4a","duration_ms":3307},{"path":"media/8aac447d621ffc7283031c42f17ebafa58b49df4d733b6c56400b6f864d2bd5a.m4a","duration_ms":3547},{"path":"media/f5e222f0d72be71873d7905553c3bd3728942f49cb84020b3f8191c9a7c579b5.m4a","duration_ms":3379},{"path":"media/0771d4c6bef664ab6b247991bfd8a46c4dbf27ac4348ca1c0de6eb993a2c9cb5.m4a","duration_ms":3355}]'::jsonb),
  ('fiesta-04-thank-you-plan', 2, 'dialogue', '请小雨家吃饭', 'eventos', 'fiesta', 4, '[{"zh":"高飞：小雨，我想请你家人吃饭，谢谢你们。","pinyin":"Gāo Fēi: Xiǎoyǔ, wǒ xiǎng qǐng nǐ jiārén chī fàn, xièxie nǐmen.","es":"Gao Fei: Xiaoyu, quiero invitar a tu familia a comer para daros las gracias."},{"zh":"小雨：别这样，你是我们的朋友。","pinyin":"Xiǎoyǔ: Bié zhèyàng, nǐ shì wǒmen de péngyou.","es":"Xiaoyu: No hace falta, eres nuestro amigo."},{"zh":"高飞：虽然是朋友，但是我也想谢谢你们。","pinyin":"Gāo Fēi: Suīrán shì péngyou, dànshì wǒ yě xiǎng xièxie nǐmen.","es":"Gao Fei: Aunque seamos amigos, también quiero daros las gracias."},{"zh":"小雨：好吧。你想在哪儿吃？","pinyin":"Xiǎoyǔ: Hǎo ba. Nǐ xiǎng zài nǎr chī?","es":"Xiaoyu: Está bien. ¿Dónde quieres comer?"},{"zh":"高飞：学校旁边那个酒店的饭很好吃。","pinyin":"Gāo Fēi: Xuéxiào pángbiān nàge jiǔdiàn de fàn hěn hǎochī.","es":"Gao Fei: La comida del hotel que hay junto a la universidad está muy buena."},{"zh":"小雨：酒店的饭很贵吧？","pinyin":"Xiǎoyǔ: Jiǔdiàn de fàn hěn guì ba?","es":"Xiaoyu: La comida de un hotel será cara, ¿no?"},{"zh":"高飞：没关系，过年的时候我也想请你们。","pinyin":"Gāo Fēi: Méiguānxi, guònián de shíhou wǒ yě xiǎng qǐng nǐmen.","es":"Gao Fei: No importa; ya en Año Nuevo quería invitaros."},{"zh":"小雨：那星期六中午吧。明天是阴天，听说星期六是晴天。","pinyin":"Xiǎoyǔ: Nà xīngqīliù zhōngwǔ ba. Míngtiān shì yīn tiān, tīng shuō xīngqīliù shì qíng tiān.","es":"Xiaoyu: Entonces el sábado a mediodía. Mañana estará nublado, pero dicen que el sábado hará sol."},{"zh":"高飞：好，星期六我们一起去。","pinyin":"Gāo Fēi: Hǎo, xīngqīliù wǒmen yìqǐ qù.","es":"Gao Fei: Bien, el sábado vamos juntos."}]'::jsonb, '[{"prompt":"高飞为什么想请小雨家人吃饭？","options":["他过生日","想谢谢他们","他找到了工作"],"answer_index":1,"evidence_sentence":0},{"prompt":"他们在哪儿吃饭？","options":["学校旁边的酒店","小雨家","公司"],"answer_index":0,"evidence_sentence":4},{"prompt":"星期六天气怎么样？","options":["下雨","阴天","晴天"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['酒店', '晴', '阴']::text[], '[{"code":"2.7.5","level":2},{"code":"6.4.2","level":2}]'::jsonb, 'neural', '[{"path":"media/a1c21dc9c4a000a64514798cc089eb0fca1b6c8fb96a77b60e9d9840628ee437.m4a","duration_ms":4027},{"path":"media/86d36128b66cb977347d4474535cfe46837701418fc48d6a6d97507ecd78a93b.m4a","duration_ms":2875},{"path":"media/3e5398e37ec2b66836147cf86db0984a44cd5b7e12cf2d8c4afa570e3b255045.m4a","duration_ms":3451},{"path":"media/1b66d80bdb3269a6ede5b0202577dccbc02af2d5855256876c980fc8f142c945.m4a","duration_ms":2899},{"path":"media/f304b6f9d3fda04f815230960164df996f3e0b797035818ee388c768d5864ce9.m4a","duration_ms":3475},{"path":"media/d68f7f69e1950113f1a520695a67073c7bb900fdde92fd72fa96f6b0a61ef207.m4a","duration_ms":2419},{"path":"media/811007814f55e7eff9b3cd0d7eb32da6f40488dc8eb0a559b5f56cde1f63a3ba.m4a","duration_ms":4027},{"path":"media/a76d95b8d744c06667962e56df820dde81609d17537b0c0f334faa12a7961d5a.m4a","duration_ms":5899},{"path":"media/d6973db1a380d2b4118e1f7ab1f33bbc93485f1058b3044ecc2ecd666f391a99.m4a","duration_ms":2995}]'::jsonb),
  ('fiesta-05-dinner', 2, 'story', '在酒店吃饭', 'eventos', 'fiesta', 5, '[{"zh":"星期六是晴天，天气很好。","pinyin":"Xīngqīliù shì qíng tiān, tiānqì hěn hǎo.","es":"El sábado hizo sol; el tiempo era muy bueno."},{"zh":"小雨、小雨妈妈和爷爷中午十二点到了酒店。","pinyin":"Xiǎoyǔ, Xiǎoyǔ māma hé yéye zhōngwǔ shí''èr diǎn dào le jiǔdiàn.","es":"Xiaoyu, su madre y el abuelo llegaron al hotel a las doce del mediodía."},{"zh":"高飞已经在门口等他们了，手里拿着花。","pinyin":"Gāo Fēi yǐjīng zài ménkǒu děng tāmen le, shǒu lǐ ná zhe huā.","es":"Gao Fei ya los esperaba en la puerta con unas flores en la mano."},{"zh":"他给小雨妈妈送花，说谢谢她过年的时候请他去家里。","pinyin":"Tā gěi Xiǎoyǔ māma sòng huā, shuō xièxie tā guònián de shíhou qǐng tā qù jiā lǐ.","es":"Le dio las flores a la madre de Xiaoyu y le agradeció que lo invitara a su casa en Año Nuevo."},{"zh":"小雨妈妈很高兴，说高飞是一个很好的孩子。","pinyin":"Xiǎoyǔ māma hěn gāoxìng, shuō Gāo Fēi shì yí gè hěn hǎo de háizi.","es":"La madre de Xiaoyu se puso muy contenta y dijo que Gao Fei es un chico muy bueno."},{"zh":"酒店的菜很好吃，爷爷吃了很多。","pinyin":"Jiǔdiàn de cài hěn hǎochī, yéye chī le hěn duō.","es":"La comida del hotel estaba muy buena y el abuelo comió mucho."},{"zh":"吃完饭，他们喝了咖啡，说了很长时间。","pinyin":"Chī wán fàn, tāmen hē le kāfēi, shuō le hěn cháng shíjiān.","es":"Después de comer tomaron café y estuvieron hablando mucho rato."},{"zh":"旁边桌子的一个小女孩儿看着高飞笑。","pinyin":"Pángbiān zhuōzi de yí gè xiǎo nǚháir kàn zhe Gāo Fēi xiào.","es":"Una niña pequeña de la mesa de al lado miraba a Gao Fei y se reía."},{"zh":"小雨妈妈说，明年过年高飞还要来她家。","pinyin":"Xiǎoyǔ māma shuō, míngnián guònián Gāo Fēi hái yào lái tā jiā.","es":"La madre de Xiaoyu dijo que el año que viene Gao Fei tiene que volver a su casa en Año Nuevo."}]'::jsonb, '[{"prompt":"高飞在门口拿着什么？","options":["咖啡","花","手表"],"answer_index":1,"evidence_sentence":2},{"prompt":"吃完饭，他们喝了什么？","options":["咖啡","茶","水"],"answer_index":0,"evidence_sentence":6},{"prompt":"小雨妈妈说明年高飞要做什么？","options":["回国","去酒店工作","还来她家过年"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['咖啡', '送', '女孩儿']::text[], '[{"code":"3.1.1","level":2},{"code":"5.3","level":2}]'::jsonb, 'neural', '[{"path":"media/1fc7818e9b39e228772afee640def4248a65289130bf096e410c777287aa4c05.m4a","duration_ms":2851},{"path":"media/4dc20d6ecdec5cbf5f1372d859b1b3c3c2cb43a3c13fdd876bc92e407a7edf59.m4a","duration_ms":4459},{"path":"media/c203cf0ae99446870be4192b2e278f27f9e14d7177347f0724aa412a81c98320.m4a","duration_ms":3763},{"path":"media/ec769556f5811a8ffe912dba85cb04d0daf2554639eaf85a8a146cc523c54bad.m4a","duration_ms":4819},{"path":"media/337f2a5d6d85a40b348a65635481905fe74402c4b3e594bdcedffe53b425c2ef.m4a","duration_ms":4099},{"path":"media/1659b85478245d5b6b5c68de044e8f3e65e381b9c8ba442873ffc46ccfddc76c.m4a","duration_ms":3259},{"path":"media/4351651b7c11d31d40c120a0ba10c66838ba667d9284db6e04f1faccfd6cbdae.m4a","duration_ms":3739},{"path":"media/51aa1fde9710206ed4733c4ea12a8636da48b5a73ae87b8c8edd8087c252c907.m4a","duration_ms":3499},{"path":"media/35d68fe1b24a2d7a96bc3ba2f098521eefa18c014dd8a5a76d5cf0a3e9633a77.m4a","duration_ms":3907}]'::jsonb),
  ('leisure-01-weekend-plan', 2, 'short_text', '我们的爱好', 'ocio', 'ocio', 1, '[{"zh":"我叫方方，我的爱好是看电影和看书。","pinyin":"Wǒ jiào Fāngfāng, wǒ de àihào shì kàn diànyǐng hé kàn shū.","es":"Me llamo Fangfang; mis aficiones son ver películas y leer."},{"zh":"我有一个好朋友，他叫小飞。","pinyin":"Wǒ yǒu yí gè hǎo péngyou, tā jiào Xiǎofēi.","es":"Tengo un buen amigo que se llama Xiaofei."},{"zh":"小飞最大的爱好是运动。","pinyin":"Xiǎofēi zuì dà de àihào shì yùndòng.","es":"La mayor afición de Xiaofei es el deporte."},{"zh":"他每个星期都踢足球，有时候也打篮球。","pinyin":"Tā měi gè xīngqī dōu tī zúqiú, yǒushíhou yě dǎ lánqiú.","es":"Juega al fútbol todas las semanas y a veces también al baloncesto."},{"zh":"他还很会游泳，从小就喜欢在水里玩。","pinyin":"Tā hái hěn huì yóuyǒng, cóngxiǎo jiù xǐhuan zài shuǐ lǐ wán.","es":"Además nada muy bien; desde pequeño le gusta jugar en el agua."},{"zh":"我不会游泳，也不喜欢踢球。","pinyin":"Wǒ bú huì yóuyǒng, yě bù xǐhuan tī qiú.","es":"Yo no sé nadar y tampoco me gusta jugar al fútbol."},{"zh":"我觉得跑来跑去没意思，很累也很热。","pinyin":"Wǒ juéde pǎo lái pǎo qù méiyìsi, hěn lèi yě hěn rè.","es":"Me parece aburrido correr de un lado a otro: cansa mucho y da mucho calor."},{"zh":"虽然我不喜欢运动，但是我们是很好的朋友。","pinyin":"Suīrán wǒ bù xǐhuan yùndòng, dànshì wǒmen shì hěn hǎo de péngyou.","es":"Aunque a mí no me gusta el deporte, somos muy buenos amigos."},{"zh":"小飞说，他想让我和他一起运动。","pinyin":"Xiǎofēi shuō, tā xiǎng ràng wǒ hé tā yìqǐ yùndòng.","es":"Xiaofei dice que quiere que haga deporte con él."}]'::jsonb, '[{"prompt":"方方的爱好是什么？","options":["踢足球","看电影和看书","游泳"],"answer_index":1,"evidence_sentence":0},{"prompt":"小飞每个星期做什么？","options":["踢足球","看书","去医院"],"answer_index":0,"evidence_sentence":3},{"prompt":"方方觉得跑来跑去怎么样？","options":["很快乐","很有意思","没意思"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['爱好', '足球', '没意思']::text[], '[{"code":"2.9.1","level":2},{"code":"6.4.2","level":2}]'::jsonb, 'neural', '[{"path":"media/9651ad48f9604df234db4add4ce235eaf161de75a683f9fa118785af87bc076d.m4a","duration_ms":4051},{"path":"media/9ae6499c2b3f7232c8718c44f53748bf2e90f401fe4e94303ea9cd3b3ad73f82.m4a","duration_ms":3019},{"path":"media/2913cb7bd4b9c0de264f920a074fe1213e06d60861e040f5950d0c05cb2c6854.m4a","duration_ms":2971},{"path":"media/068a35ce60cecdbe52c2a0fe9517b8e4277f56b05ab0c15a5dadd26456b3943a.m4a","duration_ms":4195},{"path":"media/72788e5e06bc954536b8872bf454d586af04d3539fa6b5f2ca39f40672a64ef4.m4a","duration_ms":3979},{"path":"media/7e0c7ea123a33c784148b88c0dc74a796fd46281badef8a5a912fbdb9b5305c3.m4a","duration_ms":3379},{"path":"media/fa1c5561a743bd9d4968fab1e263ae646f036321a2661f6852613cb4ca650532.m4a","duration_ms":4051},{"path":"media/db827eec3d5deda497e959dda12f15d36c788a9ee9c2e9eb0d181d3e870ea57f.m4a","duration_ms":4435},{"path":"media/93026bc98acc5e490cb545d0207c3b2a42cd08e386f9fb8470098c49723c293f.m4a","duration_ms":3691}]'::jsonb),
  ('ocio-02-swimming', 2, 'dialogue', '我教你游泳', 'ocio', 'ocio', 2, '[{"zh":"小飞：方方，星期六天气很好，我们去游泳吧！","pinyin":"Xiǎofēi: Fāngfāng, xīngqīliù tiānqì hěn hǎo, wǒmen qù yóuyǒng ba!","es":"Xiaofei: Fangfang, el sábado hará muy buen tiempo; ¡vamos a nadar!"},{"zh":"方方：我不会游泳，你知道的。","pinyin":"Fāngfāng: Wǒ bú huì yóuyǒng, nǐ zhīdào de.","es":"Fangfang: No sé nadar, ya lo sabes."},{"zh":"小飞：没关系，我可以教你。","pinyin":"Xiǎofēi: Méiguānxi, wǒ kěyǐ jiāo nǐ.","es":"Xiaofei: No pasa nada, yo te puedo enseñar."},{"zh":"方方：我觉得在水里很不舒服。","pinyin":"Fāngfāng: Wǒ juéde zài shuǐ lǐ hěn bù shūfu.","es":"Fangfang: En el agua me siento muy incómoda."},{"zh":"小飞：别这样想，我们在水里走一会儿就好了。","pinyin":"Xiǎofēi: Bié zhèyàng xiǎng, wǒmen zài shuǐ lǐ zǒu yíhuìr jiù hǎo le.","es":"Xiaofei: No pienses eso; caminamos un rato por el agua y ya verás."},{"zh":"方方：学游泳要多长时间？","pinyin":"Fāngfāng: Xué yóuyǒng yào duō cháng shíjiān?","es":"Fangfang: ¿Cuánto se tarda en aprender a nadar?"},{"zh":"小飞：有的人一个星期就会了。","pinyin":"Xiǎofēi: Yǒude rén yí gè xīngqī jiù huì le.","es":"Xiaofei: Hay gente que aprende en una semana."},{"zh":"方方：好吧，因为是你教我，所以我去。","pinyin":"Fāngfāng: Hǎo ba, yīnwèi shì nǐ jiāo wǒ, suǒyǐ wǒ qù.","es":"Fangfang: Está bien; como me enseñas tú, voy."},{"zh":"小飞：太好了！星期六上午九点，学校门口见。","pinyin":"Xiǎofēi: Tài hǎo le! Xīngqīliù shàngwǔ jiǔ diǎn, xuéxiào ménkǒu jiàn.","es":"Xiaofei: ¡Estupendo! El sábado a las nueve de la mañana, nos vemos en la puerta de la universidad."}]'::jsonb, '[{"prompt":"小飞想星期六做什么？","options":["踢足球","去游泳","看电影"],"answer_index":1,"evidence_sentence":0},{"prompt":"谁可以教方方游泳？","options":["小飞","老师","方方的妈妈"],"answer_index":0,"evidence_sentence":2},{"prompt":"他们星期六在哪儿见？","options":["电影院","小飞家","学校门口"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['游泳', '教', '一会儿']::text[], '[{"code":"2.2.2","level":2},{"code":"6.4.3","level":2}]'::jsonb, 'neural', '[{"path":"media/00af98bf21c220b2001cbac03abafff295846f26044b1f30e09634a8216cebd2.m4a","duration_ms":4555},{"path":"media/5354fb573821db502a267cbd4944036bcd2397eec0cb0fe9ee0f1bd6db32b154.m4a","duration_ms":2899},{"path":"media/72b1e1224bca45004d5b4cc95d4843e705b855edca8e7a16fd2072d99414d68d.m4a","duration_ms":2851},{"path":"media/77dbca190fd4e3c055c9d1f7c666dccdd3d5bcd6536d6b29128941257ee9df98.m4a","duration_ms":2755},{"path":"media/cbfb0b476a3481dabc446dc31d66624122bbe09039f36cfecd33f1ad99215bb0.m4a","duration_ms":3523},{"path":"media/0474a1fdc3b6ac443d47fa17bd89f1b422de8e988f2762ad187a226cc8b24499.m4a","duration_ms":2707},{"path":"media/090dd03a703fe83c81cff7105603bedfcdd5ad7de321485b1d78e5fb42207dc2.m4a","duration_ms":2491},{"path":"media/d530f69b1b94f8ba67ea9eb8d206b1333c4ff0b7869b4dd0f4308cdb683feaae.m4a","duration_ms":3595},{"path":"media/f34761fadc2870759190d4ad2c6cc457e366aa98369a8d08af61ef5f52acd1fe.m4a","duration_ms":4987}]'::jsonb),
  ('ocio-03-learning-to-swim', 2, 'story', '第一次游泳', 'ocio', 'ocio', 3, '[{"zh":"星期六上午，方方和小飞去学校里游泳。","pinyin":"Xīngqīliù shàngwǔ, Fāngfāng hé Xiǎofēi qù xuéxiào lǐ yóuyǒng.","es":"El sábado por la mañana, Fangfang y Xiaofei fueron a nadar a la universidad."},{"zh":"水里有很多人，有大人，也有小孩儿。","pinyin":"Shuǐ lǐ yǒu hěn duō rén, yǒu dà rén, yě yǒu xiǎoháir.","es":"En el agua había mucha gente: adultos y también niños."},{"zh":"小飞让方方在水里走一会儿。","pinyin":"Xiǎofēi ràng Fāngfāng zài shuǐ lǐ zǒu yíhuìr.","es":"Xiaofei le dijo a Fangfang que caminara un rato por el agua."},{"zh":"方方走得很慢，她说水有一点儿冷。","pinyin":"Fāngfāng zǒu de hěn màn, tā shuō shuǐ yǒuyìdiǎnr lěng.","es":"Fangfang caminaba muy despacio; decía que el agua estaba un poco fría."},{"zh":"小飞教她怎么在水里动手。","pinyin":"Xiǎofēi jiāo tā zěnme zài shuǐ lǐ dòng shǒu.","es":"Xiaofei le enseñó a mover las manos en el agua."},{"zh":"一个小时后，方方可以游一会儿了。","pinyin":"Yí gè xiǎoshí hòu, Fāngfāng kěyǐ yóu yíhuìr le.","es":"Una hora después, Fangfang ya podía nadar un poco."},{"zh":"她游得不快，但是她笑得很高兴。","pinyin":"Tā yóu de bú kuài, dànshì tā xiào de hěn gāoxìng.","es":"No nadaba rápido, pero sonreía muy contenta."},{"zh":"方方说游泳比她想的有意思。","pinyin":"Fāngfāng shuō yóuyǒng bǐ tā xiǎng de yǒuyìsi.","es":"Fangfang dijo que nadar era más divertido de lo que pensaba."},{"zh":"小飞说下个星期他要踢足球，请她去看。","pinyin":"Xiǎofēi shuō xià gè xīngqī tā yào tī zúqiú, qǐng tā qù kàn.","es":"Xiaofei le dijo que la semana que viene juega al fútbol y la invitó a verlo."}]'::jsonb, '[{"prompt":"他们在哪儿游泳？","options":["在酒店","在学校里","在家里"],"answer_index":1,"evidence_sentence":0},{"prompt":"方方说水怎么样？","options":["有一点儿冷","很热","很好喝"],"answer_index":0,"evidence_sentence":3},{"prompt":"一个小时后，方方怎么样了？","options":["回家了","睡觉了","可以游一会儿了"],"answer_index":2,"evidence_sentence":5}]'::jsonb, array['游', '慢', '笑']::text[], '[{"code":"5.4.3","level":2},{"code":"2.7.3","level":2}]'::jsonb, 'neural', '[{"path":"media/c885966fd331b07a1258315122da5c5aab649e35b8a2ecb976b32775f558a9f0.m4a","duration_ms":4339},{"path":"media/5b89d6c1aa3323152687fe8e886f3afb90fc26bcfae6c066ef7665b2f4d80cbe.m4a","duration_ms":3907},{"path":"media/10fcefd208ea267e2220cc52d89acae92a2873bd187674f87d63d59b0fa5ee6b.m4a","duration_ms":2947},{"path":"media/cb2825099b077cdcb79c6aa0a96c805f5415316a0d4009da6ea1eafe5f1dea7f.m4a","duration_ms":4099},{"path":"media/c9dd83898dd9c60b9a1bec43fe9645f53eee1c37ae97f89ea6d019deb290a5d1.m4a","duration_ms":3091},{"path":"media/43a2568d5488c2bd55aa93428e4b08f3061f2cc52407b756a317ba5ba47d7c79.m4a","duration_ms":3523},{"path":"media/e0787f4591d917f30366e57ece091ef2491c6c6254a2b98e83c8ad25660b2638.m4a","duration_ms":3499},{"path":"media/23897549d4cf8465d8f592b95521d0fdd9dbb224ba53c4061941554ad7a07608.m4a","duration_ms":3451},{"path":"media/ed8edb8508bab705c49cd6f7cf012963d00f9158c5621a3086e2c2a4a01c815a.m4a","duration_ms":4483}]'::jsonb),
  ('ocio-04-football', 2, 'short_text', '看小飞踢球', 'ocio', 'ocio', 4, '[{"zh":"星期天下午，方方去学校看小飞踢足球。","pinyin":"Xīngqītiān xiàwǔ, Fāngfāng qù xuéxiào kàn Xiǎofēi tī zúqiú.","es":"El domingo por la tarde, Fangfang fue a la universidad a ver jugar al fútbol a Xiaofei."},{"zh":"旁边有很多同学，大家都在看。","pinyin":"Pángbiān yǒu hěn duō tóngxué, dàjiā dōu zài kàn.","es":"Alrededor había muchos compañeros mirando."},{"zh":"小飞穿着红色的衣服，跑得非常快。","pinyin":"Xiǎofēi chuān zhe hóngsè de yīfu, pǎo de fēicháng kuài.","es":"Xiaofei llevaba ropa roja y corría muchísimo."},{"zh":"他踢进去了两个球。","pinyin":"Tā tī jìnqù le liǎng gè qiú.","es":"Metió dos goles."},{"zh":"方方也很高兴，她第一次觉得踢球很有意思。","pinyin":"Fāngfāng yě hěn gāoxìng, tā dì yī cì juéde tī qiú hěn yǒuyìsi.","es":"Fangfang también se puso muy contenta; por primera vez el fútbol le pareció interesante."},{"zh":"踢完球，小飞给方方介绍他的朋友们。","pinyin":"Tī wán qiú, Xiǎofēi gěi Fāngfāng jièshào tā de péngyou men.","es":"Después del partido, Xiaofei le presentó a sus amigos."},{"zh":"他们说下个星期要打篮球，问方方想不想来。","pinyin":"Tāmen shuō xià gè xīngqī yào dǎ lánqiú, wèn Fāngfāng xiǎng bu xiǎng lái.","es":"Le dijeron que la semana que viene juegan al baloncesto y le preguntaron si quería ir."},{"zh":"方方说她不会打篮球，但是可以来看。","pinyin":"Fāngfāng shuō tā bú huì dǎ lánqiú, dànshì kěyǐ lái kàn.","es":"Fangfang dijo que no sabe jugar al baloncesto, pero que puede ir a verlos."},{"zh":"回家的时候，方方想请小飞看电影。","pinyin":"Huí jiā de shíhou, Fāngfāng xiǎng qǐng Xiǎofēi kàn diànyǐng.","es":"De vuelta a casa, Fangfang pensó en invitar a Xiaofei al cine."}]'::jsonb, '[{"prompt":"小飞穿着什么颜色的衣服？","options":["白色的","红色的","黑色的"],"answer_index":1,"evidence_sentence":2},{"prompt":"小飞踢进去了几个球？","options":["两个","一个","三个"],"answer_index":0,"evidence_sentence":3},{"prompt":"方方想请小飞做什么？","options":["打篮球","游泳","看电影"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['踢', '球', '篮球']::text[], '[{"code":"2.8.3","level":2},{"code":"2.10.2","level":2}]'::jsonb, 'neural', '[{"path":"media/9a116dda9c975edc66cb6ceffe2eafc166616624b60799345496e22526a49d0c.m4a","duration_ms":4603},{"path":"media/a65ae0df016cb87bcb4876d2eaea95d50659aaf7b343684060cd0aa1a0922019.m4a","duration_ms":3547},{"path":"media/9c94074a2ac372e0ef1a656c9d1791071d4a688a5460e49b0e20be1a43950c76.m4a","duration_ms":3835},{"path":"media/45ee269a0984ada91a56430ddca17149f6e0b67d0417926440704a55891581b8.m4a","duration_ms":2419},{"path":"media/2da2b9fbee866abfa4622ac0c6a9cdf6e8044b075d8de014f840151f06eddb5e.m4a","duration_ms":4699},{"path":"media/220cacde2dd5971ff0dba3afdc8d07115cb599c57b4275ceba606adaee810c8c.m4a","duration_ms":4051},{"path":"media/3e06190dcb950461f5a8cabd8f6a64c6a8a3ff7eaf2bdb63c4dbd3a2a19f51ef.m4a","duration_ms":4627},{"path":"media/2a70eb487bd5062e76f8ebd7ad987aea6c028c50fa52a10dab77c1a60ffb27bb.m4a","duration_ms":4051},{"path":"media/327f99754b877ace4831320b6d35a57b5bf41482f858d407d551767b8032a55b.m4a","duration_ms":4075}]'::jsonb),
  ('ocio-05-movie', 2, 'dialogue', '一起看电影', 'ocio', 'ocio', 5, '[{"zh":"方方：小飞，谢谢你教我游泳，我请你看电影吧。","pinyin":"Fāngfāng: Xiǎofēi, xièxie nǐ jiāo wǒ yóuyǒng, wǒ qǐng nǐ kàn diànyǐng ba.","es":"Fangfang: Xiaofei, gracias por enseñarme a nadar; te invito al cine."},{"zh":"小飞：好啊！你想看什么电影？","pinyin":"Xiǎofēi: Hǎo a! Nǐ xiǎng kàn shénme diànyǐng?","es":"Xiaofei: ¡Vale! ¿Qué película quieres ver?"},{"zh":"方方：有一个新电影，是说两个朋友去外国旅游的。","pinyin":"Fāngfāng: Yǒu yí gè xīn diànyǐng, shì shuō liǎng gè péngyou qù wàiguó lǚyóu de.","es":"Fangfang: Hay una película nueva sobre dos amigos que viajan al extranjero."},{"zh":"小飞：听起来不错。我们星期六去还是星期天去？","pinyin":"Xiǎofēi: Tīng qǐlái búcuò. Wǒmen xīngqīliù qù háishi xīngqītiān qù?","es":"Xiaofei: Suena bien. ¿Vamos el sábado o el domingo?"},{"zh":"方方：星期六吧，星期天你们要打篮球。","pinyin":"Fāngfāng: Xīngqīliù ba, xīngqītiān nǐmen yào dǎ lánqiú.","es":"Fangfang: El sábado; el domingo jugáis al baloncesto."},{"zh":"小飞：对，你记得！我在网上买票吧。","pinyin":"Xiǎofēi: Duì, nǐ jìde! Wǒ zài wǎngshang mǎi piào ba.","es":"Xiaofei: ¡Es verdad, te acuerdas! Compro las entradas por internet."},{"zh":"方方：别，是我请你，票我来买。","pinyin":"Fāngfāng: Bié, shì wǒ qǐng nǐ, piào wǒ lái mǎi.","es":"Fangfang: No, te invito yo; las entradas las compro yo."},{"zh":"小飞：那样也好。看完电影，我请你喝奶茶。","pinyin":"Xiǎofēi: Nàyàng yě hǎo. Kàn wán diànyǐng, wǒ qǐng nǐ hē nǎichá.","es":"Xiaofei: Así también está bien. Después de la película te invito a un té con leche."},{"zh":"方方：好！我们都很快乐。","pinyin":"Fāngfāng: Hǎo! Wǒmen dōu hěn kuàilè.","es":"Fangfang: ¡Vale! Así estamos los dos contentos."}]'::jsonb, '[{"prompt":"方方为什么请小飞看电影？","options":["他过生日","他教她游泳","他买了票"],"answer_index":1,"evidence_sentence":0},{"prompt":"他们什么时候去看电影？","options":["星期六","星期天","今天"],"answer_index":0,"evidence_sentence":4},{"prompt":"看完电影，小飞请方方做什么？","options":["打篮球","吃饭","喝奶茶"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['票', '电影', '那样']::text[], '[{"code":"6.2.1","level":2},{"code":"2.10.3","level":2}]'::jsonb, 'neural', '[{"path":"media/42a1a6f9101d0c683d6abf69376fd04587120ae095a70953199e224cc83392b7.m4a","duration_ms":4363},{"path":"media/358116452928a7622719f7f9533d1fa7deb7d65d81d24b1812827e1ded337b56.m4a","duration_ms":3739},{"path":"media/c4db9164c98ae8dc08cdf63245f56ce7c93e69f84edcfbd263f8c798e7361dee.m4a","duration_ms":4579},{"path":"media/f2d029e02856f739211927bf760a1087b5401311ccc3e3bdccd784e024d9dab1.m4a","duration_ms":4915},{"path":"media/e7ff71494df1be6d8012a624a4b8a8f57bbf7f75d91217bd2c4e45d347c3ae20.m4a","duration_ms":3883},{"path":"media/0ffcda4f016b076229f8cf10100005e10f9e1b36649b94ce174a90f03207ebea.m4a","duration_ms":4291},{"path":"media/3f1a53bf16b9a0d4eb6286d7fb467b6b93096379a2967e6b77a604cdf2de160a.m4a","duration_ms":3307},{"path":"media/c40bffa0e7954bc481bd653c408c2e4fb619be3fe9075826e48850d323765472.m4a","duration_ms":4531},{"path":"media/bfce7d5ac80b2a7df35e71d80531033e97aba419150c7334cc20fc49bd73e4dd.m4a","duration_ms":3019}]'::jsonb),
  ('oficina-01-first-day', 2, 'short_text', '第一天上班', 'trabajo', 'oficina', 1, '[{"zh":"张红今年二十三岁，她找到了一个新工作。","pinyin":"Zhāng Hóng jīnnián èrshísān suì, tā zhǎo dào le yí gè xīn gōngzuò.","es":"Zhang Hong tiene veintitrés años y ha encontrado un trabajo nuevo."},{"zh":"今天是她第一天上班。","pinyin":"Jīntiān shì tā dì yī tiān shàngbān.","es":"Hoy es su primer día de trabajo."},{"zh":"公司离她家很远，坐公交车要一个小时。","pinyin":"Gōngsī lí tā jiā hěn yuǎn, zuò gōngjiāochē yào yí gè xiǎoshí.","es":"La empresa está muy lejos de su casa: en autobús se tarda una hora."},{"zh":"所以她七点就出门了。","pinyin":"Suǒyǐ tā qī diǎn jiù chūmén le.","es":"Por eso salió de casa ya a las siete."},{"zh":"公交车上人很多，她站了一个小时。","pinyin":"Gōngjiāochē shàng rén hěn duō, tā zhàn le yí gè xiǎoshí.","es":"En el autobús había mucha gente y estuvo una hora de pie."},{"zh":"八点半，她到了公司的楼下。","pinyin":"Bā diǎn bàn, tā dào le gōngsī de lóu xià.","es":"A las ocho y media llegó al pie del edificio de la empresa."},{"zh":"这个楼很高，她的公司在十二楼。","pinyin":"Zhège lóu hěn gāo, tā de gōngsī zài shí''èr lóu.","es":"El edificio es muy alto; su empresa está en la planta doce."},{"zh":"她进了楼，很快就上去了。","pinyin":"Tā jìn le lóu, hěn kuài jiù shàngqù le.","es":"Entró en el edificio y subió enseguida."},{"zh":"她有一点儿累，但是很高兴，她希望在新公司做得好。","pinyin":"Tā yǒuyìdiǎnr lèi, dànshì hěn gāoxìng, tā xīwàng zài xīn gōngsī zuò de hǎo.","es":"Está un poco cansada pero muy contenta; espera hacerlo bien en la empresa nueva."}]'::jsonb, '[{"prompt":"张红坐什么去公司？","options":["地铁","公交车","出租车"],"answer_index":1,"evidence_sentence":2},{"prompt":"张红几点出门？","options":["七点","八点半","九点"],"answer_index":0,"evidence_sentence":3},{"prompt":"张红的公司在几楼？","options":["二楼","十楼","十二楼"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['出门', '公交车', '楼']::text[], '[{"code":"5.2","level":2},{"code":"2.8.1","level":2}]'::jsonb, 'neural', '[{"path":"media/bac11cf7a7f4e6a4028e1fccbef264a68960f11989b9614388db3a8ee311abb7.m4a","duration_ms":4075},{"path":"media/055f284b442caf3e99b6554495a66fcc52ed35fbd49f04ff6fe3ee553da114a7.m4a","duration_ms":2491},{"path":"media/e8490da698f3e11bbe55eb77ec327be45212b794d9b18340df5d1f4cd415a59e.m4a","duration_ms":4243},{"path":"media/68594861802fe1bdf4370bf812b755552950da0cc51f9466bc0c9fa448993c81.m4a","duration_ms":2635},{"path":"media/6f46d1b368f0c88b862b56e5935a743650c9e12bb463e88b3c9cb7b523d30ec6.m4a","duration_ms":3595},{"path":"media/df0ec99cc21a9036c17128f2a26ad371e04d46228128afa8f4067d4c1799a035.m4a","duration_ms":2899},{"path":"media/338b52910b7fe1d6de57444f31b402696c5139456ab59dfb8a4d157bcd5ddd17.m4a","duration_ms":3379},{"path":"media/89769550fdf3bc0153119d2ac6093fdaaa5aef5a1f3e868eec6b538544f2bfc2.m4a","duration_ms":2731},{"path":"media/d0038bd7c17edba820ac647fcb7b80bf53b4addd383694905d14a25743be361b.m4a","duration_ms":4963}]'::jsonb),
  ('oficina-02-new-colleague', 2, 'dialogue', '新同事', 'trabajo', 'oficina', 2, '[{"zh":"马力：你好！你是新来的吧？我叫马力。","pinyin":"Mǎ Lì: Nǐhǎo! Nǐ shì xīn lái de ba? Wǒ jiào Mǎ Lì.","es":"Ma Li: ¡Hola! Eres la nueva, ¿verdad? Me llamo Ma Li."},{"zh":"张红：你好，我叫张红，今天第一天上班。","pinyin":"Zhāng Hóng: Nǐhǎo, wǒ jiào Zhāng Hóng, jīntiān dì yī tiān shàngbān.","es":"Zhang Hong: Hola, me llamo Zhang Hong; hoy es mi primer día."},{"zh":"马力：请你在这里写一下你的姓名，我们再一起看看公司。","pinyin":"Mǎ Lì: Qǐng nǐ zài zhèlǐ xiě yíxià nǐ de xìngmíng, wǒmen zài yìqǐ kàn kàn gōngsī.","es":"Ma Li: Escribe aquí tu nombre y luego vemos juntos la empresa."},{"zh":"张红：好，谢谢你。洗手间在哪儿？","pinyin":"Zhāng Hóng: Hǎo, xièxie nǐ. Xǐshǒujiān zài nǎr?","es":"Zhang Hong: Vale, gracias. ¿Dónde está el baño?"},{"zh":"马力：往前走，再往左，门上写着字。","pinyin":"Mǎ Lì: Wǎng qián zǒu, zài wǎng zuǒ, mén shàng xiě zhe zì.","es":"Ma Li: Sigue recto y luego a la izquierda; en la puerta está escrito."},{"zh":"张红：那边那个房间是谁的？","pinyin":"Zhāng Hóng: Nàbiān nàge fángjiān shì shuí de?","es":"Zhang Hong: ¿De quién es aquella habitación de allí?"},{"zh":"马力：是白先生的，公司是他的。","pinyin":"Mǎ Lì: Shì Bái xiānsheng de, gōngsī shì tā de.","es":"Ma Li: Es del señor Bai; la empresa es suya."},{"zh":"白先生：张红，你来了！有问题就问马力。","pinyin":"Bái xiānsheng: Zhāng Hóng, nǐ lái le! Yǒu wèntí jiù wèn Mǎ Lì.","es":"Señor Bai: ¡Zhang Hong, ya estás aquí! Si tienes alguna duda, pregúntale a Ma Li."},{"zh":"张红：好的，白先生。","pinyin":"Zhāng Hóng: Hǎo de, Bái xiānsheng.","es":"Zhang Hong: De acuerdo, señor Bai."}]'::jsonb, '[{"prompt":"马力让张红在那里写什么？","options":["电话","姓名","时间"],"answer_index":1,"evidence_sentence":2},{"prompt":"洗手间怎么走？","options":["往前走，再往左","往右走","上楼"],"answer_index":0,"evidence_sentence":4},{"prompt":"公司是谁的？","options":["马力的","张红的","白先生的"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['姓名', '洗手间', '往']::text[], '[{"code":"2.8.2","level":2},{"code":"2.1.1","level":2},{"code":"6.3.1","level":2}]'::jsonb, 'neural', '[{"path":"media/7dee0206ade6e5e6ce24b4dd7bcbc7d1508e0ecf736545937315d0af7a03ad12.m4a","duration_ms":4843},{"path":"media/0b6b045270a6d78e032ae22deeec99bb6f640d8b8065e616bd8d96e4f6597e50.m4a","duration_ms":3907},{"path":"media/abfd43940ebf3ffbf762d905fd9bb9a76f95f1099d700a2be9e555e721911235.m4a","duration_ms":4363},{"path":"media/90b0061227d4b259dc2d150be7c1f63bc0800273927b72e2768bb60cef1e3a15.m4a","duration_ms":3739},{"path":"media/6293e57fc09f9696469829fa9b0bbc35c000ec860b93e7f651ae0f00f41d48c8.m4a","duration_ms":3883},{"path":"media/20a768e431199c7c6dab04c7a2328327ded7751d3ac53bb323670bd66a690f9e.m4a","duration_ms":2539},{"path":"media/e5dac8fbd09546fa7b85a0c547c0f2a2a4634e0db5eb4bff7edb2ca7d7cd812b.m4a","duration_ms":3259},{"path":"media/9bba2f883864b0adfd79ff204c8b765fd2be5c09db9aeef269e3bd63daf5f3a1.m4a","duration_ms":3811},{"path":"media/f36d0a40abb4f9656e786750a5b315e1c249f66c456d7835fd22b3c67a340a24.m4a","duration_ms":2275}]'::jsonb),
  ('oficina-03-late', 2, 'story', '下雨的早上', 'trabajo', 'oficina', 3, '[{"zh":"星期三早上下大雨，路上车很多。","pinyin":"Xīngqīsān zǎoshang xià dà yǔ, lùshang chē hěn duō.","es":"El miércoles por la mañana llovía mucho y había mucho tráfico."},{"zh":"张红在车站等了二十分钟，公交车还没有来。","pinyin":"Zhāng Hóng zài chēzhàn děng le èrshí fēnzhōng, gōngjiāochē hái méiyǒu lái.","es":"Zhang Hong esperó veinte minutos en la parada y el autobús todavía no había llegado."},{"zh":"她看了看手表，已经八点多了。","pinyin":"Tā kàn le kàn shǒubiǎo, yǐjīng bā diǎn duō le.","es":"Miró el reloj: ya eran más de las ocho."},{"zh":"她想，坐公交车可能会晚，就打车去公司。","pinyin":"Tā xiǎng, zuò gōngjiāochē kěnéng huì wǎn, jiù dǎchē qù gōngsī.","es":"Pensó que en autobús llegaría tarde, así que cogió un taxi a la empresa."},{"zh":"出租车开得很慢，她九点十分到了公司。","pinyin":"Chūzūchē kāi de hěn màn, tā jiǔ diǎn shí fēn dào le gōngsī.","es":"El taxi iba muy despacio y llegó a la empresa a las nueve y diez."},{"zh":"她进门的时候，白先生正在打电话。","pinyin":"Tā jìn mén de shíhou, Bái xiānsheng zhèngzài dǎdiànhuà.","es":"Cuando entró, el señor Bai estaba hablando por teléfono."},{"zh":"张红对白先生说对不起，她来晚了。","pinyin":"Zhāng Hóng duì Bái xiānsheng shuō duìbuqǐ, tā lái wǎn le.","es":"Zhang Hong le pidió perdón al señor Bai por llegar tarde."},{"zh":"白先生说没关系，今天下雨，很多人都来晚了。","pinyin":"Bái xiānsheng shuō méiguānxi, jīntiān xiàyǔ, hěn duō rén dōu lái wǎn le.","es":"El señor Bai dijo que no pasaba nada: hoy llovía y mucha gente había llegado tarde."},{"zh":"马力给她拿来热水，张红觉得很高兴。","pinyin":"Mǎ Lì gěi tā ná lái rè shuǐ, Zhāng Hóng juéde hěn gāoxìng.","es":"Ma Li le trajo agua caliente y Zhang Hong se sintió muy contenta."}]'::jsonb, '[{"prompt":"张红在车站等了多长时间？","options":["十分钟","二十分钟","一个小时"],"answer_index":1,"evidence_sentence":1},{"prompt":"张红几点到公司？","options":["九点十分","八点","八点半"],"answer_index":0,"evidence_sentence":4},{"prompt":"张红进门的时候，白先生在做什么？","options":["喝水","看书","打电话"],"answer_index":2,"evidence_sentence":5}]'::jsonb, array['打车', '正', '路上']::text[], '[{"code":"2.7.3","level":2},{"code":"6.1.1","level":2}]'::jsonb, 'neural', '[{"path":"media/5ede5123e4c27cbed7a13c588b5d8539a7bda07d84e09e42e1fb41bce1278393.m4a","duration_ms":3667},{"path":"media/2b2af0a8e4b70bebff58a86f63388497832f869d59f410b1dda15f59f52a3cbf.m4a","duration_ms":4531},{"path":"media/c6546010df4ba61192a27ed884fc3d86b4e7546c073d4134645017a5ceef8da6.m4a","duration_ms":3139},{"path":"media/57d84ee1cb86047547fc833f582a4b85dc42cd172c83c7238a7f749c56a37096.m4a","duration_ms":4459},{"path":"media/a23825e1cd41b5bf8074b56b942a129134c3ab08a2b9517239bdc3dba5137ac0.m4a","duration_ms":4003},{"path":"media/5a6c581d3f69f258c575380b29ce8736d676f11adc90d9b81b8bb92bf4bc3924.m4a","duration_ms":3667},{"path":"media/6440bc4f4683b59966f238f08861e08cb54c96e68a3f66117e7853658dacf9db.m4a","duration_ms":3787},{"path":"media/a22389abf16f38fa3e2ba99158c62dfcf0c2c09289255ff65f1a2905ac00ad7d.m4a","duration_ms":4987},{"path":"media/08e89926c39d6da76c6764b0bf83c6e3bc069cc5fbd44c5bc047ac7f02061c12.m4a","duration_ms":3859}]'::jsonb),
  ('oficina-04-lunch', 2, 'dialogue', '一起吃午饭', 'trabajo', 'oficina', 4, '[{"zh":"中午，马力和张红去公司旁边的饭馆吃饭。","pinyin":"Zhōngwǔ, Mǎ Lì hé Zhāng Hóng qù gōngsī pángbiān de fànguǎn chī fàn.","es":"A mediodía, Ma Li y Zhang Hong van a comer al restaurante que hay junto a la empresa."},{"zh":"马力：你想吃米饭还是面条儿？","pinyin":"Mǎ Lì: Nǐ xiǎng chī mǐfàn háishi miàntiáor?","es":"Ma Li: ¿Quieres arroz o fideos?"},{"zh":"张红：面条儿吧。马力，你家离公司远吗？","pinyin":"Zhāng Hóng: Miàntiáor ba. Mǎ Lì, nǐ jiā lí gōngsī yuǎn ma?","es":"Zhang Hong: Fideos. Ma Li, ¿tu casa está lejos de la empresa?"},{"zh":"马力：不远，我走路十分钟就到。你呢？","pinyin":"Mǎ Lì: Bù yuǎn, wǒ zǒulù shí fēnzhōng jiù dào. Nǐ ne?","es":"Ma Li: No; andando llego en diez minutos. ¿Y tú?"},{"zh":"张红：我家很远，每天在路上要两个小时。","pinyin":"Zhāng Hóng: Wǒ jiā hěn yuǎn, měi tiān zài lùshang yào liǎng gè xiǎoshí.","es":"Zhang Hong: Mi casa está muy lejos; cada día paso dos horas de camino."},{"zh":"马力：那太累了。你可以住得近一点儿。","pinyin":"Mǎ Lì: Nà tài lèi le. Nǐ kěyǐ zhù de jìn yìdiǎnr.","es":"Ma Li: Eso cansa demasiado. Podrías vivir un poco más cerca."},{"zh":"张红：我也这样想，但是不知道哪儿有房间。","pinyin":"Zhāng Hóng: Wǒ yě zhèyàng xiǎng, dànshì bù zhīdào nǎr yǒu fángjiān.","es":"Zhang Hong: Yo también lo pienso, pero no sé dónde hay habitaciones."},{"zh":"马力：我住的楼里有一个房间，你自己去看看吧。","pinyin":"Mǎ Lì: Wǒ zhù de lóu lǐ yǒu yí gè fángjiān, nǐ zìjǐ qù kàn kàn ba.","es":"Ma Li: En el edificio donde vivo hay una habitación libre; ve tú misma a verla."},{"zh":"张红：太好了！明天下班后我就去。","pinyin":"Zhāng Hóng: Tài hǎo le! Míngtiān xiàbān hòu wǒ jiù qù.","es":"Zhang Hong: ¡Estupendo! Mañana después del trabajo voy."}]'::jsonb, '[{"prompt":"张红想吃什么？","options":["米饭","面条儿","饺子"],"answer_index":1,"evidence_sentence":2},{"prompt":"马力走路去公司要多长时间？","options":["十分钟","两个小时","一个小时"],"answer_index":0,"evidence_sentence":3},{"prompt":"张红什么时候去看房间？","options":["今天中午","星期天","明天下班后"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['饭馆', '近', '远']::text[], '[{"code":"6.4.1","level":2},{"code":"2.3.2","level":2}]'::jsonb, 'neural', '[{"path":"media/64bb0ec55e428ffec88c70967d57c6305ef062e118608e31ee1bd27c2121ad6f.m4a","duration_ms":4603},{"path":"media/fe17ad4252e67912c57dc1025691d073e5a35176f75b3fd6791a2eddc43f32d3.m4a","duration_ms":3019},{"path":"media/c649fa7c8e76b845ccfcdcd37e52d8874c37f0526620df77653fd1e1f30d6204.m4a","duration_ms":3979},{"path":"media/15aadd32f33ab16943381737f1d1a512bb17963e986e104dc35d95e61c6f9513.m4a","duration_ms":4291},{"path":"media/ed6a7e8b287cf103c45d6ca489aae402cf527ccc16f3663e23cce73e2443d61f.m4a","duration_ms":3763},{"path":"media/3cd4fbf6bfe01cfaccd5224613aec734aad446e5d65e23cc4e1dff5ee7f31319.m4a","duration_ms":3691},{"path":"media/ce7a56d82356e84d3186d335535232adbca369c442dbdc98e748f912cf74b365.m4a","duration_ms":3907},{"path":"media/1b1fd619f856a60abab9e2ff709bb0f4fc78f784403a5b987cffca85e56ba6ea.m4a","duration_ms":4195},{"path":"media/6c1b740b48fdab8594960280eec0f7e206a82da85f77521d4443d54d9a2596b4.m4a","duration_ms":3595}]'::jsonb),
  ('oficina-05-moving', 2, 'short_text', '住得近了', 'trabajo', 'oficina', 5, '[{"zh":"张红看了那个房间，很喜欢，第二个星期就住进去了。","pinyin":"Zhāng Hóng kàn le nàge fángjiān, hěn xǐhuan, dì èr gè xīngqī jiù zhù jìnqù le.","es":"Zhang Hong vio la habitación, le gustó mucho y a la semana siguiente ya se había mudado."},{"zh":"现在她家离公司很近，走路十分钟就到了。","pinyin":"Xiànzài tā jiā lí gōngsī hěn jìn, zǒulù shí fēnzhōng jiù dào le.","es":"Ahora su casa está muy cerca de la empresa: andando llega en diez minutos."},{"zh":"她每天早上七点半起床，起床后还能去外面运动。","pinyin":"Tā měi tiān zǎoshang qī diǎn bàn qǐchuáng, qǐchuáng hòu hái néng qù wàimiàn yùndòng.","es":"Cada mañana se levanta a las siete y media y después todavía puede salir a hacer ejercicio."},{"zh":"下班后，她有时候跟马力一起去跑步。","pinyin":"Xiàbān hòu, tā yǒushíhou gēn Mǎ Lì yìqǐ qù pǎobù.","es":"Después del trabajo, a veces sale a correr con Ma Li."},{"zh":"晚上她自己做饭，还看书学习。","pinyin":"Wǎnshang tā zìjǐ zuòfàn, hái kàn shū xuéxí.","es":"Por la noche se hace ella misma la cena y además lee y estudia."},{"zh":"白先生说，张红来了一个月，工作做得很好。","pinyin":"Bái xiānsheng shuō, Zhāng Hóng lái le yí gè yuè, gōngzuò zuò de hěn hǎo.","es":"El señor Bai dice que Zhang Hong lleva un mes y trabaja muy bien."},{"zh":"他说张红是这个月公司里做得最好的新人。","pinyin":"Tā shuō Zhāng Hóng shì zhège yuè gōngsī lǐ zuò de zuì hǎo de xīn rén.","es":"Dice que es la persona nueva que mejor ha trabajado este mes en la empresa."},{"zh":"张红很高兴，她觉得住得近真好。","pinyin":"Zhāng Hóng hěn gāoxìng, tā juéde zhù de jìn zhēn hǎo.","es":"Zhang Hong está muy contenta; cree que vivir cerca es estupendo."},{"zh":"她给妈妈打电话，说她在这里很快乐。","pinyin":"Tā gěi māma dǎdiànhuà, shuō tā zài zhèlǐ hěn kuàilè.","es":"Llama a su madre y le dice que aquí es muy feliz."}]'::jsonb, '[{"prompt":"张红现在走路去公司要多长时间？","options":["十分钟","一个小时","两个小时"],"answer_index":0,"evidence_sentence":1},{"prompt":"下班后张红有时候做什么？","options":["跟马力去跑步","去饭馆","打车回家"],"answer_index":0,"evidence_sentence":3},{"prompt":"白先生觉得张红怎么样？","options":["常常来晚","不喜欢工作","工作做得很好"],"answer_index":2,"evidence_sentence":5}]'::jsonb, array['运动', '进去', '最']::text[], '[{"code":"5.4.3","level":2},{"code":"2.7.6","level":2}]'::jsonb, 'neural', '[{"path":"media/228a52dcd5f647af4d4456a436d038f0d1abeb8ac5fa18f22bb8df6b99711230.m4a","duration_ms":5107},{"path":"media/06f7f0d13b8eb989657d9f7a32e7da94d9e2d985f238c00d3d5844dce9f02859.m4a","duration_ms":4267},{"path":"media/8ae27d2dc7e57a5ed05538b6eddaf0565868d2a640022ec97b36c7c55c81648f.m4a","duration_ms":5059},{"path":"media/3f365de2a08f3749adc33744ddff226d44baa29328911e845d7e015703e98b91.m4a","duration_ms":4003},{"path":"media/ab02989fa0a8f073811879642300a639d69ba86d759c8d6fa5a1769508636d77.m4a","duration_ms":3427},{"path":"media/273ac0d6854bf0880871cbc28a6b438aa83e38ff369f4636a756051990ae1633.m4a","duration_ms":4507},{"path":"media/d0c8ee999c0429e348f2953a0917508e7b9d14c0d47127f93fa23995466cde1b.m4a","duration_ms":4147},{"path":"media/e0df5c3ad3d9642dddd28ab15ffb35eb653a4865ef9f8a998886285f55841ae0.m4a","duration_ms":3859},{"path":"media/aca6d6a444472e2f080077732fd9974d061512beb6281b64ec8a3ff5ad5ee0e9.m4a","duration_ms":3811}]'::jsonb),
  ('health-01-i-feel-bad', 2, 'dialogue', '头疼', 'salud', 'salud', 1, '[{"zh":"陈东和他的妻子小丽住在一起。","pinyin":"Chén Dōng hé tā de qīzi Xiǎolì zhù zài yìqǐ.","es":"Chen Dong vive con su mujer, Xiaoli."},{"zh":"小丽：陈东，七点了，你怎么还不起床？","pinyin":"Xiǎolì: Chén Dōng, qī diǎn le, nǐ zěnme hái bù qǐchuáng?","es":"Xiaoli: Chen Dong, ya son las siete; ¿cómo es que todavía no te levantas?"},{"zh":"陈东：我头很疼，身体也不舒服。","pinyin":"Chén Dōng: Wǒ tóu hěn téng, shēntǐ yě bù shūfu.","es":"Chen Dong: Me duele mucho la cabeza y tampoco me encuentro bien."},{"zh":"小丽：你昨天晚上几点睡的？","pinyin":"Xiǎolì: Nǐ zuótiān wǎnshang jǐ diǎn shuì de?","es":"Xiaoli: ¿A qué hora te acostaste anoche?"},{"zh":"陈东：两点多。昨天工作太多了。","pinyin":"Chén Dōng: Liǎng diǎn duō. Zuótiān gōngzuò tài duō le.","es":"Chen Dong: Pasadas las dos. Ayer tenía demasiado trabajo."},{"zh":"小丽：你最近每天都睡得很晚。","pinyin":"Xiǎolì: Nǐ zuì jìn měi tiān dōu shuì de hěn wǎn.","es":"Xiaoli: Últimamente te acuestas tarde todos los días."},{"zh":"陈东：我休息休息就好了。","pinyin":"Chén Dōng: Wǒ xiūxi xiūxi jiù hǎo le.","es":"Chen Dong: Con descansar un poco se me pasa."},{"zh":"小丽：别这样，我们今天去医院看看。","pinyin":"Xiǎolì: Bié zhèyàng, wǒmen jīntiān qù yīyuàn kàn kàn.","es":"Xiaoli: No digas eso; hoy vamos al hospital a que te vean."},{"zh":"陈东：好吧，我给公司打个电话。","pinyin":"Chén Dōng: Hǎo ba, wǒ gěi gōngsī dǎ gè diànhuà.","es":"Chen Dong: Está bien; llamo a la empresa."}]'::jsonb, '[{"prompt":"陈东哪儿不舒服？","options":["手","头","眼睛"],"answer_index":1,"evidence_sentence":2},{"prompt":"陈东昨天几点睡的？","options":["两点多","十点","七点"],"answer_index":0,"evidence_sentence":4},{"prompt":"小丽让陈东做什么？","options":["去公司","多睡觉","去医院看看"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['头', '疼', '妻子']::text[], '[{"code":"2.2.1","level":2},{"code":"6.1.1","level":2}]'::jsonb, 'neural', '[{"path":"media/8ca610fea8557ebedbcb982f873647919f115d187e2e6426e2cf38e6de0c3ec0.m4a","duration_ms":3163},{"path":"media/c760be7fe36444101465bc21abc624a665623d877d108054dbea049fa1aed291.m4a","duration_ms":3619},{"path":"media/e10f90897774bc0875858c1b90e915048b1756d114dbf23542ff78530df500ca.m4a","duration_ms":3115},{"path":"media/63cc8941f884d1fbcd78a35cb98ee0306886465de91a6d90bf53076b8dd330a9.m4a","duration_ms":2659},{"path":"media/087c4189e3c6dab23f29d10e9f5de6681d3a1b7c05b1fe6942484a97f235dbeb.m4a","duration_ms":3667},{"path":"media/169ffbaedb8abfc40839d797bfbc9065027bac1870cbcb5b4a8d0b7453174c0f.m4a","duration_ms":2803},{"path":"media/cf18e2927d68a5ec8d1ad91f45344d357392cebe34e2ba9c8b9c06de397c6897.m4a","duration_ms":2275},{"path":"media/e71fa2722cd735704d36cecc4b113f7968266e862357a18b2f9238ec77fe6f7d.m4a","duration_ms":3403},{"path":"media/6a6a685e2aa3090315b2057d372b0f0f255593a35fc23338418810e6bd401cbf.m4a","duration_ms":3139}]'::jsonb),
  ('salud-02-hospital', 2, 'short_text', '在医院', 'salud', 'salud', 2, '[{"zh":"上午九点，陈东和小丽到了医院。","pinyin":"Shàngwǔ jiǔ diǎn, Chén Dōng hé Xiǎolì dào le yīyuàn.","es":"A las nueve de la mañana, Chen Dong y Xiaoli llegaron al hospital."},{"zh":"医院里人很多，他们等了四十分钟。","pinyin":"Yīyuàn lǐ rén hěn duō, tāmen děng le sìshí fēnzhōng.","es":"En el hospital había mucha gente y esperaron cuarenta minutos."},{"zh":"医生是一位女医生，她问陈东哪儿不舒服。","pinyin":"Yīshēng shì yí wèi nǚ yīshēng, tā wèn Chén Dōng nǎr bù shūfu.","es":"La médica le preguntó a Chen Dong qué le pasaba."},{"zh":"陈东说他头疼，晚上也睡不好。","pinyin":"Chén Dōng shuō tā tóu téng, wǎnshang yě shuì bù hǎo.","es":"Chen Dong dijo que le duele la cabeza y que por las noches tampoco duerme bien."},{"zh":"医生说没有大问题，是因为太累了。","pinyin":"Yīshēng shuō méiyǒu dà wèntí, shì yīnwèi tài lèi le.","es":"La médica dijo que no era nada grave, que era porque estaba demasiado cansado."},{"zh":"她给了陈东一些药，让他一天吃三次。","pinyin":"Tā gěi le Chén Dōng yìxiē yào, ràng tā yì tiān chī sān cì.","es":"Le dio unas medicinas a Chen Dong y le dijo que las tomara tres veces al día."},{"zh":"医生还说，他要多休息，晚上十一点前睡觉。","pinyin":"Yīshēng hái shuō, tā yào duō xiūxi, wǎnshang shíyī diǎn qián shuìjiào.","es":"La médica también le dijo que tiene que descansar más y acostarse antes de las once."},{"zh":"从医院出来，小丽说这几天她来做饭。","pinyin":"Cóng yīyuàn chūlái, Xiǎolì shuō zhè jǐ tiān tā lái zuòfàn.","es":"Al salir del hospital, Xiaoli dijo que estos días cocinaría ella."},{"zh":"陈东觉得有这样的妻子真好。","pinyin":"Chén Dōng juéde yǒu zhèyàng de qīzi zhēn hǎo.","es":"Chen Dong piensa que tener una mujer así es estupendo."}]'::jsonb, '[{"prompt":"他们在医院等了多长时间？","options":["十分钟","四十分钟","两个小时"],"answer_index":1,"evidence_sentence":1},{"prompt":"医生说陈东为什么不舒服？","options":["因为太累了","因为吃得太多","因为天气冷"],"answer_index":0,"evidence_sentence":4},{"prompt":"药一天吃几次？","options":["一次","两次","三次"],"answer_index":2,"evidence_sentence":5}]'::jsonb, array['药', '次', '累']::text[], '[{"code":"2.6.2","level":2},{"code":"2.8.4","level":2}]'::jsonb, 'neural', '[{"path":"media/7ea8572d3dbbb5995dc274693f0b058ca93059e85f5085e8e617137d6a439232.m4a","duration_ms":3547},{"path":"media/c30bca9955ffb75bb69b1a9d1c7181c1fde21810c3c2cc7475a494363c374b65.m4a","duration_ms":3187},{"path":"media/812ffb1505df39f4548ddd4532e4e15e466b6f3dd01cd98918c12a9b8271e10b.m4a","duration_ms":3691},{"path":"media/f74056dcabe123b39090b12f339bedb37480869e8f07454e6337c045a9476a30.m4a","duration_ms":3067},{"path":"media/1263bd1f22e942cc56934952d0686b79234ca264dbed9a7ecff75989d20d05f5.m4a","duration_ms":3427},{"path":"media/83e69f33ea674ff38456146683bf81d543a78abc748ccdb2489912ad3286eedf.m4a","duration_ms":3619},{"path":"media/b62b1583ae712bc809d1d3eba6aff235c55450bc91c0170de07a2373ef9e06a0.m4a","duration_ms":4195},{"path":"media/a29b2bb6ca4b6f1896f1df44f2f9e50032a9f5ec78d52480cbf6a465479b12c0.m4a","duration_ms":3883},{"path":"media/edb264a52f9275afa85d710885b48fd4f7ef0ea1f4dcd09517d8790bbe590487.m4a","duration_ms":2947}]'::jsonb),
  ('salud-03-pharmacy', 2, 'story', '去药店', 'salud', 'salud', 3, '[{"zh":"第二天，陈东的药快要吃完了。","pinyin":"Dì èr tiān, Chén Dōng de yào kuàiyào chī wán le.","es":"Al día siguiente, a Chen Dong ya casi se le habían acabado las medicinas."},{"zh":"小丽去药店买药，陈东在家里睡觉。","pinyin":"Xiǎolì qù yàodiàn mǎi yào, Chén Dōng zài jiā lǐ shuìjiào.","es":"Xiaoli fue a la farmacia a comprar medicinas y Chen Dong se quedó durmiendo en casa."},{"zh":"药店离他们家不远，走路五分钟就到了。","pinyin":"Yàodiàn lí tāmen jiā bù yuǎn, zǒulù wǔ fēnzhōng jiù dào le.","es":"La farmacia no está lejos de su casa: andando se llega en cinco minutos."},{"zh":"药店的人说这个药很好，但是别吃得太多。","pinyin":"Yàodiàn de rén shuō zhège yào hěn hǎo, dànshì bié chī de tài duō.","es":"En la farmacia le dijeron que esta medicina es muy buena, pero que no se tome demasiada."},{"zh":"回家的路上，小丽还买了一些水果和面条儿。","pinyin":"Huí jiā de lùshang, Xiǎolì hái mǎi le yìxiē shuǐguǒ hé miàntiáor.","es":"De camino a casa, Xiaoli compró además algo de fruta y fideos."},{"zh":"中午，她做了陈东最喜欢吃的面条儿。","pinyin":"Zhōngwǔ, tā zuò le Chén Dōng zuì xǐhuan chī de miàntiáor.","es":"A mediodía preparó los fideos que más le gustan a Chen Dong."},{"zh":"吃饭前，小丽让陈东去洗手。","pinyin":"Chī fàn qián, Xiǎolì ràng Chén Dōng qù xǐ shǒu.","es":"Antes de comer, Xiaoli le dijo a Chen Dong que fuera a lavarse las manos."},{"zh":"陈东洗完手，坐下来吃了很多。","pinyin":"Chén Dōng xǐ wán shǒu, zuò xiàlái chī le hěn duō.","es":"Chen Dong se lavó las manos, se sentó y comió mucho."},{"zh":"他说吃了药，睡了一个上午，现在头已经不疼了。","pinyin":"Tā shuō chī le yào, shuì le yí gè shàngwǔ, xiànzài tóu yǐjīng bù téng le.","es":"Dijo que, después de tomar la medicina y dormir toda la mañana, ya no le dolía la cabeza."}]'::jsonb, '[{"prompt":"小丽去哪儿买药？","options":["医院","药店","超市"],"answer_index":1,"evidence_sentence":1},{"prompt":"药店的人说什么？","options":["别吃得太多","一天吃五次","药不好"],"answer_index":0,"evidence_sentence":3},{"prompt":"吃饭前，小丽让陈东做什么？","options":["睡觉","吃药","洗手"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['药店', '洗', '手']::text[], '[{"code":"3.1.2","level":2},{"code":"2.7.5","level":2}]'::jsonb, 'neural', '[{"path":"media/8f1923c2b1a306b764eadc845da1e0dc5d07afd1facd26300b182da3b6bfbf95.m4a","duration_ms":3091},{"path":"media/1b9bf981cf97d09ee434111edafbdadf0b4763a512168e3ad228f85c22b042b9.m4a","duration_ms":3691},{"path":"media/f9b8ab5b3b8cdddbf303114a93a6a043c72120f95584af5d9a49c9238737fb9f.m4a","duration_ms":3739},{"path":"media/2e1d26302bf36f1227f6bf6decf5548c45006f9596f8d1a2c5aecd0073a958a3.m4a","duration_ms":4027},{"path":"media/1ae90847bd73bf35d52f4f0486d90e4f200b958ea592e7830363558c490dfb88.m4a","duration_ms":3979},{"path":"media/ce155b51cfed0bb81c65a8fef42023bc47a3437281dd352b71a2d4c9f8d2e46e.m4a","duration_ms":3595},{"path":"media/981a6772fa278c0263e1337459c14f8bd1dd939c97b7c28f7856dc56794d2b16.m4a","duration_ms":3091},{"path":"media/c7698171e851950bbb1b2aebfa3e80ece061158bf5a2ed908e46e786d36f9747.m4a","duration_ms":3187},{"path":"media/f61e6cef25b71e4c1ebedf85e6e5d844bfe77969caef0c1cbf223b744987df90.m4a","duration_ms":4339}]'::jsonb),
  ('salud-04-check-up', 2, 'dialogue', '医生说要运动', 'salud', 'salud', 4, '[{"zh":"一个星期后，陈东再去医院看医生。","pinyin":"Yí gè xīngqī hòu, Chén Dōng zài qù yīyuàn kàn yīshēng.","es":"Una semana después, Chen Dong volvió al hospital a ver a la médica."},{"zh":"医生：你好，这几天身体怎么样？","pinyin":"Yīshēng: Nǐhǎo, zhè jǐ tiān shēntǐ zěnmeyàng?","es":"Médica: Hola, ¿qué tal estos días?"},{"zh":"陈东：好多了，头不疼了，晚上也睡得很好。","pinyin":"Chén Dōng: Hǎo duō le, tóu bù téng le, wǎnshang yě shuì de hěn hǎo.","es":"Chen Dong: Mucho mejor; ya no me duele la cabeza y por las noches duermo bien."},{"zh":"医生：很好。你每天工作几个小时？","pinyin":"Yīshēng: Hěn hǎo. Nǐ měi tiān gōngzuò jǐ gè xiǎoshí?","es":"Médica: Muy bien. ¿Cuántas horas trabajas al día?"},{"zh":"陈东：十个小时，我每天都坐在电脑前面。","pinyin":"Chén Dōng: Shí gè xiǎoshí, wǒ měi tiān dōu zuò zài diànnǎo qiánmiàn.","es":"Chen Dong: Diez horas; me paso el día sentado delante del ordenador."},{"zh":"医生：别坐那么长时间，要经常站起来动一动。","pinyin":"Yīshēng: Bié zuò nàme cháng shíjiān, yào jīngcháng zhàn qǐlái dòng yi dòng.","es":"Médica: No estés sentado tanto tiempo; tienes que levantarte a menudo y moverte un poco."},{"zh":"陈东：好的。我还要吃药吗？","pinyin":"Chén Dōng: Hǎo de. Wǒ hái yào chī yào ma?","es":"Chen Dong: De acuerdo. ¿Tengo que seguir tomando la medicina?"},{"zh":"医生：不要吃了。你要每天运动半个小时。","pinyin":"Yīshēng: Búyào chī le. Nǐ yào měi tiān yùndòng bàn gè xiǎoshí.","es":"Médica: Ya no hace falta. Tienes que hacer media hora de ejercicio cada día."},{"zh":"陈东：好，明天早上我就开始跑步。","pinyin":"Chén Dōng: Hǎo, míngtiān zǎoshang wǒ jiù kāishǐ pǎobù.","es":"Chen Dong: Bien; mañana por la mañana empiezo a correr."}]'::jsonb, '[{"prompt":"陈东现在晚上睡得怎么样？","options":["睡不好","睡得很好","不睡觉"],"answer_index":1,"evidence_sentence":2},{"prompt":"陈东每天工作几个小时？","options":["十个小时","八个小时","五个小时"],"answer_index":0,"evidence_sentence":4},{"prompt":"医生让陈东每天做什么？","options":["吃三次药","多睡觉","运动半个小时"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['运动', '动', '前面']::text[], '[{"code":"2.7.6","level":2},{"code":"6.2.2","level":2}]'::jsonb, 'neural', '[{"path":"media/7466bd6606d33352761facfe3902e1a3ee253e07b93a99ce9c33fed1bd1b9f2d.m4a","duration_ms":3403},{"path":"media/8a405ebdc275fc07110b39b989bddd38b660f0cc77b276d4a93c7c30c214266b.m4a","duration_ms":2827},{"path":"media/e8c52ce539a8dc61925d90a01bea3cde24c57200133b327f17fc3ac9ae9458fa.m4a","duration_ms":4051},{"path":"media/261ed8336860cc339a75f318fa64331335c8cdcfc9438a2a742ac77360ee9866.m4a","duration_ms":3619},{"path":"media/4dd4b0300454c685796f36f8c30472195c66d50e5845be29c074f1e5253bcf15.m4a","duration_ms":4411},{"path":"media/265b6f90422a4edcbf0061186593bf791e67b66f453cf5f8e91e8f58957f1f82.m4a","duration_ms":3955},{"path":"media/19c91a74904688deb99811c52fc3de5b5cf25e01d29bd41fd5816d84b3641c3d.m4a","duration_ms":3259},{"path":"media/5d8198b3f737af3a2c464c3c9d8e710559ebf2819e3c289c9c839fde5d2f2e90.m4a","duration_ms":3955},{"path":"media/01840ff2174d9d22802c588a88c6fbc913ca59f876040b25211474df4f68b8a8.m4a","duration_ms":3379}]'::jsonb),
  ('salud-05-running-together', 2, 'short_text', '丈夫和妻子一起跑步', 'salud', 'salud', 5, '[{"zh":"现在陈东每天早上六点半起床去跑步。","pinyin":"Xiànzài Chén Dōng měi tiān zǎoshang liù diǎn bàn qǐchuáng qù pǎobù.","es":"Ahora Chen Dong se levanta cada mañana a las seis y media para ir a correr."},{"zh":"小丽说她也想跑，所以丈夫和妻子一起去。","pinyin":"Xiǎolì shuō tā yě xiǎng pǎo, suǒyǐ zhàngfu hé qīzi yìqǐ qù.","es":"Xiaoli dice que ella también quiere correr, así que van juntos marido y mujer."},{"zh":"第一天，他们跑了十分钟就很累了。","pinyin":"Dì yī tiān, tāmen pǎo le shí fēnzhōng jiù hěn lèi le.","es":"El primer día, a los diez minutos ya estaban muy cansados."},{"zh":"他们慢慢跑，一个星期后可以跑半个小时了。","pinyin":"Tāmen màn màn pǎo, yí gè xīngqī hòu kěyǐ pǎo bàn gè xiǎoshí le.","es":"Fueron corriendo despacio y, una semana después, ya podían correr media hora."},{"zh":"跑步后，他们一起吃早饭，说说今天要做的事情。","pinyin":"Pǎobù hòu, tāmen yìqǐ chī zǎofàn, shuō shuō jīntiān yào zuò de shìqing.","es":"Después de correr desayunan juntos y hablan de lo que tienen que hacer ese día."},{"zh":"陈东觉得自己的身体比上个月好多了。","pinyin":"Chén Dōng juéde zìjǐ de shēntǐ bǐ shàng gè yuè hǎo duō le.","es":"Chen Dong siente que está mucho mejor que el mes pasado."},{"zh":"他晚上十一点前就睡觉，工作的时候也经常站起来动一动。","pinyin":"Tā wǎnshang shíyī diǎn qián jiù shuìjiào, gōngzuò de shíhou yě jīngcháng zhàn qǐlái dòng yi dòng.","es":"Se acuesta antes de las once y, cuando trabaja, se levanta a menudo a moverse un poco."},{"zh":"小丽说她丈夫现在很少生病了。","pinyin":"Xiǎolì shuō tā zhàngfu xiànzài hěn shǎo shēngbìng le.","es":"Xiaoli dice que ahora su marido casi no se pone enfermo."},{"zh":"他们希望每天都能一起跑步。","pinyin":"Tāmen xīwàng měi tiān dōu néng yìqǐ pǎobù.","es":"Esperan poder correr juntos todos los días."}]'::jsonb, '[{"prompt":"陈东每天早上几点起床？","options":["六点","六点半","七点"],"answer_index":1,"evidence_sentence":0},{"prompt":"第一天，他们跑了多长时间？","options":["十分钟","半个小时","一个小时"],"answer_index":0,"evidence_sentence":2},{"prompt":"跑步后，他们一起做什么？","options":["去公司","去医院","吃早饭"],"answer_index":2,"evidence_sentence":4}]'::jsonb, array['丈夫', '跑步', '身体']::text[], '[{"code":"2.4.1","level":2},{"code":"6.3.4","level":2}]'::jsonb, 'neural', '[{"path":"media/18959dc45c23c8ff4e1cb08526176bd55dc94d6e943990a3001462356b1d4864.m4a","duration_ms":3739},{"path":"media/a6ab170441f7243784a201d06ba535ede529871386740992fa76962a4668ec60.m4a","duration_ms":4147},{"path":"media/d90309f8f54ccbc13bbf95128b4d0dcf42657ba2542a3866bc8240391bb34abd.m4a","duration_ms":3307},{"path":"media/a3c0129953caac903f783f3f881542ea71538bf856418c6827cfbb4b01bd52fd.m4a","duration_ms":4003},{"path":"media/0dca0729a8ce1002a501dfcefab79bc779f85724876943d7f3d589f084821ce1.m4a","duration_ms":4387},{"path":"media/4758d36e2cfbc1e0de4c042b9f646b6df3a33c985dfcaac841e26cad3d57b6f5.m4a","duration_ms":3691},{"path":"media/8761e9eabc6c360d4d8a3e17cf489cb9b74153bb8b5520f9f6699592b984e318.m4a","duration_ms":5179},{"path":"media/06e9bf261887859d308e6c794805f14438fb37a181560f7027d12fe0d9dd8dc4.m4a","duration_ms":3019},{"path":"media/6385b1b6495974ee1b0a2106e4270971f8701b6aeaf5156a417b7cefe59bd92c.m4a","duration_ms":2947}]'::jsonb),
  ('shop-01-tea-and-coffee', 2, 'short_text', '学校旁边的商店', 'compras', 'tienda', 1, '[{"zh":"我叫小林，是大学生。","pinyin":"Wǒ jiào Xiǎolín, shì dàxuéshēng.","es":"Me llamo Xiaolin y soy universitario."},{"zh":"我们学校旁边有一个小商店，东西不贵。","pinyin":"Wǒmen xuéxiào pángbiān yǒu yí gè xiǎo shāngdiàn, dōngxi bú guì.","es":"Al lado de nuestra universidad hay una tienda pequeña donde las cosas no son caras."},{"zh":"今天下午，我和朋友小美一起去那里买喝的。","pinyin":"Jīntiān xiàwǔ, wǒ hé péngyou Xiǎoměi yìqǐ qù nàlǐ mǎi hē de.","es":"Esta tarde, mi amiga Xiaomei y yo hemos ido allí a comprar algo de beber."},{"zh":"商店的先生很好，他认识我们。","pinyin":"Shāngdiàn de xiānsheng hěn hǎo, tā rènshi wǒmen.","es":"El dependiente de la tienda es muy amable; nos conoce."},{"zh":"我买了绿茶，小美想喝奶茶。","pinyin":"Wǒ mǎi le lǜchá, Xiǎoměi xiǎng hē nǎichá.","es":"Yo he comprado té verde y Xiaomei quería té con leche."},{"zh":"奶茶比绿茶贵两块钱。","pinyin":"Nǎichá bǐ lǜchá guì liǎng kuài qián.","es":"El té con leche cuesta dos yuanes más que el té verde."},{"zh":"先生说他们的红茶也很好喝，我们下次可以买红茶。","pinyin":"Xiānsheng shuō tāmen de hóngchá yě hěn hǎo hē, wǒmen xià cì kěyǐ mǎi hóngchá.","es":"El dependiente dice que su té negro también está muy bueno; la próxima vez podemos comprarlo."},{"zh":"我们坐在商店门口喝茶，说了很长时间。","pinyin":"Wǒmen zuò zài shāngdiàn ménkǒu hē chá, shuō le hěn cháng shíjiān.","es":"Nos sentamos a la puerta de la tienda a tomar el té y estuvimos hablando mucho rato."},{"zh":"小美说这个商店不错，她明天还想来。","pinyin":"Xiǎoměi shuō zhège shāngdiàn búcuò, tā míngtiān hái xiǎng lái.","es":"Xiaomei dice que esta tienda está muy bien y que mañana quiere volver."}]'::jsonb, '[{"prompt":"小林买了什么？","options":["奶茶","绿茶","咖啡"],"answer_index":1,"evidence_sentence":4},{"prompt":"奶茶比绿茶贵多少？","options":["两块钱","十块钱","一样贵"],"answer_index":0,"evidence_sentence":5},{"prompt":"小美觉得这个商店怎么样？","options":["太贵了","很远","不错"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['红茶', '奶茶', '绿茶']::text[], '[{"code":"6.3.4","level":2},{"code":"2.10.3","level":2}]'::jsonb, 'neural', '[{"path":"media/71e36ae24590c2a203077179514b055ae9842608d495d198e305910c08ea58c2.m4a","duration_ms":2875},{"path":"media/c6597e7f071c64a0fbc338c27a5aa6f2c63d4f2bce05f66df9f491f9d032ca31.m4a","duration_ms":4051},{"path":"media/0166ce6e18c1f88e2b578d061385a89ad07487fc2c59d5e529d0f6f1f34606dc.m4a","duration_ms":4219},{"path":"media/b6528d6dde4d135cf0563727cbaf2afe815ef86d6661bf97236acb051861c62e.m4a","duration_ms":3427},{"path":"media/bdd08fdf18774f06b3a490bac9c56e2d8ac4694b69238c061b4a2c761e8353b5.m4a","duration_ms":3403},{"path":"media/3e661fa4b06010e6206637906178d991028087c78df0b33a1cada46d45dc66fe.m4a","duration_ms":2923},{"path":"media/8a7947c1efe0392e70caf52db47071888d6cf2f36591143766fe85ab1c8b8f77.m4a","duration_ms":4987},{"path":"media/d17c055ee55e1bd9c789732e00248e111eb09cf7a264fe1e5bc5b93375d6aec8.m4a","duration_ms":3955},{"path":"media/bf07be462b534485e214ae501b877634ea20144c4d1b8ed153606ed93f15ca2e.m4a","duration_ms":4555}]'::jsonb),
  ('market-02-too-expensive', 2, 'dialogue', '这条裤子太贵了', 'compras', 'tienda', 2, '[{"zh":"星期六，小林和小美去一个衣服店买裤子。","pinyin":"Xīngqīliù, Xiǎolín hé Xiǎoměi qù yí gè yīfu diàn mǎi kùzi.","es":"El sábado, Xiaolin y Xiaomei van a una tienda de ropa a comprar unos pantalones."},{"zh":"小林：先生，这条黑色的裤子多少钱？","pinyin":"Xiǎolín: Xiānsheng, zhè tiáo hēisè de kùzi duōshao qián?","es":"Xiaolin: Disculpe, ¿cuánto cuestan estos pantalones negros?"},{"zh":"先生：三百八十块。","pinyin":"Xiānsheng: Sānbǎibāshí kuài.","es":"Dependiente: Trescientos ochenta yuanes."},{"zh":"小林：太贵了！有没有便宜一点儿的？","pinyin":"Xiǎolín: Tài guì le! Yǒu méiyǒu piányi yìdiǎnr de?","es":"Xiaolin: ¡Qué caros! ¿Tiene algunos más baratos?"},{"zh":"先生：这条白色的便宜，两百块。","pinyin":"Xiānsheng: Zhè tiáo báisè de piányi, liǎngbǎi kuài.","es":"Dependiente: Estos blancos son más baratos: doscientos yuanes."},{"zh":"小美：你喜欢黑色的还是白色的？","pinyin":"Xiǎoměi: Nǐ xǐhuan hēisè de háishi báisè de?","es":"Xiaomei: ¿Te gustan más los negros o los blancos?"},{"zh":"小林：我最喜欢黑色的，但是白色的也不错。","pinyin":"Xiǎolín: Wǒ zuì xǐhuan hēisè de, dànshì báisè de yě búcuò.","es":"Xiaolin: Los que más me gustan son los negros, pero los blancos tampoco están mal."},{"zh":"先生：你可以穿一下，看看大小。","pinyin":"Xiānsheng: Nǐ kěyǐ chuān yíxià, kàn kàn dà xiǎo.","es":"Dependiente: Puedes probártelos para ver la talla."},{"zh":"小美：很好看！就买这条白色的吧。","pinyin":"Xiǎoměi: Hěn hǎokàn! Jiù mǎi zhè tiáo báisè de ba.","es":"Xiaomei: ¡Te quedan muy bien! Cómprate estos blancos."}]'::jsonb, '[{"prompt":"黑色的裤子多少钱？","options":["两百块","三百八十块","八十块"],"answer_index":1,"evidence_sentence":2},{"prompt":"小林最喜欢什么颜色的？","options":["黑色的","白色的","红色的"],"answer_index":0,"evidence_sentence":6},{"prompt":"小美觉得白色的裤子怎么样？","options":["太长了","太贵了","很好看"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['裤子', '条', '黑色']::text[], '[{"code":"2.6.1","level":2},{"code":"2.7.1","level":2},{"code":"6.2.1","level":2}]'::jsonb, 'neural', '[{"path":"media/5c598a5132f23811419a7b9b9591c2049b8f6982298062a3ead3abfeadd0b0d6.m4a","duration_ms":4387},{"path":"media/d5b8149ed6bf0dca265a27f17030185a721b0769f6eced169a8ffa745d3bacd6.m4a","duration_ms":3763},{"path":"media/25db8271648c67819677d947534099ba0288c740209fa3e6d152a92bbe5885ab.m4a","duration_ms":1915},{"path":"media/84243216f97d94e979084c144f5cc1f2887ac8ae2c19a7302622d22ba4dbd903.m4a","duration_ms":3547},{"path":"media/46bef891ae6f23332bb948529cfbf59fe311068ec84bf8b2697d79094bd807ee.m4a","duration_ms":2851},{"path":"media/3f347abb4b93015b7b1ccb0a9e4f9e869a75396358012d855bc8071856a9c943.m4a","duration_ms":3019},{"path":"media/986e15885a31ac48eb100f13d23535495808247efd0f29352df39ea0467741fe.m4a","duration_ms":3763},{"path":"media/d47267816d4df3f21438d678f030af32eb68b00620cc6f118c316baf27414e9c.m4a","duration_ms":2443},{"path":"media/ee0953eeea1c9ceb2764763bb7cd429c2a35f9388489c64eb8de879bc83f0ddb.m4a","duration_ms":3715}]'::jsonb),
  ('market-03-buying-fruit', 2, 'short_text', '在网上买书包', 'compras', 'tienda', 3, '[{"zh":"小林的书包坏了，他想买一个新的。","pinyin":"Xiǎolín de shūbāo huài le, tā xiǎng mǎi yí gè xīn de.","es":"La mochila de Xiaolin se ha roto y quiere comprarse una nueva."},{"zh":"小美说网上的东西很多，也很便宜。","pinyin":"Xiǎoměi shuō wǎngshang de dōngxi hěn duō, yě hěn piányi.","es":"Xiaomei dice que en internet hay muchas cosas y además son baratas."},{"zh":"晚上，小林上网看了很长时间。","pinyin":"Wǎnshang, Xiǎolín shàngwǎng kàn le hěn cháng shíjiān.","es":"Por la noche, Xiaolin estuvo mucho rato mirando en internet."},{"zh":"网上有大书包、小书包，有黑色的、红色的、白色的什么的。","pinyin":"Wǎngshang yǒu dà shūbāo, xiǎo shūbāo, yǒu hēisè de, hóngsè de, báisè de shénme de.","es":"En internet hay mochilas grandes y pequeñas: negras, rojas, blancas y de otros colores."},{"zh":"这个黑色的书包九十九块钱，不贵。","pinyin":"Zhège hēisè de shūbāo jiǔshíjiǔ kuài qián, bú guì.","es":"Esta mochila negra cuesta noventa y nueve yuanes; no es cara."},{"zh":"小林很快就买了。","pinyin":"Xiǎolín hěn kuài jiù mǎi le.","es":"Xiaolin la compró enseguida."},{"zh":"网上说三天后书包就到了。","pinyin":"Wǎngshang shuō sān tiān hòu shūbāo jiù dào le.","es":"En la web dice que la mochila llegará en tres días."},{"zh":"小林很高兴，他告诉小美，他在网上买了书包。","pinyin":"Xiǎolín hěn gāoxìng, tā gàosu Xiǎoměi, tā zài wǎngshang mǎi le shūbāo.","es":"Xiaolin está muy contento y le cuenta a Xiaomei que ha comprado una mochila por internet."},{"zh":"小美说她也想看看。","pinyin":"Xiǎoměi shuō tā yě xiǎng kàn kàn.","es":"Xiaomei dice que ella también quiere verla."}]'::jsonb, '[{"prompt":"小林为什么想买书包？","options":["书包太贵了","他的书包坏了","小美让他买"],"answer_index":1,"evidence_sentence":0},{"prompt":"小林在哪儿买书包？","options":["在网上","在商场","在学校旁边的商店"],"answer_index":0,"evidence_sentence":7},{"prompt":"书包多少钱？","options":["十九块","九百块","九十九块"],"answer_index":2,"evidence_sentence":4}]'::jsonb, array['网上', '上网', '书包']::text[], '[{"code":"3.3.1","level":2},{"code":"2.7.3","level":2}]'::jsonb, 'neural', '[{"path":"media/713079ecdb2724755660724c5070a69cd15d9e18d1116daee93d945875499af4.m4a","duration_ms":3499},{"path":"media/3847f8996d18760dea65cada190fa63b0d0bee7289686be42709a8f1507d29ef.m4a","duration_ms":4171},{"path":"media/9ebf35654b3f23d7fa6ab9440c44aa1ddb0eb14f52f46bb4c8bba29aedcd9d58.m4a","duration_ms":3595},{"path":"media/0198296060ded2e76a4db4f3e6e6dcdafca33dc48abb5a3903e1500589539e46.m4a","duration_ms":6331},{"path":"media/fb264cc6654985ee9670a26abd1693d55fadbb64b2773f6ba708a978e3b8e114.m4a","duration_ms":4147},{"path":"media/f21795006c0e11e50d0b7edc820f5dd60e862fb7a9a416b03aae2f91b042c265.m4a","duration_ms":2227},{"path":"media/eae7cdebafdaa9f1b510191a70c180b45a7ac030a515bce3cd4758b4084e059b.m4a","duration_ms":3667},{"path":"media/5237e52fceecca004e806d656ce9ee526b3b62a102279ca775d1af2f24c97102.m4a","duration_ms":4843},{"path":"media/d19e8e2b6fbcbf09fe0868d1db9f9c8606cb8b6611483f69c22bebab6a2a2388.m4a","duration_ms":2587}]'::jsonb),
  ('tienda-04-broken-bag', 2, 'story', '书包到了', 'compras', 'tienda', 4, '[{"zh":"三天后，小林的书包到了。","pinyin":"Sān tiān hòu, Xiǎolín de shūbāo dào le.","es":"Tres días después llegó la mochila de Xiaolin."},{"zh":"他很高兴，很快打开看了看。","pinyin":"Tā hěn gāoxìng, hěn kuài dǎkāi kàn le kàn.","es":"Muy contento, la abrió enseguida para verla."},{"zh":"书包是黑色的，很好看。","pinyin":"Shūbāo shì hēisè de, hěn hǎokàn.","es":"La mochila es negra y muy bonita."},{"zh":"但是书包的右边坏了。","pinyin":"Dànshì shūbāo de yòubian huài le.","es":"Pero el lado derecho de la mochila está roto."},{"zh":"小林很不高兴，他给小美打电话。","pinyin":"Xiǎolín hěn bù gāoxìng, tā gěi Xiǎoměi dǎdiànhuà.","es":"Xiaolin se enfada mucho y llama por teléfono a Xiaomei."},{"zh":"小美说网上买东西，有时候会这样。","pinyin":"Xiǎoměi shuō wǎngshang mǎi dōngxi, yǒushíhou huì zhèyàng.","es":"Xiaomei dice que, al comprar por internet, a veces pasa esto."},{"zh":"她让小林给商店打电话，让他们再送一个新的来。","pinyin":"Tā ràng Xiǎolín gěi shāngdiàn dǎdiànhuà, ràng tāmen zài sòng yí gè xīn de lái.","es":"Le dice a Xiaolin que llame a la tienda para que le envíen otra nueva."},{"zh":"小林打了电话，商店的先生说对不起，明天给他送一个新的来。","pinyin":"Xiǎolín dǎ le diànhuà, shāngdiàn de xiānsheng shuō duìbuqǐ, míngtiān gěi tā sòng yí gè xīn de lái.","es":"Xiaolin llamó; el dependiente de la tienda le pidió perdón y le dijo que mañana le lleva una nueva."},{"zh":"小林说没关系，他在家等着新书包。","pinyin":"Xiǎolín shuō méiguānxi, tā zài jiā děng zhe xīn shūbāo.","es":"Xiaolin dijo que no pasaba nada; espera la mochila nueva en casa."}]'::jsonb, '[{"prompt":"书包到了，小林做了什么？","options":["给商店写字","很快打开看了看","睡觉了"],"answer_index":1,"evidence_sentence":1},{"prompt":"书包哪儿坏了？","options":["左边","右边","里面"],"answer_index":1,"evidence_sentence":3},{"prompt":"商店的先生说什么时候送新书包？","options":["今天","下个星期","明天"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['打开', '坏', '右边']::text[], '[{"code":"5.4.2","level":2},{"code":"2.3.3","level":2}]'::jsonb, 'neural', '[{"path":"media/895821b38f5d1f6835579dead6e28314e39c3c22981deec9165ab8454d0b2b83.m4a","duration_ms":3235},{"path":"media/21a805d7a4025bf69837f197075058dd2116e73c7bad8f0b4272f2fde249e4dd.m4a","duration_ms":3211},{"path":"media/363f14ea7ceb4d782887a076456665ed45f116d28d64c7fb180d608706eb102f.m4a","duration_ms":3043},{"path":"media/41490e8f153001acb77f295497c49260115d3e02014ca26f621da6425a4512af.m4a","duration_ms":2323},{"path":"media/ca3dbd0f1490d26a716c63bb6621acc240880700edd3735a3647dfdae83c334e.m4a","duration_ms":3667},{"path":"media/27c822438fd5d46f6efa86da9c19b40c6187b61b51689e0cc3712930c8215091.m4a","duration_ms":4219},{"path":"media/27e2c57d661d359c44cc9f941ef3b0e318ae97f40f3b185d40441a45e6d8cce0.m4a","duration_ms":4603},{"path":"media/7864882b027d8d68ee9948b49af337b7283b83079dde7edeb430bdd18d27c376.m4a","duration_ms":5659},{"path":"media/be6c36498950874deec17c5e1f3c169b48dcf0e937485f6c3c75a52ffd321a27.m4a","duration_ms":4195}]'::jsonb),
  ('tienda-05-new-bag', 2, 'dialogue', '新书包', 'compras', 'tienda', 5, '[{"zh":"第二天下午，商店的先生给小林送书包来了。","pinyin":"Dì èr tiān xiàwǔ, shāngdiàn de xiānsheng gěi Xiǎolín sòng shūbāo lái le.","es":"Al día siguiente por la tarde, el dependiente de la tienda le llevó la mochila a Xiaolin."},{"zh":"先生：你好，你是小林吧？这是你的新书包。","pinyin":"Xiānsheng: Nǐhǎo, nǐ shì Xiǎolín ba? Zhè shì nǐ de xīn shūbāo.","es":"Dependiente: Hola, eres Xiaolin, ¿verdad? Aquí tienes tu mochila nueva."},{"zh":"小林：谢谢！您是从商店来的吗？","pinyin":"Xiǎolín: Xièxie! Nín shì cóng shāngdiàn lái de ma?","es":"Xiaolin: ¡Gracias! ¿Viene usted desde la tienda?"},{"zh":"先生：是的，我们的商店离你们学校不远。","pinyin":"Xiānsheng: Shì de, wǒmen de shāngdiàn lí nǐmen xuéxiào bù yuǎn.","es":"Dependiente: Sí, nuestra tienda no está lejos de vuestra universidad."},{"zh":"先生：真不好意思，上次的书包是坏的。","pinyin":"Xiānsheng: Zhēn bùhǎoyìsi, shàng cì de shūbāo shì huài de.","es":"Dependiente: Lo siento mucho; la mochila de la otra vez estaba rota."},{"zh":"小林：没关系，您还送来了，我很高兴。","pinyin":"Xiǎolín: Méiguānxi, nín hái sòng lái le, wǒ hěn gāoxìng.","es":"Xiaolin: No pasa nada; además me la ha traído usted, estoy muy contento."},{"zh":"先生：你打开看看，这个好不好？","pinyin":"Xiānsheng: Nǐ dǎkāi kàn kàn, zhège hǎo bu hǎo?","es":"Dependiente: Ábrela y mira si esta está bien."},{"zh":"小林：很好，没有坏。您等一会儿，我给您拿一些水。","pinyin":"Xiǎolín: Hěn hǎo, méiyǒu huài. Nín děng yíhuìr, wǒ gěi nín ná yìxiē shuǐ.","es":"Xiaolin: Está muy bien, no está rota. Espere un momento, que le traigo un poco de agua."},{"zh":"先生：谢谢你，我不喝了，还要去送东西呢。","pinyin":"Xiānsheng: Xièxie nǐ, wǒ bù hē le, hái yào qù sòng dōngxi ne.","es":"Dependiente: Gracias, pero no; todavía tengo que ir a entregar más cosas."}]'::jsonb, '[{"prompt":"谁给小林送书包来了？","options":["小美","商店的先生","老师"],"answer_index":1,"evidence_sentence":0},{"prompt":"商店离学校远吗？","options":["不远","很远","在学校里面"],"answer_index":0,"evidence_sentence":3},{"prompt":"先生为什么不喝水？","options":["他不喜欢喝水","他已经喝了","他还要去送东西"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['不好意思', '离', '一会儿']::text[], '[{"code":"2.7.7","level":2},{"code":"6.3.5","level":2}]'::jsonb, 'neural', '[{"path":"media/036fb3a107e3963e78605b138cb7de2fb5461aaeb0a6de97ab19d6aee4232b6a.m4a","duration_ms":4555},{"path":"media/8f31fee5ff218307ccc69dcd0771114bddf8fb9469ace202813668abccfa5648.m4a","duration_ms":3931},{"path":"media/cab31d75265e131d8304af318872548d08a6fee58fc996a03049b2730f46d0ca.m4a","duration_ms":3475},{"path":"media/be25be8c90ce251d3a01aaa45c34e6f1ee78b118b443666de7fed2b128de4156.m4a","duration_ms":3139},{"path":"media/33998e8da016ead8f075286b109c7140c4d2257f1c72b1647f2c94d28e3188dd.m4a","duration_ms":3235},{"path":"media/cf945b428c1f9a027a69391e256e3fe0fdef9a2d6596db3f93ee882fc43bccf8.m4a","duration_ms":3739},{"path":"media/b626dd143c39cec5670ad5d1c899c328b4edbd94210fea68ee2818dee6bf8175.m4a","duration_ms":2419},{"path":"media/2712b0c624a1d54e888b58038c93bc780bacc9f216ca2a9daa5720eaa846fa8d.m4a","duration_ms":5131},{"path":"media/327037b7f76ee8bd940cc5235d6f9ccc9032effc624d6fc29d214f4a2bf84630.m4a","duration_ms":3331}]'::jsonb),
  ('tienda-06-thank-you', 2, 'story', '再去那个商店', 'compras', 'tienda', 6, '[{"zh":"新书包很好，小林每天上课都拿着它。","pinyin":"Xīn shūbāo hěn hǎo, Xiǎolín měi tiān shàngkè dōu ná zhe tā.","es":"La mochila nueva es muy buena; Xiaolin la lleva todos los días a clase."},{"zh":"他想谢谢那个商店的先生。","pinyin":"Tā xiǎng xièxie nàge shāngdiàn de xiānsheng.","es":"Quiere dar las gracias al dependiente de aquella tienda."},{"zh":"星期天，他和小美一起去了那个商店。","pinyin":"Xīngqītiān, tā hé Xiǎoměi yìqǐ qù le nàge shāngdiàn.","es":"El domingo, él y Xiaomei fueron juntos a aquella tienda."},{"zh":"商店不大，但是里面东西很多，有书包、本子、笔什么的。","pinyin":"Shāngdiàn bú dà, dànshì lǐmiàn dōngxi hěn duō, yǒu shūbāo, běnzi, bǐ shénme de.","es":"La tienda no es grande, pero dentro hay muchas cosas: mochilas, cuadernos, bolígrafos y demás."},{"zh":"先生说，商店开了十年了，卖了一万多个书包。","pinyin":"Xiānsheng shuō, shāngdiàn kāi le shí nián le, mài le yíwàn duō gè shūbāo.","es":"El dependiente cuenta que la tienda lleva diez años abierta y ha vendido más de diez mil mochilas."},{"zh":"小美说这个商店这么小，卖了那么多书包，真不错。","pinyin":"Xiǎoměi shuō zhège shāngdiàn zhème xiǎo, mài le nàme duō shūbāo, zhēn búcuò.","es":"Xiaomei dice que, para ser una tienda tan pequeña, ha vendido muchísimas mochilas; está muy bien."},{"zh":"小林在商店里买了本子和笔。","pinyin":"Xiǎolín zài shāngdiàn lǐ mǎi le běnzi hé bǐ.","es":"Xiaolin compró en la tienda cuadernos y bolígrafos."},{"zh":"先生说他们下次来，他给他们便宜一点儿。","pinyin":"Xiānsheng shuō tāmen xià cì lái, tā gěi tāmen piányi yìdiǎnr.","es":"El dependiente les dijo que, la próxima vez que vengan, se lo dejará un poco más barato."},{"zh":"小林觉得在这样的小商店买东西也很好。","pinyin":"Xiǎolín juéde zài zhèyàng de xiǎo shāngdiàn mǎi dōngxi yě hěn hǎo.","es":"Xiaolin piensa que comprar en una tienda pequeña como esta también está muy bien."}]'::jsonb, '[{"prompt":"小林为什么去那个商店？","options":["书包又坏了","想谢谢先生","想买裤子"],"answer_index":1,"evidence_sentence":1},{"prompt":"商店卖了多少书包？","options":["一千多个","一万多个","一百多个"],"answer_index":1,"evidence_sentence":4},{"prompt":"先生说他们下次来会怎么样？","options":["送他们书包","不卖东西","给他们便宜一点儿"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['这么', '那么', '万']::text[], '[{"code":"2.5","level":2},{"code":"8.1","level":2}]'::jsonb, 'neural', '[{"path":"media/c7f2609f2fa6afae36b60fc1563a6a7c8a0f2ce2d9142c74ff16f838626bcb84.m4a","duration_ms":4099},{"path":"media/093c7ae045ca959e6acca99af34b9ebc02615b5f0b80d2aa8386baf6efb74a69.m4a","duration_ms":2659},{"path":"media/bf4f5235b69ff46dc9ddf6719873c26d00b6f09d790bd38d07abf4d894377fc7.m4a","duration_ms":3811},{"path":"media/071cdbc3f26abe69934832ccd8b93d514d49d3d88285ec50d490edd7f396fe8d.m4a","duration_ms":5779},{"path":"media/27ce454ff4610187ec10774ead7936f4493938d19e4ddaae8d8b92213d04d1d7.m4a","duration_ms":4819},{"path":"media/3c16a2cb5fcc90780d0543969a065b225b474f98f3cb5639a26cef70c30e5673.m4a","duration_ms":5443},{"path":"media/623ba7dab484aab59de17be450dff5049e48b89f3d9e2019795d768a3006b3b2.m4a","duration_ms":3211},{"path":"media/8fb4145ac2834bbd33bbd23b0604825b5959bd54a34ba54408684d93e68271fc.m4a","duration_ms":3811},{"path":"media/bed9ef3594e92fe2fc4374c0927c58a26f0df9ea3c8b7bf7dd4811b04f33f342.m4a","duration_ms":4291}]'::jsonb),
  ('vecinos-01-moving-in', 2, 'story', '新家', 'comunicación interpersonal', 'vecinos', 1, '[{"zh":"小平今年十六岁，在高中上学。","pinyin":"Xiǎopíng jīnnián shíliù suì, zài gāozhōng shàngxué.","es":"Xiaoping tiene dieciséis años y estudia en el instituto."},{"zh":"这个星期六，他和爸爸妈妈住进了一个新楼。","pinyin":"Zhège xīngqīliù, tā hé bàba māma zhù jìn le yí gè xīn lóu.","es":"Este sábado se mudó con sus padres a un edificio nuevo."},{"zh":"他们的家在五楼，有三个房间。","pinyin":"Tāmen de jiā zài wǔ lóu, yǒu sān gè fángjiān.","es":"Su casa está en el quinto piso y tiene tres habitaciones."},{"zh":"东西很多，他们从早上忙到下午。","pinyin":"Dōngxi hěn duō, tāmen cóng zǎoshang máng dào xiàwǔ.","es":"Tenían muchas cosas y estuvieron ocupados desde la mañana hasta la tarde."},{"zh":"小平拿着一个大包上楼的时候，楼上下来一位奶奶。","pinyin":"Xiǎopíng ná zhe yí gè dà bāo shàng lóu de shíhou, lóu shàng xiàlái yí wèi nǎinai.","es":"Cuando Xiaoping subía con una bolsa grande, una anciana bajó del piso de arriba."},{"zh":"她说大家都叫她李奶奶，她住在六楼。","pinyin":"Tā shuō dàjiā dōu jiào tā Lǐ nǎinai, tā zhù zài liù lóu.","es":"Dijo que todos la llaman abuela Li y que vive en el sexto."},{"zh":"李奶奶帮他开门，让他快进来。","pinyin":"Lǐ nǎinai bāng tā kāi mén, ràng tā kuài jìnlái.","es":"La abuela Li le abrió la puerta y le dijo que entrara rápido."},{"zh":"小平说谢谢，李奶奶笑着说没关系。","pinyin":"Xiǎopíng shuō xièxie, Lǐ nǎinai xiào zhe shuō méiguānxi.","es":"Xiaoping le dio las gracias y la abuela Li dijo sonriendo que no era nada."},{"zh":"她还说有问题可以过来找她。","pinyin":"Tā hái shuō yǒu wèntí kěyǐ guòlái zhǎo tā.","es":"También le dijo que, si tenía algún problema, podía ir a buscarla."}]'::jsonb, '[{"prompt":"小平的家在几楼？","options":["六楼","五楼","三楼"],"answer_index":1,"evidence_sentence":2},{"prompt":"李奶奶住在几楼？","options":["六楼","五楼","一楼"],"answer_index":0,"evidence_sentence":5},{"prompt":"李奶奶帮小平做了什么？","options":["拿包","做饭","开门"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['高中', '进来', '过来']::text[], '[{"code":"5.4.2","level":2},{"code":"3.1.2","level":2}]'::jsonb, 'neural', '[{"path":"media/e24de56de4e7ae287e0346181f8bb0048446b5d24e97b048c96d9959d6422684.m4a","duration_ms":3283},{"path":"media/48398167428983b5337772672946a3f8f9630053827bc23a215bb866820eafff.m4a","duration_ms":3859},{"path":"media/29d9be68818c4b44d40b693f8b8500f0f7da4912c43d4f0b0e1f0a07b1ec64ec.m4a","duration_ms":3019},{"path":"media/3e75d8ab096dc3778f6f95f3a75641bfe4482e1ce9a13199f593df09f8eb8057.m4a","duration_ms":3379},{"path":"media/99fe63ede81fae369443be5fc49758a04ad784bfaa4d2f28c5264f91c07e2c74.m4a","duration_ms":4435},{"path":"media/9d1c057f320eb6f56bf4e780ffd72356311b418d481e1c67c4c12540279e8288.m4a","duration_ms":3883},{"path":"media/7b76bb30c69d2a6fe9b23f687fa2137e43ca72ed18b0290feeb2ababaf455d43.m4a","duration_ms":2971},{"path":"media/11bf410d5e8fb462c382d08e034d4fa69a0bb99b4dd0a3ab94bc5736ebb5f0c3.m4a","duration_ms":3715},{"path":"media/943b4e8f2c9de71739893f172fe22a87e9560ad0afe45b914cd5eb5bb285951e.m4a","duration_ms":2875}]'::jsonb),
  ('vecinos-02-grandma-li', 2, 'dialogue', '楼上的李奶奶', 'comunicación interpersonal', 'vecinos', 2, '[{"zh":"第二天晚上，李奶奶拿着一包东西下楼来了。","pinyin":"Dì èr tiān wǎnshang, Lǐ nǎinai ná zhe yì bāo dōngxi xià lóu lái le.","es":"La noche siguiente, la abuela Li bajó con un paquete."},{"zh":"李奶奶：小平，这是我做的包子，你们吃吧。","pinyin":"Lǐ nǎinai: Xiǎopíng, zhè shì wǒ zuò de bāozi, nǐmen chī ba.","es":"Abuela Li: Xiaoping, son baozi que he hecho yo; coméoslos."},{"zh":"小平：谢谢李奶奶！您进来坐一会儿吧。","pinyin":"Xiǎopíng: Xièxie Lǐ nǎinai! Nín jìnlái zuò yíhuìr ba.","es":"Xiaoping: ¡Gracias, abuela Li! Pase y siéntese un rato."},{"zh":"李奶奶：好。你在哪个学校上学？","pinyin":"Lǐ nǎinai: Hǎo. Nǐ zài nǎge xuéxiào shàngxué?","es":"Abuela Li: Bien. ¿En qué escuela estudias?"},{"zh":"小平：在旁边的那个高中，走路十分钟。","pinyin":"Xiǎopíng: Zài pángbiān de nàge gāozhōng, zǒulù shí fēnzhōng.","es":"Xiaoping: En el instituto de al lado; está a diez minutos andando."},{"zh":"李奶奶：那个学校很好，我儿子小时候也在那里上学。","pinyin":"Lǐ nǎinai: Nàge xuéxiào hěn hǎo, wǒ érzi xiǎoshíhou yě zài nàlǐ shàngxué.","es":"Abuela Li: Es muy buena escuela; mi hijo también estudió allí de pequeño."},{"zh":"小平：您的儿子现在住在哪儿？","pinyin":"Xiǎopíng: Nín de érzi xiànzài zhù zài nǎr?","es":"Xiaoping: ¿Dónde vive ahora su hijo?"},{"zh":"李奶奶：他在外国工作，一年回来一次。","pinyin":"Lǐ nǎinai: Tā zài wàiguó gōngzuò, yì nián huílái yí cì.","es":"Abuela Li: Trabaja en el extranjero y vuelve una vez al año."},{"zh":"小平：您一个人住，有事就叫我，我很快就上来。","pinyin":"Xiǎopíng: Nín yí gè rén zhù, yǒu shì jiù jiào wǒ, wǒ hěn kuài jiù shànglái.","es":"Xiaoping: Usted vive sola; si necesita algo, llámeme y subo enseguida."},{"zh":"李奶奶：你真是一个好孩子！","pinyin":"Lǐ nǎinai: Nǐ zhēn shì yí gè hǎo háizi!","es":"Abuela Li: ¡Qué buen chico eres!"}]'::jsonb, '[{"prompt":"李奶奶给小平拿来了什么？","options":["水果","包子","面条儿"],"answer_index":1,"evidence_sentence":1},{"prompt":"李奶奶的儿子在哪儿工作？","options":["在外国","在高中","在医院"],"answer_index":0,"evidence_sentence":6},{"prompt":"小平说李奶奶有事可以怎么样？","options":["给她儿子打电话","去医院","叫他"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['包', '上来', '高中']::text[], '[{"code":"6.3.6","level":2},{"code":"2.10.3","level":2}]'::jsonb, 'neural', '[{"path":"media/0e357dc3c51d869dbcd1a457ee0cc28bc7847d3ba47c7e8460c5fd7ceaf257f0.m4a","duration_ms":4003},{"path":"media/2bcb29d5ecb52d227ae62bb45149a4af99d73e92851e2809c6f7dde27af46b81.m4a","duration_ms":3523},{"path":"media/a83c049d55f349d839a85fdf9237d1ed0886fc484457e0b24f2e3c26c5eda54d.m4a","duration_ms":3691},{"path":"media/f71f217d6967130a8d28c3659e58f29dc7a1779204b2767d601aaedeae0afa0c.m4a","duration_ms":3211},{"path":"media/3aa9b45669a24ae8d41c07e627b8431842aea6ab3b2f56a34e11fd5963f16a78.m4a","duration_ms":3739},{"path":"media/db675a4a8c67fa0a3ebf0a7e5560032faffa4d35a9ca1cd7909ccb58e269b3df.m4a","duration_ms":4531},{"path":"media/eaf67c972cf1d136772e677383a225934dfb2c18c9f18a05f6381640b877885c.m4a","duration_ms":2995},{"path":"media/bd5897d86e8dc2286007a39ca4a0bb6b78a0b592a04a0f027214db15b82caa92.m4a","duration_ms":3187},{"path":"media/025a40458f6f92f90af23e0be619c6ed690eaffff5b93a199fe060e79b2b7681.m4a","duration_ms":4363},{"path":"media/3706b442665d1ca033e30c7546bc16b57ebe75a1d2c92d58e3847f09fc045bea.m4a","duration_ms":2131}]'::jsonb),
  ('vecinos-03-helping', 2, 'short_text', '帮李奶奶', 'comunicación interpersonal', 'vecinos', 3, '[{"zh":"安安是小平的同学，她家在小平家后面。","pinyin":"Ān''ān shì Xiǎopíng de tóngxué, tā jiā zài Xiǎopíng jiā hòumiàn.","es":"Anan es compañera de clase de Xiaoping; su casa está detrás de la de él."},{"zh":"星期天上午，安安来小平家玩。","pinyin":"Xīngqītiān shàngwǔ, Ān''ān lái Xiǎopíng jiā wán.","es":"El domingo por la mañana, Anan fue a casa de Xiaoping."},{"zh":"他们出门的时候，看见李奶奶在楼下。","pinyin":"Tāmen chūmén de shíhou, kànjiàn Lǐ nǎinai zài lóu xià.","es":"Al salir, vieron a la abuela Li abajo."},{"zh":"她买了很多东西，有肉、有水果，还有一大包鸡蛋。","pinyin":"Tā mǎi le hěn duō dōngxi, yǒu ròu, yǒu shuǐguǒ, hái yǒu yí dà bāo jīdàn.","es":"Había comprado muchas cosas: carne, fruta y una bolsa grande de huevos."},{"zh":"小平和安安很快跑过去帮她拿。","pinyin":"Xiǎopíng hé Ān''ān hěn kuài pǎo guòqù bāng tā ná.","es":"Xiaoping y Anan corrieron enseguida a ayudarla a llevarlo."},{"zh":"东西很快就拿到了六楼。","pinyin":"Dōngxi hěn kuài jiù ná dào le liù lóu.","es":"Enseguida subieron las cosas al sexto."},{"zh":"李奶奶说他们走得比她快多了。","pinyin":"Lǐ nǎinai shuō tāmen zǒu de bǐ tā kuài duō le.","es":"La abuela Li dijo que ellos subían mucho más rápido que ella."},{"zh":"她想给他们钱，但他们不要。","pinyin":"Tā xiǎng gěi tāmen qián, dàn tāmen búyào.","es":"Quiso darles dinero, pero no lo aceptaron."},{"zh":"李奶奶就给了他们每人一个苹果。","pinyin":"Lǐ nǎinai jiù gěi le tāmen měi rén yí gè píngguǒ.","es":"Así que la abuela Li les dio una manzana a cada uno."}]'::jsonb, '[{"prompt":"安安家在哪儿？","options":["小平家旁边","小平家后面","六楼"],"answer_index":1,"evidence_sentence":0},{"prompt":"李奶奶买了什么？","options":["肉、水果和鸡蛋","包子和茶","衣服"],"answer_index":0,"evidence_sentence":3},{"prompt":"最后李奶奶给了他们什么？","options":["钱","包子","苹果"],"answer_index":2,"evidence_sentence":8}]'::jsonb, array['后面', '出', '但']::text[], '[{"code":"6.3.4","level":2},{"code":"5.4.2","level":2}]'::jsonb, 'neural', '[{"path":"media/8fa9183c3a0655f1f6c1c6d56b86afcc6ab742519666b8365bde11460298fc58.m4a","duration_ms":3835},{"path":"media/84d55d930d02a367ba4981f6069dfe8040f007000885e515a8960607040467b3.m4a","duration_ms":3067},{"path":"media/8ec32c68c532bce7efff2a81d236882fab178e0abc644a5f9518b21eac2b5f64.m4a","duration_ms":3451},{"path":"media/02e5d40b6e909ae517dc2433de62ccabb28b85d29b641ae82912a14d9d00368f.m4a","duration_ms":4843},{"path":"media/3e3a5753fb66ed2af94d84be5781ceae0202bd45972e5db8f61c3688782e466b.m4a","duration_ms":2971},{"path":"media/1488f5a3ea193946b60b04bb9ba4ff0b22a3a22d0b5f771d03bc9b06c52fa50e.m4a","duration_ms":2467},{"path":"media/96325ffe368a1575ff27b53f20b8e81bfa4d2ded20bdb4b95af819dfb0b43388.m4a","duration_ms":2971},{"path":"media/d2d0f77aca87d414ffc7d3a71669148cdf19726fbeaaddf975c7527581cf46e1.m4a","duration_ms":2875},{"path":"media/509adc56c7f4fa2cdc6de71e8dc763ab656c7db60bfc0781ee4ea9bbedde92f3.m4a","duration_ms":3187}]'::jsonb),
  ('vecinos-04-phone', 2, 'story', '在手机上见面', 'comunicación interpersonal', 'vecinos', 4, '[{"zh":"这周三，李奶奶来找小平。","pinyin":"Zhè zhōu sān, Lǐ nǎinai lái zhǎo Xiǎopíng.","es":"Este miércoles, la abuela Li vino a buscar a Xiaoping."},{"zh":"她说她很想儿子，但是不会在手机上跟他见面。","pinyin":"Tā shuō tā hěn xiǎng érzi, dànshì bú huì zài shǒujī shàng gēn tā jiàn miàn.","es":"Dijo que echa mucho de menos a su hijo, pero que no sabe verlo por el móvil."},{"zh":"小平叫来了安安，他们一起去李奶奶家。","pinyin":"Xiǎopíng jiào lái le Ān''ān, tāmen yìqǐ qù Lǐ nǎinai jiā.","es":"Xiaoping llamó a Anan y fueron juntos a casa de la abuela Li."},{"zh":"李奶奶家不大，桌子上有很多她儿子的书。","pinyin":"Lǐ nǎinai jiā bú dà, zhuōzi shàng yǒu hěn duō tā érzi de shū.","es":"La casa de la abuela Li no es grande; en la mesa hay muchos libros de su hijo."},{"zh":"安安拿着手机，教李奶奶怎么给儿子打电话。","pinyin":"Ān''ān ná zhe shǒujī, jiāo Lǐ nǎinai zěnme gěi érzi dǎdiànhuà.","es":"Anan cogió el móvil y le enseñó a la abuela Li a llamar a su hijo."},{"zh":"李奶奶看看手机，再看看安安，学得很慢。","pinyin":"Lǐ nǎinai kàn kàn shǒujī, zài kàn kàn Ān''ān, xué de hěn màn.","es":"La abuela Li miraba el móvil y luego a Anan, aprendiendo despacio."},{"zh":"半个小时后，她在手机上看见了儿子。","pinyin":"Bàn gè xiǎoshí hòu, tā zài shǒujī shàng kànjiàn le érzi.","es":"Media hora después, vio a su hijo en el móvil."},{"zh":"李奶奶笑了，她说已经一年没有见面了。","pinyin":"Lǐ nǎinai xiào le, tā shuō yǐjīng yì nián méiyǒu jiàn miàn le.","es":"La abuela Li sonrió; dijo que hacía ya un año que no se veían."},{"zh":"小平和安安都觉得很高兴。","pinyin":"Xiǎopíng hé Ān''ān dōu juéde hěn gāoxìng.","es":"Xiaoping y Anan se alegraron mucho."}]'::jsonb, '[{"prompt":"李奶奶为什么来找小平？","options":["想吃包子","不会在手机上跟儿子见面","身体不舒服"],"answer_index":1,"evidence_sentence":1},{"prompt":"谁教李奶奶打电话？","options":["安安","小平的妈妈","她儿子"],"answer_index":0,"evidence_sentence":4},{"prompt":"李奶奶和儿子多长时间没有见面了？","options":["一个星期","一个月","一年"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['周', '面', '见']::text[], '[{"code":"2.2.1","level":2},{"code":"2.7.7","level":2}]'::jsonb, 'neural', '[{"path":"media/2fbf14550b413cb6c6a46d1cf22d237bd7672e2059613abb42d2e6c761f79c14.m4a","duration_ms":2851},{"path":"media/5d22dc90f29f3cf9986d0d8a8d07619842211117e3e3eec648fca824985b2a62.m4a","duration_ms":4363},{"path":"media/3d435ae0eb0813fe33ccc41856ff7debf255628062229d36a4a65e7164448e6b.m4a","duration_ms":3907},{"path":"media/46078053b76abb9fe202f0a15cfea5fb6e538c214bf37067eadf9864c1288b17.m4a","duration_ms":3979},{"path":"media/2ba8c36d142397ccecbb993ea1dbc49e7b2a01de66b26c12e7e191b2f9859d4d.m4a","duration_ms":3979},{"path":"media/e64e6cdb0f38d12449960d3f364855a0b6c2884cb53bca20f1ceb6dda2b6aab8.m4a","duration_ms":4003},{"path":"media/202ce742b53d5e48b3d28e154a0646e6ea7745bc2dc94c476aa68def4d82477b.m4a","duration_ms":3475},{"path":"media/93e0b666688fe04a744b68f0da12c42b29cef9eb6531eaa5682bd27412adb4a7.m4a","duration_ms":3787},{"path":"media/724d851949239b8dbeb64643402a786834ff3ce3fde4385186af88ccc342bb8d.m4a","duration_ms":2683}]'::jsonb),
  ('vecinos-05-dinner', 2, 'dialogue', '李奶奶请吃饭', 'comunicación interpersonal', 'vecinos', 5, '[{"zh":"星期六晚上，李奶奶请小平和安安去她家吃饭。","pinyin":"Xīngqīliù wǎnshang, Lǐ nǎinai qǐng Xiǎopíng hé Ān''ān qù tā jiā chī fàn.","es":"El sábado por la noche, la abuela Li invitó a Xiaoping y a Anan a cenar en su casa."},{"zh":"李奶奶：你们帮了我很多，今天我给你们做面条儿。","pinyin":"Lǐ nǎinai: Nǐmen bāng le wǒ hěn duō, jīntiān wǒ gěi nǐmen zuò miàntiáor.","es":"Abuela Li: Me habéis ayudado mucho; hoy os hago fideos."},{"zh":"安安：太好了！李奶奶，您做的面条儿真好吃。","pinyin":"Ān''ān: Tài hǎo le! Lǐ nǎinai, nín zuò de miàntiáor zhēn hǎochī.","es":"Anan: ¡Estupendo! Abuela Li, sus fideos están buenísimos."},{"zh":"李奶奶：好吃就多吃一点儿。小平，你多高了？","pinyin":"Lǐ nǎinai: Hǎochī jiù duō chī yìdiǎnr. Xiǎopíng, nǐ duō gāo le?","es":"Abuela Li: Si están buenos, come un poco más. Xiaoping, ¿cuánto mides ya?"},{"zh":"小平：我现在有我爸爸那么高了。","pinyin":"Xiǎopíng: Wǒ xiànzài yǒu wǒ bàba nàme gāo le.","es":"Xiaoping: Ahora ya soy tan alto como mi padre."},{"zh":"李奶奶：我儿子十六岁时，也是那么高。","pinyin":"Lǐ nǎinai: Wǒ érzi shíliù suì shí, yě shì nàme gāo.","es":"Abuela Li: Mi hijo, a los dieciséis, también era así de alto."},{"zh":"安安：您的儿子什么时候回来？","pinyin":"Ān''ān: Nín de érzi shénme shíhou huílái?","es":"Anan: ¿Cuándo vuelve su hijo?"},{"zh":"李奶奶：下个月。他说要来谢谢你们。","pinyin":"Lǐ nǎinai: Xià gè yuè. Tā shuō yào lái xièxie nǐmen.","es":"Abuela Li: El mes que viene. Dice que quiere venir a daros las gracias."},{"zh":"小平：别这么说，我们住在一个楼里，就是一家人。","pinyin":"Xiǎopíng: Bié zhème shuō, wǒmen zhù zài yí gè lóu lǐ, jiù shì yì jiārén.","es":"Xiaoping: No diga eso; vivimos en el mismo edificio, somos como una familia."}]'::jsonb, '[{"prompt":"李奶奶给他们做了什么？","options":["包子","面条儿","饺子"],"answer_index":1,"evidence_sentence":1},{"prompt":"小平现在有多高？","options":["有他爸爸那么高","比他爸爸高","没有安安高"],"answer_index":0,"evidence_sentence":4},{"prompt":"李奶奶的儿子什么时候回来？","options":["明天","明年","下个月"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['时', '那么', '面条儿']::text[], '[{"code":"6.3.2","level":2},{"code":"2.8.3","level":2}]'::jsonb, 'neural', '[{"path":"media/e1f554d7f6a8b88d33bb14a00cde6563ab6d23160fcaaf82584606852edbb448.m4a","duration_ms":4363},{"path":"media/8b8ff222b865d798b1bfb3226bdea50787e59d3787772dd2e56ba937bf1b30a8.m4a","duration_ms":3667},{"path":"media/1fcdc27ec0722dc104e0ae667339a5284c0f281e796a846a9ee63d6acebd3f8a.m4a","duration_ms":4747},{"path":"media/fdd95771ea1a4e239fcb6b42faac671091ebe88d149d95d906d2e480ec2299a4.m4a","duration_ms":4171},{"path":"media/75f4c249a39662648105fdba1227b4a07f35f9cfba3192fda7347a3800fff291.m4a","duration_ms":2515},{"path":"media/35e572ce5cb4a1eebf659abdde676ab8f3ce07b572d90ffc25741737a168c5ad.m4a","duration_ms":3211},{"path":"media/29bee621146f0938b2e6cdf6328b4cc08143f0728fe2c86ff3d1bdb697396680.m4a","duration_ms":2587},{"path":"media/f2b37b4426eed09aab382e67e0b85a566af73117096451d30065c76914917677.m4a","duration_ms":3595},{"path":"media/2d459c4bee38512a2015a82a2abdc7439807173804bf9f58b1ad3eb0909fb1ce.m4a","duration_ms":4531}]'::jsonb),
  ('travel-01-asking-the-way', 2, 'dialogue', '在机场', 'lugares', 'viaje', 1, '[{"zh":"大山第一次来中国，小月去机场等他。","pinyin":"Dàshān dì yī cì lái Zhōngguó, Xiǎoyuè qù jīchǎng děng tā.","es":"Dashan viene a China por primera vez y Xiaoyue va al aeropuerto a esperarlo."},{"zh":"大山：喂，小月，我已经下飞机了！你在哪儿？","pinyin":"Dàshān: Wèi, Xiǎoyuè, wǒ yǐjīng xià fēijī le! Nǐ zài nǎr?","es":"Dashan: ¡Hola, Xiaoyue, ya he bajado del avión! ¿Dónde estás?"},{"zh":"小月：我在门口，你出来就能看见我。","pinyin":"Xiǎoyuè: Wǒ zài ménkǒu, nǐ chūlái jiù néng kànjiàn wǒ.","es":"Xiaoyue: Estoy en la salida; en cuanto salgas me verás."},{"zh":"大山：这里有很多门，是哪个门？","pinyin":"Dàshān: Zhèlǐ yǒu hěn duō mén, shì nǎge mén?","es":"Dashan: Aquí hay muchas puertas; ¿cuál es?"},{"zh":"小月：三号门。你往前走，三号门在右边。","pinyin":"Xiǎoyuè: Sān hào mén. Nǐ wǎng qián zǒu, sān hào mén zài yòubian.","es":"Xiaoyue: La puerta tres. Sigue recto; la puerta tres está a la derecha."},{"zh":"大山：好，我看见了，前面人很多。","pinyin":"Dàshān: Hǎo, wǒ kànjiàn le, qiánmiàn rén hěn duō.","es":"Dashan: Vale, ya la veo; delante hay mucha gente."},{"zh":"小月：我穿着红色的衣服，手里拿着一本书。","pinyin":"Xiǎoyuè: Wǒ chuān zhe hóngsè de yīfu, shǒu lǐ ná zhe yì běn shū.","es":"Xiaoyue: Llevo ropa roja y tengo un libro en la mano."},{"zh":"大山：我看见你了！小月，你好！","pinyin":"Dàshān: Wǒ kànjiàn nǐ le! Xiǎoyuè, nǐhǎo!","es":"Dashan: ¡Ya te veo! ¡Hola, Xiaoyue!"},{"zh":"小月：你好！这是你第几次坐飞机？","pinyin":"Xiǎoyuè: Nǐhǎo! Zhè shì nǐ dì jǐ cì zuò fēijī?","es":"Xiaoyue: ¡Hola! ¿Cuántas veces has volado en avión?"},{"zh":"大山：第二次，但是坐这么长时间是第一次。","pinyin":"Dàshān: Dì èr cì, dànshì zuò zhème cháng shíjiān shì dì yī cì.","es":"Dashan: Es la segunda, pero es la primera vez que vuelo tanto rato."}]'::jsonb, '[{"prompt":"小月在哪儿等大山？","options":["酒店","机场","车站"],"answer_index":1,"evidence_sentence":0},{"prompt":"三号门在哪边？","options":["右边","左边","后面"],"answer_index":0,"evidence_sentence":4},{"prompt":"小月穿着什么颜色的衣服？","options":["白色的","黑色的","红色的"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['机场', '前面', '右边']::text[], '[{"code":"1.1","level":2},{"code":"2.6.2","level":2}]'::jsonb, 'neural', '[{"path":"media/61a0ecb2d7eed3f8eca3552f3ab8b74cfa9e1f834086def36f99a892b04c29a8.m4a","duration_ms":3739},{"path":"media/ee6942bf0215a1ad675062ccc2c844eaff5e08bf09dfd05fc761d0d1eaed3a4e.m4a","duration_ms":4651},{"path":"media/cd62deffeb65ba834e743a8a71865880c6a65c802a41db90b2feee94a62fac93.m4a","duration_ms":3163},{"path":"media/d7f25c2f4c991c47c701e6835a5db5179d414aeaa364a0eee393deec4151f998.m4a","duration_ms":3355},{"path":"media/3ceed360a9a2cd65c65416001b5cad35af0841af369a528f3276e3431c235fd4.m4a","duration_ms":4363},{"path":"media/76da3a90683118d9d038902b7788b03621f7561ead5a10e7c20fb235e8490c7d.m4a","duration_ms":3619},{"path":"media/0bbdb27811788f90f07d54c31fd1136305689228262637d439d644c25532a145.m4a","duration_ms":3691},{"path":"media/4a285382838324cf1764863e2ba1f85a59cf507d63bbee929a0919bbf6258628.m4a","duration_ms":3907},{"path":"media/603071fd48334e7b38c841ea1eea07a4f6dae001dccd37195e976296acd89dba.m4a","duration_ms":3571},{"path":"media/ef08696fce9c041dad45ac2d5cc56793f33d19cf231e5b59e6e19bf7f40f796d.m4a","duration_ms":3763}]'::jsonb),
  ('viaje-02-hotel', 2, 'story', '酒店的房间', 'lugares', 'viaje', 2, '[{"zh":"从机场出来，他们坐地铁去酒店。","pinyin":"Cóng jīchǎng chūlái, tāmen zuò dìtiě qù jiǔdiàn.","es":"Al salir del aeropuerto, fueron en metro al hotel."},{"zh":"地铁很快，四十分钟就到了。","pinyin":"Dìtiě hěn kuài, sìshí fēnzhōng jiù dào le.","es":"El metro es muy rápido: en cuarenta minutos llegaron."},{"zh":"大山的房间在十八楼，房间不大，但是很舒服。","pinyin":"Dàshān de fángjiān zài shíbā lóu, fángjiān bú dà, dànshì hěn shūfu.","es":"La habitación de Dashan está en la planta dieciocho; no es grande, pero es muy cómoda."},{"zh":"他从房间里往下面看，下面是一个很大的大学。","pinyin":"Tā cóng fángjiān lǐ wǎng xiàmiàn kàn, xiàmiàn shì yí gè hěn dà de dàxué.","es":"Desde la habitación miró hacia abajo: abajo hay una universidad muy grande."},{"zh":"大学里有很多人，有的在跑步，有的在跳舞。","pinyin":"Dàxué lǐ yǒu hěn duō rén, yǒude zài pǎobù, yǒude zài tiàowǔ.","es":"En la universidad hay mucha gente: unos corren y otros bailan."},{"zh":"还有很多鸟在大学上面飞来飞去。","pinyin":"Hái yǒu hěn duō niǎo zài dàxué shàngmiàn fēi lái fēi qù.","es":"Además, muchos pájaros vuelan de un lado a otro por encima de la universidad."},{"zh":"大山说他从小就喜欢看鸟。","pinyin":"Dàshān shuō tā cóngxiǎo jiù xǐhuan kàn niǎo.","es":"Dashan dice que desde pequeño le gusta mirar los pájaros."},{"zh":"小月说明天早上可以下去走走，大学离酒店很近。","pinyin":"Xiǎoyuè shuō míngtiān zǎoshang kěyǐ xiàqù zǒu zǒu, dàxué lí jiǔdiàn hěn jìn.","es":"Xiaoyue dice que mañana por la mañana pueden bajar a pasear; la universidad está muy cerca del hotel."},{"zh":"那天晚上，大山很累，十点就睡觉了。","pinyin":"Nà tiān wǎnshang, Dàshān hěn lèi, shí diǎn jiù shuìjiào le.","es":"Aquella noche Dashan estaba muy cansado y a las diez ya se había dormido."}]'::jsonb, '[{"prompt":"他们怎么去酒店？","options":["坐出租车","坐地铁","走路"],"answer_index":1,"evidence_sentence":0},{"prompt":"从房间里往下面看，能看见什么？","options":["一个大学","一个机场","一个商场"],"answer_index":0,"evidence_sentence":3},{"prompt":"大山从小就喜欢做什么？","options":["跑步","跳舞","看鸟"],"answer_index":2,"evidence_sentence":6}]'::jsonb, array['下面', '鸟', '酒店']::text[], '[{"code":"5.4.2","level":2},{"code":"2.8.2","level":2}]'::jsonb, 'neural', '[{"path":"media/292c5570f4e6ae351167663f7135f4f9fd0f4b92949ece4bdf008f0f8684d942.m4a","duration_ms":3379},{"path":"media/cb4c7690cd9fb2085fcd7702d6b20a56304d4b8422901d881db54a51c8fb8118.m4a","duration_ms":2755},{"path":"media/9ba8012d09c024b168de56e74c3c29a548a7a2003e022b6ecc643eeb35557d29.m4a","duration_ms":4387},{"path":"media/9280881308c9a9fbbe741e59855258aea268c06bd5c644434038edcb83f0bd85.m4a","duration_ms":4267},{"path":"media/fff480cf67bc932500f3c190191ae2e2c953e96a0bffa5e56f74cb848c95d97b.m4a","duration_ms":4195},{"path":"media/82c062e32bc8b4178603c845b10bea88c0ad3f62619cfed773825797e054ddaa.m4a","duration_ms":3235},{"path":"media/d1383b1b0250e9a1b598115807773d5c901bd258b3e65d9216b3227a4e27eff5.m4a","duration_ms":2947},{"path":"media/0d70415c409fc2b3ea45c0c9e4ea1b22ccbc196f12470d0169dfd478625e1750.m4a","duration_ms":4267},{"path":"media/7aa2998f15571485ccce470393baad190934bbee032216af1fcbf4c609b0036e.m4a","duration_ms":3667}]'::jsonb),
  ('viaje-03-tall-building', 2, 'short_text', '上楼看看', 'lugares', 'viaje', 3, '[{"zh":"第二天，大山和小月去看这里最高的楼。","pinyin":"Dì èr tiān, Dàshān hé Xiǎoyuè qù kàn zhèlǐ zuì gāo de lóu.","es":"Al día siguiente, Dashan y Xiaoyue fueron a ver el edificio más alto de la ciudad."},{"zh":"楼下有很多人，他们在楼下等了二十分钟。","pinyin":"Lóu xià yǒu hěn duō rén, tāmen zài lóu xià děng le èrshí fēnzhōng.","es":"Abajo había mucha gente y esperaron veinte minutos."},{"zh":"门票一百二十块钱，有一点儿贵。","pinyin":"Ménpiào yìbǎi''èrshí kuài qián, yǒuyìdiǎnr guì.","es":"La entrada cuesta ciento veinte yuanes; es un poco cara."},{"zh":"他们很快就上去了。","pinyin":"Tāmen hěn kuài jiù shàngqù le.","es":"Subieron enseguida."},{"zh":"从上面往下看，下面的车和人都很小。","pinyin":"Cóng shàngmiàn wǎng xià kàn, xiàmiàn de chē hé rén dōu hěn xiǎo.","es":"Mirando hacia abajo desde arriba, los coches y la gente se ven muy pequeños."},{"zh":"大山说他没有看过这么高的楼。","pinyin":"Dàshān shuō tā méiyǒu kànguo zhème gāo de lóu.","es":"Dashan dice que nunca había visto un edificio tan alto."},{"zh":"他们在上面玩了两个小时。","pinyin":"Tāmen zài shàngmiàn wán le liǎng gè xiǎoshí.","es":"Estuvieron dos horas arriba."},{"zh":"下来后，他们去旁边的饭馆吃饭。","pinyin":"Xiàlái hòu, tāmen qù pángbiān de fànguǎn chī fàn.","es":"Después de bajar, fueron a comer al restaurante de al lado."},{"zh":"大山觉得门票虽然贵，但是很有意思。","pinyin":"Dàshān juéde ménpiào suīrán guì, dànshì hěn yǒuyìsi.","es":"A Dashan le pareció que, aunque la entrada era cara, valía mucho la pena."}]'::jsonb, '[{"prompt":"他们在楼下等了多长时间？","options":["十分钟","二十分钟","两个小时"],"answer_index":1,"evidence_sentence":1},{"prompt":"门票多少钱？","options":["一百二十块","二十块","一百块"],"answer_index":0,"evidence_sentence":2},{"prompt":"下来后，他们去哪儿了？","options":["酒店","机场","饭馆"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['门票', '上去', '下来']::text[], '[{"code":"5.4.4","level":2},{"code":"8.1","level":2},{"code":"7.1.2","level":2}]'::jsonb, 'neural', '[{"path":"media/9dffa4af215346bd4ec853158065880f8ac9c02be9c749fe6625b9e94741cae9.m4a","duration_ms":3859},{"path":"media/3f39fed3eeccff4fef9eb1cd4bd6e8ad005df4d548abc0c995b83673d3a251ab.m4a","duration_ms":4123},{"path":"media/1961a3916e0f91b5ffe4e24fac302fe7c732e3e35d6221d0f389b5230940f51d.m4a","duration_ms":3115},{"path":"media/28bbbe0f3de5d4c5f15e6e5dddd6cbfb6f5a80568cf90fe21d237794c1f5af17.m4a","duration_ms":2083},{"path":"media/9a1e486d9f38840d62fc9ded70ff3f52de2bdc476cdf9fe3535258f4ca84af6b.m4a","duration_ms":3643},{"path":"media/ea6544da31a54aef2b1e2bb8c0b9501971bc31a71c3f3552f182054587d0044e.m4a","duration_ms":3091},{"path":"media/a2dfe3e09a4dd54644e4c8bd7fb8d7a8624908d58f8a9c77786900bebe2c454d.m4a","duration_ms":2563},{"path":"media/8c125a4abeda904b373aeda8519b4022a1b5fe968aeb0304ebc1b981b1a9cea1.m4a","duration_ms":3115},{"path":"media/2994967261e9c720f5422408e08fd29c7b05d0c8dde88765e659e6b18f3f0162.m4a","duration_ms":3955}]'::jsonb),
  ('viaje-04-wrong-way', 2, 'dialogue', '走错路了', 'lugares', 'viaje', 4, '[{"zh":"下午，大山和小月去找小月说的那个饭馆。","pinyin":"Xiàwǔ, Dàshān hé Xiǎoyuè qù zhǎo Xiǎoyuè shuō de nàge fànguǎn.","es":"Por la tarde, Dashan y Xiaoyue van a buscar el restaurante del que habló Xiaoyue."},{"zh":"大山：小月，我们走了半个小时了，饭馆在哪儿？","pinyin":"Dàshān: Xiǎoyuè, wǒmen zǒu le bàn gè xiǎoshí le, fànguǎn zài nǎr?","es":"Dashan: Xiaoyue, llevamos media hora andando; ¿dónde está el restaurante?"},{"zh":"小月：手机上说就在前面，但是我没看见。","pinyin":"Xiǎoyuè: Shǒujī shàng shuō jiù zài qiánmiàn, dànshì wǒ méi kànjiàn.","es":"Xiaoyue: El móvil dice que está justo delante, pero no lo veo."},{"zh":"大山：我们是不是走错路了？","pinyin":"Dàshān: Wǒmen shì bu shì zǒu cuò lù le?","es":"Dashan: ¿No nos habremos equivocado de camino?"},{"zh":"小月：可能是，因为我们在那个路口往左走了。","pinyin":"Xiǎoyuè: Kěnéng shì, yīnwèi wǒmen zài nàge lù kǒu wǎng zuǒ zǒu le.","es":"Xiaoyue: Puede ser, porque en aquel cruce giramos a la izquierda."},{"zh":"大山：那我们回去吧。","pinyin":"Dàshān: Nà wǒmen huíqù ba.","es":"Dashan: Entonces volvamos."},{"zh":"小月：别回去，你看，手机上说往右走，过去就是。","pinyin":"Xiǎoyuè: Bié huíqù, nǐ kàn, shǒujī shàng shuō wǎng yòu zǒu, guòqù jiù shì.","es":"Xiaoyue: No volvamos; mira, el móvil dice que giremos a la derecha y que está justo al cruzar."},{"zh":"大山：真的！饭馆就在右边，门口有很多人。","pinyin":"Dàshān: Zhēn de! Fànguǎn jiù zài yòubian, ménkǒu yǒu hěn duō rén.","es":"Dashan: ¡Es verdad! El restaurante está a la derecha y hay mucha gente en la puerta."},{"zh":"小月：太好了，我们进去吧，我想吃饭了。","pinyin":"Xiǎoyuè: Tài hǎo le, wǒmen jìnqù ba, wǒ xiǎng chī fàn le.","es":"Xiaoyue: ¡Estupendo, entremos! Ya tengo ganas de comer."}]'::jsonb, '[{"prompt":"他们走了多长时间？","options":["十分钟","半个小时","两个小时"],"answer_index":1,"evidence_sentence":1},{"prompt":"他们为什么走错了？","options":["在路口往左走了","没有手机","下雨了"],"answer_index":0,"evidence_sentence":4},{"prompt":"饭馆在哪边？","options":["左边","后面","右边"],"answer_index":2,"evidence_sentence":7}]'::jsonb, array['过去', '右', '回去']::text[], '[{"code":"2.8.4","level":2},{"code":"2.7.5","level":2}]'::jsonb, 'neural', '[{"path":"media/8d4909adb6e21780b62d0255888e7d4f7fe374b5537054595967c4de660ac388.m4a","duration_ms":4075},{"path":"media/32590bbaf5821ff6f4b3dfbaecb528fed1d88bc0b20544983235ec39cc4e8435.m4a","duration_ms":4459},{"path":"media/75e419fc5a7c9617bccd096c12b2ae20433accc5d186a95407760e9d18b96bab.m4a","duration_ms":3787},{"path":"media/003986f8eb12fc9adb3295f3fc45525c734908afa8bc6e7e09479c278e501ff1.m4a","duration_ms":2635},{"path":"media/d7d3b608cc4aea3217b5f1f3c0518290f19bfeb1e958847ba9014855b682b901.m4a","duration_ms":3835},{"path":"media/00d345bd5f264b102f58234ed554194addcdd61697698b443f44c621433c01a0.m4a","duration_ms":2155},{"path":"media/79c3a05c53bb65825bdf6afeae8390971a6c2b781553a06593afb119ba4f2288.m4a","duration_ms":4771},{"path":"media/a7058b6800f192b9173240dbcb3bc8adf38216cd5ce20faf43447cdb8a02a13e.m4a","duration_ms":5011},{"path":"media/ce29dcfd10b8c3f9356d9afe21bf9133f04c504e72b68d81ca32e56374b1c81f.m4a","duration_ms":3475}]'::jsonb),
  ('viaje-05-last-day', 2, 'story', '最后一天', 'lugares', 'viaje', 5, '[{"zh":"大山在中国住了一个星期。","pinyin":"Dàshān zài Zhōngguó zhù le yí gè xīngqī.","es":"Dashan pasó una semana en China."},{"zh":"这几天，他跟小月去了很多商场和饭馆。","pinyin":"Zhè jǐ tiān, tā gēn Xiǎoyuè qù le hěn duō shāngchǎng hé fànguǎn.","es":"Estos días fue con Xiaoyue a muchos centros comerciales y restaurantes."},{"zh":"他们有时坐地铁，有时走路。","pinyin":"Tāmen yǒushí zuò dìtiě, yǒushí zǒulù.","es":"A veces iban en metro y a veces a pie."},{"zh":"大山最喜欢酒店下面的那个大学，他每天早上都去那里走路。","pinyin":"Dàshān zuì xǐhuan jiǔdiàn xiàmiàn de nàge dàxué, tā měi tiān zǎoshang dōu qù nàlǐ zǒulù.","es":"Lo que más le gustó a Dashan fue la universidad de debajo del hotel; iba a pasear allí todas las mañanas."},{"zh":"最后一天，他给家人买了茶和衣服。","pinyin":"Zuì hòu yì tiān, tā gěi jiārén mǎi le chá hé yīfu.","es":"El último día compró té y ropa para su familia."},{"zh":"下午，小月送他去机场。","pinyin":"Xiàwǔ, Xiǎoyuè sòng tā qù jīchǎng.","es":"Por la tarde, Xiaoyue lo acompañó al aeropuerto."},{"zh":"在机场，大山说他很喜欢中国，明年还想来。","pinyin":"Zài jīchǎng, Dàshān shuō tā hěn xǐhuan Zhōngguó, míngnián hái xiǎng lái.","es":"En el aeropuerto, Dashan dijo que le gusta mucho China y que el año que viene quiere volver."},{"zh":"小月说她希望大山明年再来。","pinyin":"Xiǎoyuè shuō tā xīwàng Dàshān míngnián zài lái.","es":"Xiaoyue dijo que espera que Dashan vuelva el año que viene."},{"zh":"大山进去后，小月一个人坐地铁回家了。","pinyin":"Dàshān jìnqù hòu, Xiǎoyuè yī gè rén zuò dìtiě huí jiā le.","es":"Después de que Dashan entrara, Xiaoyue volvió sola a casa en metro."}]'::jsonb, '[{"prompt":"大山在中国住了多长时间？","options":["一个月","一个星期","两天"],"answer_index":1,"evidence_sentence":0},{"prompt":"大山最喜欢哪儿？","options":["酒店下面的大学","机场","商场"],"answer_index":0,"evidence_sentence":3},{"prompt":"最后一天，大山给家人买了什么？","options":["手表和书","鱼和肉","茶和衣服"],"answer_index":2,"evidence_sentence":4}]'::jsonb, array['有时', '送', '进去']::text[], '[{"code":"2.9.1","level":2},{"code":"2.10.2","level":2}]'::jsonb, 'neural', '[{"path":"media/72804ee489c591a8ccda907558078