values
  (2, 'A', '{"code":"A","level":2,"groups":[{"slug":"a-l1-01","part":"L1","example":{"audio":[{"zh":"我坐飞机去中国。","pinyin":"Wǒ zuò fēijī qù Zhōngguó.","speaker":"F"}],"images":["plane","train","bike"],"answer":0},"items":[{"audio":[{"zh":"我很喜欢喝咖啡。","pinyin":"Wǒ hěn xǐhuan hē kāfēi.","speaker":"M"}],"images":["tea","coffee","milk"],"answer":1},{"audio":[{"zh":"现在九点了，我们走吧。","pinyin":"Xiànzài jiǔ diǎn le, wǒmen zǒu ba.","speaker":"F"}],"images":["clock-3","clock-6","clock-9"],"answer":2},{"audio":[{"zh":"这是我家的狗。","pinyin":"Zhè shì wǒ jiā de gǒu.","speaker":"M"}],"images":["cat","dog","fish"],"answer":1},{"audio":[{"zh":"今天下雨了，你别出去了。","pinyin":"Jīntiān xià yǔ le, nǐ bié chūqù le.","speaker":"F"}],"images":["rain","sun","snow"],"answer":0},{"audio":[{"zh":"他每天早上都去跑步。","pinyin":"Tā měi tiān zǎoshang dōu qù pǎobù.","speaker":"M"}],"images":["run","ball","sleep"],"answer":0}]},{"slug":"a-l2-01","part":"L2","images":["phone","book","apple","hospital","computer","bed"],"example":{"stimulus":[{"zh":"你在做什么呢？","pinyin":"Nǐ zài zuò shénme ne?","speaker":"M"},{"zh":"我在给妈妈打电话。","pinyin":"Wǒ zài gěi māma dǎ diànhuà.","speaker":"F"}],"answer":0},"items":[{"audio":[{"zh":"你下午去哪儿？","pinyin":"Nǐ xiàwǔ qù nǎr?","speaker":"M"},{"zh":"我身体不舒服，要去医院。","pinyin":"Wǒ shēntǐ bù shūfu, yào qù yīyuàn.","speaker":"F"}],"answer":3},{"audio":[{"zh":"你想吃什么？","pinyin":"Nǐ xiǎng chī shénme?","speaker":"F"},{"zh":"给我一个苹果吧。","pinyin":"Gěi wǒ yí gè píngguǒ ba.","speaker":"M"}],"answer":2},{"audio":[{"zh":"你昨天晚上几点睡觉的？","pinyin":"Nǐ zuótiān wǎnshang jǐ diǎn shuìjiào de?","speaker":"M"},{"zh":"十一点，我太累了。","pinyin":"Shíyī diǎn, wǒ tài lèi le.","speaker":"F"}],"answer":5},{"audio":[{"zh":"这本书怎么样？","pinyin":"Zhè běn shū zěnmeyàng?","speaker":"F"},{"zh":"很好看，我看了两次。","pinyin":"Hěn hǎokàn, wǒ kàn le liǎng cì.","speaker":"M"}],"answer":1},{"audio":[{"zh":"你在电脑上看什么？","pinyin":"Nǐ zài diànnǎo shàng kàn shénme?","speaker":"M"},{"zh":"看明天的天气。","pinyin":"Kàn míngtiān de tiānqì.","speaker":"F"}],"answer":4}]},{"slug":"a-l2-02","part":"L2","images":["gift","flower","taxi","shirt","tv"],"items":[{"audio":[{"zh":"这是送给你的。","pinyin":"Zhè shì sòng gěi nǐ de.","speaker":"F"},{"zh":"谢谢！是什么东西？","pinyin":"Xièxie! Shì shénme dōngxi?","speaker":"M"}],"answer":0},{"audio":[{"zh":"这些花真漂亮！","pinyin":"Zhèxiē huā zhēn piàoliang!","speaker":"M"},{"zh":"是我朋友送的。","pinyin":"Shì wǒ péngyou sòng de.","speaker":"F"}],"answer":1},{"audio":[{"zh":"我们怎么去火车站？","pinyin":"Wǒmen zěnme qù huǒchē zhàn?","speaker":"F"},{"zh":"太远了，坐出租车吧。","pinyin":"Tài yuǎn le, zuò chūzūchē ba.","speaker":"M"}],"answer":2},{"audio":[{"zh":"这件衣服怎么样？","pinyin":"Zhè jiàn yīfu zěnmeyàng?","speaker":"M"},{"zh":"颜色很好，就是有点儿贵。","pinyin":"Yánsè hěn hǎo, jiù shì yǒudiǎnr guì.","speaker":"F"}],"answer":3},{"audio":[{"zh":"晚上你做什么？","pinyin":"Wǎnshang nǐ zuò shénme?","speaker":"F"},{"zh":"在家看电视。","pinyin":"Zài jiā kàn diànshì.","speaker":"M"}],"answer":4}]},{"slug":"a-l3-01","part":"L3","example":{"audio":[{"zh":"你明天几点来？","pinyin":"Nǐ míngtiān jǐ diǎn lái?","speaker":"M"},{"zh":"上午十点吧。","pinyin":"Shàngwǔ shí diǎn ba.","speaker":"F"}],"question":{"zh":"女的明天几点来？","pinyin":"Nǚ de míngtiān jǐ diǎn lái?","speaker":"M"},"options":[{"zh":"十点","pinyin":"Shí diǎn"},{"zh":"九点","pinyin":"Jiǔ diǎn"},{"zh":"十一点","pinyin":"Shíyī diǎn"}],"answer":0},"items":[{"audio":[{"zh":"你去商店买什么？","pinyin":"Nǐ qù shāngdiàn mǎi shénme?","speaker":"F"},{"zh":"买水果和牛奶。","pinyin":"Mǎi shuǐguǒ hé niúnǎi.","speaker":"M"}],"question":{"zh":"男的要买什么？","pinyin":"Nán de yào mǎi shénme?","speaker":"F"},"options":[{"zh":"水果和牛奶","pinyin":"Shuǐguǒ hé niúnǎi"},{"zh":"衣服","pinyin":"Yīfu"},{"zh":"电脑","pinyin":"Diànnǎo"}],"answer":0},{"audio":[{"zh":"你哥哥是做什么工作的？","pinyin":"Nǐ gēge shì zuò shénme gōngzuò de?","speaker":"M"},{"zh":"他是医生，在医院工作。","pinyin":"Tā shì yīshēng, zài yīyuàn gōngzuò.","speaker":"F"}],"question":{"zh":"她哥哥做什么工作？","pinyin":"Tā gēge zuò shénme gōngzuò?","speaker":"M"},"options":[{"zh":"老师","pinyin":"Lǎoshī"},{"zh":"医生","pinyin":"Yīshēng"},{"zh":"学生","pinyin":"Xuésheng"}],"answer":1},{"audio":[{"zh":"你怎么不吃了？","pinyin":"Nǐ zěnme bù chī le?","speaker":"F"},{"zh":"我已经吃了很多了。","pinyin":"Wǒ yǐjīng chī le hěn duō le.","speaker":"M"}],"question":{"zh":"男的为什么不吃了？","pinyin":"Nán de wèi shénme bù chī le?","speaker":"F"},"options":[{"zh":"不好吃","pinyin":"Bù hǎochī"},{"zh":"吃了很多","pinyin":"Chī le hěn duō"},{"zh":"没有时间","pinyin":"Méiyǒu shíjiān"}],"answer":1},{"audio":[{"zh":"今天星期几？","pinyin":"Jīntiān xīngqī jǐ?","speaker":"M"},{"zh":"星期五，明天就可以休息了。","pinyin":"Xīngqī wǔ, míngtiān jiù kěyǐ xiūxi le.","speaker":"F"}],"question":{"zh":"今天星期几？","pinyin":"Jīntiān xīngqī jǐ?","speaker":"M"},"options":[{"zh":"星期四","pinyin":"Xīngqī sì"},{"zh":"星期五","pinyin":"Xīngqī wǔ"},{"zh":"星期六","pinyin":"Xīngqī liù"}],"answer":1},{"audio":[{"zh":"你的汉语说得真好！","pinyin":"Nǐ de Hànyǔ shuō de zhēn hǎo!","speaker":"F"},{"zh":"谢谢，我学了三年了。","pinyin":"Xièxie, wǒ xué le sān nián le.","speaker":"M"}],"question":{"zh":"男的学汉语多长时间了？","pinyin":"Nán de xué Hànyǔ duō cháng shíjiān le?","speaker":"F"},"options":[{"zh":"一年","pinyin":"Yì nián"},{"zh":"两年","pinyin":"Liǎng nián"},{"zh":"三年","pinyin":"Sān nián"}],"answer":2},{"audio":[{"zh":"喂，你在哪儿呢？","pinyin":"Wèi, nǐ zài nǎr ne?","speaker":"M"},{"zh":"我在学校门口等你。","pinyin":"Wǒ zài xuéxiào ménkǒu děng nǐ.","speaker":"F"}],"question":{"zh":"女的在哪儿？","pinyin":"Nǚ de zài nǎr?","speaker":"M"},"options":[{"zh":"学校门口","pinyin":"Xuéxiào ménkǒu"},{"zh":"家里","pinyin":"Jiā lǐ"},{"zh":"商店里","pinyin":"Shāngdiàn lǐ"}],"answer":0},{"audio":[{"zh":"你喜欢什么颜色？","pinyin":"Nǐ xǐhuan shénme yánsè?","speaker":"F"},{"zh":"我最喜欢红色。","pinyin":"Wǒ zuì xǐhuan hóngsè.","speaker":"M"}],"question":{"zh":"男的喜欢什么颜色？","pinyin":"Nán de xǐhuan shénme yánsè?","speaker":"F"},"options":[{"zh":"白色","pinyin":"Báisè"},{"zh":"黑色","pinyin":"Hēisè"},{"zh":"红色","pinyin":"Hóngsè"}],"answer":2},{"audio":[{"zh":"外面冷吗？","pinyin":"Wàimiàn lěng ma?","speaker":"M"},{"zh":"很冷，你要多穿衣服。","pinyin":"Hěn lěng, nǐ yào duō chuān yīfu.","speaker":"F"}],"question":{"zh":"外面天气怎么样？","pinyin":"Wàimiàn tiānqì zěnmeyàng?","speaker":"M"},"options":[{"zh":"很热","pinyin":"Hěn rè"},{"zh":"很冷","pinyin":"Hěn lěng"},{"zh":"下雨了","pinyin":"Xià yǔ le"}],"answer":1},{"audio":[{"zh":"这件事你告诉妈妈了吗？","pinyin":"Zhè jiàn shì nǐ gàosu māma le ma?","speaker":"F"},{"zh":"还没有，我晚上告诉她。","pinyin":"Hái méiyǒu, wǒ wǎnshang gàosu tā.","speaker":"M"}],"question":{"zh":"男的什么时候告诉妈妈？","pinyin":"Nán de shénme shíhou gàosu māma?","speaker":"F"},"options":[{"zh":"晚上","pinyin":"Wǎnshang"},{"zh":"早上","pinyin":"Zǎoshang"},{"zh":"中午","pinyin":"Zhōngwǔ"}],"answer":0},{"audio":[{"zh":"我们走路去吧，不远。","pinyin":"Wǒmen zǒulù qù ba, bù yuǎn.","speaker":"M"},{"zh":"好，十分钟就到了。","pinyin":"Hǎo, shí fēnzhōng jiù dào le.","speaker":"F"}],"question":{"zh":"他们怎么去？","pinyin":"Tāmen zěnme qù?","speaker":"M"},"options":[{"zh":"走路","pinyin":"Zǒulù"},{"zh":"坐车","pinyin":"Zuò chē"},{"zh":"坐飞机","pinyin":"Zuò fēijī"}],"answer":0}]},{"slug":"a-r1-01","part":"R1","images":["swim","dance","write","breakfast","clock-12","umbrella"],"example":{"stimulus":{"zh":"我每个星期都去游泳。","pinyin":"Wǒ měi gè xīngqī dōu qù yóuyǒng."},"answer":0},"items":[{"text":{"zh":"她很喜欢跳舞。","pinyin":"Tā hěn xǐhuan tiàowǔ."},"answer":1},{"text":{"zh":"弟弟在写汉字。","pinyin":"Dìdi zài xiě Hànzì."},"answer":2},{"text":{"zh":"早上我喝牛奶，吃鸡蛋。","pinyin":"Zǎoshang wǒ hē niúnǎi, chī jīdàn."},"answer":3},{"text":{"zh":"中午十二点了，我们去吃饭吧。","pinyin":"Zhōngwǔ shí''èr diǎn le, wǒmen qù chī fàn ba."},"answer":4},{"text":{"zh":"下雨了，我们快回家吧。","pinyin":"Xià yǔ le, wǒmen kuài huí jiā ba."},"answer":5}]},{"slug":"a-r2-01","part":"R2","bank":[{"zh":"已经","pinyin":"Yǐjīng"},{"zh":"离","pinyin":"Lí"},{"zh":"一起","pinyin":"Yìqǐ"},{"zh":"准备","pinyin":"Zhǔnbèi"},{"zh":"因为","pinyin":"Yīnwèi"},{"zh":"再","pinyin":"Zài"}],"example":{"text":{"zh":"我（ ）吃过饭了。","pinyin":"Wǒ chī guo fàn le."},"answer":0},"items":[{"text":{"zh":"我家（ ）学校很近。","pinyin":"Wǒ jiā xuéxiào hěn jìn."},"answer":1},{"text":{"zh":"明天我们（ ）去看电影吧。","pinyin":"Míngtiān wǒmen qù kàn diànyǐng ba."},"answer":2},{"text":{"zh":"你（ ）好了吗？我们要走了。","pinyin":"Nǐ hǎo le ma? Wǒmen