  (2, 'B', '{"code":"B","level":2,"groups":[{"slug":"b-l1-01","part":"L1","example":{"audio":[{"zh":"今天是晴天，天气很好。","pinyin":"Jīntiān shì qíng tiān, tiānqì hěn hǎo.","speaker":"M"}],"images":["sun","rain","snow"],"answer":0},"items":[{"audio":[{"zh":"这是爸爸送给我的手表。","pinyin":"Zhè shì bàba sòng gěi wǒ de shǒubiǎo.","speaker":"F"}],"images":["watch","phone","computer"],"answer":0},{"audio":[{"zh":"我每天早上七点起床。","pinyin":"Wǒ měi tiān zǎoshang qī diǎn qǐchuáng.","speaker":"M"}],"images":["clock-12","clock-7","clock-3"],"answer":1},{"audio":[{"zh":"我女儿很喜欢小猫。","pinyin":"Wǒ nǚ''ér hěn xǐhuan xiǎo māo.","speaker":"F"}],"images":["cat","fish","dog"],"answer":0},{"audio":[{"zh":"晚饭我想吃米饭。","pinyin":"Wǎnfàn wǒ xiǎng chī mǐfàn.","speaker":"M"}],"images":["apple","breakfast","rice"],"answer":2},{"audio":[{"zh":"妈妈正在做饭呢。","pinyin":"Māma zhèngzài zuò fàn ne.","speaker":"F"}],"images":["read","sing","cook"],"answer":2}]},{"slug":"b-l2-01","part":"L2","images":["call","money","medicine","ball","shop","door"],"example":{"stimulus":[{"zh":"你在给谁打电话？","pinyin":"Nǐ zài gěi shéi dǎ diànhuà?","speaker":"M"},{"zh":"给我姐姐。","pinyin":"Gěi wǒ jiějie.","speaker":"F"}],"answer":0},"items":[{"audio":[{"zh":"这个多少钱？","pinyin":"Zhège duōshao qián?","speaker":"F"},{"zh":"二十块钱。","pinyin":"Èrshí kuài qián.","speaker":"M"}],"answer":1},{"audio":[{"zh":"你生病了吗？","pinyin":"Nǐ shēngbìng le ma?","speaker":"M"},{"zh":"是的，医生让我每天吃药。","pinyin":"Shì de, yīshēng ràng wǒ měi tiān chī yào.","speaker":"F"}],"answer":2},{"audio":[{"zh":"你喜欢什么运动？","pinyin":"Nǐ xǐhuan shénme yùndòng?","speaker":"F"},{"zh":"我最喜欢踢足球。","pinyin":"Wǒ zuì xǐhuan tī zúqiú.","speaker":"M"}],"answer":3},{"audio":[{"zh":"我们去商店买东西吧。","pinyin":"Wǒmen qù shāngdiàn mǎi dōngxi ba.","speaker":"M"},{"zh":"好，我也要买一些水果。","pinyin":"Hǎo, wǒ yě yào mǎi yìxiē shuǐguǒ.","speaker":"F"}],"answer":4},{"audio":[{"zh":"请开一下门，好吗？","pinyin":"Qǐng kāi yíxià mén, hǎo ma?","speaker":"F"},{"zh":"好的，你等一下。","pinyin":"Hǎo de, nǐ děng yíxià.","speaker":"M"}],"answer":5}]},{"slug":"b-l2-02","part":"L2","images":["cake","bus","chair","tea","plane"],"items":[{"audio":[{"zh":"生日快乐！","pinyin":"Shēngrì kuàilè!","speaker":"M"},{"zh":"谢谢你！你还记得我的生日。","pinyin":"Xièxie nǐ! Nǐ hái jìde wǒ de shēngrì.","speaker":"F"}],"answer":0},{"audio":[{"zh":"你每天怎么去公司？","pinyin":"Nǐ měi tiān zěnme qù gōngsī?","speaker":"F"},{"zh":"坐车去，车上人很多。","pinyin":"Zuò chē qù, chē shàng rén hěn duō.","speaker":"M"}],"answer":1},{"audio":[{"zh":"请坐，请坐！","pinyin":"Qǐng zuò, qǐng zuò!","speaker":"M"},{"zh":"谢谢，你家真大。","pinyin":"Xièxie, nǐ jiā zhēn dà.","speaker":"F"}],"answer":2},{"audio":[{"zh":"你想喝点什么？","pinyin":"Nǐ xiǎng hē diǎn shénme?","speaker":"F"},{"zh":"我想喝茶。","pinyin":"Wǒ xiǎng hē chá.","speaker":"M"}],"answer":3},{"audio":[{"zh":"你什么时候去中国？","pinyin":"Nǐ shénme shíhou qù Zhōngguó?","speaker":"M"},{"zh":"下个星期，我已经买了机票。","pinyin":"Xià gè xīngqī, wǒ yǐjīng mǎi le jīpiào.","speaker":"F"}],"answer":4}]},{"slug":"b-l3-01","part":"L3","example":{"audio":[{"zh":"你几点下班？","pinyin":"Nǐ jǐ diǎn xiàbān?","speaker":"F"},{"zh":"下午五点半。","pinyin":"Xiàwǔ wǔ diǎn bàn.","speaker":"M"}],"question":{"zh":"男的几点下班？","pinyin":"Nán de jǐ diǎn xiàbān?","speaker":"F"},"options":[{"zh":"五点半","pinyin":"Wǔ diǎn bàn"},{"zh":"五点","pinyin":"Wǔ diǎn"},{"zh":"六点","pinyin":"Liù diǎn"}],"answer":0},"items":[{"audio":[{"zh":"你女儿多大了？","pinyin":"Nǐ nǚ''ér duō dà le?","speaker":"M"},{"zh":"她今年七岁，上小学了。","pinyin":"Tā jīnnián qī suì, shàng xiǎoxué le.","speaker":"F"}],"question":{"zh":"她女儿多大了？","pinyin":"Tā nǚ''ér duō dà le?","speaker":"M"},"options":[{"zh":"五岁","pinyin":"Wǔ suì"},{"zh":"六岁","pinyin":"Liù suì"},{"zh":"七岁","pinyin":"Qī suì"}],"answer":2},{"audio":[{"zh":"你喜欢吃什么水果？","pinyin":"Nǐ xǐhuan chī shénme shuǐguǒ?","speaker":"F"},{"zh":"我最喜欢吃苹果。","pinyin":"Wǒ zuì xǐhuan chī píngguǒ.","speaker":"M"}],"question":{"zh":"男的喜欢什么水果？","pinyin":"Nán de xǐhuan shénme shuǐguǒ?","speaker":"F"},"options":[{"zh":"苹果","pinyin":"Píngguǒ"},{"zh":"牛奶","pinyin":"Niúnǎi"},{"zh":"鸡蛋","pinyin":"Jīdàn"}],"answer":0},{"audio":[{"zh":"你怎么还没睡觉？","pinyin":"Nǐ zěnme hái méi shuìjiào?","speaker":"M"},{"zh":"明天有考试，我在准备呢。","pinyin":"Míngtiān yǒu kǎoshì, wǒ zài zhǔnbèi ne.","speaker":"F"}],"question":{"zh":"女的为什么还没睡觉？","pinyin":"Nǚ de wèi shénme hái méi shuìjiào?","speaker":"M"},"options":[{"zh":"在看电视","pinyin":"Zài kàn diànshì"},{"zh":"明天考试","pinyin":"Míngtiān kǎoshì"},{"zh":"身体不好","pinyin":"Shēntǐ bù hǎo"}],"answer":1},{"audio":[{"zh":"这个房间怎么样？","pinyin":"Zhège fángjiān zěnmeyàng?","speaker":"F"},{"zh":"很大，但是有点儿贵。","pinyin":"Hěn dà, dànshì yǒudiǎnr guì.","speaker":"M"}],"question":{"zh":"男的觉得房间怎么样？","pinyin":"Nán de juéde fángjiān zěnmeyàng?","speaker":"F"},"options":[{"zh":"很小","pinyin":"Hěn xiǎo"},{"zh":"很便宜","pinyin":"Hěn piányi"},{"zh":"有点儿贵","pinyin":"Yǒudiǎnr guì"}],"answer":2},{"audio":[{"zh":"你昨天去哪儿了？","pinyin":"Nǐ zuótiān qù nǎr le?","speaker":"M"},{"zh":"我和朋友去看电影了。","pinyin":"Wǒ hé péngyou qù kàn diànyǐng le.","speaker":"F"}],"question":{"zh":"女的昨天做什么了？","pinyin":"Nǚ de zuótiān zuò shénme le?","speaker":"M"},"options":[{"zh":"看电影","pinyin":"Kàn diànyǐng"},{"zh":"去商店","pinyin":"Qù shāngdiàn"},{"zh":"去医院","pinyin":"Qù yīyuàn"}],"answer":0},{"audio":[{"zh":"你的手机呢？","pinyin":"Nǐ de shǒujī ne?","speaker":"F"},{"zh":"我忘在家里了。","pinyin":"Wǒ wàng zài jiā lǐ le.","speaker":"M"}],"question":{"zh":"男的手机在哪儿？","pinyin":"Nán de shǒujī zài nǎr?","speaker":"F"},"options":[{"zh":"在公司","pinyin":"Zài gōngsī"},{"zh":"在家里","pinyin":"Zài jiā lǐ"},{"zh":"在学校","pinyin":"Zài xuéxiào"}],"answer":1},{"audio":[{"zh":"我们几点在哪儿见？","pinyin":"Wǒmen jǐ diǎn zài nǎr jiàn?","speaker":"M"},{"zh":"明天上午九点，在火车站。","pinyin":"Míngtiān shàngwǔ jiǔ diǎn, zài huǒchē zhàn.","speaker":"F"}],"question":{"zh":"他们在哪儿见？","pinyin":"Tāmen zài nǎr jiàn?","speaker":"M"},"options":[{"zh":"学校","pinyin":"Xuéxiào"},{"zh":"饭店","pinyin":"Fàndiàn"},{"zh":"火车站","pinyin":"Huǒchē zhàn"}],"answer":2},{"audio":[{"zh":"你哥哥会说汉语吗？","pinyin":"Nǐ gēge huì shuō Hànyǔ ma?","speaker":"F"},{"zh":"会一点儿，他在学。","pinyin":"Huì yìdiǎnr, tā zài xué.","speaker":"M"}],"question":{"zh":"男的哥哥汉语说得怎么样？","pinyin":"Nán de gēge Hànyǔ shuō de zěnmeyàng?","speaker":"F"},"options":[{"zh":"会一点儿","pinyin":"Huì yìdiǎnr"},{"zh":"很好","pinyin":"Hěn hǎo"},{"zh":"不会","pinyin":"Bú huì"}],"answer":0},{"audio":[{"zh":"外面下雪了！","pinyin":"Wàimiàn xià xuě le!","speaker":"M"},{"zh":"真的？我们出去看看吧。","pinyin":"Zhēn de? Wǒmen chūqù kàn kàn ba.","speaker":"F"}],"question":{"zh":"外面天气怎么样？","pinyin":"Wàimiàn tiānqì zěnmeyàng?","speaker":"M"},"options":[{"zh":"下雨了","pinyin":"Xià yǔ le"},{"zh":"下雪了","pinyin":"Xià xuě le"},{"zh":"很热","pinyin":"Hěn rè"}],"answer":1},{"audio":[{"zh":"你认识那个人吗？","pinyin":"Nǐ rènshi nàge rén ma?","speaker":"F"},{"zh":"认识，他是我们的新老师。","pinyin":"Rènshi, tā shì wǒmen de xīn lǎoshī.","speaker":"M"}],"question":{"zh":"那个人是谁？","pinyin":"Nàge rén shì shéi?","speaker":"F"},"options":[{"zh":"新同学","pinyin":"Xīn tóngxué"},{"zh":"新医生","pinyin":"Xīn yīshēng"},{"zh":"新老师","pinyin":"Xīn lǎoshī"}],"answer":2}]},{"slug":"b-r1-01","part":"R1","images":["basketball","egg","house","tv","flower","run"],"example":{"stimulus":{"zh":"他们每天下午都打篮球。","pinyin":"Tāmen měi tiān xiàwǔ dōu dǎ lánqiú."},"answer":0},"items":[{"text":{"zh":"今天早上我吃了两个鸡蛋。","pinyin":"Jīntiān zǎoshang wǒ chī le liǎng gè jīdàn."},"answer":1},{"text":{"zh":"这是我的新家，你来看看吧。","pinyin":"Zhè shì wǒ de xīn jiā, nǐ lái kàn kàn ba."},"answer":2},{"text":{"zh":"爷爷每天晚上都看电视。","pinyin":"Yéye měi tiān wǎnshang dōu kàn diànshì."},"answer":3},{"text":{"zh":"这些花是我从商店买的。","pinyin":"Zhèxiē huā shì wǒ cóng shāngdiàn mǎi de."},"answer":4},{"text":{"zh":"跑了一个小时，我太累了。","pinyin":"Pǎo le yí gè xiǎoshí, wǒ tài lèi le."},"answer":5}]},{"slug":"b-r2-01","part":"R2","bank":[{"zh":"可能","pinyin":"Kěnéng"},{"zh":"还","pinyin":"Hái"},{"zh":"慢","pinyin":"Màn"},{"zh":"得","pinyin":"De"},{"zh":"经常","pinyin":"Jīngcháng"},{"zh":"觉得","pinyin":"Juéde"}],"example":{"text":{"zh":"明天（ ）会下雨，你别出去了。","pinyin":"Míngtiān huì xià yǔ, nǐ bié chūqù le."},"answer":0},"items":[{"text":{"zh":"已经十点了，他（ ）没起床。","pinyin":"Yǐjīng shí diǎn le, tā méi qǐchuáng."},"answer":1},{"text":{"zh":"你说得太快了，请说（ ）一点儿。","pinyin":"Nǐ shuō de tài kuài le, qǐng shuō yìdiǎnr."},"answer":2},{"text":{"zh":"她唱歌唱（ ）很好听。","pinyin":"Tā chàng gē chàng hěn hǎotīng."},"answer":3},{"text":{"zh":"我（ ）去那家饭店吃饭。","pinyin":"Wǒ qù nà jiā fàndiàn chī fàn."},"answer":4},{"text":{"zh":"A：这件衣服怎么样？B：我（ ）很漂亮。","pinyin":"A: Zhè jiàn yīfu zěnmeyàng? B: Wǒ hěn piàoliang."},"answer":5}]},{"slug":"b-r3-01","part":"R3","bank":[{"zh":"我也很高兴认识你。","pinyin":"Wǒ yě hěn gāoxìng rènshi nǐ."},{"zh":"明天见！","pinyin":"Míngtiān jiàn!"},{"zh":"坐飞机去。","pinyin":"Zuò fēijī qù."},{"zh":"不客气。","pinyin":"Bú kèqi."},{"zh":"她在房间里睡觉呢。","pinyin":"Tā zài fángjiān lǐ shuìjiào ne."},{"zh":"一个小时。","pinyin":"Yí gè xiǎoshí."}],"example":{"text":{"zh":"认识你很高兴。","pinyin":"Rènshi nǐ hěn gāoxìng."},"answer":0},"items":[{"text":{"zh":"我要走了，再见！","pinyin":"Wǒ yào zǒu le, zàijiàn!"},"answer":1},{"text":{"zh":"你怎么去中国？","pinyin":"Nǐ zěnme qù Zhōngguó?"},"answer":2},{"text":{"zh":"谢谢你帮我。","pinyin":"Xièxie nǐ bāng wǒ."},"answer":3},{"text":{"zh":"你妹妹呢？","pinyin":"Nǐ mèimei ne?"},"answer":4},{"text":{"zh":"你每天学习多长时间汉语？","pinyin":"Nǐ měi tiān xuéxí duō cháng shíjiān Hànyǔ?"},"answer":5}]},{"slug":"b-r3-02","part":"R3","bank":[{"zh":"有，你要几个？","pinyin":"Yǒu, nǐ yào jǐ gè?"},{"zh":"因为我生病了。","pinyin":"Yīnwèi wǒ shēngbìng le."},{"zh":"好啊，几点？","pinyin":"Hǎo a, jǐ diǎn?"},{"zh":"在那儿，门口旁边。","pinyin":"Zài nàr, ménkǒu pángbiān."},{"zh":"不是，是我同学的。","pinyin":"Bú shì, shì wǒ tóngxué de."}],"items":[{"text":{"zh":"明天晚上一起吃饭吧。","pinyin":"Míngtiān wǎnshang yìqǐ chī fàn ba."},"answer":2},{"text":{"zh":"请问，洗手间在哪儿？","pinyin":"Qǐngwèn, xǐshǒujiān zài nǎr?"},"answer":3},{"text":{"zh":"这是你的书吗？","pinyin":"Zhè shì nǐ de shū ma?"},"answer":4},{"text":{"zh":"还有电影票吗？","pinyin":"Hái yǒu diànyǐng piào ma?"},"answer":0},{"text":{"zh":"你昨天为什么没来上课？","pinyin":"Nǐ zuótiān wèi shénme méi lái shàngkè?"},"answer":1}]},{"slug":"b-r4-01","part":"R4","items":[{"passage":{"zh":"我姐姐是医生，她每天工作很忙，晚上九点回家。","pinyin":"Wǒ jiějie shì yīshēng, tā měi tiān gōngzuò hěn máng