  (2, 'C', '{"code":"C","level":2,"groups":[{"slug":"c-l1-01","part":"L1","example":{"audio":[{"zh":"我家有一只小狗。","pinyin":"Wǒ jiā yǒu yì zhī xiǎo gǒu.","speaker":"F"}],"images":["dog","cat","fish"],"answer":0},"items":[{"audio":[{"zh":"我们坐火车去吧。","pinyin":"Wǒmen zuò huǒchē qù ba.","speaker":"M"}],"images":["plane","bus","train"],"answer":2},{"audio":[{"zh":"电影晚上八点开始。","pinyin":"Diànyǐng wǎnshang bā diǎn kāishǐ.","speaker":"F"}],"images":["clock-8","clock-6","clock-12"],"answer":0},{"audio":[{"zh":"桌子上有两个鸡蛋。","pinyin":"Zhuōzi shàng yǒu liǎng gè jīdàn.","speaker":"M"}],"images":["apple","egg","rice"],"answer":1},{"audio":[{"zh":"外面雪下得很大。","pinyin":"Wàimiàn xuě xià de hěn dà.","speaker":"F"}],"images":["sun","rain","snow"],"answer":2},{"audio":[{"zh":"他在房间里唱歌。","pinyin":"Tā zài fángjiān lǐ chàng gē.","speaker":"M"}],"images":["sing","swim","cook"],"answer":0}]},{"slug":"c-l2-01","part":"L2","images":["house","watch","taxi","medicine","book","coffee"],"example":{"stimulus":[{"zh":"你家在哪儿？","pinyin":"Nǐ jiā zài nǎr?","speaker":"M"},{"zh":"就在前面，那个红色的就是。","pinyin":"Jiù zài qiánmiàn, nàge hóngsè de jiù shì.","speaker":"F"}],"answer":0},"items":[{"audio":[{"zh":"现在几点了？","pinyin":"Xiànzài jǐ diǎn le?","speaker":"F"},{"zh":"我看一下手表，十点二十。","pinyin":"Wǒ kàn yíxià shǒubiǎo, shí diǎn èrshí.","speaker":"M"}],"answer":1},{"audio":[{"zh":"我们怎么去医院？","pinyin":"Wǒmen zěnme qù yīyuàn?","speaker":"M"},{"zh":"打车吧，快一点儿。","pinyin":"Dǎchē ba, kuài yìdiǎnr.","speaker":"F"}],"answer":2},{"audio":[{"zh":"你生病了，要多喝水。","pinyin":"Nǐ shēngbìng le, yào duō hē shuǐ.","speaker":"F"},{"zh":"好的，我已经吃药了。","pinyin":"Hǎo de, wǒ yǐjīng chī yào le.","speaker":"M"}],"answer":3},{"audio":[{"zh":"你在读什么？","pinyin":"Nǐ zài dú shénme?","speaker":"M"},{"zh":"一本中文书，很有意思。","pinyin":"Yì běn Zhōngwén shū, hěn yǒu yìsi.","speaker":"F"}],"answer":4},{"audio":[{"zh":"早上你喝什么？","pinyin":"Zǎoshang nǐ hē shénme?","speaker":"F"},{"zh":"我每天早上都喝咖啡。","pinyin":"Wǒ měi tiān zǎoshang dōu hē kāfēi.","speaker":"M"}],"answer":5}]},{"slug":"c-l