insert into public.communicative_task (slug, hsk_level, situation_es, mode, intent, required_markers, min_chars, max_chars, model_answer)
values
  ('2-01-manana-antes-de-clase', 2, 'Un amigo te pregunta qué haces por las mañanas antes de ir a clase. Cuéntale dos cosas que haces y en qué orden.', 'write', array['contar al menos dos cosas que haces por la mañana', 'dejar claro en qué orden las haces']::text[], '[{"hsk_level":2,"code":"2.7.6"}]'::jsonb, 8, 40, '{"zh":"我每天早上吃完早饭，再坐公交车去学校。","pinyin":"Wǒ měitiān zǎoshang chī wán zǎofàn, zài zuò gōngjiāochē qù xuéxiào.","es":"Todas las mañanas, después de desayunar, voy al colegio en autobús."}'::jsonb),
  ('2-02-donde-esta-el-movil', 2, 'Tu madre no encuentra su móvil. Tú lo has visto hace un momento: dile dónde está.', 'speak', array['decir dónde está el móvil', 'situarlo respecto a otro objeto de la casa']::text[], '[{"hsk_level":2,"code":"1.1"}]'::jsonb, 6, 30, '{"zh":"你的手机在桌子上面，电脑的前面。","pinyin":"Nǐ de shǒujī zài zhuōzi shàngmiàn, diànnǎo de qiánmiàn.","es":"Tu móvil está encima de la mesa, delante del ordenador."}'::jsonb),
  ('2-03-pedir-ayuda-deberes', 2, 'No entiendes una pregunta de los deberes de chino. Pide ayuda a un compañero de clase y dile qué es lo que no entiendes.', 'write', array['pedir ayuda al compañero', 'decir qué es lo que no entiendes']::text[], '[{"hsk_level":2,"code":"5.4.1"}]'::jsonb, 8, 40, '{"zh":"这个问题我没看懂，你能帮帮我吗？","pinyin":"Zhège wèntí wǒ méi kàn dǒng, nǐ néng bāngbang wǒ ma?","es":"No he entendido esta pregunta, ¿me puedes ayudar?"}'::jsonb),
  ('2-04-hablar-o-escribir', 2, 'Tu profesora te pregunta qué te cuesta más en chino: hablar o escribir. Compara las dos cosas.', 'write', array['comparar hablar y escribir', 'decir cuál de las dos te cuesta más']::text[], '[{"hsk_level":2,"code":"6.3.4"}]'::jsonb, 6, 40, '{"zh":"我觉得写汉字比说汉语累多了，要写很长时间。","pinyin":"Wǒ juéde xiě Hànzì bǐ shuō Hànyǔ lèi duō le, yào xiě hěn cháng shíjiān.","es":"Me parece que escribir caracteres cansa mucho más que hablar chino: hay que pasar mucho rato escribiendo."}'::jsonb),
  ('2-05-llegar-tarde-al-trabajo', 2, 'Llegas tarde al trabajo y tu jefe te pregunta qué ha pasado. Explícale por qué llegas tarde.', 'write', array['reconocer que llegas tarde', 'explicar el motivo del retraso']::text[], '[{"hsk_level":2,"code":"6.4.3"}]'::jsonb, 8, 40, '{"zh":"对不起，我来晚了，因为路上车太多了。","pinyin":"Duìbuqǐ, wǒ lái wǎn le, yīnwèi lùshang chē tài duō le.","es":"Perdone, llego tarde porque había demasiado tráfico."}'::jsonb),
  ('2-06-cuanto-llevas-trabajando', 2, 'Un compañero nuevo te pregunta cuánto tiempo llevas trabajando en la empresa y qué haces. Contéstale.', 'write', array['decir cuánto tiempo llevas trabajando ahí', 'decir en qué consiste tu trabajo']::text[], '[{"hsk_level":2,"code":"5.4.4"}]'::jsonb, 10, 50, '{"zh":"我在这里工作了两年，每天都要给很多人打电话。","pinyin":"Wǒ zài zhèlǐ gōngzuò le liǎng nián, měitiān dōu yào gěi hěn duō rén dǎ diànhuà.","es":"Llevo dos años trabajando aquí; todos los días tengo que llamar por teléfono a mucha gente."}'::jsonb),
  ('2-07-cumpleanos-de-una-amiga', 2, 'Hoy es el cumpleaños de tu amiga. Felicítala y dile qué le has comprado.', 'write', array['felicitarla por su cumpleaños', 'decir qué regalo le has comprado']::text[], '[{"hsk_level":2,"code":"6.3.7"}]'::jsonb, 8, 40, '{"zh":"生日快乐！我给你买了一本书，希望你喜欢。","pinyin":"Shēngrì kuàilè! Wǒ gěi nǐ mǎi le yì běn shū, xīwàng nǐ xǐhuan.","es":"¡Feliz cumpleaños! Te he comprado un libro; espero que te guste."}'::jsonb),
  ('2-08-como-fue-la-fiesta', 2, 'Ayer fuiste a una fiesta. Un amigo que no pudo ir te pregunta cómo fue.', 'write', array['decir cómo fue la fiesta', 'contar algo concreto que pasó en ella']::text[], '[{"hsk_level":2,"code":"5.4.3"}]'::jsonb, 10, 50, '{"zh":"昨天大家玩得很高兴，我们唱歌、跳舞，玩到十一点。","pinyin":"Zuótiān dàjiā wán de hěn gāoxìng, wǒmen chàng gē, tiào wǔ, wán dào shíyī diǎn.","es":"Ayer lo pasamos todos muy bien: cantamos y bailamos hasta las once."}'::jsonb),
  ('2-09-indicar-el-camino', 2, 'Un turista te pregunta cómo llegar a la estación de tren. Explícale el camino.', 'speak', array['indicar hacia dónde tiene que ir', 'decir dónde está la estación al llegar']::text[], '[{"hsk_level":2,"code":"2.8.2"}]'::jsonb, 8, 50, '{"zh":"你从这儿往前走，再往右走，火车站就在左边。","pinyin":"Nǐ cóng zhèr wǎng qián zǒu, zài wǎng yòu zǒu, huǒchēzhàn jiù zài zuǒbian.","es":"Desde aquí sigue recto y luego gira a la derecha; la estación está a la izquierda."}'::jsonb),
  ('2-10-cerca-de-tu-casa', 2, 'Un amigo va a venir a visitarte por primera vez. Cuéntale qué hay cerca de tu casa.', 'write', array['decir qué hay cerca de tu casa', 'situar al menos un lugar respecto a otro']::text[], '[{"hsk_level":2,"code":"6.3.2"}]'::jsonb, 10, 50, '{"zh":"我家旁边有一个很大的商店，商店后面有一个小饭馆。","pinyin":"Wǒ jiā pángbiān yǒu yí gè hěn dà de shāngdiàn, shāngdiàn hòumiàn yǒu yí gè xiǎo fànguǎn.","es":"Al lado de mi casa hay una tienda muy grande, y detrás de la tienda hay un restaurante pequeño."}'::jsonb),
  ('2-11-comprar-pescado', 2, 'En el mercado quieres comprar pescado. Pregunta el precio y di cuánto quieres.', 'speak', array['preguntar el precio', 'decir cuánto quieres comprar']::text[], '[{"hsk_level":2,"code":"2.6.1"}]'::jsonb, 6, 30, '{"zh":"这条鱼多少钱？我要两条。","pinyin":"Zhè tiáo yú duōshao qián? Wǒ yào liǎng tiáo.","es":"¿Cuánto cuesta este pescado? Quiero dos."}'::jsonb),
  ('2-12-una-talla-mas-grande', 2, 'En una tienda te pruebas una prenda que te gusta, pero te queda pequeña. Díselo al dependiente y pide una más grande.', 'write', array['decir que te gusta pero te queda pequeña', 'pedir una más grande']::text[], '[{"hsk_level":2,"code":"6.4.2"}]'::jsonb, 10, 50, '{"zh":"这件衣服虽然很好看，但是太小了，有大一点儿的吗？","pinyin":"Zhè jiàn yīfu suīrán hěn hǎokàn, dànshì tài xiǎo le, yǒu dà yìdiǎnr de ma?","es":"Esta prenda es muy bonita, pero me queda pequeña. ¿Tienen una un poco más grande?"}'::jsonb),
  ('2-13-en-el-medico', 2, 'Estás en el médico. Dile qué te duele y desde cuándo.', 'speak', array['decir qué te duele', 'decir desde cuándo te duele']::text[], '[{"hsk_level":2,"code":"2.7.3"}]'::jsonb, 6, 40, '{"zh":"医生，我头疼，已经两天了。","pinyin":"Yīshēng, wǒ tóu téng, yǐjīng liǎng tiān le.","es":"Doctor, me duele la cabeza desde hace dos días."}'::jsonb),
  ('2-14-amigo-enfermo', 2, 'Tu amigo está resfriado y quiere ir a jugar al fútbol. Aconséjale que no vaya.', 'write', array['aconsejarle que no vaya', 'darle un motivo o proponerle otra cosa']::text[], '[{"hsk_level":2,"code":"6.2.2"}]'::jsonb, 8, 40, '{"zh":"你生病了，别去踢足球了，在家多休息吧。","pinyin":"Nǐ shēngbìng le, bié qù tī zúqiú le, zài jiā duō xiūxi ba.","es":"Estás enfermo; no vayas a jugar al fútbol, quédate en casa y descansa."}'::jsonb),
  ('2-15-que-hiciste-el-fin-de-semana', 2, 'El lunes un compañero te pregunta qué hiciste el fin de semana. Cuéntaselo y di qué te pareció.', 'write', array['contar qué hiciste', 'dar tu opinión sobre ello']::text[], '[{"hsk_level":2,"code":"2.7.2"}]'::jsonb, 10, 50, '{"zh":"星期六我和朋友一起去看电影了，那个电影很有意思。","pinyin":"Xīngqīliù wǒ hé péngyou yìqǐ qù kàn diànyǐng le, nàge diànyǐng hěn yǒu yìsi.","es":"El sábado fui al cine con un amigo; la película fue muy interesante."}'::jsonb),
  ('2-16-has-estado-en-china', 2, 'Un amigo chino te pregunta si has estado alguna vez en China. Contesta y añade algo sobre el viaje o sobre tus planes.', 'write', array['decir si has estado o no', 'añadir un detalle sobre el viaje o sobre tus planes']::text[], '[{"hsk_level":2,"code":"7.1.2"}]'::jsonb, 6, 40, '{"zh":"我去过中国，中国菜很好吃。","pinyin":"Wǒ qù guo Zhōngguó, Zhōngguó cài hěn hǎochī.","es":"He estado en China; la comida china está muy buena."}'::jsonb),
  ('2-17-presentar-a-una-companera', 2, 'Presentas a una compañera de clase a tu profesor. Dile quién es y algo sobre ella.', 'write', array['presentar a la compañera', 'decir algo sobre ella']::text[], '[{"hsk_level":2,"code":"5.4.3"}]'::jsonb, 10, 50, '{"zh":"老师，这是我的同学，她是中国人，汉语说得很好。","pinyin":"Lǎoshī, zhè shì wǒ de tóngxué, tā shì Zhōngguó rén, Hànyǔ shuō de hěn hǎo.","es":"Profesor, esta es mi compañera de clase; es china y habla muy bien chino."}'::jsonb),
  ('2-18-animar-a-un-amigo', 2, 'Tu amigo está triste porque le ha salido mal un examen. Anímale.', 'write', array['quitarle importancia o mostrar que le entiendes', 'animarle de cara a la próxima vez']::text[], '[{"hsk_level":2,"code":"2.7.6"}]'::jsonb, 8, 40, '{"zh":"没关系，下次再好好准备，你能考好的。","pinyin":"Méi guānxi, xià cì zài hǎohāo zhǔnbèi, nǐ néng kǎo hǎo de.","es":"No pasa nada; la próxima vez prepáratelo bien y te saldrá bien."}'::jsonb),
  ('2-19-saludar-a-un-vecino', 2, 'Por la mañana te encuentras en el ascensor con tu vecino mayor. Salúdale y pregúntale cómo está.', 'speak', array['saludarle', 'preguntarle cómo está']::text[], '[{"hsk_level":2,"code":"2.10.3"}]'::jsonb, 6, 40, '{"zh":"早上好！我去上班，您呢？最近身体好吗？","pinyin":"Zǎoshang hǎo! Wǒ qù shàngbān, nín ne? Zuìjìn shēntǐ hǎo ma?","es":"¡Buenos días! Yo voy a trabajar, ¿y usted? ¿Qué tal de salud últimamente?"}'::jsonb),
  ('2-20-pedir-un-numero-de-telefono', 2, 'Quieres llamar esta noche a un compañero nuevo para preguntarle algo de la clase de mañana. Pídele su número y dile para qué lo quieres.', 'write', array['pedirle su número de teléfono', 'decir para qué lo quieres']::text[], '[{"hsk_level":2,"code":"2.8.3"}]'::jsonb, 8, 40, '{"zh":"你能告诉我你的手机号吗？晚上我给你打电话，问问明天上课的事。","pinyin":"Nǐ néng gàosu wǒ nǐ de shǒujī hào ma? Wǎnshang wǒ gěi nǐ dǎ diànhuà, wènwen míngtiān shàngkè de shì.","es":"¿Me das tu número de móvil? Te llamo esta noche para preguntarte una cosa de la clase de mañana."}'::jsonb),
  ('2-21-invitar-a-cenar', 2, 'Quieres invitar a tu compañero a cenar en tu casa el sábado. Invítale y dile a qué hora.', 'write', array['invitarle a cenar', 'decir el día y la hora']::text[], '[{"hsk_level":2,"code":"6.3.6"}]'::jsonb, 8, 40, '{"zh":"星期六晚上我请你来我家吃饭，七点来吧！","pinyin":"Xīngqīliù wǎnshang wǒ qǐng nǐ lái wǒ jiā chī fàn, qī diǎn lái ba!","es":"Te invito a cenar a mi casa el sábado por la noche; ¡ven a las siete!"}'::jsonb),
  ('2-22-rechazar-una-invitacion', 2, 'Tu compañera te invita al cine el sábado. No puedes: explica por qué y propón otro día.', 'write', array['rechazar la invitación', 'dar un motivo', 'proponer otro día']::text[], '[{"hsk_level":2,"code":"6.4.3"}]'::jsonb, 10, 50, '{"zh":"对不起，星期六我有事，所以不能去。星期天去吧！","pinyin":"Duìbuqǐ, xīngqīliù wǒ yǒu shì, suǒyǐ bù néng qù. Xīngqītiān qù ba!","es":"Lo siento, el sábado tengo cosas que hacer, así que no puedo ir. ¡Vamos el domingo!"}'::jsonb),
  ('2-23-disculparse-por-el-vaso', 2, 'Has roto el vaso de tu compañera de piso. Discúlpate y ofrécele una solución.', 'write', array['disculparte', 'ofrecer una solución']::text[], '[{"hsk_level":2,"code":"2.7.6"}]'::jsonb, 8, 40, '{"zh":"对不起，我没拿好你的杯子，杯子坏了。明天我再给你买一个。","pinyin":"Duìbuqǐ, wǒ méi ná hǎo nǐ de bēizi, bēizi huài le. Míngtiān wǒ zài gěi nǐ mǎi yí gè.","es":"Perdona, se me ha caído tu vaso y se ha roto. Mañana te compro otro."}'::jsonb),
  ('2-24-describir-a-tu-mejor-amigo', 2, 'Describe a tu mejor amigo: cómo es y qué le gusta hacer.', 'write', array['describir cómo es', 'decir qué le gusta hacer']::text[], '[{"hsk_level":2,"code":"2.7.1"}]'::jsonb, 10, 50, '{"zh":"我最好的朋友个子很高，很爱笑，他最喜欢打篮球。","pinyin":"Wǒ zuì hǎo de péngyou gèzi hěn gāo, hěn ài xiào, tā zuì xǐhuan dǎ lánqiú.","es":"Mi mejor amigo es muy alto y se ríe mucho; lo que más le gusta es jugar al baloncesto."}'::jsonb)
