), resolved as (
  select ci.id as content_id, 'word'::public.learning_target_kind as target_kind, w.id as target_id
  from reading_targets t
  join public.content_item ci on ci.source_table = 'reading' and ci.source_id = t.slug
  join lateral (
    select w.id
    from public.words w
    join public.reading r on r.slug = t.slug
    where t.target_kind = 'word' and w.hanzi = t.target_value and w.hsk_level <= r.hsk_level
    order by w.hsk_level desc, coalesce(w.sense_index, 0), w.id
    limit 1
  ) w on true
  union all
  select ci.id, 'grammar'::public.learning_target_kind, g.id
  from reading_targets t
  join public.content_item ci on ci.source_table = 'reading' and ci.source_id = t.slug
  join public.grammar_points g on g.code = t.target_value and g.hsk_level = t.target_level
)
select distinct content_id, target_kind, target_id, 'target'::public.teaches_role
from resolved
on conflict (content_id, target_kind, target_id) do update set role = excluded.role;

on conflict (level, code) do update set content = excluded.content, timeline = excluded.timeline, media = excluded.media;

on conflict (slug) do update set hsk_level = excluded.hsk_level, situation_es = excluded.situation_es, mode = excluded.mode, intent = excluded.intent, required_markers = excluded.required_markers, min_chars = excluded.min_chars, max_chars = excluded.max_chars, model_answer = excluded.model_answer;

commit;
